window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["LEV"]={"book":"LEV","editions":{"hbo-source":[[1,1,"וַ⁠יִּקְרָ֖א אֶל־מֹשֶׁ֑ה וַ⁠יְדַבֵּ֤ר יְהוָה֙ אֵלָ֔י⁠ו מֵ⁠אֹ֥הֶל מוֹעֵ֖ד לֵ⁠אמֹֽר׃","wa⁠yi̇qĕrá֖ʼ ʼel-mòşě֑h wa⁠yĕdabé֤̇r yĕhwáh֙ ʼélá֔y⁠w mé⁠ʼò֥hel mwòʻé֖d lé⁠ʼmòֽr׃"],[1,2,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם אָדָ֗ם כִּֽי־יַקְרִ֥יב מִ⁠כֶּ֛ם קָרְבָּ֖ן לַֽ⁠יהוָ֑ה מִן־הַ⁠בְּהֵמָ֗ה מִן־הַ⁠בָּקָר֙ וּ⁠מִן־הַ⁠צֹּ֔אן תַּקְרִ֖יבוּ אֶת־קָרְבַּנְ⁠כֶֽם׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m ʼádá֗m kiֽ̇y-yaqĕri֥yb mi⁠kė֛m qárĕbá֖̇n laֽ⁠yhwá֑h min-ha⁠bĕ̇hémá֗h min-ha⁠bá̇qár֙ ẇ⁠min-ha⁠ẕò̇֔ʼn ţȧqĕri֖ybẇ ʼeţ-qárĕbȧnĕ⁠keֽm׃"],[1,3,"אִם־עֹלָ֤ה קָרְבָּנ⁠וֹ֙ מִן־הַ⁠בָּקָ֔ר זָכָ֥ר תָּמִ֖ים יַקְרִיבֶ֑⁠נּוּ אֶל־פֶּ֝תַח אֹ֤הֶל מוֹעֵד֙ יַקְרִ֣יב אֹת֔⁠וֹ לִ⁠רְצֹנ֖⁠וֹ לִ⁠פְנֵ֥י יְהוָֽה׃","ʼim-ʻòlá֤h qárĕbá̇n⁠wò֙ min-ha⁠bá̇qá֔r záká֥r ţá̇mi֖ym yaqĕriybe֑⁠ṅẇ ʼel-pė֝ţaẖ ʼò֤hel mwòʻéd֙ yaqĕri֣yb ʼòţ֔⁠wò li⁠rĕẕòn֖⁠wò li⁠pĕné֥y yĕhwáֽh׃"],[1,4,"וְ⁠סָמַ֣ךְ יָד֔⁠וֹ עַ֖ל רֹ֣אשׁ הָ⁠עֹלָ֑ה וְ⁠נִרְצָ֥ה ל֖⁠וֹ לְ⁠כַפֵּ֥ר עָלָֽי⁠ו׃","wĕ⁠sáma֣kĕ yád֔⁠wò ʻa֖l rò֣ʼş̌ há⁠ʻòlá֑h wĕ⁠nirĕẕá֥h l֖⁠wò lĕ⁠kapé֥̇r ʻáláֽy⁠w׃"],[1,5,"וְ⁠שָׁחַ֛ט אֶת־בֶּ֥ן הַ⁠בָּקָ֖ר לִ⁠פְנֵ֣י יְהוָ֑ה וְ֠⁠הִקְרִיבוּ בְּנֵ֨י אַהֲרֹ֤ן הַֽ⁠כֹּֽהֲנִים֙ אֶת־הַ⁠דָּ֔ם וְ⁠זָרְק֨וּ אֶת־הַ⁠דָּ֤ם עַל־הַ⁠מִּזְבֵּ֨חַ֙ סָבִ֔יב אֲשֶׁר־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠şá̌ẖa֛t ʼeţ-bė֥n ha⁠bá̇qá֖r li⁠pĕné֣y yĕhwá֑h wĕ֠⁠hiqĕriybẇ bĕ̇né֨y ʼahàrò֤n hֽa⁠kòֽ̇hàniym֙ ʼeţ-ha⁠dá̇֔m wĕ⁠zárĕq֨ẇ ʼeţ-ha⁠dá֤̇m ʻal-ha⁠mi̇zĕbé̇֨ẖa֙ sábi֔yb ʼàşěr-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[1,6,"וְ⁠הִפְשִׁ֖יט אֶת־הָ⁠עֹלָ֑ה וְ⁠נִתַּ֥ח אֹתָ֖⁠הּ לִ⁠נְתָחֶֽי⁠הָ׃","wĕ⁠hipĕşǐ֖yt ʼeţ-há⁠ʻòlá֑h wĕ⁠niţȧ֥ẖ ʼòţá֖⁠ḣ li⁠nĕţáẖeֽy⁠há׃"],[1,7,"וְ֠⁠נָתְנוּ בְּנֵ֨י אַהֲרֹ֧ן הַ⁠כֹּהֵ֛ן אֵ֖שׁ עַל־הַ⁠מִּזְבֵּ֑חַ וְ⁠עָרְכ֥וּ עֵצִ֖ים עַל־הָ⁠אֵֽשׁ׃","wĕ֠⁠náţĕnẇ bĕ̇né֨y ʼahàrò֧n ha⁠kò̇hé֛n ʼé֖ş̌ ʻal-ha⁠mi̇zĕbé֑̇ẖa wĕ⁠ʻárĕk֥ẇ ʻéẕi֖ym ʻal-há⁠ʼéֽş̌׃"],[1,8,"וְ⁠עָרְכ֗וּ בְּנֵ֤י אַהֲרֹן֙ הַ⁠כֹּ֣הֲנִ֔ים אֵ֚ת הַ⁠נְּתָחִ֔ים אֶת־הָ⁠רֹ֖אשׁ וְ⁠אֶת־הַ⁠פָּ֑דֶר עַל־הָ⁠עֵצִים֙ אֲשֶׁ֣ר עַל־הָ⁠אֵ֔שׁ אֲשֶׁ֖ר עַל־הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠ʻárĕk֗ẇ bĕ̇né֤y ʼahàròn֙ ha⁠kò֣̇hàni֔ym ʼé֚ţ ha⁠nĕ̇ţáẖi֔ym ʼeţ-há⁠rò֖ʼş̌ wĕ⁠ʼeţ-ha⁠pá֑̇der ʻal-há⁠ʻéẕiym֙ ʼàşě֣r ʻal-há⁠ʼé֔ş̌ ʼàşě֖r ʻal-ha⁠mi̇zĕbéֽ̇ẖa׃"],[1,9,"וְ⁠קִרְבּ֥⁠וֹ וּ⁠כְרָעָ֖י⁠ו יִרְחַ֣ץ בַּ⁠מָּ֑יִם וְ⁠הִקְטִ֨יר הַ⁠כֹּהֵ֤ן אֶת־הַ⁠כֹּל֙ הַ⁠מִּזְבֵּ֔חָ⁠ה עֹלָ֛ה אִשֵּׁ֥ה רֵֽיחַ־נִיח֖וֹחַ לַֽ⁠יהוָֽה׃ס","wĕ⁠qirĕḃ֥⁠wò ẇ⁠kĕráʻá֖y⁠w yirĕẖa֣ẕ bȧ⁠má֑̇yim wĕ⁠hiqĕti֨yr ha⁠kò̇hé֤n ʼeţ-ha⁠kò̇l֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʻòlá֛h ʼişé֥̇̌h réֽyẖa-niyẖ֖wòẖa laֽ⁠yhwáֽh׃s"],[1,10,"וְ⁠אִם־מִן־הַ⁠צֹּ֨אן קָרְבָּנ֧⁠וֹ מִן־הַ⁠כְּשָׂבִ֛ים א֥וֹ מִן־הָ⁠עִזִּ֖ים לְ⁠עֹלָ֑ה זָכָ֥ר תָּמִ֖ים יַקְרִיבֶֽ⁠נּוּ׃","wĕ⁠ʼim-min-ha⁠ẕò̇֨ʼn qárĕbá̇n֧⁠wò min-ha⁠kĕ̇şá̂bi֛ym ʼ֥wò min-há⁠ʻizi֖̇ym lĕ⁠ʻòlá֑h záká֥r ţá̇mi֖ym yaqĕriybeֽ⁠ṅẇ׃"],[1,11,"וְ⁠שָׁחַ֨ט אֹת֜⁠וֹ עַ֣ל יֶ֧רֶךְ הַ⁠מִּזְבֵּ֛חַ צָפֹ֖נָ⁠ה לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠זָרְק֡וּ בְּנֵי֩ אַהֲרֹ֨ן הַ⁠כֹּהֲנִ֧ים אֶת־דָּמ֛⁠וֹ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠şá̌ẖa֨t ʼòţ֜⁠wò ʻa֣l ye֧rekĕ ha⁠mi̇zĕbé֛̇ẖa ẕápò֖ná⁠h li⁠pĕné֣y yĕhwá֑h wĕ⁠zárĕq֡ẇ bĕ̇néy֩ ʼahàrò֨n ha⁠kò̇hàni֧ym ʼeţ-dá̇m֛⁠wò ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[1,12,"וְ⁠נִתַּ֤ח אֹת⁠וֹ֙ לִ⁠נְתָחָ֔י⁠ו וְ⁠אֶת־רֹאשׁ֖⁠וֹ וְ⁠אֶת־פִּדְר֑⁠וֹ וְ⁠עָרַ֤ךְ הַ⁠כֹּהֵן֙ אֹתָ֔⁠ם עַל־הָֽ⁠עֵצִים֙ אֲשֶׁ֣ר עַל־הָ⁠אֵ֔שׁ אֲשֶׁ֖ר עַל־הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠niţȧ֤ẖ ʼòţ⁠wò֙ li⁠nĕţáẖá֔y⁠w wĕ⁠ʼeţ-ròʼş֖̌⁠wò wĕ⁠ʼeţ-pi̇dĕr֑⁠wò wĕ⁠ʻára֤kĕ ha⁠kò̇hén֙ ʼòţá֔⁠m ʻal-háֽ⁠ʻéẕiym֙ ʼàşě֣r ʻal-há⁠ʼé֔ş̌ ʼàşě֖r ʻal-ha⁠mi̇zĕbéֽ̇ẖa׃"],[1,13,"וְ⁠הַ⁠קֶּ֥רֶב וְ⁠הַ⁠כְּרָעַ֖יִם יִרְחַ֣ץ בַּ⁠מָּ֑יִם וְ⁠הִקְרִ֨יב הַ⁠כֹּהֵ֤ן אֶת־הַ⁠כֹּל֙ וְ⁠הִקְטִ֣יר הַ⁠מִּזְבֵּ֔חָ⁠ה עֹלָ֣ה ה֗וּא אִשֵּׁ֛ה רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָֽה׃פ","wĕ⁠ha⁠qė֥reb wĕ⁠ha⁠kĕ̇ráʻa֖yim yirĕẖa֣ẕ bȧ⁠má֑̇yim wĕ⁠hiqĕri֨yb ha⁠kò̇hé֤n ʼeţ-ha⁠kò̇l֙ wĕ⁠hiqĕti֣yr ha⁠mi̇zĕbé̇֔ẖá⁠h ʻòlá֣h h֗ẇʼ ʼişé֛̇̌h ré֥yẖa niyẖò֖ẖa la⁠yhwáֽh׃p"],[1,14,"וְ⁠אִ֧ם מִן־הָ⁠ע֛וֹף עֹלָ֥ה קָרְבָּנ֖⁠וֹ לַֽ⁠יהוָ֑ה וְ⁠הִקְרִ֣יב מִן־הַ⁠תֹּרִ֗ים א֛וֹ מִן־בְּנֵ֥י הַ⁠יּוֹנָ֖ה אֶת־קָרְבָּנֽ⁠וֹ׃","wĕ⁠ʼi֧m min-há⁠ʻ֛wòp ʻòlá֥h qárĕbá̇n֖⁠wò laֽ⁠yhwá֑h wĕ⁠hiqĕri֣yb min-ha⁠ţò̇ri֗ym ʼ֛wò min-bĕ̇né֥y ha⁠ẏwòná֖h ʼeţ-qárĕbá̇nֽ⁠wò׃"],[1,15,"וְ⁠הִקְרִיב֤⁠וֹ הַ⁠כֹּהֵן֙ אֶל־הַ⁠מִּזְבֵּ֔חַ וּ⁠מָלַק֙ אֶת־רֹאשׁ֔⁠וֹ וְ⁠הִקְטִ֖יר הַ⁠מִּזְבֵּ֑חָ⁠ה וְ⁠נִמְצָ֣ה דָמ֔⁠וֹ עַ֖ל קִ֥יר הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠hiqĕriyb֤⁠wò ha⁠kò̇hén֙ ʼel-ha⁠mi̇zĕbé̇֔ẖa ẇ⁠málaq֙ ʼeţ-ròʼş̌֔⁠wò wĕ⁠hiqĕti֖yr ha⁠mi̇zĕbé֑̇ẖá⁠h wĕ⁠nimĕẕá֣h dám֔⁠wò ʻa֖l qi֥yr ha⁠mi̇zĕbéֽ̇ẖa׃"],[1,16,"וְ⁠הֵסִ֥יר אֶת־מֻרְאָת֖⁠וֹ בְּ⁠נֹצָתָ֑⁠הּ וְ⁠הִשְׁלִ֨יךְ אֹתָ֜⁠הּ אֵ֤צֶל הַ⁠מִּזְבֵּ֨חַ֙ קֵ֔דְמָ⁠ה אֶל־מְק֖וֹם הַ⁠דָּֽשֶׁן׃","wĕ⁠hési֥yr ʼeţ-murĕʼáţ֖⁠wò bĕ̇⁠nòẕáţá֑⁠ḣ wĕ⁠hişĕ̌li֨ykĕ ʼòţá֜⁠ḣ ʼé֤ẕel ha⁠mi̇zĕbé̇֨ẖa֙ qé֔dĕmá⁠h ʼel-mĕq֖wòm ha⁠dáֽ̇şěn׃"],[1,17,"וְ⁠שִׁסַּ֨ע אֹת֣⁠וֹ בִ⁠כְנָפָי⁠ו֮ לֹ֣א יַבְדִּיל֒ וְ⁠הִקְטִ֨יר אֹת֤⁠וֹ הַ⁠כֹּהֵן֙ הַ⁠מִּזְבֵּ֔חָ⁠ה עַל־הָ⁠עֵצִ֖ים אֲשֶׁ֣ר עַל־הָ⁠אֵ֑שׁ עֹלָ֣ה ה֗וּא אִשֵּׁ֛ה רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָֽה׃ס","wĕ⁠şǐsȧ֨ʻ ʼòţ֣⁠wò bi⁠kĕnápáy⁠w֮ lò֣ʼ yabĕdi̇yl֒ wĕ⁠hiqĕti֨yr ʼòţ֤⁠wò ha⁠kò̇hén֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʻal-há⁠ʻéẕi֖ym ʼàşě֣r ʻal-há⁠ʼé֑ş̌ ʻòlá֣h h֗ẇʼ ʼişé֛̇̌h ré֥yẖa niyẖò֖ẖa la⁠yhwáֽh׃s"],[2,1,"וְ⁠נֶ֗פֶשׁ כִּֽי־תַקְרִ֞יב קָרְבַּ֤ן מִנְחָה֙ לַֽ⁠יהוָ֔ה סֹ֖לֶת יִהְיֶ֣ה קָרְבָּנ֑⁠וֹ וְ⁠יָצַ֤ק עָלֶ֨י⁠הָ֙ שֶׁ֔מֶן וְ⁠נָתַ֥ן עָלֶ֖י⁠הָ לְבֹנָֽה׃","wĕ⁠ne֗peş̌ kiֽ̇y-ţaqĕri֞yb qárĕbȧ֤n minĕẖáh֙ laֽ⁠yhwá֔h sò֖leţ yihĕye֣h qárĕbá̇n֑⁠wò wĕ⁠yáẕa֤q ʻále֨y⁠há֙ şě֔men wĕ⁠náţa֥n ʻále֖y⁠há lĕbònáֽh׃"],[2,2,"וֶֽ⁠הֱבִיאָ֗⁠הּ אֶל־בְּנֵ֣י אַהֲרֹן֮ הַ⁠כֹּהֲנִים֒ וְ⁠קָמַ֨ץ מִ⁠שָּׁ֜ם מְלֹ֣א קֻמְצ֗⁠וֹ מִ⁠סָּלְתָּ⁠הּ֙ וּ⁠מִ⁠שַּׁמְנָ֔⁠הּ עַ֖ל כָּל־לְבֹנָתָ֑⁠הּ וְ⁠הִקְטִ֨יר הַ⁠כֹּהֵ֜ן אֶת־אַזְכָּרָתָ⁠הּ֙ הַ⁠מִּזְבֵּ֔חָ⁠ה אִשֵּׁ֛ה רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָֽה׃","wֽe⁠hèbiyʼá֗⁠ḣ ʼel-bĕ̇né֣y ʼahàròn֮ ha⁠kò̇hàniym֒ wĕ⁠qáma֨ẕ mi⁠şá̇̌֜m mĕlò֣ʼ qumĕẕ֗⁠wò mi⁠sá̇lĕţá̇⁠ḣ֙ ẇ⁠mi⁠şȧ̌mĕná֔⁠ḣ ʻa֖l ká̇l-lĕbònáţá֑⁠ḣ wĕ⁠hiqĕti֨yr ha⁠kò̇hé֜n ʼeţ-ʼazĕká̇ráţá⁠ḣ֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʼişé֛̇̌h ré֥yẖa niyẖò֖ẖa la⁠yhwáֽh׃"],[2,3,"וְ⁠הַ⁠נּוֹתֶ֨רֶת֙ מִן־הַ⁠מִּנְחָ֔ה לְ⁠אַהֲרֹ֖ן וּ⁠לְ⁠בָנָ֑י⁠ו קֹ֥דֶשׁ קָֽדָשִׁ֖ים מֵ⁠אִשֵּׁ֥י יְהוָֽה׃ס","wĕ⁠ha⁠ṅwòţe֨reţ֙ min-ha⁠mi̇nĕẖá֔h lĕ⁠ʼahàrò֖n ẇ⁠lĕ⁠báná֑y⁠w qò֥deş̌ qáֽdáşǐ֖ym mé⁠ʼişé֥̇̌y yĕhwáֽh׃s"],[2,4,"וְ⁠כִ֥י תַקְרִ֛ב קָרְבַּ֥ן מִנְחָ֖ה מַאֲפֵ֣ה תַנּ֑וּר סֹ֣לֶת חַלּ֤וֹת מַצֹּת֙ בְּלוּלֹ֣ת בַּ⁠שֶּׁ֔מֶן וּ⁠רְקִיקֵ֥י מַצּ֖וֹת מְשֻׁחִ֥ים בַּ⁠שָּֽׁמֶן׃ס","wĕ⁠ki֥y ţaqĕri֛b qárĕbȧ֥n minĕẖá֖h maʼàpé֣h ţaṅ֑ẇr sò֣leţ ẖal֤̇wòţ maẕò̇ţ֙ bĕ̇lẇlò֣ţ bȧ⁠şė̌֔men ẇ⁠rĕqiyqé֥y maẕ֖̇wòţ mĕşǔẖi֥ym bȧ⁠şáֽ̇̌men׃s"],[2,5,"וְ⁠אִם־מִנְחָ֥ה עַל־הַֽ⁠מַּחֲבַ֖ת קָרְבָּנֶ֑⁠ךָ סֹ֛לֶת בְּלוּלָ֥ה בַ⁠שֶּׁ֖מֶן מַצָּ֥ה תִהְיֶֽה׃","wĕ⁠ʼim-minĕẖá֥h ʻal-haֽ⁠mȧẖàba֖ţ qárĕbá̇ne֑⁠ká sò֛leţ bĕ̇lẇlá֥h ba⁠şė֖̌men maẕá֥̇h ţihĕyeֽh׃"],[2,6,"פָּת֤וֹת אֹתָ⁠הּ֙ פִּתִּ֔ים וְ⁠יָצַקְתָּ֥ עָלֶ֖י⁠הָ שָׁ֑מֶן מִנְחָ֖ה הִֽוא׃ס","pá̇ţ֤wòţ ʼòţá⁠ḣ֙ pi̇ţi̇֔ym wĕ⁠yáẕaqĕţá֥̇ ʻále֖y⁠há şá֑̌men minĕẖá֖h hiֽwʼ׃s"],[2,7,"וְ⁠אִם־מִנְחַ֥ת מַרְחֶ֖שֶׁת קָרְבָּנֶ֑⁠ךָ סֹ֥לֶת בַּ⁠שֶּׁ֖מֶן תֵּעָשֶֽׂה׃","wĕ⁠ʼim-minĕẖa֥ţ marĕẖe֖şěţ qárĕbá̇ne֑⁠ká sò֥leţ bȧ⁠şė֖̌men ţé̇ʻáşêֽh׃"],[2,8,"וְ⁠הֵבֵאתָ֣ אֶת־הַ⁠מִּנְחָ֗ה אֲשֶׁ֧ר יֵעָשֶׂ֛ה מֵ⁠אֵ֖לֶּה לַ⁠יהוָ֑ה וְ⁠הִקְרִיבָ⁠הּ֙ אֶל־הַ⁠כֹּהֵ֔ן וְ⁠הִגִּישָׁ֖⁠הּ אֶל־הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠hébéʼţá֣ ʼeţ-ha⁠mi̇nĕẖá֗h ʼàşě֧r yéʻáşê֛h mé⁠ʼé֖lėh la⁠yhwá֑h wĕ⁠hiqĕriybá⁠ḣ֙ ʼel-ha⁠kò̇hé֔n wĕ⁠higi̇yşá֖̌⁠ḣ ʼel-ha⁠mi̇zĕbéֽ̇ẖa׃"],[2,9,"וְ⁠הֵרִ֨ים הַ⁠כֹּהֵ֤ן מִן־הַ⁠מִּנְחָה֙ אֶת־אַזְכָּ֣רָתָ֔⁠הּ וְ⁠הִקְטִ֖יר הַ⁠מִּזְבֵּ֑חָ⁠ה אִשֵּׁ֛ה רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָֽה׃","wĕ⁠héri֨ym ha⁠kò̇hé֤n min-ha⁠mi̇nĕẖáh֙ ʼeţ-ʼazĕká֣̇ráţá֔⁠ḣ wĕ⁠hiqĕti֖yr ha⁠mi̇zĕbé֑̇ẖá⁠h ʼişé֛̇̌h ré֥yẖa niyẖò֖ẖa la⁠yhwáֽh׃"],[2,10,"וְ⁠הַ⁠נּוֹתֶ֨רֶת֙ מִן־הַ⁠מִּנְחָ֔ה לְ⁠אַהֲרֹ֖ן וּ⁠לְ⁠בָנָ֑י⁠ו קֹ֥דֶשׁ קָֽדָשִׁ֖ים מֵ⁠אִשֵּׁ֥י יְהוָֽה׃","wĕ⁠ha⁠ṅwòţe֨reţ֙ min-ha⁠mi̇nĕẖá֔h lĕ⁠ʼahàrò֖n ẇ⁠lĕ⁠báná֑y⁠w qò֥deş̌ qֽádáşǐ֖ym mé⁠ʼişé֥̇̌y yĕhwáֽh׃"],[2,11,"כָּל־הַ⁠מִּנְחָ֗ה אֲשֶׁ֤ר תַּקְרִ֨יבוּ֙ לַ⁠יהוָ֔ה לֹ֥א תֵעָשֶׂ֖ה חָמֵ֑ץ כִּ֤י כָל־שְׂאֹר֙ וְ⁠כָל־דְּבַ֔שׁ לֹֽא־תַקְטִ֧ירוּ מִמֶּ֛⁠נּוּ אִשֶּׁ֖ה לַֽ⁠יהוָֽה׃","ká̇l-ha⁠mi̇nĕẖá֗h ʼàşě֤r ţȧqĕri֨ybẇ֙ la⁠yhwá֔h lò֥ʼ ţéʻáşê֖h ẖámé֑ẕ ki֤̇y kál-şĕ̂ʼòr֙ wĕ⁠kál-dĕ̇ba֔ş̌ lòֽʼ-ţaqĕti֧yrẇ mimė֛⁠ṅẇ ʼişė֖̌h laֽ⁠yhwáֽh׃"],[2,12,"קָרְבַּ֥ן רֵאשִׁ֛ית תַּקְרִ֥יבוּ אֹתָ֖⁠ם לַ⁠יהוָ֑ה וְ⁠אֶל־הַ⁠מִּזְבֵּ֥חַ לֹא־יַעֲל֖וּ לְ⁠רֵ֥יחַ נִיחֹֽחַ׃","qárĕbȧ֥n réʼşǐ֛yţ ţȧqĕri֥ybẇ ʼòţá֖⁠m la⁠yhwá֑h wĕ⁠ʼel-ha⁠mi̇zĕbé֥̇ẖa lòʼ-yaʻàl֖ẇ lĕ⁠ré֥yẖa niyẖòֽẖa׃"],[2,13,"וְ⁠כָל־קָרְבַּ֣ן מִנְחָתְ⁠ךָ֮ בַּ⁠מֶּ֣לַח תִּמְלָח֒ וְ⁠לֹ֣א תַשְׁבִּ֗ית מֶ֚לַח בְּרִ֣ית אֱלֹהֶ֔י⁠ךָ מֵ⁠עַ֖ל מִנְחָתֶ֑⁠ךָ עַ֥ל כָּל־קָרְבָּנְ⁠ךָ֖ תַּקְרִ֥יב מֶֽלַח׃ס","wĕ⁠kál-qárĕbȧ֣n minĕẖáţĕ⁠ká֮ bȧ⁠mė֣laẖ ţi̇mĕláẖ֒ wĕ⁠lò֣ʼ ţaşĕ̌bi̇֗yţ me֚laẖ bĕ̇ri֣yţ ʼèlòhe֔y⁠ká mé⁠ʻa֖l minĕẖáţe֑⁠ká ʻa֥l ká̇l-qárĕbá̇nĕ⁠ká֖ ţȧqĕri֥yb meֽlaẖ׃s"],[2,14,"וְ⁠אִם־תַּקְרִ֛יב מִנְחַ֥ת בִּכּוּרִ֖ים לַ⁠יהוָ֑ה אָבִ֞יב קָל֤וּי בָּ⁠אֵשׁ֙ גֶּ֣רֶשׂ כַּרְמֶ֔ל תַּקְרִ֕יב אֵ֖ת מִנְחַ֥ת בִּכּוּרֶֽי⁠ךָ׃","wĕ⁠ʼim-ţȧqĕri֛yb minĕẖa֥ţ bi̇k̇ẇri֖ym la⁠yhwá֑h ʼábi֞yb qál֤ẇy bá̇⁠ʼéş̌֙ gė֣reş̂ kȧrĕme֔l ţȧqĕri֕yb ʼé֖ţ minĕẖa֥ţ bi̇k̇ẇreֽy⁠ká׃"],[2,15,"וְ⁠נָתַתָּ֤ עָלֶ֨י⁠הָ֙ שֶׁ֔מֶן וְ⁠שַׂמְתָּ֥ עָלֶ֖י⁠הָ לְבֹנָ֑ה מִנְחָ֖ה הִֽוא׃","wĕ⁠náţaţá֤̇ ʻále֨y⁠há֙ şě֔men wĕ⁠şâmĕţá֥̇ ʻále֖y⁠há lĕbòná֑h minĕẖá֖h hiֽwʼ׃"],[2,16,"וְ⁠הִקְטִ֨יר הַ⁠כֹּהֵ֜ן אֶת־אַזְכָּרָתָ֗⁠הּ מִ⁠גִּרְשָׂ⁠הּ֙ וּ⁠מִ⁠שַּׁמְנָ֔⁠הּ עַ֖ל כָּל־לְבֹנָתָ֑⁠הּ אִשֶּׁ֖ה לַ⁠יהוָֽה׃פ","wĕ⁠hiqĕti֨yr ha⁠kò̇hé֜n ʼeţ-ʼazĕká̇ráţá֗⁠ḣ mi⁠gi̇rĕşá̂⁠ḣ֙ ẇ⁠mi⁠şȧ̌mĕná֔⁠ḣ ʻa֖l ká̇l-lĕbònáţá֑⁠ḣ ʼişė֖̌h la⁠yhwáֽh׃p"],[3,1,"וְ⁠אִם־זֶ֥בַח שְׁלָמִ֖ים קָרְבָּנ֑⁠וֹ אִ֤ם מִן־הַ⁠בָּקָר֙ ה֣וּא מַקְרִ֔יב אִם־זָכָר֙ אִם־נְקֵבָ֔ה תָּמִ֥ים יַקְרִיבֶ֖⁠נּוּ לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠ʼim-ze֥baẖ şĕ̌lámi֖ym qárĕbá̇n֑⁠wò ʼi֤m min-ha⁠bá̇qár֙ h֣ẇʼ maqĕri֔yb ʼim-zákár֙ ʼim-nĕqébá֔h ţá̇mi֥ym yaqĕriybe֖⁠ṅẇ li⁠pĕné֥y yĕhwáֽh׃"],[3,2,"וְ⁠סָמַ֤ךְ יָד⁠וֹ֙ עַל־רֹ֣אשׁ קָרְבָּנ֔⁠וֹ וּ⁠שְׁחָט֕⁠וֹ פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד וְ⁠זָרְק֡וּ בְּנֵי֩ אַהֲרֹ֨ן הַ⁠כֹּהֲנִ֧ים אֶת־הַ⁠דָּ֛ם עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠sáma֤kĕ yád⁠wò֙ ʻal-rò֣ʼş̌ qárĕbá̇n֔⁠wò ẇ⁠şĕ̌ẖát֕⁠wò pė֖ţaẖ ʼò֣hel mwòʻé֑d wĕ⁠zárĕq֡ẇ bĕ̇néy֩ ʼahàrò֨n ha⁠kò̇hàni֧ym ʼeţ-ha⁠dá֛̇m ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[3,3,"וְ⁠הִקְרִיב֙ מִ⁠זֶּ֣בַח הַ⁠שְּׁלָמִ֔ים אִשֶּׁ֖ה לַ⁠יהוָ֑ה אֶת־הַ⁠חֵ֨לֶב֙ הַֽ⁠מְכַסֶּ֣ה אֶת־הַ⁠קֶּ֔רֶב וְ⁠אֵת֙ כָּל־הַ⁠חֵ֔לֶב אֲשֶׁ֖ר עַל־הַ⁠קֶּֽרֶב׃","wĕ⁠hiqĕriyb֙ mi⁠zė֣baẖ ha⁠şĕ̇̌lámi֔ym ʼişė֖̌h la⁠yhwá֑h ʼeţ-ha⁠ẖé֨leb֙ haֽ⁠mĕkasė֣h ʼeţ-ha⁠qė֔reb wĕ⁠ʼéţ֙ ká̇l-ha⁠ẖé֔leb ʼàşě֖r ʻal-ha⁠qėֽreb׃"],[3,4,"וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵ⁠הֶ֔ן אֲשֶׁ֖ר עַל־הַ⁠כְּסָלִ֑ים וְ⁠אֶת־הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד עַל־הַ⁠כְּלָי֖וֹת יְסִירֶֽ⁠נָּה׃","wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàlé⁠he֔n ʼàşě֖r ʻal-ha⁠kĕ̇sáli֑ym wĕ⁠ʼeţ-ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d ʻal-ha⁠kĕ̇láy֖wòţ yĕsiyreֽ⁠ná̇h׃"],[3,5,"וְ⁠הִקְטִ֨ירוּ אֹת֤⁠וֹ בְנֵֽי־אַהֲרֹן֙ הַ⁠מִּזְבֵּ֔חָ⁠ה עַל־הָ֣⁠עֹלָ֔ה אֲשֶׁ֥ר עַל־הָ⁠עֵצִ֖ים אֲשֶׁ֣ר עַל־הָ⁠אֵ֑שׁ אִשֵּׁ֛ה רֵ֥יחַ נִיחֹ֖חַ לַֽ⁠יהוָֽה׃פ","wĕ⁠hiqĕti֨yrẇ ʼòţ֤⁠wò bĕnéֽy-ʼahàròn֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʻal-há֣⁠ʻòlá֔h ʼàşě֥r ʻal-há⁠ʻéẕi֖ym ʼàşě֣r ʻal-há⁠ʼé֑ş̌ ʼişé֛̇̌h ré֥yẖa niyẖò֖ẖa laֽ⁠yhwáֽh׃p"],[3,6,"וְ⁠אִם־מִן־הַ⁠צֹּ֧אן קָרְבָּנ֛⁠וֹ לְ⁠זֶ֥בַח שְׁלָמִ֖ים לַ⁠יהוָ֑ה זָכָר֙ א֣וֹ נְקֵבָ֔ה תָּמִ֖ים יַקְרִיבֶֽ⁠נּוּ׃","wĕ⁠ʼim-min-ha⁠ẕò֧̇ʼn qárĕbá̇n֛⁠wò lĕ⁠ze֥baẖ şĕ̌lámi֖ym la⁠yhwá֑h zákár֙ ʼ֣wò nĕqébá֔h ţá̇mi֖ym yaqĕriybeֽ⁠ṅẇ׃"],[3,7,"אִם־כֶּ֥שֶׂב הֽוּא־מַקְרִ֖יב אֶת־קָרְבָּנ֑⁠וֹ וְ⁠הִקְרִ֥יב אֹת֖⁠וֹ לִ⁠פְנֵ֥י יְהוָֽה׃","ʼim-kė֥şêb hֽẇʼ-maqĕri֖yb ʼeţ-qárĕbá̇n֑⁠wò wĕ⁠hiqĕri֥yb ʼòţ֖⁠wò li⁠pĕné֥y yĕhwáֽh׃"],[3,8,"וְ⁠סָמַ֤ךְ אֶת־יָד⁠וֹ֙ עַל־רֹ֣אשׁ קָרְבָּנ֔⁠וֹ וְ⁠שָׁחַ֣ט אֹת֔⁠וֹ לִ⁠פְנֵ֖י אֹ֣הֶל מוֹעֵ֑ד וְ֠⁠זָרְקוּ בְּנֵ֨י אַהֲרֹ֧ן אֶת־דָּמ֛⁠וֹ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠sáma֤kĕ ʼeţ-yád⁠wò֙ ʻal-rò֣ʼş̌ qárĕbá̇n֔⁠wò wĕ⁠şá̌ẖa֣t ʼòţ֔⁠wò li⁠pĕné֖y ʼò֣hel mwòʻé֑d wĕ֠⁠zárĕqẇ bĕ̇né֨y ʼahàrò֧n ʼeţ-dá̇m֛⁠wò ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[3,9,"וְ⁠הִקְרִ֨יב מִ⁠זֶּ֣בַח הַ⁠שְּׁלָמִים֮ אִשֶּׁ֣ה לַ⁠יהוָה֒ חֶלְבּ⁠וֹ֙ הָ⁠אַלְיָ֣ה תְמִימָ֔ה לְ⁠עֻמַּ֥ת הֶ⁠עָצֶ֖ה יְסִירֶ֑⁠נָּה וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ הַֽ⁠מְכַסֶּ֣ה אֶת־הַ⁠קֶּ֔רֶב וְ⁠אֵת֙ כָּל־הַ⁠חֵ֔לֶב אֲשֶׁ֖ר עַל־הַ⁠קֶּֽרֶב׃","wĕ⁠hiqĕri֨yb mi⁠zė֣baẖ ha⁠şĕ̇̌lámiym֮ ʼişė֣̌h la⁠yhwáh֒ ẖelĕḃ⁠wò֙ há⁠ʼalĕyá֣h ţĕmiymá֔h lĕ⁠ʻumȧ֥ţ he⁠ʻáẕe֖h yĕsiyre֑⁠ná̇h wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ haֽ⁠mĕkasė֣h ʼeţ-ha⁠qė֔reb wĕ⁠ʼéţ֙ ká̇l-ha⁠ẖé֔leb ʼàşě֖r ʻal-ha⁠qėֽreb׃"],[3,10,"וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵ⁠הֶ֔ן אֲשֶׁ֖ר עַל־הַ⁠כְּסָלִ֑ים וְ⁠אֶת־הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד עַל־הַ⁠כְּלָיֹ֖ת יְסִירֶֽ⁠נָּה׃","wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàlé⁠he֔n ʼàşě֖r ʻal-ha⁠kĕ̇sáli֑ym wĕ⁠ʼeţ-ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d ʻal-ha⁠kĕ̇láyò֖ţ yĕsiyreֽ⁠ná̇h׃"],[3,11,"וְ⁠הִקְטִיר֥⁠וֹ הַ⁠כֹּהֵ֖ן הַ⁠מִּזְבֵּ֑חָ⁠ה לֶ֥חֶם אִשֶּׁ֖ה לַ⁠יהוָֽה׃פ","wĕ⁠hiqĕtiyr֥⁠wò ha⁠kò̇hé֖n ha⁠mi̇zĕbé֑̇ẖá⁠h le֥ẖem ʼişė֖̌h la⁠yhwáֽh׃p"],[3,12,"וְ⁠אִ֥ם עֵ֖ז קָרְבָּנ֑⁠וֹ וְ⁠הִקְרִיב֖⁠וֹ לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠ʼi֥m ʻé֖z qárĕbá̇n֑⁠wò wĕ⁠hiqĕriyb֖⁠wò li⁠pĕné֥y yĕhwáֽh׃"],[3,13,"וְ⁠סָמַ֤ךְ אֶת־יָד⁠וֹ֙ עַל־רֹאשׁ֔⁠וֹ וְ⁠שָׁחַ֣ט אֹת֔⁠וֹ לִ⁠פְנֵ֖י אֹ֣הֶל מוֹעֵ֑ד וְ֠⁠זָרְקוּ בְּנֵ֨י אַהֲרֹ֧ן אֶת־דָּמ֛⁠וֹ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠sáma֤kĕ ʼeţ-yád⁠wò֙ ʻal-ròʼş̌֔⁠wò wĕ⁠şá̌ẖa֣t ʼòţ֔⁠wò li⁠pĕné֖y ʼò֣hel mwòʻé֑d wĕ֠⁠zárĕqẇ bĕ̇né֨y ʼahàrò֧n ʼeţ-dá̇m֛⁠wò ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[3,14,"וְ⁠הִקְרִ֤יב מִמֶּ֨⁠נּוּ֙ קָרְבָּנ֔⁠וֹ אִשֶּׁ֖ה לַֽ⁠יהוָ֑ה אֶת־הַ⁠חֵ֨לֶב֙ הַֽ⁠מְכַסֶּ֣ה אֶת־הַ⁠קֶּ֔רֶב וְ⁠אֵת֙ כָּל־הַ⁠חֵ֔לֶב אֲשֶׁ֖ר עַל־הַ⁠קֶּֽרֶב׃","wĕ⁠hiqĕri֤yb mimė֨⁠ṅẇ֙ qárĕbá̇n֔⁠wò ʼişė֖̌h laֽ⁠yhwá֑h ʼeţ-ha⁠ẖé֨leb֙ haֽ⁠mĕkasė֣h ʼeţ-ha⁠qė֔reb wĕ⁠ʼéţ֙ ká̇l-ha⁠ẖé֔leb ʼàşě֖r ʻal-ha⁠qėֽreb׃"],[3,15,"וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵ⁠הֶ֔ן אֲשֶׁ֖ר עַל־הַ⁠כְּסָלִ֑ים וְ⁠אֶת־הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד עַל־הַ⁠כְּלָיֹ֖ת יְסִירֶֽ⁠נָּה׃","wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàlé⁠he֔n ʼàşě֖r ʻal-ha⁠kĕ̇sáli֑ym wĕ⁠ʼeţ-ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d ʻal-ha⁠kĕ̇láyò֖ţ yĕsiyreֽ⁠ná̇h׃"],[3,16,"וְ⁠הִקְטִירָ֥⁠ם הַ⁠כֹּהֵ֖ן הַ⁠מִּזְבֵּ֑חָ⁠ה לֶ֤חֶם אִשֶּׁה֙ לְ⁠רֵ֣יחַ נִיחֹ֔חַ כָּל־חֵ֖לֶב לַ⁠יהוָֽה׃","wĕ⁠hiqĕtiyrá֥⁠m ha⁠kò̇hé֖n ha⁠mi̇zĕbé֑̇ẖá⁠h le֤ẖem ʼişė̌h֙ lĕ⁠ré֣yẖa niyẖò֔ẖa ká̇l-ẖé֖leb la⁠yhwáֽh׃"],[3,17,"חֻקַּ֤ת עוֹלָם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם בְּ⁠כֹ֖ל מֽוֹשְׁבֹתֵי⁠כֶ֑ם כָּל־חֵ֥לֶב וְ⁠כָל־דָּ֖ם לֹ֥א תֹאכֵֽלוּ׃פ","ẖuqȧ֤ţ ʻwòlám֙ lĕ⁠dòrò֣ţéy⁠ke֔m bĕ̇⁠kò֖l mֽwòşĕ̌bòţéy⁠ke֑m ká̇l-ẖé֥leb wĕ⁠kál-dá֖̇m lò֥ʼ ţòʼkéֽlẇ׃p"],[4,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[4,2,"דַּבֵּ֞ר אֶל־בְּנֵ֣י יִשְׂרָאֵ֘ל לֵ⁠אמֹר֒ נֶ֗פֶשׁ כִּֽי־תֶחֱטָ֤א בִ⁠שְׁגָגָה֙ מִ⁠כֹּל֙ מִצְוֺ֣ת יְהוָ֔ה אֲשֶׁ֖ר לֹ֣א תֵעָשֶׂ֑ינָה וְ⁠עָשָׂ֕ה מֵ⁠אַחַ֖ת מֵ⁠הֵֽנָּה׃","dȧbé̇֞r ʼel-bĕ̇né֣y yişĕ̂ráʼé֘l lé⁠ʼmòr֒ ne֗peş̌ kiֽ̇y-ţeẖètá֤ʼ bi⁠şĕ̌gágáh֙ mi⁠kò̇l֙ miẕĕwֺ֣ţ yĕhwá֔h ʼàşě֖r lò֣ʼ ţéʻáşê֑ynáh wĕ⁠ʻáşá̂֕h mé⁠ʼaẖa֖ţ mé⁠héֽná̇h׃"],[4,3,"אִ֣ם הַ⁠כֹּהֵ֧ן הַ⁠מָּשִׁ֛יחַ יֶחֱטָ֖א לְ⁠אַשְׁמַ֣ת הָ⁠עָ֑ם וְ⁠הִקְרִ֡יב עַ֣ל חַטָּאת⁠וֹ֩ אֲשֶׁ֨ר חָטָ֜א פַּ֣ר בֶּן־בָּקָ֥ר תָּמִ֛ים לַ⁠יהוָ֖ה לְ⁠חַטָּֽאת׃","ʼi֣m ha⁠kò̇hé֧n ha⁠má̇şǐ֛yẖa yeẖètá֖ʼ lĕ⁠ʼaşĕ̌ma֣ţ há⁠ʻá֑m wĕ⁠hiqĕri֡yb ʻa֣l ẖatá̇ʼţ⁠wò֩ ʼàşě֨r ẖátá֜ʼ pȧ֣r bėn-bá̇qá֥r ţá̇mi֛ym la⁠yhwá֖h lĕ⁠ẖatáֽ̇ʼţ׃"],[4,4,"וְ⁠הֵבִ֣יא אֶת־הַ⁠פָּ֗ר אֶל־פֶּ֛תַח אֹ֥הֶל מוֹעֵ֖ד לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠סָמַ֤ךְ אֶת־יָד⁠וֹ֙ עַל־רֹ֣אשׁ הַ⁠פָּ֔ר וְ⁠שָׁחַ֥ט אֶת־הַ⁠פָּ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠hébi֣yʼ ʼeţ-ha⁠pá̇֗r ʼel-pė֛ţaẖ ʼò֥hel mwòʻé֖d li⁠pĕné֣y yĕhwá֑h wĕ⁠sáma֤kĕ ʼeţ-yád⁠wò֙ ʻal-rò֣ʼş̌ ha⁠pá̇֔r wĕ⁠şá̌ẖa֥t ʼeţ-ha⁠pá֖̇r li⁠pĕné֥y yĕhwáֽh׃"],[4,5,"וְ⁠לָקַ֛ח הַ⁠כֹּהֵ֥ן הַ⁠מָּשִׁ֖יחַ מִ⁠דַּ֣ם הַ⁠פָּ֑ר וְ⁠הֵבִ֥יא אֹת֖⁠וֹ אֶל־אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠láqa֛ẖ ha⁠kò̇hé֥n ha⁠má̇şǐ֖yẖa mi⁠dȧ֣m ha⁠pá֑̇r wĕ⁠hébi֥yʼ ʼòţ֖⁠wò ʼel-ʼò֥hel mwòʻéֽd׃"],[4,6,"וְ⁠טָבַ֧ל הַ⁠כֹּהֵ֛ן אֶת־אֶצְבָּע֖⁠וֹ בַּ⁠דָּ֑ם וְ⁠הִזָּ֨ה מִן־הַ⁠דָּ֜ם שֶׁ֤בַע פְּעָמִים֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֶת־פְּנֵ֖י פָּרֹ֥כֶת הַ⁠קֹּֽדֶשׁ׃","wĕ⁠tába֧l ha⁠kò̇hé֛n ʼeţ-ʼeẕĕbá̇ʻ֖⁠wò bȧ⁠dá֑̇m wĕ⁠hizá̇֨h min-ha⁠dá̇֜m şě֤baʻ pĕ̇ʻámiym֙ li⁠pĕné֣y yĕhwá֔h ʼeţ-pĕ̇né֖y pá̇rò֥keţ ha⁠qòֽ̇deş̌׃"],[4,7,"וְ⁠נָתַן֩ הַ⁠כֹּהֵ֨ן מִן־הַ⁠דָּ֜ם עַל־קַ֠רְנוֹת מִזְבַּ֨ח קְטֹ֤רֶת הַ⁠סַּמִּים֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֲשֶׁ֖ר בְּ⁠אֹ֣הֶל מוֹעֵ֑ד וְ⁠אֵ֣ת ׀ כָּל־דַּ֣ם הַ⁠פָּ֗ר יִשְׁפֹּךְ֙ אֶל־יְסוֹד֙ מִזְבַּ֣ח הָ⁠עֹלָ֔ה אֲשֶׁר־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠náţan֩ ha⁠kò̇hé֨n min-ha⁠dá̇֜m ʻal-qa֠rĕnwòţ mizĕbȧ֨ẖ qĕtò֤reţ ha⁠sȧmi̇ym֙ li⁠pĕné֣y yĕhwá֔h ʼàşě֖r bĕ̇⁠ʼò֣hel mwòʻé֑d wĕ⁠ʼé֣ţ ׀ ká̇l-dȧ֣m ha⁠pá̇֗r yişĕ̌pò̇kĕ֙ ʼel-yĕswòd֙ mizĕbȧ֣ẖ há⁠ʻòlá֔h ʼàşěr-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[4,8,"וְ⁠אֶת־כָּל־חֵ֛לֶב פַּ֥ר הַֽ⁠חַטָּ֖את יָרִ֣ים מִמֶּ֑⁠נּוּ אֶת־הַ⁠חֵ֨לֶב֙ הַֽ⁠מְכַסֶּ֣ה עַל־הַ⁠קֶּ֔רֶב וְ⁠אֵת֙ כָּל־הַ⁠חֵ֔לֶב אֲשֶׁ֖ר עַל־הַ⁠קֶּֽרֶב׃","wĕ⁠ʼeţ-ká̇l-ẖé֛leb pȧ֥r haֽ⁠ẖatá֖̇ʼţ yári֣ym mimė֑⁠ṅẇ ʼeţ-ha⁠ẖé֨leb֙ haֽ⁠mĕkasė֣h ʻal-ha⁠qė֔reb wĕ⁠ʼéţ֙ ká̇l-ha⁠ẖé֔leb ʼàşě֖r ʻal-ha⁠qėֽreb׃"],[4,9,"וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵי⁠הֶ֔ן אֲשֶׁ֖ר עַל־הַ⁠כְּסָלִ֑ים וְ⁠אֶת־הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד עַל־הַ⁠כְּלָי֖וֹת יְסִירֶֽ⁠נָּה׃","wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàléy⁠he֔n ʼàşě֖r ʻal-ha⁠kĕ̇sáli֑ym wĕ⁠ʼeţ-ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d ʻal-ha⁠kĕ̇láy֖wòţ yĕsiyreֽ⁠ná̇h׃"],[4,10,"כַּ⁠אֲשֶׁ֣ר יוּרַ֔ם מִ⁠שּׁ֖וֹר זֶ֣בַח הַ⁠שְּׁלָמִ֑ים וְ⁠הִקְטִירָ⁠ם֙ הַ⁠כֹּהֵ֔ן עַ֖ל מִזְבַּ֥ח הָ⁠עֹלָֽה׃","kȧ⁠ʼàşě֣r yẇra֔m mi⁠ş֖̇̌wòr ze֣baẖ ha⁠şĕ̇̌lámi֑ym wĕ⁠hiqĕtiyrá⁠m֙ ha⁠kò̇hé֔n ʻa֖l mizĕbȧ֥ẖ há⁠ʻòláֽh׃"],[4,11,"וְ⁠אֶת־ע֤וֹר הַ⁠פָּר֙ וְ⁠אֶת־כָּל־בְּשָׂר֔⁠וֹ עַל־רֹאשׁ֖⁠וֹ וְ⁠עַל־כְּרָעָ֑י⁠ו וְ⁠קִרְבּ֖⁠וֹ וּ⁠פִרְשֽׁ⁠וֹ׃","wĕ⁠ʼeţ-ʻ֤wòr ha⁠pá̇r֙ wĕ⁠ʼeţ-ká̇l-bĕ̇şá̂r֔⁠wò ʻal-ròʼş֖̌⁠wò wĕ⁠ʻal-kĕ̇ráʻá֑y⁠w wĕ⁠qirĕḃ֖⁠wò ẇ⁠pirĕşֽ̌⁠wò׃"],[4,12,"וְ⁠הוֹצִ֣יא אֶת־כָּל־הַ֠⁠פָּר אֶל־מִ⁠ח֨וּץ לַֽ⁠מַּחֲנֶ֜ה אֶל־מָק֤וֹם טָהוֹר֙ אֶל־שֶׁ֣פֶךְ הַ⁠דֶּ֔שֶׁן וְ⁠שָׂרַ֥ף אֹת֛⁠וֹ עַל־עֵצִ֖ים בָּ⁠אֵ֑שׁ עַל־שֶׁ֥פֶךְ הַ⁠דֶּ֖שֶׁן יִשָּׂרֵֽף׃פ","wĕ⁠hwòẕi֣yʼ ʼeţ-ká̇l-ha֠⁠pá̇r ʼel-mi⁠ẖ֨ẇẕ laֽ⁠mȧẖàne֜h ʼel-máq֤wòm táhwòr֙ ʼel-şě֣pekĕ ha⁠dė֔şěn wĕ⁠şá̂ra֥p ʼòţ֛⁠wò ʻal-ʻéẕi֖ym bá̇⁠ʼé֑ş̌ ʻal-şě֥pekĕ ha⁠dė֖şěn yişá̇̂réֽp׃p"],[4,13,"וְ⁠אִ֨ם כָּל־עֲדַ֤ת יִשְׂרָאֵל֙ יִשְׁגּ֔וּ וְ⁠נֶעְלַ֣ם דָּבָ֔ר מֵ⁠עֵינֵ֖י הַ⁠קָּהָ֑ל וְ֠⁠עָשׂוּ אַחַ֨ת מִ⁠כָּל־מִצְוֺ֧ת יְהוָ֛ה אֲשֶׁ֥ר לֹא־תֵעָשֶׂ֖ינָה וְ⁠אָשֵֽׁמוּ׃","wĕ⁠ʼi֨m ká̇l-ʻàda֤ţ yişĕ̂ráʼél֙ yişĕ̌ġ֔ẇ wĕ⁠neʻĕla֣m dá̇bá֔r mé⁠ʻéyné֖y ha⁠qá̇há֑l wĕ֠⁠ʻáş̂ẇ ʼaẖa֨ţ mi⁠ká̇l-miẕĕwֺ֧ţ yĕhwá֛h ʼàşě֥r lòʼ-ţéʻáşê֖ynáh wĕ⁠ʼáşéֽ̌mẇ׃"],[4,14,"וְ⁠נֽוֹדְעָה֙ הַֽ⁠חַטָּ֔את אֲשֶׁ֥ר חָטְא֖וּ עָלֶ֑י⁠הָ וְ⁠הִקְרִ֨יבוּ הַ⁠קָּהָ֜ל פַּ֤ר בֶּן־בָּקָר֙ לְ⁠חַטָּ֔את וְ⁠הֵבִ֣יאוּ אֹת֔⁠וֹ לִ⁠פְנֵ֖י אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠nֽwòdĕʻáh֙ haֽ⁠ẖatá̇֔ʼţ ʼàşě֥r ẖátĕʼ֖ẇ ʻále֑y⁠há wĕ⁠hiqĕri֨ybẇ ha⁠qá̇há֜l pȧ֤r bėn-bá̇qár֙ lĕ⁠ẖatá̇֔ʼţ wĕ⁠hébi֣yʼẇ ʼòţ֔⁠wò li⁠pĕné֖y ʼò֥hel mwòʻéֽd׃"],[4,15,"וְ֠⁠סָמְכוּ זִקְנֵ֨י הָ⁠עֵדָ֧ה אֶת־יְדֵי⁠הֶ֛ם עַל־רֹ֥אשׁ הַ⁠פָּ֖ר לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠שָׁחַ֥ט אֶת־הַ⁠פָּ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ֠⁠sámĕkẇ ziqĕné֨y há⁠ʻédá֧h ʼeţ-yĕdéy⁠he֛m ʻal-rò֥ʼş̌ ha⁠pá֖̇r li⁠pĕné֣y yĕhwá֑h wĕ⁠şá̌ẖa֥t ʼeţ-ha⁠pá֖̇r li⁠pĕné֥y yĕhwáֽh׃"],[4,16,"וְ⁠הֵבִ֛יא הַ⁠כֹּהֵ֥ן הַ⁠מָּשִׁ֖יחַ מִ⁠דַּ֣ם הַ⁠פָּ֑ר אֶל־אֹ֖הֶל מוֹעֵֽד׃","wĕ⁠hébi֛yʼ ha⁠kò̇hé֥n ha⁠má̇şǐ֖yẖa mi⁠dȧ֣m ha⁠pá֑̇r ʼel-ʼò֖hel mwòʻéֽd׃"],[4,17,"וְ⁠טָבַ֧ל הַ⁠כֹּהֵ֛ן אֶצְבָּע֖⁠וֹ מִן־הַ⁠דָּ֑ם וְ⁠הִזָּ֞ה שֶׁ֤בַע פְּעָמִים֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֵ֖ת פְּנֵ֥י הַ⁠פָּרֹֽכֶת׃","wĕ⁠tába֧l ha⁠kò̇hé֛n ʼeẕĕbá̇ʻ֖⁠wò min-ha⁠dá֑̇m wĕ⁠hizá̇֞h şě֤baʻ pĕ̇ʻámiym֙ li⁠pĕné֣y yĕhwá֔h ʼé֖ţ pĕ̇né֥y ha⁠pá̇ròֽkeţ׃"],[4,18,"וּ⁠מִן־הַ⁠דָּ֞ם יִתֵּ֣ן ׀ עַל־קַרְנֹ֣ת הַ⁠מִּזְבֵּ֗חַ אֲשֶׁר֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֲשֶׁ֖ר בְּ⁠אֹ֣הֶל מוֹעֵ֑ד וְ⁠אֵ֣ת כָּל־הַ⁠דָּ֗ם יִשְׁפֹּךְ֙ אֶל־יְסוֹד֙ מִזְבַּ֣ח הָ⁠עֹלָ֔ה אֲשֶׁר־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","ẇ⁠min-ha⁠dá̇֞m yiţé֣̇n ׀ ʻal-qarĕnò֣ţ ha⁠mi̇zĕbé̇֗ẖa ʼàşěr֙ li⁠pĕné֣y yĕhwá֔h ʼàşě֖r bĕ̇⁠ʼò֣hel mwòʻé֑d wĕ⁠ʼé֣ţ ká̇l-ha⁠dá̇֗m yişĕ̌pò̇kĕ֙ ʼel-yĕswòd֙ mizĕbȧ֣ẖ há⁠ʻòlá֔h ʼàşěr-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[4,19,"וְ⁠אֵ֥ת כָּל־חֶלְבּ֖⁠וֹ יָרִ֣ים מִמֶּ֑⁠נּוּ וְ⁠הִקְטִ֖יר הַ⁠מִּזְבֵּֽחָ⁠ה׃","wĕ⁠ʼé֥ţ ká̇l-ẖelĕḃ֖⁠wò yári֣ym mimė֑⁠ṅẇ wĕ⁠hiqĕti֖yr ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[4,20,"וְ⁠עָשָׂ֣ה לַ⁠פָּ֔ר כַּ⁠אֲשֶׁ֤ר עָשָׂה֙ לְ⁠פַ֣ר הַֽ⁠חַטָּ֔את כֵּ֖ן יַעֲשֶׂה־לּ֑⁠וֹ וְ⁠כִפֶּ֧ר עֲלֵ⁠הֶ֛ם הַ⁠כֹּהֵ֖ן וְ⁠נִסְלַ֥ח לָ⁠הֶֽם׃","wĕ⁠ʻáşá֣̂h la⁠pá̇֔r kȧ⁠ʼàşě֤r ʻáşá̂h֙ lĕ⁠pa֣r haֽ⁠ẖatá̇֔ʼţ ké֖̇n yaʻàşêh-l֑̇⁠wò wĕ⁠kipė֧r ʻàlé⁠he֛m ha⁠kò̇hé֖n wĕ⁠nisĕla֥ẖ lá⁠heֽm׃"],[4,21,"וְ⁠הוֹצִ֣יא אֶת־הַ⁠פָּ֗ר אֶל־מִ⁠חוּץ֙ לַֽ⁠מַּחֲנֶ֔ה וְ⁠שָׂרַ֣ף אֹת֔⁠וֹ כַּ⁠אֲשֶׁ֣ר שָׂרַ֔ף אֵ֖ת הַ⁠פָּ֣ר הָ⁠רִאשׁ֑וֹן חַטַּ֥את הַ⁠קָּהָ֖ל הֽוּא׃פ","wĕ⁠hwòẕi֣yʼ ʼeţ-ha⁠pá̇֗r ʼel-mi⁠ẖẇẕ֙ laֽ⁠mȧẖàne֔h wĕ⁠şá̂ra֣p ʼòţ֔⁠wò kȧ⁠ʼàşě֣r şá̂ra֔p ʼé֖ţ ha⁠pá֣̇r há⁠riʼş֑̌wòn ẖatȧ֥ʼţ ha⁠qá̇há֖l hֽẇʼ׃p"],[4,22,"אֲשֶׁ֥ר נָשִׂ֖יא יֶֽחֱטָ֑א וְ⁠עָשָׂ֡ה אַחַ֣ת מִ⁠כָּל־מִצְוֺת֩ יְהוָ֨ה אֱלֹהָ֜י⁠ו אֲשֶׁ֧ר לֹא־תֵעָשֶׂ֛ינָה בִּ⁠שְׁגָגָ֖ה וְ⁠אָשֵֽׁם׃","ʼàşě֥r náşî֖yʼ yeֽẖètá֑ʼ wĕ⁠ʻáşá̂֡h ʼaẖa֣ţ mi⁠ká̇l-miẕĕwֺţ֩ yĕhwá֨h ʼèlòhá֜y⁠w ʼàşě֧r lòʼ-ţéʻáşê֛ynáh bi̇⁠şĕ̌gágá֖h wĕ⁠ʼáşéֽ̌m׃"],[4,23,"אֽוֹ־הוֹדַ֤ע אֵלָי⁠ו֙ חַטָּאת֔⁠וֹ אֲשֶׁ֥ר חָטָ֖א בָּ֑⁠הּ וְ⁠הֵבִ֧יא אֶת־קָרְבָּנ֛⁠וֹ שְׂעִ֥יר עִזִּ֖ים זָכָ֥ר תָּמִֽים׃","ʼֽwò-hwòda֤ʻ ʼéláy⁠w֙ ẖatá̇ʼţ֔⁠wò ʼàşě֥r ẖátá֖ʼ bá֑̇⁠ḣ wĕ⁠hébi֧yʼ ʼeţ-qárĕbá̇n֛⁠wò şĕ̂ʻi֥yr ʻizi֖̇ym záká֥r ţá̇miֽym׃"],[4,24,"וְ⁠סָמַ֤ךְ יָד⁠וֹ֙ עַל־רֹ֣אשׁ הַ⁠שָּׂעִ֔יר וְ⁠שָׁחַ֣ט אֹת֔⁠וֹ בִּ⁠מְק֛וֹם אֲשֶׁר־יִשְׁחַ֥ט אֶת־הָ⁠עֹלָ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה חַטָּ֖את הֽוּא׃","wĕ⁠sáma֤kĕ yád⁠wò֙ ʻal-rò֣ʼş̌ ha⁠şá̇̂ʻi֔yr wĕ⁠şá̌ẖa֣t ʼòţ֔⁠wò bi̇⁠mĕq֛wòm ʼàşěr-yişĕ̌ẖa֥t ʼeţ-há⁠ʻòlá֖h li⁠pĕné֣y yĕhwá֑h ẖatá֖̇ʼţ hֽẇʼ׃"],[4,25,"וְ⁠לָקַ֨ח הַ⁠כֹּהֵ֜ן מִ⁠דַּ֤ם הַֽ⁠חַטָּאת֙ בְּ⁠אֶצְבָּע֔⁠וֹ וְ⁠נָתַ֕ן עַל־קַרְנֹ֖ת מִזְבַּ֣ח הָ⁠עֹלָ֑ה וְ⁠אֶת־דָּמ֣⁠וֹ יִשְׁפֹּ֔ךְ אֶל־יְס֖וֹד מִזְבַּ֥ח הָ⁠עֹלָֽה׃","wĕ⁠láqa֨ẖ ha⁠kò̇hé֜n mi⁠dȧ֤m haֽ⁠ẖatá̇ʼţ֙ bĕ̇⁠ʼeẕĕbá̇ʻ֔⁠wò wĕ⁠náţa֕n ʻal-qarĕnò֖ţ mizĕbȧ֣ẖ há⁠ʻòlá֑h wĕ⁠ʼeţ-dá̇m֣⁠wò yişĕ̌pò̇֔kĕ ʼel-yĕs֖wòd mizĕbȧ֥ẖ há⁠ʻòláֽh׃"],[4,26,"וְ⁠אֶת־כָּל־חֶלְבּ⁠וֹ֙ יַקְטִ֣יר הַ⁠מִּזְבֵּ֔חָ⁠ה כְּ⁠חֵ֖לֶב זֶ֣בַח הַ⁠שְּׁלָמִ֑ים וְ⁠כִפֶּ֨ר עָלָ֧י⁠ו הַ⁠כֹּהֵ֛ן מֵ⁠חַטָּאת֖⁠וֹ וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃פ","wĕ⁠ʼeţ-ká̇l-ẖelĕḃ⁠wò֙ yaqĕti֣yr ha⁠mi̇zĕbé̇֔ẖá⁠h kĕ̇⁠ẖé֖leb ze֣baẖ ha⁠şĕ̇̌lámi֑ym wĕ⁠kipė֨r ʻálá֧y⁠w ha⁠kò̇hé֛n mé⁠ẖatá̇ʼţ֖⁠wò wĕ⁠nisĕla֥ẖ lֽ⁠wò׃p"],[4,27,"וְ⁠אִם־נֶ֧פֶשׁ אַחַ֛ת תֶּחֱטָ֥א בִ⁠שְׁגָגָ֖ה מֵ⁠עַ֣ם הָ⁠אָ֑רֶץ בַּ֠⁠עֲשֹׂתָ⁠הּ אַחַ֨ת מִ⁠מִּצְוֺ֧ת יְהוָ֛ה אֲשֶׁ֥ר לֹא־תֵעָשֶׂ֖ינָה וְ⁠אָשֵֽׁם׃","wĕ⁠ʼim-ne֧peş̌ ʼaẖa֛ţ ţėẖètá֥ʼ bi⁠şĕ̌gágá֖h mé⁠ʻa֣m há⁠ʼá֑reẕ bȧ֠⁠ʻàşò̂ţá⁠ḣ ʼaẖa֨ţ mi⁠mi̇ẕĕwֺ֧ţ yĕhwá֛h ʼàşě֥r lòʼ-ţéʻáşê֖ynáh wĕ⁠ʼáşéֽ̌m׃"],[4,28,"א֚וֹ הוֹדַ֣ע אֵלָ֔י⁠ו חַטָּאת֖⁠וֹ אֲשֶׁ֣ר חָטָ֑א וְ⁠הֵבִ֨יא קָרְבָּנ֜⁠וֹ שְׂעִירַ֤ת עִזִּים֙ תְּמִימָ֣ה נְקֵבָ֔ה עַל־חַטָּאת֖⁠וֹ אֲשֶׁ֥ר חָטָֽא׃","ʼ֚wò hwòda֣ʻ ʼélá֔y⁠w ẖatá̇ʼţ֖⁠wò ʼàşě֣r ẖátá֑ʼ wĕ⁠hébi֨yʼ qárĕbá̇n֜⁠wò şĕ̂ʻiyra֤ţ ʻizi̇ym֙ ţĕ̇miymá֣h nĕqébá֔h ʻal-ẖatá̇ʼţ֖⁠wò ʼàşě֥r ẖátáֽʼ׃"],[4,29,"וְ⁠סָמַךְ֙ אֶת־יָד֔⁠וֹ עַ֖ל רֹ֣אשׁ הַֽ⁠חַטָּ֑את וְ⁠שָׁחַט֙ אֶת־הַ֣⁠חַטָּ֔את בִּ⁠מְק֖וֹם הָ⁠עֹלָֽה׃","wĕ⁠sámakĕ֙ ʼeţ-yád֔⁠wò ʻa֖l rò֣ʼş̌ haֽ⁠ẖatá֑̇ʼţ wĕ⁠şá̌ẖat֙ ʼeţ-ha֣⁠ẖatá̇֔ʼţ bi̇⁠mĕq֖wòm há⁠ʻòláֽh׃"],[4,30,"וְ⁠לָקַ֨ח הַ⁠כֹּהֵ֤ן מִ⁠דָּמָ⁠הּ֙ בְּ⁠אֶצְבָּע֔⁠וֹ וְ⁠נָתַ֕ן עַל־קַרְנֹ֖ת מִזְבַּ֣ח הָ⁠עֹלָ֑ה וְ⁠אֶת־כָּל־דָּמָ֣⁠הּ יִשְׁפֹּ֔ךְ אֶל־יְס֖וֹד הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠láqa֨ẖ ha⁠kò̇hé֤n mi⁠dá̇má⁠ḣ֙ bĕ̇⁠ʼeẕĕbá̇ʻ֔⁠wò wĕ⁠náţa֕n ʻal-qarĕnò֖ţ mizĕbȧ֣ẖ há⁠ʻòlá֑h wĕ⁠ʼeţ-ká̇l-dá̇má֣⁠ḣ yişĕ̌pò̇֔kĕ ʼel-yĕs֖wòd ha⁠mi̇zĕbéֽ̇ẖa׃"],[4,31,"וְ⁠אֶת־כָּל־חֶלְבָּ֣⁠הּ יָסִ֗יר כַּ⁠אֲשֶׁ֨ר הוּסַ֣ר חֵלֶב֮ מֵ⁠עַ֣ל זֶ֣בַח הַ⁠שְּׁלָמִים֒ וְ⁠הִקְטִ֤יר הַ⁠כֹּהֵן֙ הַ⁠מִּזְבֵּ֔חָ⁠ה לְ⁠רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָ֑ה וְ⁠כִפֶּ֥ר עָלָ֛י⁠ו הַ⁠כֹּהֵ֖ן וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃פ","wĕ⁠ʼeţ-ká̇l-ẖelĕbá֣̇⁠ḣ yási֗yr kȧ⁠ʼàşě֨r hẇsa֣r ẖéleb֮ mé⁠ʻa֣l ze֣baẖ ha⁠şĕ̇̌lámiym֒ wĕ⁠hiqĕti֤yr ha⁠kò̇hén֙ ha⁠mi̇zĕbé̇֔ẖá⁠h lĕ⁠ré֥yẖa niyẖò֖ẖa la⁠yhwá֑h wĕ⁠kipė֥r ʻálá֛y⁠w ha⁠kò̇hé֖n wĕ⁠nisĕla֥ẖ lֽ⁠wò׃p"],[4,32,"וְ⁠אִם־כֶּ֛בֶשׂ יָבִ֥יא קָרְבָּנ֖⁠וֹ לְ⁠חַטָּ֑את נְקֵבָ֥ה תְמִימָ֖ה יְבִיאֶֽ⁠נָּה׃","wĕ⁠ʼim-kė֛beş̂ yábi֥yʼ qárĕbá̇n֖⁠wò lĕ⁠ẖatá֑̇ʼţ nĕqébá֥h ţĕmiymá֖h yĕbiyʼeֽ⁠ná̇h׃"],[4,33,"וְ⁠סָמַךְ֙ אֶת־יָד֔⁠וֹ עַ֖ל רֹ֣אשׁ הַֽ⁠חַטָּ֑את וְ⁠שָׁחַ֤ט אֹתָ⁠הּ֙ לְ⁠חַטָּ֔את בִּ⁠מְק֕וֹם אֲשֶׁ֥ר יִשְׁחַ֖ט אֶת־הָ⁠עֹלָֽה׃","wĕ⁠sámakĕ֙ ʼeţ-yád֔⁠wò ʻa֖l rò֣ʼş̌ haֽ⁠ẖatá֑̇ʼţ wĕ⁠şá̌ẖa֤t ʼòţá⁠ḣ֙ lĕ⁠ẖatá̇֔ʼţ bi̇⁠mĕq֕wòm ʼàşě֥r yişĕ̌ẖa֖t ʼeţ-há⁠ʻòláֽh׃"],[4,34,"וְ⁠לָקַ֨ח הַ⁠כֹּהֵ֜ן מִ⁠דַּ֤ם הַֽ⁠חַטָּאת֙ בְּ⁠אֶצְבָּע֔⁠וֹ וְ⁠נָתַ֕ן עַל־קַרְנֹ֖ת מִזְבַּ֣ח הָ⁠עֹלָ֑ה וְ⁠אֶת־כָּל־דָּמָ֣⁠הּ יִשְׁפֹּ֔ךְ אֶל־יְס֖וֹד הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠láqa֨ẖ ha⁠kò̇hé֜n mi⁠dȧ֤m haֽ⁠ẖatá̇ʼţ֙ bĕ̇⁠ʼeẕĕbá̇ʻ֔⁠wò wĕ⁠náţa֕n ʻal-qarĕnò֖ţ mizĕbȧ֣ẖ há⁠ʻòlá֑h wĕ⁠ʼeţ-ká̇l-dá̇má֣⁠ḣ yişĕ̌pò̇֔kĕ ʼel-yĕs֖wòd ha⁠mi̇zĕbéֽ̇ẖa׃"],[4,35,"וְ⁠אֶת־כָּל־חֶלְבָּ֣⁠ה יָסִ֗יר כַּ⁠אֲשֶׁ֨ר יוּסַ֥ר חֵֽלֶב־הַ⁠כֶּשֶׂב֮ מִ⁠זֶּ֣בַח הַ⁠שְּׁלָמִים֒ וְ⁠הִקְטִ֨יר הַ⁠כֹּהֵ֤ן אֹתָ⁠ם֙ הַ⁠מִּזְבֵּ֔חָ⁠ה עַ֖ל אִשֵּׁ֣י יְהוָ֑ה וְ⁠כִפֶּ֨ר עָלָ֧י⁠ו הַ⁠כֹּהֵ֛ן עַל־חַטָּאת֥⁠וֹ אֲשֶׁר־חָטָ֖א וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃פ","wĕ⁠ʼeţ-ká̇l-ẖelĕbá֣̇⁠h yási֗yr kȧ⁠ʼàşě֨r yẇsa֥r ẖéֽleb-ha⁠kėşêb֮ mi⁠zė֣baẖ ha⁠şĕ̇̌lámiym֒ wĕ⁠hiqĕti֨yr ha⁠kò̇hé֤n ʼòţá⁠m֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʻa֖l ʼişé֣̇̌y yĕhwá֑h wĕ⁠kipė֨r ʻálá֧y⁠w ha⁠kò̇hé֛n ʻal-ẖatá̇ʼţ֥⁠wò ʼàşěr-ẖátá֖ʼ wĕ⁠nisĕla֥ẖ lֽ⁠wò׃p"],[5,1,"וְ⁠נֶ֣פֶשׁ כִּֽי־תֶחֱטָ֗א וְ⁠שָֽׁמְעָה֙ ק֣וֹל אָלָ֔ה וְ⁠ה֣וּא עֵ֔ד א֥וֹ רָאָ֖ה א֣וֹ יָדָ֑ע אִם־ל֥וֹא יַגִּ֖יד וְ⁠נָשָׂ֥א עֲוֺנֽ⁠וֹ׃","wĕ⁠ne֣peş̌ kiֽ̇y-ţeẖètá֗ʼ wĕ⁠şáֽ̌mĕʻáh֙ q֣wòl ʼálá֔h wĕ⁠h֣ẇʼ ʻé֔d ʼ֥wò ráʼá֖h ʼ֣wò yádá֑ʻ ʼim-l֥wòʼ yagi֖̇yd wĕ⁠náşá֥̂ʼ ʻàwֺnֽ⁠wò׃"],[5,2,"א֣וֹ נֶ֗פֶשׁ אֲשֶׁ֣ר תִּגַּע֮ בְּ⁠כָל־דָּבָ֣ר טָמֵא֒ אוֹ֩ בְ⁠נִבְלַ֨ת חַיָּ֜ה טְמֵאָ֗ה א֤וֹ בְּ⁠נִבְלַת֙ בְּהֵמָ֣ה טְמֵאָ֔ה א֕וֹ בְּ⁠נִבְלַ֖ת שֶׁ֣רֶץ טָמֵ֑א וְ⁠נֶעְלַ֣ם מִמֶּ֔⁠נּוּ וְ⁠ה֥וּא טָמֵ֖א וְ⁠אָשֵֽׁם׃","ʼ֣wò ne֗peş̌ ʼàşě֣r ţi̇gȧʻ֮ bĕ̇⁠kál-dá̇bá֣r táméʼ֒ ʼwò֩ bĕ⁠nibĕla֨ţ ẖayá̇֜h tĕméʼá֗h ʼ֤wò bĕ̇⁠nibĕlaţ֙ bĕ̇hémá֣h tĕméʼá֔h ʼ֕wò bĕ̇⁠nibĕla֖ţ şě֣reẕ támé֑ʼ wĕ⁠neʻĕla֣m mimė֔⁠ṅẇ wĕ⁠h֥ẇʼ támé֖ʼ wĕ⁠ʼáşéֽ̌m׃"],[5,3,"א֣וֹ כִ֤י יִגַּע֙ בְּ⁠טֻמְאַ֣ת אָדָ֔ם לְ⁠כֹל֙ טֻמְאָת֔⁠וֹ אֲשֶׁ֥ר יִטְמָ֖א בָּ֑⁠הּ וְ⁠נֶעְלַ֣ם מִמֶּ֔⁠נּוּ וְ⁠ה֥וּא יָדַ֖ע וְ⁠אָשֵֽׁם׃","ʼ֣wò ki֤y yigȧʻ֙ bĕ̇⁠tumĕʼa֣ţ ʼádá֔m lĕ⁠kòl֙ tumĕʼáţ֔⁠wò ʼàşě֥r yitĕmá֖ʼ bá֑̇⁠ḣ wĕ⁠neʻĕla֣m mimė֔⁠ṅẇ wĕ⁠h֥ẇʼ yáda֖ʻ wĕ⁠ʼáşéֽ̌m׃"],[5,4,"א֣וֹ נֶ֡פֶשׁ כִּ֣י תִשָּׁבַע֩ לְ⁠בַטֵּ֨א בִ⁠שְׂפָתַ֜יִם לְ⁠הָרַ֣ע ׀ א֣וֹ לְ⁠הֵיטִ֗יב לְ֠⁠כֹל אֲשֶׁ֨ר יְבַטֵּ֧א הָ⁠אָדָ֛ם בִּ⁠שְׁבֻעָ֖ה וְ⁠נֶעְלַ֣ם מִמֶּ֑⁠נּוּ וְ⁠הוּא־יָדַ֥ע וְ⁠אָשֵׁ֖ם לְ⁠אַחַ֥ת מֵ⁠אֵֽלֶּה׃","ʼ֣wò ne֡peş̌ ki֣̇y ţişá̇̌baʻ֩ lĕ⁠baté̇֨ʼ bi⁠şĕ̂páţa֜yim lĕ⁠hára֣ʻ ׀ ʼ֣wò lĕ⁠héyti֗yb lĕ֠⁠kòl ʼàşě֨r yĕbaté֧̇ʼ há⁠ʼádá֛m bi̇⁠şĕ̌buʻá֖h wĕ⁠neʻĕla֣m mimė֑⁠ṅẇ wĕ⁠hẇʼ-yáda֥ʻ wĕ⁠ʼáşé֖̌m lĕ⁠ʼaẖa֥ţ mé⁠ʼéֽlėh׃"],[5,5,"וְ⁠הָיָ֥ה כִֽי־יֶאְשַׁ֖ם לְ⁠אַחַ֣ת מֵ⁠אֵ֑לֶּה וְ⁠הִ֨תְוַדָּ֔ה אֲשֶׁ֥ר חָטָ֖א עָלֶֽי⁠הָ׃","wĕ⁠háyá֥h kiֽy-yeʼĕşǎ֖m lĕ⁠ʼaẖa֣ţ mé⁠ʼé֑lėh wĕ⁠hi֨ţĕwadá̇֔h ʼàşě֥r ẖátá֖ʼ ʻáleֽy⁠há׃"],[5,6,"וְ⁠הֵבִ֣יא אֶת־אֲשָׁמ֣⁠וֹ לַ⁠יהוָ֡ה עַ֣ל חַטָּאת⁠וֹ֩ אֲשֶׁ֨ר חָטָ֜א נְקֵבָ֨ה מִן־הַ⁠צֹּ֥אן כִּשְׂבָּ֛ה אֽוֹ־שְׂעִירַ֥ת עִזִּ֖ים לְ⁠חַטָּ֑את וְ⁠כִפֶּ֥ר עָלָ֛י⁠ו הַ⁠כֹּהֵ֖ן מֵ⁠חַטָּאתֽ⁠וֹ׃","wĕ⁠hébi֣yʼ ʼeţ-ʼàşá̌m֣⁠wò la⁠yhwá֡h ʻa֣l ẖatá̇ʼţ⁠wò֩ ʼàşě֨r ẖátá֜ʼ nĕqébá֨h min-ha⁠ẕò֥̇ʼn ki̇şĕ̂bá֛̇h ʼֽwò-şĕ̂ʻiyra֥ţ ʻizi֖̇ym lĕ⁠ẖatá֑̇ʼţ wĕ⁠kipė֥r ʻálá֛y⁠w ha⁠kò̇hé֖n mé⁠ẖatá̇ʼţֽ⁠wò׃"],[5,7,"וְ⁠אִם־לֹ֨א תַגִּ֣יע יָד⁠וֹ֮ דֵּ֣י שֶׂה֒ וְ⁠הֵבִ֨יא אֶת־אֲשָׁמ֜⁠וֹ אֲשֶׁ֣ר חָטָ֗א שְׁתֵּ֥י תֹרִ֛ים אֽוֹ־שְׁנֵ֥י בְנֵֽי־יוֹנָ֖ה לַֽ⁠יהוָ֑ה אֶחָ֥ד לְ⁠חַטָּ֖את וְ⁠אֶחָ֥ד לְ⁠עֹלָֽה׃","wĕ⁠ʼim-lò֨ʼ ţagi֣̇yʻ yád⁠wò֮ dé֣̇y şêh֒ wĕ⁠hébi֨yʼ ʼeţ-ʼàşá̌m֜⁠wò ʼàşě֣r ẖátá֗ʼ şĕ̌ţé֥̇y ţòri֛ym ʼֽwò-şĕ̌né֥y bĕnéֽy-ywòná֖h laֽ⁠yhwá֑h ʼeẖá֥d lĕ⁠ẖatá֖̇ʼţ wĕ⁠ʼeẖá֥d lĕ⁠ʻòláֽh׃"],[5,8,"וְ⁠הֵבִ֤יא אֹתָ⁠ם֙ אֶל־הַ⁠כֹּהֵ֔ן וְ⁠הִקְרִ֛יב אֶת־אֲשֶׁ֥ר לַ⁠חַטָּ֖את רִאשׁוֹנָ֑ה וּ⁠מָלַ֧ק אֶת־רֹאשׁ֛⁠וֹ מִ⁠מּ֥וּל עָרְפּ֖⁠וֹ וְ⁠לֹ֥א יַבְדִּֽיל׃","wĕ⁠hébi֤yʼ ʼòţá⁠m֙ ʼel-ha⁠kò̇hé֔n wĕ⁠hiqĕri֛yb ʼeţ-ʼàşě֥r la⁠ẖatá֖̇ʼţ riʼş̌wòná֑h ẇ⁠mála֧q ʼeţ-ròʼş֛̌⁠wò mi⁠ṁ֥ẇl ʻárĕṗ֖⁠wò wĕ⁠lò֥ʼ yabĕdiֽ̇yl׃"],[5,9,"וְ⁠הִזָּ֞ה מִ⁠דַּ֤ם הַ⁠חַטָּאת֙ עַל־קִ֣יר הַ⁠מִּזְבֵּ֔חַ וְ⁠הַ⁠נִּשְׁאָ֣ר בַּ⁠דָּ֔ם יִמָּצֵ֖ה אֶל־יְס֣וֹד הַ⁠מִּזְבֵּ֑חַ חַטָּ֖את הֽוּא׃","wĕ⁠hizá̇֞h mi⁠dȧ֤m ha⁠ẖatá̇ʼţ֙ ʻal-qi֣yr ha⁠mi̇zĕbé̇֔ẖa wĕ⁠ha⁠ni̇şĕ̌ʼá֣r bȧ⁠dá̇֔m yimá̇ẕé֖h ʼel-yĕs֣wòd ha⁠mi̇zĕbé֑̇ẖa ẖatá֖̇ʼţ hֽẇʼ׃"],[5,10,"וְ⁠אֶת־הַ⁠שֵּׁנִ֛י יַעֲשֶׂ֥ה עֹלָ֖ה כַּ⁠מִּשְׁפָּ֑ט וְ⁠כִפֶּ֨ר עָלָ֧י⁠ו הַ⁠כֹּהֵ֛ן מֵ⁠חַטָּאת֥⁠וֹ אֲשֶׁר־חָטָ֖א וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃ס","wĕ⁠ʼeţ-ha⁠şé̇̌ni֛y yaʻàşê֥h ʻòlá֖h kȧ⁠mi̇şĕ̌pá֑̇t wĕ⁠kipė֨r ʻálá֧y⁠w ha⁠kò̇hé֛n mé⁠ẖatá̇ʼţ֥⁠wò ʼàşěr-ẖátá֖ʼ wĕ⁠nisĕla֥ẖ lֽ⁠wò׃s"],[5,11,"וְ⁠אִם־לֹא֩ תַשִּׂ֨יג יָד֜⁠וֹ לִ⁠שְׁתֵּ֣י תֹרִ֗ים אוֹ֮ לִ⁠שְׁנֵ֣י בְנֵי־יוֹנָה֒ וְ⁠הֵבִ֨יא אֶת־קָרְבָּנ֜⁠וֹ אֲשֶׁ֣ר חָטָ֗א עֲשִׂירִ֧ת הָ⁠אֵפָ֛ה סֹ֖לֶת לְ⁠חַטָּ֑את לֹא־יָשִׂ֨ים עָלֶ֜י⁠הָ שֶׁ֗מֶן וְ⁠לֹא־יִתֵּ֤ן עָלֶ֨י⁠הָ֙ לְבֹנָ֔ה כִּ֥י חַטָּ֖את הִֽיא׃","wĕ⁠ʼim-lòʼ֩ ţaşi̇̂֨yg yád֜⁠wò li⁠şĕ̌ţé֣̇y ţòri֗ym ʼwò֮ li⁠şĕ̌né֣y bĕnéy-ywònáh֒ wĕ⁠hébi֨yʼ ʼeţ-qárĕbá̇n֜⁠wò ʼàşě֣r ẖátá֗ʼ ʻàşîyri֧ţ há⁠ʼépá֛h sò֖leţ lĕ⁠ẖatá֑̇ʼţ lòʼ-yáşî֨ym ʻále֜y⁠há şě֗men wĕ⁠lòʼ-yiţé֤̇n ʻále֨y⁠há֙ lĕbòná֔h ki֥̇y ẖatá֖̇ʼţ hiֽyʼ׃"],[5,12,"וֶ⁠הֱבִיאָ⁠הּ֮ אֶל־הַ⁠כֹּהֵן֒ וְ⁠קָמַ֣ץ הַ⁠כֹּהֵ֣ן ׀ מִ֠מֶּ⁠נָּה מְל֨וֹא קֻמְצ֜⁠וֹ אֶת־אַזְכָּרָתָ⁠ה֙ וְ⁠הִקְטִ֣יר הַ⁠מִּזְבֵּ֔חָ⁠ה עַ֖ל אִשֵּׁ֣י יְהוָ֑ה חַטָּ֖את הִֽוא׃","we⁠hèbiyʼá⁠ḣ֮ ʼel-ha⁠kò̇hén֒ wĕ⁠qáma֣ẕ ha⁠kò̇hé֣n ׀ mi֠mė⁠ná̇h mĕl֨wòʼ qumĕẕ֜⁠wò ʼeţ-ʼazĕká̇ráţá⁠h֙ wĕ⁠hiqĕti֣yr ha⁠mi̇zĕbé̇֔ẖá⁠h ʻa֖l ʼişé֣̇̌y yĕhwá֑h ẖatá֖̇ʼţ hiֽwʼ׃"],[5,13,"וְ⁠כִפֶּר֩ עָלָ֨י⁠ו הַ⁠כֹּהֵ֜ן עַל־חַטָּאת֧⁠וֹ אֲשֶׁר־חָטָ֛א מֵֽ⁠אַחַ֥ת מֵ⁠אֵ֖לֶּה וְ⁠נִסְלַ֣ח ל֑⁠וֹ וְ⁠הָיְתָ֥ה לַ⁠כֹּהֵ֖ן כַּ⁠מִּנְחָֽה׃ס","wĕ⁠kipėr֩ ʻálá֨y⁠w ha⁠kò̇hé֜n ʻal-ẖatá̇ʼţ֧⁠wò ʼàşěr-ẖátá֛ʼ méֽ⁠ʼaẖa֥ţ mé⁠ʼé֖lėh wĕ⁠nisĕla֣ẖ l֑⁠wò wĕ⁠háyĕţá֥h la⁠kò̇hé֖n kȧ⁠mi̇nĕẖáֽh׃s"],[5,14,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[5,15,"נֶ֚פֶשׁ כִּֽי־תִמְעֹ֣ל מַ֔עַל וְ⁠חָֽטְאָה֙ בִּ⁠שְׁגָגָ֔ה מִ⁠קָּדְשֵׁ֖י יְהוָ֑ה וְ⁠הֵבִיא֩ אֶת־אֲשָׁמ֨⁠וֹ לַֽ⁠יהוָ֜ה אַ֧יִל תָּמִ֣ים מִן־הַ⁠צֹּ֗אן בְּ⁠עֶרְכְּ⁠ךָ֛ כֶּֽסֶף־שְׁקָלִ֥ים בְּ⁠שֶֽׁקֶל־הַ⁠קֹּ֖דֶשׁ לְ⁠אָשָֽׁם׃","ne֚peş̌ kiֽ̇y-ţimĕʻò֣l ma֔ʻal wĕ⁠ẖáֽtĕʼáh֙ bi̇⁠şĕ̌gágá֔h mi⁠qá̇dĕşé֖̌y yĕhwá֑h wĕ⁠hébiyʼ֩ ʼeţ-ʼàşá̌m֨⁠wò laֽ⁠yhwá֜h ʼa֧yil ţá̇mi֣ym min-ha⁠ẕò̇֗ʼn bĕ̇⁠ʻerĕkĕ̇⁠ká֛ kėֽsep-şĕ̌qáli֥ym bĕ̇⁠şěֽqel-ha⁠qò֖̇deş̌ lĕ⁠ʼáşáֽ̌m׃"],[5,16,"וְ⁠אֵ֣ת אֲשֶׁר֩ חָטָ֨א מִן־הַ⁠קֹּ֜דֶשׁ יְשַׁלֵּ֗ם וְ⁠אֶת־חֲמִֽישִׁת⁠וֹ֙ יוֹסֵ֣ף עָלָ֔י⁠ו וְ⁠נָתַ֥ן אֹת֖⁠וֹ לַ⁠כֹּהֵ֑ן וְ⁠הַ⁠כֹּהֵ֗ן יְכַפֵּ֥ר עָלָ֛י⁠ו בְּ⁠אֵ֥יל הָ⁠אָשָׁ֖ם וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃פ","wĕ⁠ʼé֣ţ ʼàşěr֩ ẖátá֨ʼ min-ha⁠qò̇֜deş̌ yĕşǎlé̇֗m wĕ⁠ʼeţ-ẖàmiֽyşǐţ⁠wò֙ ywòsé֣p ʻálá֔y⁠w wĕ⁠náţa֥n ʼòţ֖⁠wò la⁠kò̇hé֑n wĕ⁠ha⁠kò̇hé֗n yĕkapé֥̇r ʻálá֛y⁠w bĕ̇⁠ʼé֥yl há⁠ʼáşá֖̌m wĕ⁠nisĕla֥ẖ lֽ⁠wò׃p"],[5,17,"וְ⁠אִם־נֶ֨פֶשׁ֙ כִּ֣י תֶֽחֱטָ֔א וְ⁠עָֽשְׂתָ֗ה אַחַת֙ מִ⁠כָּל־מִצְוֺ֣ת יְהוָ֔ה אֲשֶׁ֖ר לֹ֣א תֵעָשֶׂ֑ינָה וְ⁠לֹֽא־יָדַ֥ע וְ⁠אָשֵׁ֖ם וְ⁠נָשָׂ֥א עֲוֺנֽ⁠וֹ׃","wĕ⁠ʼim-ne֨peş̌֙ ki֣̇y ţeֽẖètá֔ʼ wĕ⁠ʻáֽşĕ̂ţá֗h ʼaẖaţ֙ mi⁠ká̇l-miẕĕwֺ֣ţ yĕhwá֔h ʼàşě֖r lò֣ʼ ţéʻáşê֑ynáh wĕ⁠lòֽʼ-yáda֥ʻ wĕ⁠ʼáşé֖̌m wĕ⁠náşá֥̂ʼ ʻàwֺnֽ⁠wò׃"],[5,18,"וְ֠⁠הֵבִיא אַ֣יִל תָּמִ֧ים מִן־הַ⁠צֹּ֛אן בְּ⁠עֶרְכְּ⁠ךָ֥ לְ⁠אָשָׁ֖ם אֶל־הַ⁠כֹּהֵ֑ן וְ⁠כִפֶּר֩ עָלָ֨י⁠ו הַ⁠כֹּהֵ֜ן עַ֣ל שִׁגְגָת֧⁠וֹ אֲשֶׁר־שָׁגָ֛ג וְ⁠ה֥וּא לֹֽא־יָדַ֖ע וְ⁠נִסְלַ֥ח לֽ⁠וֹ׃","wĕ֠⁠hébiyʼ ʼa֣yil ţá̇mi֧ym min-ha⁠ẕò֛̇ʼn bĕ̇⁠ʻerĕkĕ̇⁠ká֥ lĕ⁠ʼáşá֖̌m ʼel-ha⁠kò̇hé֑n wĕ⁠kipėr֩ ʻálá֨y⁠w ha⁠kò̇hé֜n ʻa֣l şǐgĕgáţ֧⁠wò ʼàşěr-şá̌gá֛g wĕ⁠h֥ẇʼ lòֽʼ-yáda֖ʻ wĕ⁠nisĕla֥ẖ lֽ⁠wò׃"],[5,19,"אָשָׁ֖ם ה֑וּא אָשֹׁ֥ם אָשַׁ֖ם לַ⁠יהוָֽה׃פ","ʼáşá֖̌m h֑ẇʼ ʼáşò֥̌m ʼáşǎ֖m la⁠yhwáֽh׃p"],[6,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[6,2,"נֶ֚פֶשׁ כִּ֣י תֶחֱטָ֔א וּ⁠מָעֲלָ֥ה מַ֖עַל בַּ⁠יהוָ֑ה וְ⁠כִחֵ֨שׁ בַּ⁠עֲמִית֜⁠וֹ בְּ⁠פִקָּד֗וֹן אֽוֹ־בִ⁠תְשׂ֤וּמֶת יָד֙ א֣וֹ בְ⁠גָזֵ֔ל א֖וֹ עָשַׁ֥ק אֶת־עֲמִיתֽ⁠וֹ׃","ne֚peş̌ ki֣̇y ţeẖètá֔ʼ ẇ⁠máʻàlá֥h ma֖ʻal bȧ⁠yhwá֑h wĕ⁠kiẖé֨ş̌ bȧ⁠ʻàmiyţ֜⁠wò bĕ̇⁠piqá̇d֗wòn ʼֽwò-bi⁠ţĕş֤̂ẇmeţ yád֙ ʼ֣wò bĕ⁠gázé֔l ʼ֖wò ʻáşǎ֥q ʼeţ-ʻàmiyţֽ⁠wò׃"],[6,3,"אֽוֹ־מָצָ֧א אֲבֵדָ֛ה וְ⁠כִ֥חֶשׁ בָּ֖⁠הּ וְ⁠נִשְׁבַּ֣ע עַל־שָׁ֑קֶר עַל־אַחַ֗ת מִ⁠כֹּ֛ל אֲשֶׁר־יַעֲשֶׂ֥ה הָ⁠אָדָ֖ם לַ⁠חֲטֹ֥א בָ⁠הֵֽנָּה׃","ʼֽwò-máẕá֧ʼ ʼàbédá֛h wĕ⁠ki֥ẖeş̌ bá֖̇⁠ḣ wĕ⁠nişĕ̌bȧ֣ʻ ʻal-şá֑̌qer ʻal-ʼaẖa֗ţ mi⁠kò֛̇l ʼàşěr-yaʻàşê֥h há⁠ʼádá֖m la⁠ẖàtò֥ʼ bá⁠héֽná̇h׃"],[6,4,"וְ⁠הָיָה֮ כִּֽי־יֶחֱטָ֣א וְ⁠אָשֵׁם֒ וְ⁠הֵשִׁ֨יב אֶת־הַ⁠גְּזֵלָ֜ה אֲשֶׁ֣ר גָּזָ֗ל א֤וֹ אֶת־הָ⁠עֹ֨שֶׁק֙ אֲשֶׁ֣ר עָשָׁ֔ק א֚וֹ אֶת־הַ⁠פִּקָּד֔וֹן אֲשֶׁ֥ר הָפְקַ֖ד אִתּ֑⁠וֹ א֥וֹ אֶת־הָ⁠אֲבֵדָ֖ה אֲשֶׁ֥ר מָצָֽא׃","wĕ⁠háyáh֮ kiֽ̇y-yeẖètá֣ʼ wĕ⁠ʼáşé̌m֒ wĕ⁠héşǐ֨yb ʼeţ-ha⁠gĕ̇zélá֜h ʼàşě֣r gá̇zá֗l ʼ֤wò ʼeţ-há⁠ʻò֨şěq֙ ʼàşě֣r ʻáşá̌֔q ʼ֚wò ʼeţ-ha⁠pi̇qá̇d֔wòn ʼàşě֥r hápĕqa֖d ʼiţ֑̇⁠wò ʼ֥wò ʼeţ-há⁠ʼàbédá֖h ʼàşě֥r máẕáֽʼ׃"],[6,5,"א֠וֹ מִ⁠כֹּ֞ל אֲשֶׁר־יִשָּׁבַ֣ע עָלָי⁠ו֮ לַ⁠שֶּׁקֶר֒ וְ⁠שִׁלַּ֤ם אֹת⁠וֹ֙ בְּ⁠רֹאשׁ֔⁠וֹ וַ⁠חֲמִשִׁתָ֖י⁠ו יֹסֵ֣ף עָלָ֑י⁠ו לַ⁠אֲשֶׁ֨ר ה֥וּא ל֛⁠וֹ יִתְּנֶ֖⁠נּוּ בְּ⁠י֥וֹם אַשְׁמָתֽ⁠וֹ׃","ʼ֠wò mi⁠kò̇֞l ʼàşěr-yişá̇̌ba֣ʻ ʻáláy⁠w֮ la⁠şė̌qer֒ wĕ⁠şǐlȧ֤m ʼòţ⁠wò֙ bĕ̇⁠ròʼş̌֔⁠wò wa⁠ẖàmişǐţá֖y⁠w yòsé֣p ʻálá֑y⁠w la⁠ʼàşě֨r h֥ẇʼ l֛⁠wò yiţĕ̇ne֖⁠ṅẇ bĕ̇⁠y֥wòm ʼaşĕ̌máţֽ⁠wò׃"],[6,6,"וְ⁠אֶת־אֲשָׁמ֥⁠וֹ יָבִ֖יא לַ⁠יהוָ֑ה אַ֣יִל תָּמִ֧ים מִן־הַ⁠צֹּ֛אן בְּ⁠עֶרְכְּ⁠ךָ֥ לְ⁠אָשָׁ֖ם אֶל־הַ⁠כֹּהֵֽן׃","wĕ⁠ʼeţ-ʼàşá̌m֥⁠wò yábi֖yʼ la⁠yhwá֑h ʼa֣yil ţá̇mi֧ym min-ha⁠ẕò֛̇ʼn bĕ̇⁠ʻerĕkĕ̇⁠ká֥ lĕ⁠ʼáşá֖̌m ʼel-ha⁠kò̇héֽn׃"],[6,7,"וְ⁠כִפֶּ֨ר עָלָ֧י⁠ו הַ⁠כֹּהֵ֛ן לִ⁠פְנֵ֥י יְהוָ֖ה וְ⁠נִסְלַ֣ח ל֑⁠וֹ עַל־אַחַ֛ת מִ⁠כֹּ֥ל אֲשֶֽׁר־יַעֲשֶׂ֖ה לְ⁠אַשְׁמָ֥ה בָֽ⁠הּ׃פ","wĕ⁠kipė֨r ʻálá֧y⁠w ha⁠kò̇hé֛n li⁠pĕné֥y yĕhwá֖h wĕ⁠nisĕla֣ẖ l֑⁠wò ʻal-ʼaẖa֛ţ mi⁠kò֥̇l ʼàşěֽr-yaʻàşê֖h lĕ⁠ʼaşĕ̌má֥h báֽ⁠ḣ׃p"],[6,8,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[6,9,"צַ֤ו אֶֽת־אַהֲרֹן֙ וְ⁠אֶת־בָּנָ֣י⁠ו לֵ⁠אמֹ֔ר זֹ֥את תּוֹרַ֖ת הָ⁠עֹלָ֑ה הִ֣וא הָ⁠עֹלָ֡ה עַל֩ מוֹקְדָ֨ה עַל־הַ⁠מִּזְבֵּ֤חַ כָּל־הַ⁠לַּ֨יְלָה֙ עַד־הַ⁠בֹּ֔קֶר וְ⁠אֵ֥שׁ הַ⁠מִּזְבֵּ֖חַ תּ֥וּקַד בּֽ⁠וֹ׃","ẕa֤w ʼeֽţ-ʼahàròn֙ wĕ⁠ʼeţ-bá̇ná֣y⁠w lé⁠ʼmò֔r zò֥ʼţ ţ̇wòra֖ţ há⁠ʻòlá֑h hi֣wʼ há⁠ʻòlá֡h ʻal֩ mwòqĕdá֨h ʻal-ha⁠mi̇zĕbé֤̇ẖa ká̇l-ha⁠lȧ֨yĕláh֙ ʻad-ha⁠bò̇֔qer wĕ⁠ʼé֥ş̌ ha⁠mi̇zĕbé֖̇ẖa ţ֥̇ẇqad ḃֽ⁠wò׃"],[6,10,"וְ⁠לָבַ֨שׁ הַ⁠כֹּהֵ֜ן מִדּ֣⁠וֹ בַ֗ד וּ⁠מִֽכְנְסֵי־בַד֮ יִלְבַּ֣שׁ עַל־בְּשָׂר⁠וֹ֒ וְ⁠הֵרִ֣ים אֶת־הַ⁠דֶּ֗שֶׁן אֲשֶׁ֨ר תֹּאכַ֥ל הָ⁠אֵ֛שׁ אֶת־הָ⁠עֹלָ֖ה עַל־הַ⁠מִּזְבֵּ֑חַ וְ⁠שָׂמ֕⁠וֹ אֵ֖צֶל הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠lába֨ş̌ ha⁠kò̇hé֜n miḋ֣⁠wò ba֗d ẇ⁠miֽkĕnĕséy-bad֮ yilĕbȧ֣ş̌ ʻal-bĕ̇şá̂r⁠wò֒ wĕ⁠héri֣ym ʼeţ-ha⁠dė֗şěn ʼàşě֨r ţò̇ʼka֥l há⁠ʼé֛ş̌ ʼeţ-há⁠ʻòlá֖h ʻal-ha⁠mi̇zĕbé֑̇ẖa wĕ⁠şá̂m֕⁠wò ʼé֖ẕel ha⁠mi̇zĕbéֽ̇ẖa׃"],[6,11,"וּ⁠פָשַׁט֙ אֶת־בְּגָדָ֔י⁠ו וְ⁠לָבַ֖שׁ בְּגָדִ֣ים אֲחֵרִ֑ים וְ⁠הוֹצִ֤יא אֶת־הַ⁠דֶּ֨שֶׁן֙ אֶל־מִ⁠ח֣וּץ לַֽ⁠מַּחֲנֶ֔ה אֶל־מָק֖וֹם טָהֽוֹר׃","ẇ⁠páşǎt֙ ʼeţ-bĕ̇gádá֔y⁠w wĕ⁠lába֖ş̌ bĕ̇gádi֣ym ʼàẖéri֑ym wĕ⁠hwòẕi֤yʼ ʼeţ-ha⁠dė֨şěn֙ ʼel-mi⁠ẖ֣ẇẕ laֽ⁠mȧẖàne֔h ʼel-máq֖wòm táhֽwòr׃"],[6,12,"וְ⁠הָ⁠אֵ֨שׁ עַל־הַ⁠מִּזְבֵּ֤חַ תּֽוּקַד־בּ⁠וֹ֙ לֹ֣א תִכְבֶּ֔ה וּ⁠בִעֵ֨ר עָלֶ֧י⁠הָ הַ⁠כֹּהֵ֛ן עֵצִ֖ים בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֑קֶר וְ⁠עָרַ֤ךְ עָלֶ֨י⁠הָ֙ הָֽ⁠עֹלָ֔ה וְ⁠הִקְטִ֥יר עָלֶ֖י⁠הָ חֶלְבֵ֥י הַ⁠שְּׁלָמִֽים׃","wĕ⁠há⁠ʼé֨ş̌ ʻal-ha⁠mi̇zĕbé֤̇ẖa ţֽ̇ẇqad-ḃ⁠wò֙ lò֣ʼ ţikĕbė֔h ẇ⁠biʻé֨r ʻále֧y⁠há ha⁠kò̇hé֛n ʻéẕi֖ym bȧ⁠bò֣̇qer bȧ⁠bò֑̇qer wĕ⁠ʻára֤kĕ ʻále֨y⁠há֙ háֽ⁠ʻòlá֔h wĕ⁠hiqĕti֥yr ʻále֖y⁠há ẖelĕbé֥y ha⁠şĕ̇̌lámiֽym׃"],[6,13,"אֵ֗שׁ תָּמִ֛יד תּוּקַ֥ד עַל־הַ⁠מִּזְבֵּ֖חַ לֹ֥א תִכְבֶֽה׃ס","ʼé֗ş̌ ţá̇mi֛yd ţ̇ẇqa֥d ʻal-ha⁠mi̇zĕbé֖̇ẖa lò֥ʼ ţikĕbeֽh׃s"],[6,14,"וְ⁠זֹ֥את תּוֹרַ֖ת הַ⁠מִּנְחָ֑ה הַקְרֵ֨ב אֹתָ֤⁠הּ בְּנֵֽי־אַהֲרֹן֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֶל־פְּנֵ֖י הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠zò֥ʼţ ţ̇wòra֖ţ ha⁠mi̇nĕẖá֑h haqĕré֨b ʼòţá֤⁠ḣ bĕ̇néֽy-ʼahàròn֙ li⁠pĕné֣y yĕhwá֔h ʼel-pĕ̇né֖y ha⁠mi̇zĕbéֽ̇ẖa׃"],[6,15,"וְ⁠הֵרִ֨ים מִמֶּ֜⁠נּוּ בְּ⁠קֻמְצ֗⁠וֹ מִ⁠סֹּ֤לֶת הַ⁠מִּנְחָה֙ וּ⁠מִ⁠שַּׁמְנָ֔⁠הּ וְ⁠אֵת֙ כָּל־הַ⁠לְּבֹנָ֔ה אֲשֶׁ֖ר עַל־הַ⁠מִּנְחָ֑ה וְ⁠הִקְטִ֣יר הַ⁠מִּזְבֵּ֗חַ רֵ֧יחַ נִיחֹ֛חַ אַזְכָּרָתָ֖⁠הּ לַ⁠יהוָֽה׃","wĕ⁠héri֨ym mimė֜⁠ṅẇ bĕ̇⁠qumĕẕ֗⁠wò mi⁠sò֤̇leţ ha⁠mi̇nĕẖáh֙ ẇ⁠mi⁠şȧ̌mĕná֔⁠ḣ wĕ⁠ʼéţ֙ ká̇l-ha⁠lĕ̇bòná֔h ʼàşě֖r ʻal-ha⁠mi̇nĕẖá֑h wĕ⁠hiqĕti֣yr ha⁠mi̇zĕbé̇֗ẖa ré֧yẖa niyẖò֛ẖa ʼazĕká̇ráţá֖⁠ḣ la⁠yhwáֽh׃"],[6,16,"וְ⁠הַ⁠נּוֹתֶ֣רֶת מִמֶּ֔⁠נָּה יֹאכְל֖וּ אַהֲרֹ֣ן וּ⁠בָנָ֑י⁠ו מַצּ֤וֹת תֵּֽאָכֵל֙ בְּ⁠מָק֣וֹם קָדֹ֔שׁ בַּ⁠חֲצַ֥ר אֹֽהֶל־מוֹעֵ֖ד יֹאכְלֽוּ⁠הָ׃","wĕ⁠ha⁠ṅwòţe֣reţ mimė֔⁠ná̇h yòʼkĕl֖ẇ ʼahàrò֣n ẇ⁠báná֑y⁠w maẕ֤̇wòţ ţéֽ̇ʼákél֙ bĕ̇⁠máq֣wòm qádò֔ş̌ bȧ⁠ẖàẕa֥r ʼòֽhel-mwòʻé֖d yòʼkĕlֽẇ⁠há׃"],[6,17,"לֹ֤א תֵאָפֶה֙ חָמֵ֔ץ חֶלְקָ֛⁠ם נָתַ֥תִּי אֹתָ֖⁠הּ מֵ⁠אִשָּׁ֑⁠י קֹ֤דֶשׁ קָֽדָשִׁים֙ הִ֔וא כַּ⁠חַטָּ֖את וְ⁠כָ⁠אָשָֽׁם׃","lò֤ʼ ţéʼápeh֙ ẖámé֔ẕ ẖelĕqá֛⁠m náţa֥ţi̇y ʼòţá֖⁠ḣ mé⁠ʼişá֑̇̌⁠y qò֤deş̌ qáֽdáşǐym֙ hi֔wʼ kȧ⁠ẖatá֖̇ʼţ wĕ⁠ká⁠ʼáşáֽ̌m׃"],[6,18,"כָּל־זָכָ֞ר בִּ⁠בְנֵ֤י אַהֲרֹן֙ יֹֽאכֲלֶ֔⁠נָּה חָק־עוֹלָם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם מֵ⁠אִשֵּׁ֖י יְהוָ֑ה כֹּ֛ל אֲשֶׁר־יִגַּ֥ע בָּ⁠הֶ֖ם יִקְדָּֽשׁ׃פ","ká̇l-záká֞r bi̇⁠bĕné֤y ʼahàròn֙ yòֽʼkàle֔⁠ná̇h ẖáq-ʻwòlám֙ lĕ⁠dòrò֣ţéy⁠ke֔m mé⁠ʼişé֖̇̌y yĕhwá֑h kò֛̇l ʼàşěr-yigȧ֥ʻ bá̇⁠he֖m yiqĕdáֽ̇ş̌׃p"],[6,19,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[6,20,"זֶ֡ה קָרְבַּן֩ אַהֲרֹ֨ן וּ⁠בָנָ֜י⁠ו אֲשֶׁר־יַקְרִ֣יבוּ לַֽ⁠יהוָ֗ה בְּ⁠יוֹם֙ הִמָּשַׁ֣ח אֹת֔⁠וֹ עֲשִׂירִ֨ת הָ⁠אֵפָ֥ה סֹ֛לֶת מִנְחָ֖ה תָּמִ֑יד מַחֲצִיתָ֣⁠הּ בַּ⁠בֹּ֔קֶר וּ⁠מַחֲצִיתָ֖⁠הּ בָּ⁠עָֽרֶב׃","ze֡h qárĕbȧn֩ ʼahàrò֨n ẇ⁠báná֜y⁠w ʼàşěr-yaqĕri֣ybẇ laֽ⁠yhwá֗h bĕ̇⁠ywòm֙ himá̇şǎ֣ẖ ʼòţ֔⁠wò ʻàşîyri֨ţ há⁠ʼépá֥h sò֛leţ minĕẖá֖h ţá̇mi֑yd maẖàẕiyţá֣⁠ḣ bȧ⁠bò̇֔qer ẇ⁠maẖàẕiyţá֖⁠ḣ bá̇⁠ʻáֽreb׃"],[6,21,"עַֽל־מַחֲבַ֗ת בַּ⁠שֶּׁ֛מֶן תֵּעָשֶׂ֖ה מֻרְבֶּ֣כֶת תְּבִיאֶ֑⁠נָּה תֻּפִינֵי֙ מִנְחַ֣ת פִּתִּ֔ים תַּקְרִ֥יב רֵֽיחַ־נִיחֹ֖חַ לַ⁠יהוָֽה׃","ʻaֽl-maẖàba֗ţ bȧ⁠şė֛̌men ţé̇ʻáşê֖h murĕbė֣keţ ţĕ̇biyʼe֑⁠ná̇h ţu̇piynéy֙ minĕẖa֣ţ pi̇ţi̇֔ym ţȧqĕri֥yb réֽyẖa-niyẖò֖ẖa la⁠yhwáֽh׃"],[6,22,"וְ⁠הַ⁠כֹּהֵ֨ן הַ⁠מָּשִׁ֧יחַ תַּחְתָּ֛י⁠ו מִ⁠בָּנָ֖י⁠ו יַעֲשֶׂ֣ה אֹתָ֑⁠הּ חָק־עוֹלָ֕ם לַ⁠יהוָ֖ה כָּלִ֥יל תָּקְטָֽר׃","wĕ⁠ha⁠kò̇hé֨n ha⁠má̇şǐ֧yẖa ţȧẖĕţá֛̇y⁠w mi⁠bá̇ná֖y⁠w yaʻàşê֣h ʼòţá֑⁠ḣ ẖáq-ʻwòlá֕m la⁠yhwá֖h ká̇li֥yl ţá̇qĕtáֽr׃"],[6,23,"וְ⁠כָל־מִנְחַ֥ת כֹּהֵ֛ן כָּלִ֥יל תִּהְיֶ֖ה לֹ֥א תֵאָכֵֽל׃פ","wĕ⁠kál-minĕẖa֥ţ kò̇hé֛n ká̇li֥yl ţi̇hĕye֖h lò֥ʼ ţéʼákéֽl׃p"],[6,24,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[6,25,"דַּבֵּ֤ר אֶֽל־אַהֲרֹן֙ וְ⁠אֶל־בָּנָ֣י⁠ו לֵ⁠אמֹ֔ר זֹ֥את תּוֹרַ֖ת הַֽ⁠חַטָּ֑את בִּ⁠מְק֡וֹם אֲשֶׁר֩ תִּשָּׁחֵ֨ט הָ⁠עֹלָ֜ה תִּשָּׁחֵ֤ט הַֽ⁠חַטָּאת֙ לִ⁠פְנֵ֣י יְהוָ֔ה קֹ֥דֶשׁ קָֽדָשִׁ֖ים הִֽוא׃","dȧbé֤̇r ʼeֽl-ʼahàròn֙ wĕ⁠ʼel-bá̇ná֣y⁠w lé⁠ʼmò֔r zò֥ʼţ ţ̇wòra֖ţ haֽ⁠ẖatá֑̇ʼţ bi̇⁠mĕq֡wòm ʼàşěr֩ ţi̇şá̇̌ẖé֨t há⁠ʻòlá֜h ţi̇şá̇̌ẖé֤t haֽ⁠ẖatá̇ʼţ֙ li⁠pĕné֣y yĕhwá֔h qò֥deş̌ qֽádáşǐ֖ym hiֽwʼ׃"],[6,26,"הַ⁠כֹּהֵ֛ן הַֽ⁠מְחַטֵּ֥א אֹתָ֖⁠הּ יֹאכֲלֶ֑⁠נָּה בְּ⁠מָק֤וֹם קָדֹשׁ֙ תֵּֽאָכֵ֔ל בַּ⁠חֲצַ֖ר אֹ֥הֶל מוֹעֵֽד׃","ha⁠kò̇hé֛n haֽ⁠mĕẖaté֥̇ʼ ʼòţá֖⁠ḣ yòʼkàle֑⁠ná̇h bĕ̇⁠máq֤wòm qádòş̌֙ ţéֽ̇ʼáké֔l bȧ⁠ẖàẕa֖r ʼò֥hel mwòʻéֽd׃"],[6,27,"כֹּ֛ל אֲשֶׁר־יִגַּ֥ע בִּ⁠בְשָׂרָ֖⁠הּ יִקְדָּ֑שׁ וַ⁠אֲשֶׁ֨ר יִזֶּ֤ה מִ⁠דָּמָ⁠הּ֙ עַל־הַ⁠בֶּ֔גֶד אֲשֶׁר֙ יִזֶּ֣ה עָלֶ֔י⁠הָ תְּכַבֵּ֖ס בְּ⁠מָק֥וֹם קָדֹֽשׁ׃","kò֛̇l ʼàşěr-yigȧ֥ʻ bi̇⁠bĕşá̂rá֖⁠ḣ yiqĕdá֑̇ş̌ wa⁠ʼàşě֨r yizė֤h mi⁠dá̇má⁠ḣ֙ ʻal-ha⁠bė֔ged ʼàşěr֙ yizė֣h ʻále֔y⁠há ţĕ̇kabé֖̇s bĕ̇⁠máq֥wòm qádòֽş̌׃"],[6,28,"וּ⁠כְלִי־חֶ֛רֶשׂ אֲשֶׁ֥ר תְּבֻשַּׁל־בּ֖⁠וֹ יִשָּׁבֵ֑ר וְ⁠אִם־בִּ⁠כְלִ֤י נְחֹ֨שֶׁת֙ בֻּשָּׁ֔לָה וּ⁠מֹרַ֥ק וְ⁠שֻׁטַּ֖ף בַּ⁠מָּֽיִם׃","ẇ⁠kĕliy-ẖe֛reş̂ ʼàşě֥r ţĕ̇buşȧ̌l-ḃ֖⁠wò yişá̇̌bé֑r wĕ⁠ʼim-bi̇⁠kĕli֤y nĕẖò֨şěţ֙ bu̇şá̇̌֔láh ẇ⁠mòra֥q wĕ⁠şǔtȧ֖p bȧ⁠máֽ̇yim׃"],[6,29,"כָּל־זָכָ֥ר בַּ⁠כֹּהֲנִ֖ים יֹאכַ֣ל אֹתָ֑⁠הּ קֹ֥דֶשׁ קָֽדָשִׁ֖ים הִֽוא׃","ká̇l-záká֥r bȧ⁠kò̇hàni֖ym yòʼka֣l ʼòţá֑⁠ḣ qò֥deş̌ qֽádáşǐ֖ym hiֽwʼ׃"],[6,30,"וְ⁠כָל־חַטָּ֡את אֲשֶׁר֩ יוּבָ֨א מִ⁠דָּמָ֜⁠הּ אֶל־אֹ֧הֶל מוֹעֵ֛ד לְ⁠כַפֵּ֥ר בַּ⁠קֹּ֖דֶשׁ לֹ֣א תֵאָכֵ֑ל בָּ⁠אֵ֖שׁ תִּשָּׂרֵֽף׃פ","wĕ⁠kál-ẖatá̇֡ʼţ ʼàşěr֩ yẇbá֨ʼ mi⁠dá̇má֜⁠ḣ ʼel-ʼò֧hel mwòʻé֛d lĕ⁠kapé֥̇r bȧ⁠qò֖̇deş̌ lò֣ʼ ţéʼáké֑l bá̇⁠ʼé֖ş̌ ţi̇şá̇̂réֽp׃p"],[7,1,"וְ⁠זֹ֥את תּוֹרַ֖ת הָ⁠אָשָׁ֑ם קֹ֥דֶשׁ קָֽדָשִׁ֖ים הֽוּא׃","wĕ⁠zò֥ʼţ ţ̇wòra֖ţ há⁠ʼáşá֑̌m qò֥deş̌ qֽádáşǐ֖ym hֽẇʼ׃"],[7,2,"בִּ⁠מְק֗וֹם אֲשֶׁ֤ר יִשְׁחֲטוּ֙ אֶת־הָ֣⁠עֹלָ֔ה יִשְׁחֲט֖וּ אֶת־הָ⁠אָשָׁ֑ם וְ⁠אֶת־דָּמ֛⁠וֹ יִזְרֹ֥ק עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","bi̇⁠mĕq֗wòm ʼàşě֤r yişĕ̌ẖàtẇ֙ ʼeţ-há֣⁠ʻòlá֔h yişĕ̌ẖàt֖ẇ ʼeţ-há⁠ʼáşá֑̌m wĕ⁠ʼeţ-dá̇m֛⁠wò yizĕrò֥q ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[7,3,"וְ⁠אֵ֥ת כָּל־חֶלְבּ֖⁠וֹ יַקְרִ֣יב מִמֶּ֑⁠נּוּ אֵ֚ת הָֽ⁠אַלְיָ֔ה וְ⁠אֶת־הַ⁠חֵ֖לֶב הַֽ⁠מְכַסֶּ֥ה אֶת־הַ⁠קֶּֽרֶב׃","wĕ⁠ʼé֥ţ ká̇l-ẖelĕḃ֖⁠wò yaqĕri֣yb mimė֑⁠ṅẇ ʼé֚ţ háֽ⁠ʼalĕyá֔h wĕ⁠ʼeţ-ha⁠ẖé֖leb haֽ⁠mĕkasė֥h ʼeţ-ha⁠qėֽreb׃"],[7,4,"וְ⁠אֵת֙ שְׁתֵּ֣י הַ⁠כְּלָיֹ֔ת וְ⁠אֶת־הַ⁠חֵ֨לֶב֙ אֲשֶׁ֣ר עֲלֵי⁠הֶ֔ן אֲשֶׁ֖ר עַל־הַ⁠כְּסָלִ֑ים וְ⁠אֶת־הַ⁠יֹּתֶ֨רֶת֙ עַל־הַ⁠כָּבֵ֔ד עַל־הַ⁠כְּלָיֹ֖ת יְסִירֶֽ⁠נָּה׃","wĕ⁠ʼéţ֙ şĕ̌ţé֣̇y ha⁠kĕ̇láyò֔ţ wĕ⁠ʼeţ-ha⁠ẖé֨leb֙ ʼàşě֣r ʻàléy⁠he֔n ʼàşě֖r ʻal-ha⁠kĕ̇sáli֑ym wĕ⁠ʼeţ-ha⁠yò̇ţe֨reţ֙ ʻal-ha⁠ká̇bé֔d ʻal-ha⁠kĕ̇láyò֖ţ yĕsiyreֽ⁠ná̇h׃"],[7,5,"וְ⁠הִקְטִ֨יר אֹתָ֤⁠ם הַ⁠כֹּהֵן֙ הַ⁠מִּזְבֵּ֔חָ⁠ה אִשֶּׁ֖ה לַ⁠יהוָ֑ה אָשָׁ֖ם הֽוּא׃","wĕ⁠hiqĕti֨yr ʼòţá֤⁠m ha⁠kò̇hén֙ ha⁠mi̇zĕbé̇֔ẖá⁠h ʼişė֖̌h la⁠yhwá֑h ʼáşá֖̌m hֽẇʼ׃"],[7,6,"כָּל־זָכָ֥ר בַּ⁠כֹּהֲנִ֖ים יֹאכְלֶ֑⁠נּוּ בְּ⁠מָק֤וֹם קָדוֹשׁ֙ יֵאָכֵ֔ל קֹ֥דֶשׁ קָֽדָשִׁ֖ים הֽוּא׃","ká̇l-záká֥r bȧ⁠kò̇hàni֖ym yòʼkĕle֑⁠ṅẇ bĕ̇⁠máq֤wòm qádwòş̌֙ yéʼáké֔l qò֥deş̌ qáֽdáşǐ֖ym hֽẇʼ׃"],[7,7,"כַּֽ⁠חַטָּאת֙ כָּֽ⁠אָשָׁ֔ם תּוֹרָ֥ה אַחַ֖ת לָ⁠הֶ֑ם הַ⁠כֹּהֵ֛ן אֲשֶׁ֥ר יְכַפֶּר־בּ֖⁠וֹ ל֥⁠וֹ יִהְיֶֽה׃","kȧֽ⁠ẖatá̇ʼţ֙ káֽ̇⁠ʼáşá̌֔m ţ̇wòrá֥h ʼaẖa֖ţ lá⁠he֑m ha⁠kò̇hé֛n ʼàşě֥r yĕkapėr-ḃ֖⁠wò l֥⁠wò yihĕyeֽh׃"],[7,8,"וְ⁠הַ֨⁠כֹּהֵ֔ן הַ⁠מַּקְרִ֖יב אֶת־עֹ֣לַת אִ֑ישׁ ע֤וֹר הָֽ⁠עֹלָה֙ אֲשֶׁ֣ר הִקְרִ֔יב לַ⁠כֹּהֵ֖ן ל֥⁠וֹ יִהְיֶֽה׃","wĕ⁠ha֨⁠kò̇hé֔n ha⁠mȧqĕri֖yb ʼeţ-ʻò֣laţ ʼi֑yş̌ ʻ֤wòr háֽ⁠ʻòláh֙ ʼàşě֣r hiqĕri֔yb la⁠kò̇hé֖n l֥⁠wò yihĕyeֽh׃"],[7,9,"וְ⁠כָל־מִנְחָ֗ה אֲשֶׁ֤ר תֵּֽאָפֶה֙ בַּ⁠תַּנּ֔וּר וְ⁠כָל־נַעֲשָׂ֥ה בַ⁠מַּרְחֶ֖שֶׁת וְ⁠עַֽל־מַחֲבַ֑ת לַ⁠כֹּהֵ֛ן הַ⁠מַּקְרִ֥יב אֹתָ֖⁠הּ ל֥⁠וֹ תִֽהְיֶֽה׃","wĕ⁠kál-minĕẖá֗h ʼàşě֤r ţéֽ̇ʼápeh֙ bȧ⁠ţȧṅ֔ẇr wĕ⁠kál-naʻàşá֥̂h ba⁠mȧrĕẖe֖şěţ wĕ⁠ʻaֽl-maẖàba֑ţ la⁠kò̇hé֛n ha⁠mȧqĕri֥yb ʼòţá֖⁠ḣ l֥⁠wò ţiֽhĕyeֽh׃"],[7,10,"וְ⁠כָל־מִנְחָ֥ה בְלוּלָֽה־בַ⁠שֶּׁ֖מֶן וַ⁠חֲרֵבָ֑ה לְ⁠כָל־בְּנֵ֧י אַהֲרֹ֛ן תִּהְיֶ֖ה אִ֥ישׁ כְּ⁠אָחִֽי⁠ו׃פ","wĕ⁠kál-minĕẖá֥h bĕlẇláֽh-ba⁠şė֖̌men wa⁠ẖàrébá֑h lĕ⁠kál-bĕ̇né֧y ʼahàrò֛n ţi̇hĕye֖h ʼi֥yş̌ kĕ̇⁠ʼáẖiֽy⁠w׃p"],[7,11,"וְ⁠זֹ֥את תּוֹרַ֖ת זֶ֣בַח הַ⁠שְּׁלָמִ֑ים אֲשֶׁ֥ר יַקְרִ֖יב לַ⁠יהוָֽה׃","wĕ⁠zò֥ʼţ ţ̇wòra֖ţ ze֣baẖ ha⁠şĕ̇̌lámi֑ym ʼàşě֥r yaqĕri֖yb la⁠yhwáֽh׃"],[7,12,"אִ֣ם עַל־תּוֹדָה֮ יַקְרִיבֶ⁠נּוּ֒ וְ⁠הִקְרִ֣יב ׀ עַל־זֶ֣בַח הַ⁠תּוֹדָ֗ה חַלּ֤וֹת מַצּוֹת֙ בְּלוּלֹ֣ת בַּ⁠שֶּׁ֔מֶן וּ⁠רְקִיקֵ֥י מַצּ֖וֹת מְשֻׁחִ֣ים בַּ⁠שָּׁ֑מֶן וְ⁠סֹ֣לֶת מֻרְבֶּ֔כֶת חַלֹּ֖ת בְּלוּלֹ֥ת בַּ⁠שָּֽׁמֶן׃","ʼi֣m ʻal-ţ̇wòdáh֮ yaqĕriybe⁠ṅẇ֒ wĕ⁠hiqĕri֣yb ׀ ʻal-ze֣baẖ ha⁠ţ̇wòdá֗h ẖal֤̇wòţ maẕ̇wòţ֙ bĕ̇lẇlò֣ţ bȧ⁠şė̌֔men ẇ⁠rĕqiyqé֥y maẕ֖̇wòţ mĕşǔẖi֣ym bȧ⁠şá֑̇̌men wĕ⁠sò֣leţ murĕbė֔keţ ẖalò֖̇ţ bĕ̇lẇlò֥ţ bȧ⁠şáֽ̇̌men׃"],[7,13,"עַל־חַלֹּת֙ לֶ֣חֶם חָמֵ֔ץ יַקְרִ֖יב קָרְבָּנ֑⁠וֹ עַל־זֶ֖בַח תּוֹדַ֥ת שְׁלָמָֽי⁠ו׃","ʻal-ẖalò̇ţ֙ le֣ẖem ẖámé֔ẕ yaqĕri֖yb qárĕbá̇n֑⁠wò ʻal-ze֖baẖ ţ̇wòda֥ţ şĕ̌lámáֽy⁠w׃"],[7,14,"וְ⁠הִקְרִ֨יב מִמֶּ֤⁠נּוּ אֶחָד֙ מִ⁠כָּל־קָרְבָּ֔ן תְּרוּמָ֖ה לַ⁠יהוָ֑ה לַ⁠כֹּהֵ֗ן הַ⁠זֹּרֵ֛ק אֶת־דַּ֥ם הַ⁠שְּׁלָמִ֖ים ל֥⁠וֹ יִהְיֶֽה׃","wĕ⁠hiqĕri֨yb mimė֤⁠ṅẇ ʼeẖád֙ mi⁠ká̇l-qárĕbá̇֔n ţĕ̇rẇmá֖h la⁠yhwá֑h la⁠kò̇hé֗n ha⁠zò̇ré֛q ʼeţ-dȧ֥m ha⁠şĕ̇̌lámi֖ym l֥⁠wò yihĕyeֽh׃"],[7,15,"וּ⁠בְשַׂ֗ר זֶ֚בַח תּוֹדַ֣ת שְׁלָמָ֔י⁠ו בְּ⁠י֥וֹם קָרְבָּנ֖⁠וֹ יֵאָכֵ֑ל לֹֽא־יַנִּ֥יחַ מִמֶּ֖⁠נּוּ עַד־בֹּֽקֶר׃","ẇ⁠bĕşâ֗r ze֚baẖ ţ̇wòda֣ţ şĕ̌lámá֔y⁠w bĕ̇⁠y֥wòm qárĕbá̇n֖⁠wò yéʼáké֑l lòֽʼ-yani֥̇yẖa mimė֖⁠ṅẇ ʻad-bòֽ̇qer׃"],[7,16,"וְ⁠אִם־נֶ֣דֶר ׀ א֣וֹ נְדָבָ֗ה זֶ֚בַח קָרְבָּנ֔⁠וֹ בְּ⁠י֛וֹם הַקְרִיב֥⁠וֹ אֶת־זִבְח֖⁠וֹ יֵאָכֵ֑ל וּ⁠מִֽ⁠מָּחֳרָ֔ת וְ⁠הַ⁠נּוֹתָ֥ר מִמֶּ֖⁠נּוּ יֵאָכֵֽל׃","wĕ⁠ʼim-ne֣der ׀ ʼ֣wò nĕdábá֗h ze֚baẖ qárĕbá̇n֔⁠wò bĕ̇⁠y֛wòm haqĕriyb֥⁠wò ʼeţ-zibĕẖ֖⁠wò yéʼáké֑l ẇ⁠miֽ⁠má̇ẖorá֔ţ wĕ⁠ha⁠ṅwòţá֥r mimė֖⁠ṅẇ yéʼákéֽl׃"],[7,17,"וְ⁠הַ⁠נּוֹתָ֖ר מִ⁠בְּשַׂ֣ר הַ⁠זָּ֑בַח בַּ⁠יּוֹם֙ הַ⁠שְּׁלִישִׁ֔י בָּ⁠אֵ֖שׁ יִשָּׂרֵֽף׃","wĕ⁠ha⁠ṅwòţá֖r mi⁠bĕ̇şâ֣r ha⁠zá֑̇baẖ bȧ⁠ẏwòm֙ ha⁠şĕ̇̌liyşǐ֔y bá̇⁠ʼé֖ş̌ yişá̇̂réֽp׃"],[7,18,"וְ⁠אִ֣ם הֵאָכֹ֣ל יֵ֠אָכֵל מִ⁠בְּשַׂר־זֶ֨בַח שְׁלָמָ֜י⁠ו בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁי֮ לֹ֣א יֵרָצֶה֒ הַ⁠מַּקְרִ֣יב אֹת֗⁠וֹ לֹ֧א יֵחָשֵׁ֛ב ל֖⁠וֹ פִּגּ֣וּל יִהְיֶ֑ה וְ⁠הַ⁠נֶּ֛פֶשׁ הָ⁠אֹכֶ֥לֶת מִמֶּ֖⁠נּוּ עֲוֺנָ֥⁠הּ תִּשָּֽׂא׃","wĕ⁠ʼi֣m héʼákò֣l yé֠ʼákél mi⁠bĕ̇şâr-ze֨baẖ şĕ̌lámá֜y⁠w bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐy֮ lò֣ʼ yéráẕeh֒ ha⁠mȧqĕri֣yb ʼòţ֗⁠wò lò֧ʼ yéẖáşé֛̌b l֖⁠wò pi̇ġ֣ẇl yihĕye֑h wĕ⁠ha⁠nė֛peş̌ há⁠ʼòke֥leţ mimė֖⁠ṅẇ ʻàwֺná֥⁠ḣ ţi̇şáֽ̇̂ʼ׃"],[7,19,"וְ⁠הַ⁠בָּשָׂ֞ר אֲשֶׁר־יִגַּ֤ע בְּ⁠כָל־טָמֵא֙ לֹ֣א יֵֽאָכֵ֔ל בָּ⁠אֵ֖שׁ יִשָּׂרֵ֑ף וְ⁠הַ֨⁠בָּשָׂ֔ר כָּל־טָה֖וֹר יֹאכַ֥ל בָּשָֽׂר׃","wĕ⁠ha⁠bá̇şá̂֞r ʼàşěr-yigȧ֤ʻ bĕ̇⁠kál-táméʼ֙ lò֣ʼ yéֽʼáké֔l bá̇⁠ʼé֖ş̌ yişá̇̂ré֑p wĕ⁠ha֨⁠bá̇şá̂֔r ká̇l-táh֖wòr yòʼka֥l bá̇şáֽ̂r׃"],[7,20,"וְ⁠הַ⁠נֶּ֜פֶשׁ אֲשֶׁר־תֹּאכַ֣ל בָּשָׂ֗ר מִ⁠זֶּ֤בַח הַ⁠שְּׁלָמִים֙ אֲשֶׁ֣ר לַ⁠יהוָ֔ה וְ⁠טֻמְאָת֖⁠וֹ עָלָ֑י⁠ו וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מֵ⁠עַמֶּֽי⁠הָ׃","wĕ⁠ha⁠nė֜peş̌ ʼàşěr-ţò̇ʼka֣l bá̇şá̂֗r mi⁠zė֤baẖ ha⁠şĕ̇̌lámiym֙ ʼàşě֣r la⁠yhwá֔h wĕ⁠tumĕʼáţ֖⁠wò ʻálá֑y⁠w wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ mé⁠ʻamėֽy⁠há׃"],[7,21,"וְ⁠נֶ֜פֶשׁ כִּֽי־תִגַּ֣ע בְּ⁠כָל־טָמֵ֗א בְּ⁠טֻמְאַ֤ת אָדָם֙ א֣וֹ ׀ בִּ⁠בְהֵמָ֣ה טְמֵאָ֗ה א֚וֹ בְּ⁠כָל־שֶׁ֣קֶץ טָמֵ֔א וְ⁠אָכַ֛ל מִ⁠בְּשַׂר־זֶ֥בַח הַ⁠שְּׁלָמִ֖ים אֲשֶׁ֣ר לַ⁠יהוָ֑ה וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מֵ⁠עַמֶּֽי⁠הָ׃פ","wĕ⁠ne֜peş̌ kiֽ̇y-ţigȧ֣ʻ bĕ̇⁠kál-támé֗ʼ bĕ̇⁠tumĕʼa֤ţ ʼádám֙ ʼ֣wò ׀ bi̇⁠bĕhémá֣h tĕméʼá֗h ʼ֚wò bĕ̇⁠kál-şě֣qeẕ támé֔ʼ wĕ⁠ʼáka֛l mi⁠bĕ̇şâr-ze֥baẖ ha⁠şĕ̇̌lámi֖ym ʼàşě֣r la⁠yhwá֑h wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ mé⁠ʻamėֽy⁠há׃p"],[7,22,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[7,23,"דַּבֵּ֛ר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר כָּל־חֵ֜לֶב שׁ֥וֹר וְ⁠כֶ֛שֶׂב וָ⁠עֵ֖ז לֹ֥א תֹאכֵֽלוּ׃","dȧbé֛̇r ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r ká̇l-ẖé֜leb ş֥̌wòr wĕ⁠ke֛şêb wá⁠ʻé֖z lò֥ʼ ţòʼkéֽlẇ׃"],[7,24,"וְ⁠חֵ֤לֶב נְבֵלָה֙ וְ⁠חֵ֣לֶב טְרֵפָ֔ה יֵעָשֶׂ֖ה לְ⁠כָל־מְלָאכָ֑ה וְ⁠אָכֹ֖ל לֹ֥א תֹאכְלֻֽ⁠הוּ׃","wĕ⁠ẖé֤leb nĕbéláh֙ wĕ⁠ẖé֣leb tĕrépá֔h yéʻáşê֖h lĕ⁠kál-mĕláʼká֑h wĕ⁠ʼákò֖l lò֥ʼ ţòʼkĕluֽ⁠hẇ׃"],[7,25,"כִּ֚י כָּל־אֹכֵ֣ל חֵ֔לֶב מִן־הַ֨⁠בְּהֵמָ֔ה אֲשֶׁ֨ר יַקְרִ֥יב מִמֶּ֛⁠נָּה אִשֶּׁ֖ה לַ⁠יהוָ֑ה וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הָ⁠אֹכֶ֖לֶת מֵֽ⁠עַמֶּֽי⁠הָ׃","ki֚̇y ká̇l-ʼòké֣l ẖé֔leb min-ha֨⁠bĕ̇hémá֔h ʼàşě֨r yaqĕri֥yb mimė֛⁠ná̇h ʼişė֖̌h la⁠yhwá֑h wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ há⁠ʼòke֖leţ méֽ⁠ʻamėֽy⁠há׃"],[7,26,"וְ⁠כָל־דָּם֙ לֹ֣א תֹאכְל֔וּ בְּ⁠כֹ֖ל מוֹשְׁבֹתֵי⁠כֶ֑ם לָ⁠ע֖וֹף וְ⁠לַ⁠בְּהֵמָֽה׃","wĕ⁠kál-dá̇m֙ lò֣ʼ ţòʼkĕl֔ẇ bĕ̇⁠kò֖l mwòşĕ̌bòţéy⁠ke֑m lá⁠ʻ֖wòp wĕ⁠la⁠bĕ̇hémáֽh׃"],[7,27,"כָּל־נֶ֖פֶשׁ אֲשֶׁר־תֹּאכַ֣ל כָּל־דָּ֑ם וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מֵֽ⁠עַמֶּֽי⁠הָ׃פ","ká̇l-ne֖peş̌ ʼàşěr-ţò̇ʼka֣l ká̇l-dá֑̇m wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ méֽ⁠ʻamėֽy⁠há׃p"],[7,28,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[7,29,"דַּבֵּ֛ר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר הַ⁠מַּקְרִ֞יב אֶת־זֶ֤בַח שְׁלָמָי⁠ו֙ לַ⁠יהוָ֔ה יָבִ֧יא אֶת־קָרְבָּנ֛⁠וֹ לַ⁠יהוָ֖ה מִ⁠זֶּ֥בַח שְׁלָמָֽי⁠ו׃","dȧbé֛̇r ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r ha⁠mȧqĕri֞yb ʼeţ-ze֤baẖ şĕ̌lámáy⁠w֙ la⁠yhwá֔h yábi֧yʼ ʼeţ-qárĕbá̇n֛⁠wò la⁠yhwá֖h mi⁠zė֥baẖ şĕ̌lámáֽy⁠w׃"],[7,30,"יָדָ֣י⁠ו תְּבִיאֶ֔ינָה אֵ֖ת אִשֵּׁ֣י יְהוָ֑ה אֶת־הַ⁠חֵ֤לֶב עַל־הֶֽ⁠חָזֶה֙ יְבִיאֶ֔⁠נּוּ אֵ֣ת הֶ⁠חָזֶ֗ה לְ⁠הָנִ֥יף אֹת֛⁠וֹ תְּנוּפָ֖ה לִ⁠פְנֵ֥י יְהוָֽה׃","yádá֣y⁠w ţĕ̇biyʼe֔ynáh ʼé֖ţ ʼişé֣̇̌y yĕhwá֑h ʼeţ-ha⁠ẖé֤leb ʻal-heֽ⁠ẖázeh֙ yĕbiyʼe֔⁠ṅẇ ʼé֣ţ he⁠ẖáze֗h lĕ⁠háni֥yp ʼòţ֛⁠wò ţĕ̇nẇpá֖h li⁠pĕné֥y yĕhwáֽh׃"],[7,31,"וְ⁠הִקְטִ֧יר הַ⁠כֹּהֵ֛ן אֶת־הַ⁠חֵ֖לֶב הַ⁠מִּזְבֵּ֑חָ⁠ה וְ⁠הָיָה֙ הֶֽ⁠חָזֶ֔ה לְ⁠אַהֲרֹ֖ן וּ⁠לְ⁠בָנָֽי⁠ו׃","wĕ⁠hiqĕti֧yr ha⁠kò̇hé֛n ʼeţ-ha⁠ẖé֖leb ha⁠mi̇zĕbé֑̇ẖá⁠h wĕ⁠háyáh֙ heֽ⁠ẖáze֔h lĕ⁠ʼahàrò֖n ẇ⁠lĕ⁠bánáֽy⁠w׃"],[7,32,"וְ⁠אֵת֙ שׁ֣וֹק הַ⁠יָּמִ֔ין תִּתְּנ֥וּ תְרוּמָ֖ה לַ⁠כֹּהֵ֑ן מִ⁠זִּבְחֵ֖י שַׁלְמֵי⁠כֶֽם׃","wĕ⁠ʼéţ֙ ş֣̌wòq ha⁠yá̇mi֔yn ţi̇ţĕ̇n֥ẇ ţĕrẇmá֖h la⁠kò̇hé֑n mi⁠zi̇bĕẖé֖y şǎlĕméy⁠keֽm׃"],[7,33,"הַ⁠מַּקְרִ֞יב אֶת־דַּ֧ם הַ⁠שְּׁלָמִ֛ים וְ⁠אֶת־הַ⁠חֵ֖לֶב מִ⁠בְּנֵ֣י אַהֲרֹ֑ן ל֧⁠וֹ תִהְיֶ֛ה שׁ֥וֹק הַ⁠יָּמִ֖ין לְ⁠מָנָֽה׃","ha⁠mȧqĕri֞yb ʼeţ-dȧ֧m ha⁠şĕ̇̌lámi֛ym wĕ⁠ʼeţ-ha⁠ẖé֖leb mi⁠bĕ̇né֣y ʼahàrò֑n l֧⁠wò ţihĕye֛h ş֥̌wòq ha⁠yá̇mi֖yn lĕ⁠mánáֽh׃"],[7,34,"כִּי֩ אֶת־חֲזֵ֨ה הַ⁠תְּנוּפָ֜ה וְ⁠אֵ֣ת ׀ שׁ֣וֹק הַ⁠תְּרוּמָ֗ה לָקַ֨חְתִּי֙ מֵ⁠אֵ֣ת בְּנֵֽי־יִשְׂרָאֵ֔ל מִ⁠זִּבְחֵ֖י שַׁלְמֵי⁠הֶ֑ם וָ⁠אֶתֵּ֣ן אֹ֠תָ⁠ם לְ⁠אַהֲרֹ֨ן הַ⁠כֹּהֵ֤ן וּ⁠לְ⁠בָנָי⁠ו֙ לְ⁠חָק־עוֹלָ֔ם מֵ⁠אֵ֖ת בְּנֵ֥י יִשְׂרָאֵֽל׃","ki̇y֩ ʼeţ-ẖàzé֨h ha⁠ţĕ̇nẇpá֜h wĕ⁠ʼé֣ţ ׀ ş֣̌wòq ha⁠ţĕ̇rẇmá֗h láqa֨ẖĕţi̇y֙ mé⁠ʼé֣ţ bĕ̇néֽy-yişĕ̂ráʼé֔l mi⁠zi̇bĕẖé֖y şǎlĕméy⁠he֑m wá⁠ʼeţé֣̇n ʼò֠ţá⁠m lĕ⁠ʼahàrò֨n ha⁠kò̇hé֤n ẇ⁠lĕ⁠bánáy⁠w֙ lĕ⁠ẖáq-ʻwòlá֔m mé⁠ʼé֖ţ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[7,35,"זֹ֣את מִשְׁחַ֤ת אַהֲרֹן֙ וּ⁠מִשְׁחַ֣ת בָּנָ֔י⁠ו מֵ⁠אִשֵּׁ֖י יְהוָ֑ה בְּ⁠יוֹם֙ הִקְרִ֣יב אֹתָ֔⁠ם לְ⁠כַהֵ֖ן לַ⁠יהוָֽה׃","zò֣ʼţ mişĕ̌ẖa֤ţ ʼahàròn֙ ẇ⁠mişĕ̌ẖa֣ţ bá̇ná֔y⁠w mé⁠ʼişé֖̇̌y yĕhwá֑h bĕ̇⁠ywòm֙ hiqĕri֣yb ʼòţá֔⁠m lĕ⁠kahé֖n la⁠yhwáֽh׃"],[7,36,"אֲשֶׁר֩ צִוָּ֨ה יְהוָ֜ה לָ⁠תֵ֣ת לָ⁠הֶ֗ם בְּ⁠יוֹם֙ מָשְׁח֣⁠וֹ אֹתָ֔⁠ם מֵ⁠אֵ֖ת בְּנֵ֣י יִשְׂרָאֵ֑ל חֻקַּ֥ת עוֹלָ֖ם לְ⁠דֹרֹתָֽ⁠ם׃","ʼàşěr֩ ẕiwá̇֨h yĕhwá֜h lá⁠ţé֣ţ lá⁠he֗m bĕ̇⁠ywòm֙ máşĕ̌ẖ֣⁠wò ʼòţá֔⁠m mé⁠ʼé֖ţ bĕ̇né֣y yişĕ̂ráʼé֑l ẖuqȧ֥ţ ʻwòlá֖m lĕ⁠dòròţáֽ⁠m׃"],[7,37,"זֹ֣את הַ⁠תּוֹרָ֗ה לָֽ⁠עֹלָה֙ לַ⁠מִּנְחָ֔ה וְ⁠לַֽ⁠חַטָּ֖את וְ⁠לָ⁠אָשָׁ֑ם וְ⁠לַ֨⁠מִּלּוּאִ֔ים וּ⁠לְ⁠זֶ֖בַח הַ⁠שְּׁלָמִֽים׃","zò֣ʼţ ha⁠ţ̇wòrá֗h láֽ⁠ʻòláh֙ la⁠mi̇nĕẖá֔h wĕ⁠laֽ⁠ẖatá֖̇ʼţ wĕ⁠lá⁠ʼáşá֑̌m wĕ⁠la֨⁠mi̇l̇ẇʼi֔ym ẇ⁠lĕ⁠ze֖baẖ ha⁠şĕ̇̌lámiֽym׃"],[7,38,"אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֖ה בְּ⁠הַ֣ר סִינָ֑י בְּ⁠י֨וֹם צַוֺּת֜⁠וֹ אֶת־בְּנֵ֣י יִשְׂרָאֵ֗ל לְ⁠הַקְרִ֧יב אֶת־קָרְבְּנֵי⁠הֶ֛ם לַ⁠יהוָ֖ה בְּ⁠מִדְבַּ֥ר סִינָֽי׃פ","ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֖h bĕ̇⁠ha֣r siyná֑y bĕ̇⁠y֨wòm ẕaẇֺţ֜⁠wò ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֗l lĕ⁠haqĕri֧yb ʼeţ-qárĕbĕ̇néy⁠he֛m la⁠yhwá֖h bĕ̇⁠midĕbȧ֥r siynáֽy׃p"],[8,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[8,2,"קַ֤ח אֶֽת־אַהֲרֹן֙ וְ⁠אֶת־בָּנָ֣י⁠ו אִתּ֔⁠וֹ וְ⁠אֵת֙ הַ⁠בְּגָדִ֔ים וְ⁠אֵ֖ת שֶׁ֣מֶן הַ⁠מִּשְׁחָ֑ה וְ⁠אֵ֣ת ׀ פַּ֣ר הַֽ⁠חַטָּ֗את וְ⁠אֵת֙ שְׁנֵ֣י הָֽ⁠אֵילִ֔ים וְ⁠אֵ֖ת סַ֥ל הַ⁠מַּצּֽוֹת׃","qa֤ẖ ʼeֽţ-ʼahàròn֙ wĕ⁠ʼeţ-bá̇ná֣y⁠w ʼiţ̇֔⁠wò wĕ⁠ʼéţ֙ ha⁠bĕ̇gádi֔ym wĕ⁠ʼé֖ţ şě֣men ha⁠mi̇şĕ̌ẖá֑h wĕ⁠ʼé֣ţ ׀ pȧ֣r hֽa⁠ẖatá̇֗ʼţ wĕ⁠ʼéţ֙ şĕ̌né֣y háֽ⁠ʼéyli֔ym wĕ⁠ʼé֖ţ sa֥l ha⁠mȧẕֽ̇wòţ׃"],[8,3,"וְ⁠אֵ֥ת כָּל־הָ⁠עֵדָ֖ה הַקְהֵ֑ל אֶל־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠ʼé֥ţ ká̇l-há⁠ʻédá֖h haqĕhé֑l ʼel-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[8,4,"וַ⁠יַּ֣עַשׂ מֹשֶׁ֔ה כַּֽ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֹת֑⁠וֹ וַ⁠תִּקָּהֵל֙ הָֽ⁠עֵדָ֔ה אֶל־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wa⁠yȧ֣ʻaş̂ mòşě֔h kֽ̇a⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼòţ֑⁠wò wa⁠ţi̇qá̇hél֙ háֽ⁠ʻédá֔h ʼel-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[8,5,"וַ⁠יֹּ֥אמֶר מֹשֶׁ֖ה אֶל־הָ⁠עֵדָ֑ה זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה לַ⁠עֲשֽׂוֹת׃","wa⁠yò֥̇ʼmer mòşě֖h ʼel-há⁠ʻédá֑h ze֣h ha⁠dá̇bá֔r ʼàşěr-ẕiwá֥̇h yĕhwá֖h la⁠ʻàşֽ̂wòţ׃"],[8,6,"וַ⁠יַּקְרֵ֣ב מֹשֶׁ֔ה אֶֽת־אַהֲרֹ֖ן וְ⁠אֶת־בָּנָ֑י⁠ו וַ⁠יִּרְחַ֥ץ אֹתָ֖⁠ם בַּ⁠מָּֽיִם׃","wa⁠yȧqĕré֣b mòşě֔h ʼeֽţ-ʼahàrò֖n wĕ⁠ʼeţ-bá̇ná֑y⁠w wa⁠yi̇rĕẖa֥ẕ ʼòţá֖⁠m bȧ⁠máֽ̇yim׃"],[8,7,"וַ⁠יִּתֵּ֨ן עָלָ֜י⁠ו אֶת־הַ⁠כֻּתֹּ֗נֶת וַ⁠יַּחְגֹּ֤ר אֹת⁠וֹ֙ בָּֽ⁠אַבְנֵ֔ט וַ⁠יַּלְבֵּ֤שׁ אֹת⁠וֹ֙ אֶֽת־הַ⁠מְּעִ֔יל וַ⁠יִּתֵּ֥ן עָלָ֖י⁠ו אֶת־הָ⁠אֵפֹ֑ד וַ⁠יַּחְגֹּ֣ר אֹת֗⁠וֹ בְּ⁠חֵ֨שֶׁב֙ הָֽ⁠אֵפֹ֔ד וַ⁠יֶּאְפֹּ֥ד ל֖⁠וֹ בּֽ⁠וֹ׃","wa⁠yi̇ţé̇֨n ʻálá֜y⁠w ʼeţ-ha⁠ku̇ţò̇֗neţ wa⁠yȧẖĕgò֤̇r ʼòţ⁠wò֙ báֽ̇⁠ʼabĕné֔t wa⁠yȧlĕbé֤̇ş̌ ʼòţ⁠wò֙ ʼeֽţ-ha⁠mĕ̇ʻi֔yl wa⁠yi̇ţé֥̇n ʻálá֖y⁠w ʼeţ-há⁠ʼépò֑d wa⁠yȧẖĕgò֣̇r ʼòţ֗⁠wò bĕ̇⁠ẖé֨şěb֙ háֽ⁠ʼépò֔d wa⁠yėʼĕpò֥̇d l֖⁠wò ḃֽ⁠wò׃"],[8,8,"וַ⁠יָּ֥שֶׂם עָלָ֖י⁠ו אֶת־הַ⁠חֹ֑שֶׁן וַ⁠יִּתֵּן֙ אֶל־הַ⁠חֹ֔שֶׁן אֶת־הָ⁠אוּרִ֖ים וְ⁠אֶת־הַ⁠תֻּמִּֽים׃","wa⁠yá֥̇şêm ʻálá֖y⁠w ʼeţ-ha⁠ẖò֑şěn wa⁠yi̇ţé̇n֙ ʼel-ha⁠ẖò֔şěn ʼeţ-há⁠ʼẇri֖ym wĕ⁠ʼeţ-ha⁠ţu̇miֽ̇ym׃"],[8,9,"וַ⁠יָּ֥שֶׂם אֶת־הַ⁠מִּצְנֶ֖פֶת עַל־רֹאשׁ֑⁠וֹ וַ⁠יָּ֨שֶׂם עַֽל־הַ⁠מִּצְנֶ֜פֶת אֶל־מ֣וּל פָּנָ֗י⁠ו אֵ֣ת צִ֤יץ הַ⁠זָּהָב֙ נֵ֣זֶר הַ⁠קֹּ֔דֶשׁ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wa⁠yá֥̇şêm ʼeţ-ha⁠mi̇ẕĕne֖peţ ʻal-ròʼş֑̌⁠wò wa⁠yá̇֨şêm ʻaֽl-ha⁠mi̇ẕĕne֜peţ ʼel-m֣ẇl pá̇ná֗y⁠w ʼé֣ţ ẕi֤yẕ ha⁠zá̇háb֙ né֣zer ha⁠qò̇֔deş̌ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[8,10,"וַ⁠יִּקַּ֤ח מֹשֶׁה֙ אֶת־שֶׁ֣מֶן הַ⁠מִּשְׁחָ֔ה וַ⁠יִּמְשַׁ֥ח אֶת־הַ⁠מִּשְׁכָּ֖ן וְ⁠אֶת־כָּל־אֲשֶׁר־בּ֑⁠וֹ וַ⁠יְקַדֵּ֖שׁ אֹתָֽ⁠ם׃","wa⁠yi̇qȧ֤ẖ mòşěh֙ ʼeţ-şě֣men ha⁠mi̇şĕ̌ẖá֔h wa⁠yi̇mĕşǎ֥ẖ ʼeţ-ha⁠mi̇şĕ̌ká֖̇n wĕ⁠ʼeţ-ká̇l-ʼàşěr-ḃ֑⁠wò wa⁠yĕqadé֖̇ş̌ ʼòţáֽ⁠m׃"],[8,11,"וַ⁠יַּ֥ז מִמֶּ֛⁠נּוּ עַל־הַ⁠מִּזְבֵּ֖חַ שֶׁ֣בַע פְּעָמִ֑ים וַ⁠יִּמְשַׁ֨ח אֶת־הַ⁠מִּזְבֵּ֜חַ וְ⁠אֶת־כָּל־כֵּלָ֗י⁠ו וְ⁠אֶת־הַ⁠כִּיֹּ֛ר וְ⁠אֶת־כַּנּ֖⁠וֹ לְ⁠קַדְּשָֽׁ⁠ם׃","wa⁠yȧ֥z mimė֛⁠ṅẇ ʻal-ha⁠mi̇zĕbé֖̇ẖa şě֣baʻ pĕ̇ʻámi֑ym wa⁠yi̇mĕşǎ֨ẖ ʼeţ-ha⁠mi̇zĕbé̇֜ẖa wĕ⁠ʼeţ-ká̇l-ké̇lá֗y⁠w wĕ⁠ʼeţ-ha⁠ki̇yò֛̇r wĕ⁠ʼeţ-kȧṅ֖⁠wò lĕ⁠qadĕ̇şáֽ̌⁠m׃"],[8,12,"וַ⁠יִּצֹק֙ מִ⁠שֶּׁ֣מֶן הַ⁠מִּשְׁחָ֔ה עַ֖ל רֹ֣אשׁ אַהֲרֹ֑ן וַ⁠יִּמְשַׁ֥ח אֹת֖⁠וֹ לְ⁠קַדְּשֽׁ⁠וֹ׃","wa⁠yi̇ẕòq֙ mi⁠şė֣̌men ha⁠mi̇şĕ̌ẖá֔h ʻa֖l rò֣ʼş̌ ʼahàrò֑n wa⁠yi̇mĕşǎ֥ẖ ʼòţ֖⁠wò lĕ⁠qadĕ̇şֽ̌⁠wò׃"],[8,13,"וַ⁠יַּקְרֵ֨ב מֹשֶׁ֜ה אֶת־בְּנֵ֣י אַהֲרֹ֗ן וַ⁠יַּלְבִּשֵׁ֤⁠ם כֻּתֳּנֹת֙ וַ⁠יַּחְגֹּ֤ר אֹתָ⁠ם֙ אַבְנֵ֔ט וַ⁠יַּחֲבֹ֥שׁ לָ⁠הֶ֖ם מִגְבָּע֑וֹת כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wa⁠yȧqĕré֨b mòşě֜h ʼeţ-bĕ̇né֣y ʼahàrò֗n wa⁠yȧlĕbi̇şé֤̌⁠m ku̇ţȯnòţ֙ wa⁠yȧẖĕgò֤̇r ʼòţá⁠m֙ ʼabĕné֔t wa⁠yȧẖàbò֥ş̌ lá⁠he֖m migĕbá̇ʻ֑wòţ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[8,14,"וַ⁠יַּגֵּ֕שׁ אֵ֖ת פַּ֣ר הַֽ⁠חַטָּ֑את וַ⁠יִּסְמֹ֨ךְ אַהֲרֹ֤ן וּ⁠בָנָי⁠ו֙ אֶת־יְדֵי⁠הֶ֔ם עַל־רֹ֖אשׁ פַּ֥ר הַֽ⁠חַטָּֽאת׃","wa⁠yȧgé̇֕ş̌ ʼé֖ţ pȧ֣r haֽ⁠ẖatá֑̇ʼţ wa⁠yi̇sĕmò֨kĕ ʼahàrò֤n ẇ⁠bánáy⁠w֙ ʼeţ-yĕdéy⁠he֔m ʻal-rò֖ʼş̌ pȧ֥r hֽa⁠ẖatáֽ̇ʼţ׃"],[8,15,"וַ⁠יִּשְׁחָ֗ט וַ⁠יִּקַּ֨ח מֹשֶׁ֤ה אֶת־הַ⁠דָּם֙ וַ֠⁠יִּתֵּן עַל־קַרְנ֨וֹת הַ⁠מִּזְבֵּ֤חַ סָבִיב֙ בְּ⁠אֶצְבָּע֔⁠וֹ וַ⁠יְחַטֵּ֖א אֶת־הַ⁠מִּזְבֵּ֑חַ וְ⁠אֶת־הַ⁠דָּ֗ם יָצַק֙ אֶל־יְס֣וֹד הַ⁠מִּזְבֵּ֔חַ וַֽ⁠יְקַדְּשֵׁ֖⁠הוּ לְ⁠כַפֵּ֥ר עָלָֽי⁠ו׃","wa⁠yi̇şĕ̌ẖá֗t wa⁠yi̇qȧ֨ẖ mòşě֤h ʼeţ-ha⁠dá̇m֙ wa֠⁠yi̇ţé̇n ʻal-qarĕn֨wòţ ha⁠mi̇zĕbé֤̇ẖa sábiyb֙ bĕ̇⁠ʼeẕĕbá̇ʻ֔⁠wò wa⁠yĕẖaté֖̇ʼ ʼeţ-ha⁠mi̇zĕbé֑̇ẖa wĕ⁠ʼeţ-ha⁠dá̇֗m yáẕaq֙ ʼel-yĕs֣wòd ha⁠mi̇zĕbé̇֔ẖa waֽ⁠yĕqadĕ̇şé֖̌⁠hẇ lĕ⁠kapé֥̇r ʻáláֽy⁠w׃"],[8,16,"וַ⁠יִּקַּ֗ח אֶֽת־כָּל־הַ⁠חֵלֶב֮ אֲשֶׁ֣ר עַל־הַ⁠קֶּרֶב֒ וְ⁠אֵת֙ יֹתֶ֣רֶת הַ⁠כָּבֵ֔ד וְ⁠אֶת־שְׁתֵּ֥י הַ⁠כְּלָיֹ֖ת וְ⁠אֶֽת־חֶלְבְּ⁠הֶ֑ן וַ⁠יַּקְטֵ֥ר מֹשֶׁ֖ה הַ⁠מִּזְבֵּֽחָ⁠ה׃","wa⁠yi̇qȧ֗ẖ ʼeֽţ-ká̇l-ha⁠ẖéleb֮ ʼàşě֣r ʻal-ha⁠qėreb֒ wĕ⁠ʼéţ֙ yòţe֣reţ ha⁠ká̇bé֔d wĕ⁠ʼeţ-şĕ̌ţé֥̇y ha⁠kĕ̇láyò֖ţ wĕ⁠ʼeֽţ-ẖelĕbĕ̇⁠he֑n wa⁠yȧqĕté֥r mòşě֖h ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[8,17,"וְ⁠אֶת־הַ⁠פָּ֤ר וְ⁠אֶת־עֹר⁠וֹ֙ וְ⁠אֶת־בְּשָׂר֣⁠וֹ וְ⁠אֶת־פִּרְשׁ֔⁠וֹ שָׂרַ֣ף בָּ⁠אֵ֔שׁ מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶ֑ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wĕ⁠ʼeţ-ha⁠pá֤̇r wĕ⁠ʼeţ-ʻòr⁠wò֙ wĕ⁠ʼeţ-bĕ̇şá̂r֣⁠wò wĕ⁠ʼeţ-pi̇rĕş̌֔⁠wò şá̂ra֣p bá̇⁠ʼé֔ş̌ mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàne֑h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[8,18,"וַ⁠יַּקְרֵ֕ב אֵ֖ת אֵ֣יל הָ⁠עֹלָ֑ה וַֽ⁠יִּסְמְכ֞וּ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו אֶת־יְדֵי⁠הֶ֖ם עַל־רֹ֥אשׁ הָ⁠אָֽיִל׃","wa⁠yȧqĕré֕b ʼé֖ţ ʼé֣yl há⁠ʻòlá֑h waֽ⁠yi̇sĕmĕk֞ẇ ʼahàrò֧n ẇ⁠báná֛y⁠w ʼeţ-yĕdéy⁠he֖m ʻal-rò֥ʼş̌ há⁠ʼáֽyil׃"],[8,19,"וַ⁠יִּשְׁחָ֑ט וַ⁠יִּזְרֹ֨ק מֹשֶׁ֧ה אֶת־הַ⁠דָּ֛ם עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wa⁠yi̇şĕ̌ẖá֑t wa⁠yi̇zĕrò֨q mòşě֧h ʼeţ-ha⁠dá֛̇m ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[8,20,"וְ⁠אֶת־הָ⁠אַ֔יִל נִתַּ֖ח לִ⁠נְתָחָ֑י⁠ו וַ⁠יַּקְטֵ֤ר מֹשֶׁה֙ אֶת־הָ⁠רֹ֔אשׁ וְ⁠אֶת־הַ⁠נְּתָחִ֖ים וְ⁠אֶת־הַ⁠פָּֽדֶר׃","wĕ⁠ʼeţ-há⁠ʼa֔yil niţȧ֖ẖ li⁠nĕţáẖá֑y⁠w wa⁠yȧqĕté֤r mòşěh֙ ʼeţ-há⁠rò֔ʼş̌ wĕ⁠ʼeţ-ha⁠nĕ̇ţáẖi֖ym wĕ⁠ʼeţ-ha⁠páֽ̇der׃"],[8,21,"וְ⁠אֶת־הַ⁠קֶּ֥רֶב וְ⁠אֶת־הַ⁠כְּרָעַ֖יִם רָחַ֣ץ בַּ⁠מָּ֑יִם וַ⁠יַּקְטֵר֩ מֹשֶׁ֨ה אֶת־כָּל־הָ⁠אַ֜יִל הַ⁠מִּזְבֵּ֗חָ⁠ה עֹלָ֨ה ה֤וּא לְ⁠רֵֽיחַ־נִיחֹ֨חַ֙ אִשֶּׁ֥ה הוּא֙ לַ⁠יהוָ֔ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wĕ⁠ʼeţ-ha⁠qė֥reb wĕ⁠ʼeţ-ha⁠kĕ̇ráʻa֖yim ráẖa֣ẕ bȧ⁠má֑̇yim wa⁠yȧqĕtér֩ mòşě֨h ʼeţ-ká̇l-há⁠ʼa֜yil ha⁠mi̇zĕbé̇֗ẖá⁠h ʻòlá֨h h֤ẇʼ lĕ⁠réֽyẖa-niyẖò֨ẖa֙ ʼişė֥̌h hẇʼ֙ la⁠yhwá֔h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[8,22,"וַ⁠יַּקְרֵב֙ אֶת־הָ⁠אַ֣יִל הַ⁠שֵּׁנִ֔י אֵ֖יל הַ⁠מִּלֻּאִ֑ים וַֽ⁠יִּסְמְכ֞וּ אַהֲרֹ֧ן וּ⁠בָנָ֛י⁠ו אֶת־יְדֵי⁠הֶ֖ם עַל־רֹ֥אשׁ הָ⁠אָֽיִל׃","wa⁠yȧqĕréb֙ ʼeţ-há⁠ʼa֣yil ha⁠şé̇̌ni֔y ʼé֖yl ha⁠mi̇lu̇ʼi֑ym waֽ⁠yi̇sĕmĕk֞ẇ ʼahàrò֧n ẇ⁠báná֛y⁠w ʼeţ-yĕdéy⁠he֖m ʻal-rò֥ʼş̌ há⁠ʼáֽyil׃"],[8,23,"וַ⁠יִּשְׁחָ֓ט ׀ וַ⁠יִּקַּ֤ח מֹשֶׁה֙ מִ⁠דָּמ֔⁠וֹ וַ⁠יִּתֵּ֛ן עַל־תְּנ֥וּךְ אֹֽזֶן־אַהֲרֹ֖ן הַ⁠יְמָנִ֑ית וְ⁠עַל־בֹּ֤הֶן יָד⁠וֹ֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְל֖⁠וֹ הַ⁠יְמָנִֽית׃","wa⁠yi̇şĕ̌ẖá֓t ׀ wa⁠yi̇qȧ֤ẖ mòşěh֙ mi⁠dá̇m֔⁠wò wa⁠yi̇ţé֛̇n ʻal-ţĕ̇n֥ẇkĕ ʼòֽzen-ʼahàrò֖n ha⁠yĕmáni֑yţ wĕ⁠ʻal-bò֤̇hen yád⁠wò֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕl֖⁠wò ha⁠yĕmániֽyţ׃"],[8,24,"וַ⁠יַּקְרֵ֞ב אֶת־בְּנֵ֣י אַהֲרֹ֗ן וַ⁠יִּתֵּ֨ן מֹשֶׁ֤ה מִן־הַ⁠דָּם֙ עַל־תְּנ֤וּךְ אָזְנָ⁠ם֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֤הֶן יָדָ⁠ם֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְלָ֖⁠ם הַ⁠יְמָנִ֑ית וַ⁠יִּזְרֹ֨ק מֹשֶׁ֧ה אֶת־הַ⁠דָּ֛ם עַל־הַֽ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wa⁠yȧqĕré֞b ʼeţ-bĕ̇né֣y ʼahàrò֗n wa⁠yi̇ţé̇֨n mòşě֤h min-ha⁠dá̇m֙ ʻal-ţĕ̇n֤ẇkĕ ʼázĕná⁠m֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֤̇hen yádá⁠m֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕlá֖⁠m ha⁠yĕmáni֑yţ wa⁠yi̇zĕrò֨q mòşě֧h ʼeţ-ha⁠dá֛̇m ʻal-hֽa⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[8,25,"וַ⁠יִּקַּ֞ח אֶת־הַ⁠חֵ֣לֶב וְ⁠אֶת־הָֽ⁠אַלְיָ֗ה וְ⁠אֶֽת־כָּל־הַ⁠חֵלֶב֮ אֲשֶׁ֣ר עַל־הַ⁠קֶּרֶב֒ וְ⁠אֵת֙ יֹתֶ֣רֶת הַ⁠כָּבֵ֔ד וְ⁠אֶת־שְׁתֵּ֥י הַ⁠כְּלָיֹ֖ת וְ⁠אֶֽת־חֶלְבְּ⁠הֶ֑ן וְ⁠אֵ֖ת שׁ֥וֹק הַ⁠יָּמִֽין׃","wa⁠yi̇qȧ֞ẖ ʼeţ-ha⁠ẖé֣leb wĕ⁠ʼeţ-háֽ⁠ʼalĕyá֗h wĕ⁠ʼeֽţ-ká̇l-ha⁠ẖéleb֮ ʼàşě֣r ʻal-ha⁠qėreb֒ wĕ⁠ʼéţ֙ yòţe֣reţ ha⁠ká̇bé֔d wĕ⁠ʼeţ-şĕ̌ţé֥̇y ha⁠kĕ̇láyò֖ţ wĕ⁠ʼeֽţ-ẖelĕbĕ̇⁠he֑n wĕ⁠ʼé֖ţ ş֥̌wòq ha⁠yá̇miֽyn׃"],[8,26,"וּ⁠מִ⁠סַּ֨ל הַ⁠מַּצּ֜וֹת אֲשֶׁ֣ר ׀ לִ⁠פְנֵ֣י יְהוָ֗ה לָ֠קַח חַלַּ֨ת מַצָּ֤ה אַחַת֙ וְֽ⁠חַלַּ֨ת לֶ֥חֶם שֶׁ֛מֶן אַחַ֖ת וְ⁠רָקִ֣יק אֶחָ֑ד וַ⁠יָּ֨שֶׂם֙ עַל־הַ֣⁠חֲלָבִ֔ים וְ⁠עַ֖ל שׁ֥וֹק הַ⁠יָּמִֽין׃","ẇ⁠mi⁠sȧ֨l ha⁠mȧẕ̇֜wòţ ʼàşě֣r ׀ li⁠pĕné֣y yĕhwá֗h lá֠qaẖ ẖalȧ֨ţ maẕá֤̇h ʼaẖaţ֙ wĕֽ⁠ẖalȧ֨ţ le֥ẖem şě֛men ʼaẖa֖ţ wĕ⁠ráqi֣yq ʼeẖá֑d wa⁠yá̇֨şêm֙ ʻal-ha֣⁠ẖàlábi֔ym wĕ⁠ʻa֖l ş֥̌wòq ha⁠yá̇miֽyn׃"],[8,27,"וַ⁠יִּתֵּ֣ן אֶת־הַ⁠כֹּ֔ל עַ֚ל כַּפֵּ֣י אַהֲרֹ֔ן וְ⁠עַ֖ל כַּפֵּ֣י בָנָ֑י⁠ו וַ⁠יָּ֧נֶף אֹתָ֛⁠ם תְּנוּפָ֖ה לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yi̇ţé֣̇n ʼeţ-ha⁠kò̇֔l ʻa֚l kȧpé֣̇y ʼahàrò֔n wĕ⁠ʻa֖l kȧpé֣̇y báná֑y⁠w wa⁠yá֧̇nep ʼòţá֛⁠m ţĕ̇nẇpá֖h li⁠pĕné֥y yĕhwáֽh׃"],[8,28,"וַ⁠יִּקַּ֨ח מֹשֶׁ֤ה אֹתָ⁠ם֙ מֵ⁠עַ֣ל כַּפֵּי⁠הֶ֔ם וַ⁠יַּקְטֵ֥ר הַ⁠מִּזְבֵּ֖חָ⁠ה עַל־הָ⁠עֹלָ֑ה מִלֻּאִ֥ים הֵם֙ לְ⁠רֵ֣יחַ נִיחֹ֔חַ אִשֶּׁ֥ה ה֖וּא לַ⁠יהוָֽה׃","wa⁠yi̇qȧ֨ẖ mòşě֤h ʼòţá⁠m֙ mé⁠ʻa֣l kȧpé̇y⁠he֔m wa⁠yȧqĕté֥r ha⁠mi̇zĕbé֖̇ẖá⁠h ʻal-há⁠ʻòlá֑h milu̇ʼi֥ym hém֙ lĕ⁠ré֣yẖa niyẖò֔ẖa ʼişė֥̌h h֖ẇʼ la⁠yhwáֽh׃"],[8,29,"וַ⁠יִּקַּ֤ח מֹשֶׁה֙ אֶת־הֶ֣⁠חָזֶ֔ה וַ⁠יְנִיפֵ֥⁠הוּ תְנוּפָ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה מֵ⁠אֵ֣יל הַ⁠מִּלֻּאִ֗ים לְ⁠מֹשֶׁ֤ה הָיָה֙ לְ⁠מָנָ֔ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wa⁠yi̇qȧ֤ẖ mòşěh֙ ʼeţ-he֣⁠ẖáze֔h wa⁠yĕniypé֥⁠hẇ ţĕnẇpá֖h li⁠pĕné֣y yĕhwá֑h mé⁠ʼé֣yl ha⁠mi̇lu̇ʼi֗ym lĕ⁠mòşě֤h háyáh֙ lĕ⁠máná֔h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[8,30,"וַ⁠יִּקַּ֨ח מֹשֶׁ֜ה מִ⁠שֶּׁ֣מֶן הַ⁠מִּשְׁחָ֗ה וּ⁠מִן־הַ⁠דָּם֮ אֲשֶׁ֣ר עַל־הַ⁠מִּזְבֵּחַ֒ וַ⁠יַּ֤ז עַֽל־אַהֲרֹן֙ עַל־בְּגָדָ֔י⁠ו וְ⁠עַל־בָּנָ֛י⁠ו וְ⁠עַל־בִּגְדֵ֥י בָנָ֖י⁠ו אִתּ֑⁠וֹ וַ⁠יְקַדֵּ֤שׁ אֶֽת־אַהֲרֹן֙ אֶת־בְּגָדָ֔י⁠ו וְ⁠אֶת־בָּנָ֛י⁠ו וְ⁠אֶת־בִּגְדֵ֥י בָנָ֖י⁠ו אִתּֽ⁠וֹ׃","wa⁠yi̇qȧ֨ẖ mòşě֜h mi⁠şė֣̌men ha⁠mi̇şĕ̌ẖá֗h ẇ⁠min-ha⁠dá̇m֮ ʼàşě֣r ʻal-ha⁠mi̇zĕbé̇ẖa֒ wa⁠yȧ֤z ʻaֽl-ʼahàròn֙ ʻal-bĕ̇gádá֔y⁠w wĕ⁠ʻal-bá̇ná֛y⁠w wĕ⁠ʻal-bi̇gĕdé֥y báná֖y⁠w ʼiţ֑̇⁠wò wa⁠yĕqadé֤̇ş̌ ʼeֽţ-ʼahàròn֙ ʼeţ-bĕ̇gádá֔y⁠w wĕ⁠ʼeţ-bá̇ná֛y⁠w wĕ⁠ʼeţ-bi̇gĕdé֥y báná֖y⁠w ʼiţֽ̇⁠wò׃"],[8,31,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶל־אַהֲרֹ֣ן וְ⁠אֶל־בָּנָ֗י⁠ו בַּשְּׁל֣וּ אֶת־הַ⁠בָּשָׂר֮ פֶּ֣תַח אֹ֣הֶל מוֹעֵד֒ וְ⁠שָׁם֙ תֹּאכְל֣וּ אֹת֔⁠וֹ וְ⁠אֶ֨ת־הַ⁠לֶּ֔חֶם אֲשֶׁ֖ר בְּ⁠סַ֣ל הַ⁠מִּלֻּאִ֑ים כַּ⁠אֲשֶׁ֤ר צִוֵּ֨יתִי֙ לֵ⁠אמֹ֔ר אַהֲרֹ֥ן וּ⁠בָנָ֖י⁠ו יֹאכְלֻֽ⁠הוּ׃","wa⁠yò̇֨ʼmer mòşě֜h ʼel-ʼahàrò֣n wĕ⁠ʼel-bá̇ná֗y⁠w bȧşĕ̇̌l֣ẇ ʼeţ-ha⁠bá̇şá̂r֮ pė֣ţaẖ ʼò֣hel mwòʻéd֒ wĕ⁠şá̌m֙ ţò̇ʼkĕl֣ẇ ʼòţ֔⁠wò wĕ⁠ʼe֨ţ-ha⁠lė֔ẖem ʼàşě֖r bĕ̇⁠sa֣l ha⁠mi̇lu̇ʼi֑ym kȧ⁠ʼàşě֤r ẕiwé̇֨yţiy֙ lé⁠ʼmò֔r ʼahàrò֥n ẇ⁠báná֖y⁠w yòʼkĕluֽ⁠hẇ׃"],[8,32,"וְ⁠הַ⁠נּוֹתָ֥ר בַּ⁠בָּשָׂ֖ר וּ⁠בַ⁠לָּ֑חֶם בָּ⁠אֵ֖שׁ תִּשְׂרֹֽפוּ׃","wĕ⁠ha⁠ṅwòţá֥r bȧ⁠bá̇şá֖̂r ẇ⁠ba⁠lá֑̇ẖem bá̇⁠ʼé֖ş̌ ţi̇şĕ̂ròֽpẇ׃"],[8,33,"וּ⁠מִ⁠פֶּתַח֩ אֹ֨הֶל מוֹעֵ֜ד לֹ֤א תֵֽצְאוּ֙ שִׁבְעַ֣ת יָמִ֔ים עַ֚ד י֣וֹם מְלֹ֔את יְמֵ֖י מִלֻּאֵי⁠כֶ֑ם כִּ֚י שִׁבְעַ֣ת יָמִ֔ים יְמַלֵּ֖א אֶת־יֶדְ⁠כֶֽם׃","ẇ⁠mi⁠pėţaẖ֩ ʼò֨hel mwòʻé֜d lò֤ʼ ţéֽẕĕʼẇ֙ şǐbĕʻa֣ţ yámi֔ym ʻa֚d y֣wòm mĕlò֔ʼţ yĕmé֖y milu̇ʼéy⁠ke֑m ki֚̇y şǐbĕʻa֣ţ yámi֔ym yĕmalé֖̇ʼ ʼeţ-yedĕ⁠keֽm׃"],[8,34,"כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה בַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה צִוָּ֧ה יְהוָ֛ה לַ⁠עֲשֹׂ֖ת לְ⁠כַפֵּ֥ר עֲלֵי⁠כֶֽם׃","kȧ⁠ʼàşě֥r ʻáşá֖̂h bȧ⁠ẏ֣wòm ha⁠zė֑h ẕiwá֧̇h yĕhwá֛h la⁠ʻàşò֖̂ţ lĕ⁠kapé֥̇r ʻàléy⁠keֽm׃"],[8,35,"וּ⁠פֶתַח֩ אֹ֨הֶל מוֹעֵ֜ד תֵּשְׁב֨וּ יוֹמָ֤ם וָ⁠לַ֨יְלָה֙ שִׁבְעַ֣ת יָמִ֔ים וּ⁠שְׁמַרְתֶּ֛ם אֶת־מִשְׁמֶ֥רֶת יְהוָ֖ה וְ⁠לֹ֣א תָמ֑וּתוּ כִּי־כֵ֖ן צֻוֵּֽיתִי׃","ẇ⁠peţaẖ֩ ʼò֨hel mwòʻé֜d ţé̇şĕ̌b֨ẇ ywòmá֤m wá⁠la֨yĕláh֙ şǐbĕʻa֣ţ yámi֔ym ẇ⁠şĕ̌marĕţė֛m ʼeţ-mişĕ̌me֥reţ yĕhwá֖h wĕ⁠lò֣ʼ ţám֑ẇţẇ ki̇y-ké֖n ẕuwéֽ̇yţiy׃"],[8,36,"וַ⁠יַּ֥עַשׂ אַהֲרֹ֖ן וּ⁠בָנָ֑י⁠ו אֵ֚ת כָּל־הַ⁠דְּבָרִ֔ים אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה בְּ⁠יַד־מֹשֶֽׁה׃ס","wa⁠yȧ֥ʻaş̂ ʼahàrò֖n ẇ⁠báná֑y⁠w ʼé֚ţ ká̇l-ha⁠dĕ̇bári֔ym ʼàşěr-ẕiwá֥̇h yĕhwá֖h bĕ̇⁠yad-mòşěֽh׃s"],[9,1,"וַ⁠יְהִי֙ בַּ⁠יּ֣וֹם הַ⁠שְּׁמִינִ֔י קָרָ֣א מֹשֶׁ֔ה לְ⁠אַהֲרֹ֖ן וּ⁠לְ⁠בָנָ֑י⁠ו וּ⁠לְ⁠זִקְנֵ֖י יִשְׂרָאֵֽל׃","wa⁠yĕhiy֙ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌miyni֔y qárá֣ʼ mòşě֔h lĕ⁠ʼahàrò֖n ẇ⁠lĕ⁠báná֑y⁠w ẇ⁠lĕ⁠ziqĕné֖y yişĕ̂ráʼéֽl׃"],[9,2,"וַ⁠יֹּ֣אמֶר אֶֽל־אַהֲרֹ֗ן קַח־לְ֠⁠ךָ עֵ֣גֶל בֶּן־בָּקָ֧ר לְ⁠חַטָּ֛את וְ⁠אַ֥יִל לְ⁠עֹלָ֖ה תְּמִימִ֑ם וְ⁠הַקְרֵ֖ב לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yò֣̇ʼmer ʼeֽl-ʼahàrò֗n qaẖ-lĕ֠⁠ká ʻé֣gel bėn-bá̇qá֧r lĕ⁠ẖatá֛̇ʼţ wĕ⁠ʼa֥yil lĕ⁠ʻòlá֖h ţĕ̇miymi֑m wĕ⁠haqĕré֖b li⁠pĕné֥y yĕhwáֽh׃"],[9,3,"וְ⁠אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל תְּדַבֵּ֣ר לֵ⁠אמֹ֑ר קְח֤וּ שְׂעִיר־עִזִּים֙ לְ⁠חַטָּ֔את וְ⁠עֵ֨גֶל וָ⁠כֶ֧בֶשׂ בְּנֵי־שָׁנָ֛ה תְּמִימִ֖ם לְ⁠עֹלָֽה׃","wĕ⁠ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l ţĕ̇dabé֣̇r lé⁠ʼmò֑r qĕẖ֤ẇ şĕ̂ʻiyr-ʻizi̇ym֙ lĕ⁠ẖatá̇֔ʼţ wĕ⁠ʻé֨gel wá⁠ke֧beş̂ bĕ̇néy-şá̌ná֛h ţĕ̇miymi֖m lĕ⁠ʻòláֽh׃"],[9,4,"וְ⁠שׁ֨וֹר וָ⁠אַ֜יִל לִ⁠שְׁלָמִ֗ים לִ⁠זְבֹּ֨חַ֙ לִ⁠פְנֵ֣י יְהוָ֔ה וּ⁠מִנְחָ֖ה בְּלוּלָ֣ה בַ⁠שָּׁ֑מֶן כִּ֣י הַ⁠יּ֔וֹם יְהוָ֖ה נִרְאָ֥ה אֲלֵי⁠כֶֽם׃","wĕ⁠ş̌֨wòr wá⁠ʼa֜yil li⁠şĕ̌lámi֗ym li⁠zĕbò̇֨ẖa֙ li⁠pĕné֣y yĕhwá֔h ẇ⁠minĕẖá֖h bĕ̇lẇlá֣h ba⁠şá֑̇̌men ki֣̇y ha⁠ẏ֔wòm yĕhwá֖h nirĕʼá֥h ʼàléy⁠keֽm׃"],[9,5,"וַ⁠יִּקְח֗וּ אֵ֚ת אֲשֶׁ֣ר צִוָּ֣ה מֹשֶׁ֔ה אֶל־פְּנֵ֖י אֹ֣הֶל מוֹעֵ֑ד וַֽ⁠יִּקְרְבוּ֙ כָּל־הָ֣⁠עֵדָ֔ה וַ⁠יַּֽעַמְד֖וּ לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yi̇qĕẖ֗ẇ ʼé֚ţ ʼàşě֣r ẕiwá֣̇h mòşě֔h ʼel-pĕ̇né֖y ʼò֣hel mwòʻé֑d waֽ⁠yi̇qĕrĕbẇ֙ ká̇l-há֣⁠ʻédá֔h wa⁠yȧֽʻamĕd֖ẇ li⁠pĕné֥y yĕhwáֽh׃"],[9,6,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֔ה זֶ֧ה הַ⁠דָּבָ֛ר אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה תַּעֲשׂ֑וּ וְ⁠יֵרָ֥א אֲלֵי⁠כֶ֖ם כְּב֥וֹד יְהוָֽה׃","wa⁠yò֣̇ʼmer mòşě֔h ze֧h ha⁠dá̇bá֛r ʼàşěr-ẕiwá֥̇h yĕhwá֖h ţȧʻàş֑̂ẇ wĕ⁠yérá֥ʼ ʼàléy⁠ke֖m kĕ̇b֥wòd yĕhwáֽh׃"],[9,7,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶֽל־אַהֲרֹ֗ן קְרַ֤ב אֶל־הַ⁠מִּזְבֵּ֨חַ֙ וַ⁠עֲשֵׂ֞ה אֶת־חַטָּֽאתְ⁠ךָ֙ וְ⁠אֶת־עֹ֣לָתֶ֔⁠ךָ וְ⁠כַפֵּ֥ר בַּֽעַדְ⁠ךָ֖ וּ⁠בְעַ֣ד הָ⁠עָ֑ם וַ⁠עֲשֵׂ֞ה אֶת־קָרְבַּ֤ן הָ⁠עָם֙ וְ⁠כַפֵּ֣ר בַּֽעֲדָ֔⁠ם כַּ⁠אֲשֶׁ֖ר צִוָּ֥ה יְהוָֽה׃","wa⁠yò̇֨ʼmer mòşě֜h ʼeֽl-ʼahàrò֗n qĕra֤b ʼel-ha⁠mi̇zĕbé̇֨ẖa֙ wa⁠ʻàşé̂֞h ʼeţ-ẖatáֽ̇ʼţĕ⁠ká֙ wĕ⁠ʼeţ-ʻò֣láţe֔⁠ká wĕ⁠kapé֥̇r bȧֽʻadĕ⁠ká֖ ẇ⁠bĕʻa֣d há⁠ʻá֑m wa⁠ʻàşé̂֞h ʼeţ-qárĕbȧ֤n há⁠ʻám֙ wĕ⁠kapé֣̇r ḃֽaʻàdá֔⁠m kȧ⁠ʼàşě֖r ẕiwá֥̇h yĕhwáֽh׃"],[9,8,"וַ⁠יִּקְרַ֥ב אַהֲרֹ֖ן אֶל־הַ⁠מִּזְבֵּ֑חַ וַ⁠יִּשְׁחַ֛ט אֶת־עֵ֥גֶל הַ⁠חַטָּ֖את אֲשֶׁר־לֽ⁠וֹ׃","wa⁠yi̇qĕra֥b ʼahàrò֖n ʼel-ha⁠mi̇zĕbé֑̇ẖa wa⁠yi̇şĕ̌ẖa֛t ʼeţ-ʻé֥gel ha⁠ẖatá֖̇ʼţ ʼàşěr-lֽ⁠wò׃"],[9,9,"וַ֠⁠יַּקְרִבוּ בְּנֵ֨י אַהֲרֹ֣ן אֶת־הַ⁠דָּם֮ אֵלָי⁠ו֒ וַ⁠יִּטְבֹּ֤ל אֶצְבָּע⁠וֹ֙ בַּ⁠דָּ֔ם וַ⁠יִּתֵּ֖ן עַל־קַרְנ֣וֹת הַ⁠מִּזְבֵּ֑חַ וְ⁠אֶת־הַ⁠דָּ֣ם יָצַ֔ק אֶל־יְס֖וֹד הַ⁠מִּזְבֵּֽחַ׃","wa֠⁠yȧqĕribẇ bĕ̇né֨y ʼahàrò֣n ʼeţ-ha⁠dá̇m֮ ʼéláy⁠w֒ wa⁠yi̇tĕbò֤̇l ʼeẕĕbá̇ʻ⁠wò֙ bȧ⁠dá̇֔m wa⁠yi̇ţé֖̇n ʻal-qarĕn֣wòţ ha⁠mi̇zĕbé֑̇ẖa wĕ⁠ʼeţ-ha⁠dá֣̇m yáẕa֔q ʼel-yĕs֖wòd ha⁠mi̇zĕbéֽ̇ẖa׃"],[9,10,"וְ⁠אֶת־הַ⁠חֵ֨לֶב וְ⁠אֶת־הַ⁠כְּלָיֹ֜ת וְ⁠אֶת־הַ⁠יֹּתֶ֤רֶת מִן־הַ⁠כָּבֵד֙ מִן־הַ֣⁠חַטָּ֔את הִקְטִ֖יר הַ⁠מִּזְבֵּ֑חָ⁠ה כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wĕ⁠ʼeţ-ha⁠ẖé֨leb wĕ⁠ʼeţ-ha⁠kĕ̇láyò֜ţ wĕ⁠ʼeţ-ha⁠yò̇ţe֤reţ min-ha⁠ká̇béd֙ min-ha֣⁠ẖatá̇֔ʼţ hiqĕti֖yr ha⁠mi̇zĕbé֑̇ẖá⁠h kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[9,11,"וְ⁠אֶת־הַ⁠בָּשָׂ֖ר וְ⁠אֶת־הָ⁠ע֑וֹר שָׂרַ֣ף בָּ⁠אֵ֔שׁ מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶֽה׃","wĕ⁠ʼeţ-ha⁠bá̇şá֖̂r wĕ⁠ʼeţ-há⁠ʻ֑wòr şá̂ra֣p bá̇⁠ʼé֔ş̌ mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàneֽh׃"],[9,12,"וַ⁠יִּשְׁחַ֖ט אֶת־הָ⁠עֹלָ֑ה וַ֠⁠יַּמְצִאוּ בְּנֵ֨י אַהֲרֹ֤ן אֵלָי⁠ו֙ אֶת־הַ⁠דָּ֔ם וַ⁠יִּזְרְקֵ֥⁠הוּ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wa⁠yi̇şĕ̌ẖa֖t ʼeţ-há⁠ʻòlá֑h wa֠⁠yȧmĕẕiʼẇ bĕ̇né֨y ʼahàrò֤n ʼéláy⁠w֙ ʼeţ-ha⁠dá̇֔m wa⁠yi̇zĕrĕqé֥⁠hẇ ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[9,13,"וְ⁠אֶת־הָ⁠עֹלָ֗ה הִמְצִ֧יאוּ אֵלָ֛י⁠ו לִ⁠נְתָחֶ֖י⁠הָ וְ⁠אֶת־הָ⁠רֹ֑אשׁ וַ⁠יַּקְטֵ֖ר עַל־הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠ʼeţ-há⁠ʻòlá֗h himĕẕi֧yʼẇ ʼélá֛y⁠w li⁠nĕţáẖe֖y⁠há wĕ⁠ʼeţ-há⁠rò֑ʼş̌ wa⁠yȧqĕté֖r ʻal-ha⁠mi̇zĕbéֽ̇ẖa׃"],[9,14,"וַ⁠יִּרְחַ֥ץ אֶת־הַ⁠קֶּ֖רֶב וְ⁠אֶת־הַ⁠כְּרָעָ֑יִם וַ⁠יַּקְטֵ֥ר עַל־הָ⁠עֹלָ֖ה הַ⁠מִּזְבֵּֽחָ⁠ה׃","wa⁠yi̇rĕẖa֥ẕ ʼeţ-ha⁠qė֖reb wĕ⁠ʼeţ-ha⁠kĕ̇ráʻá֑yim wa⁠yȧqĕté֥r ʻal-há⁠ʻòlá֖h ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[9,15,"וַ⁠יַּקְרֵ֕ב אֵ֖ת קָרְבַּ֣ן הָ⁠עָ֑ם וַ⁠יִּקַּ֞ח אֶת־שְׂעִ֤יר הַֽ⁠חַטָּאת֙ אֲשֶׁ֣ר לָ⁠עָ֔ם וַ⁠יִּשְׁחָטֵ֥⁠הוּ וַֽ⁠יְחַטְּאֵ֖⁠הוּ כָּ⁠רִאשֽׁוֹן׃","wa⁠yȧqĕré֕b ʼé֖ţ qárĕbȧ֣n há⁠ʻá֑m wa⁠yi̇qȧ֞ẖ ʼeţ-şĕ̂ʻi֤yr haֽ⁠ẖatá̇ʼţ֙ ʼàşě֣r lá⁠ʻá֔m wa⁠yi̇şĕ̌ẖáté֥⁠hẇ waֽ⁠yĕẖatĕ̇ʼé֖⁠hẇ ká̇⁠riʼşֽ̌wòn׃"],[9,16,"וַ⁠יַּקְרֵ֖ב אֶת־הָ⁠עֹלָ֑ה וַֽ⁠יַּעֲשֶׂ֖⁠הָ כַּ⁠מִּשְׁפָּֽט׃","wa⁠yȧqĕré֖b ʼeţ-há⁠ʻòlá֑h waֽ⁠yȧʻàşê֖⁠há kȧ⁠mi̇şĕ̌páֽ̇t׃"],[9,17,"וַ⁠יַּקְרֵב֮ אֶת־הַ⁠מִּנְחָה֒ וַ⁠יְמַלֵּ֤א כַפּ⁠וֹ֙ מִמֶּ֔⁠נָּה וַ⁠יַּקְטֵ֖ר עַל־הַ⁠מִּזְבֵּ֑חַ מִ⁠לְּ⁠בַ֖ד עֹלַ֥ת הַ⁠בֹּֽקֶר׃","wa⁠yȧqĕréb֮ ʼeţ-ha⁠mi̇nĕẖáh֒ wa⁠yĕmalé֤̇ʼ kaṗ⁠wò֙ mimė֔⁠ná̇h wa⁠yȧqĕté֖r ʻal-ha⁠mi̇zĕbé֑̇ẖa mi⁠lĕ̇⁠ba֖d ʻòla֥ţ ha⁠bòֽ̇qer׃"],[9,18,"וַ⁠יִּשְׁחַ֤ט אֶת־הַ⁠שּׁוֹר֙ וְ⁠אֶת־הָ⁠אַ֔יִל זֶ֥בַח הַ⁠שְּׁלָמִ֖ים אֲשֶׁ֣ר לָ⁠עָ֑ם וַ֠⁠יַּמְצִאוּ בְּנֵ֨י אַהֲרֹ֤ן אֶת־הַ⁠דָּם֙ אֵלָ֔י⁠ו וַ⁠יִּזְרְקֵ֥⁠הוּ עַל־הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wa⁠yi̇şĕ̌ẖa֤t ʼeţ-ha⁠ş̇̌wòr֙ wĕ⁠ʼeţ-há⁠ʼa֔yil ze֥baẖ ha⁠şĕ̇̌lámi֖ym ʼàşě֣r lá⁠ʻá֑m wa֠⁠yȧmĕẕiʼẇ bĕ̇né֨y ʼahàrò֤n ʼeţ-ha⁠dá̇m֙ ʼélá֔y⁠w wa⁠yi̇zĕrĕqé֥⁠hẇ ʻal-ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[9,19,"וְ⁠אֶת־הַ⁠חֲלָבִ֖ים מִן־הַ⁠שּׁ֑וֹר וּ⁠מִן־הָ⁠אַ֔יִל הָֽ⁠אַלְיָ֤ה וְ⁠הַֽ⁠מְכַסֶּה֙ וְ⁠הַ⁠כְּלָיֹ֔ת וְ⁠יֹתֶ֖רֶת הַ⁠כָּבֵֽד׃","wĕ⁠ʼeţ-ha⁠ẖàlábi֖ym min-ha⁠ş֑̇̌wòr ẇ⁠min-há⁠ʼa֔yil háֽ⁠ʼalĕyá֤h wĕ⁠haֽ⁠mĕkasėh֙ wĕ⁠ha⁠kĕ̇láyò֔ţ wĕ⁠yòţe֖reţ ha⁠ká̇béֽd׃"],[9,20,"וַ⁠יָּשִׂ֥ימוּ אֶת־הַ⁠חֲלָבִ֖ים עַל־הֶ⁠חָז֑וֹת וַ⁠יַּקְטֵ֥ר הַ⁠חֲלָבִ֖ים הַ⁠מִּזְבֵּֽחָ⁠ה׃","wa⁠yá̇şî֥ymẇ ʼeţ-ha⁠ẖàlábi֖ym ʻal-he⁠ẖáz֑wòţ wa⁠yȧqĕté֥r ha⁠ẖàlábi֖ym ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[9,21,"וְ⁠אֵ֣ת הֶ⁠חָז֗וֹת וְ⁠אֵת֙ שׁ֣וֹק הַ⁠יָּמִ֔ין הֵנִ֧יף אַהֲרֹ֛ן תְּנוּפָ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה כַּ⁠אֲשֶׁ֖ר צִוָּ֥ה מֹשֶֽׁה׃","wĕ⁠ʼé֣ţ he⁠ẖáz֗wòţ wĕ⁠ʼéţ֙ ş֣̌wòq ha⁠yá̇mi֔yn héni֧yp ʼahàrò֛n ţĕ̇nẇpá֖h li⁠pĕné֣y yĕhwá֑h kȧ⁠ʼàşě֖r ẕiwá֥̇h mòşěֽh׃"],[9,22,"וַ⁠יִּשָּׂ֨א אַהֲרֹ֧ן אֶת־יד⁠ו אֶל־הָ⁠עָ֖ם וַֽ⁠יְבָרְכֵ֑⁠ם וַ⁠יֵּ֗רֶד מֵ⁠עֲשֹׂ֧ת הַֽ⁠חַטָּ֛את וְ⁠הָ⁠עֹלָ֖ה וְ⁠הַ⁠שְּׁלָמִֽים׃","wa⁠yi̇şá̇̂֨ʼ ʼahàrò֧n ʼeţ-yd⁠w ʼel-há⁠ʻá֖m waֽ⁠yĕbárĕké֑⁠m wa⁠yé̇֗red mé⁠ʻàşò֧̂ţ haֽ⁠ẖatá֛̇ʼţ wĕ⁠há⁠ʻòlá֖h wĕ⁠ha⁠şĕ̇̌lámiֽym׃"],[9,23,"וַ⁠יָּבֹ֨א מֹשֶׁ֤ה וְ⁠אַהֲרֹן֙ אֶל־אֹ֣הֶל מוֹעֵ֔ד וַ⁠יֵּ֣צְא֔וּ וַֽ⁠יְבָרֲכ֖וּ אֶת־הָ⁠עָ֑ם וַ⁠יֵּרָ֥א כְבוֹד־יְהוָ֖ה אֶל־כָּל־הָ⁠עָֽם׃","wa⁠yá̇bò֨ʼ mòşě֤h wĕ⁠ʼahàròn֙ ʼel-ʼò֣hel mwòʻé֔d wa⁠yé֣̇ẕĕʼ֔ẇ waֽ⁠yĕbáràk֖ẇ ʼeţ-há⁠ʻá֑m wa⁠yé̇rá֥ʼ kĕbwòd-yĕhwá֖h ʼel-ká̇l-há⁠ʻáֽm׃"],[9,24,"וַ⁠תֵּ֤צֵא אֵשׁ֙ מִ⁠לִּ⁠פְנֵ֣י יְהוָ֔ה וַ⁠תֹּ֨אכַל֙ עַל־הַ⁠מִּזְבֵּ֔חַ אֶת־הָ⁠עֹלָ֖ה וְ⁠אֶת־הַ⁠חֲלָבִ֑ים וַ⁠יַּ֤רְא כָּל־הָ⁠עָם֙ וַ⁠יָּרֹ֔נּוּ וַֽ⁠יִּפְּל֖וּ עַל־פְּנֵי⁠הֶֽם׃","wa⁠ţé֤̇ẕéʼ ʼéş̌֙ mi⁠li̇⁠pĕné֣y yĕhwá֔h wa⁠ţò̇֨ʼkal֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa ʼeţ-há⁠ʻòlá֖h wĕ⁠ʼeţ-ha⁠ẖàlábi֑ym wa⁠yȧ֤rĕʼ ká̇l-há⁠ʻám֙ wa⁠yá̇rò֔ṅẇ waֽ⁠yi̇pĕ̇l֖ẇ ʻal-pĕ̇néy⁠heֽm׃"],[10,1,"וַ⁠יִּקְח֣וּ בְנֵֽי־אַ֠הֲרֹן נָדָ֨ב וַ⁠אֲבִיה֜וּא אִ֣ישׁ מַחְתָּת֗⁠וֹ וַ⁠יִּתְּנ֤וּ בָ⁠הֵן֙ אֵ֔שׁ וַ⁠יָּשִׂ֥ימוּ עָלֶ֖י⁠הָ קְטֹ֑רֶת וַ⁠יַּקְרִ֜בוּ לִ⁠פְנֵ֤י יְהוָה֙ אֵ֣שׁ זָרָ֔ה אֲשֶׁ֧ר לֹ֦א צִוָּ֖ה אֹתָֽ⁠ם׃","wa⁠yi̇qĕẖ֣ẇ bĕnéֽy-ʼa֠hàròn nádá֨b wa⁠ʼàbiyh֜ẇʼ ʼi֣yş̌ maẖĕţá̇ţ֗⁠wò wa⁠yi̇ţĕ̇n֤ẇ bá⁠hén֙ ʼé֔ş̌ wa⁠yá̇şî֥ymẇ ʻále֖y⁠há qĕtò֑reţ wa⁠yȧqĕri֜bẇ li⁠pĕné֤y yĕhwáh֙ ʼé֣ş̌ zárá֔h ʼàşě֧r lò֦ʼ ẕiwá֖̇h ʼòţáֽ⁠m׃"],[10,2,"וַ⁠תֵּ֥צֵא אֵ֛שׁ מִ⁠לִּ⁠פְנֵ֥י יְהוָ֖ה וַ⁠תֹּ֣אכַל אוֹתָ֑⁠ם וַ⁠יָּמֻ֖תוּ לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠ţé֥̇ẕéʼ ʼé֛ş̌ mi⁠li̇⁠pĕné֥y yĕhwá֖h wa⁠ţò֣̇ʼkal ʼwòţá֑⁠m wa⁠yá̇mu֖ţẇ li⁠pĕné֥y yĕhwáֽh׃"],[10,3,"וַ⁠יֹּ֨אמֶר מֹשֶׁ֜ה אֶֽל־אַהֲרֹ֗ן הוּא֩ אֲשֶׁר־דִּבֶּ֨ר יְהוָ֤ה ׀ לֵ⁠אמֹר֙ בִּ⁠קְרֹבַ֣⁠י אֶקָּדֵ֔שׁ וְ⁠עַל־פְּנֵ֥י כָל־הָ⁠עָ֖ם אֶכָּבֵ֑ד וַ⁠יִּדֹּ֖ם אַהֲרֹֽן׃","wa⁠yò̇֨ʼmer mòşě֜h ʼeֽl-ʼahàrò֗n hẇʼ֩ ʼàşěr-di̇bė֨r yĕhwá֤h ׀ lé⁠ʼmòr֙ bi̇⁠qĕròba֣⁠y ʼeqá̇dé֔ş̌ wĕ⁠ʻal-pĕ̇né֥y kál-há⁠ʻá֖m ʼeká̇bé֑d wa⁠yi̇dò֖̇m ʼahàròֽn׃"],[10,4,"וַ⁠יִּקְרָ֣א מֹשֶׁ֗ה אֶל־מִֽישָׁאֵל֙ וְ⁠אֶ֣ל אֶלְצָפָ֔ן בְּנֵ֥י עֻזִּיאֵ֖ל דֹּ֣ד אַהֲרֹ֑ן וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם קִ֠רְב֞וּ שְׂא֤וּ אֶת־אֲחֵי⁠כֶם֙ מֵ⁠אֵ֣ת פְּנֵי־הַ⁠קֹּ֔דֶשׁ אֶל־מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶֽה׃","wa⁠yi̇qĕrá֣ʼ mòşě֗h ʼel-miֽyşá̌ʼél֙ wĕ⁠ʼe֣l ʼelĕẕápá֔n bĕ̇né֥y ʻuzi̇yʼé֖l dò֣̇d ʼahàrò֑n wa⁠yò֣̇ʼmer ʼàlé⁠he֗m qi֠rĕb֞ẇ şĕ̂ʼ֤ẇ ʼeţ-ʼàẖéy⁠kem֙ mé⁠ʼé֣ţ pĕ̇néy-ha⁠qò̇֔deş̌ ʼel-mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàneֽh׃"],[10,5,"וַֽ⁠יִּקְרְב֗וּ וַ⁠יִּשָּׂאֻ⁠ם֙ בְּ⁠כֻתֳּנֹתָ֔⁠ם אֶל־מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶ֑ה כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר מֹשֶֽׁה׃","waֽ⁠yi̇qĕrĕb֗ẇ wa⁠yi̇şá̇̂ʼu⁠m֙ bĕ̇⁠kuţȯnòţá֔⁠m ʼel-mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàne֑h kȧ⁠ʼàşě֖r di̇bė֥r mòşěֽh׃"],[10,6,"וַ⁠יֹּ֣אמֶר מֹשֶׁ֣ה אֶֽל־אַהֲרֹ֡ן וּ⁠לְ⁠אֶלְעָזָר֩ וּ⁠לְ⁠אִֽיתָמָ֨ר ׀ בָּנָ֜י⁠ו רָֽאשֵׁי⁠כֶ֥ם אַל־תִּפְרָ֣עוּ ׀ וּ⁠בִגְדֵי⁠כֶ֤ם לֹֽא־תִפְרֹ֨מוּ֙ וְ⁠לֹ֣א תָמֻ֔תוּ וְ⁠עַ֥ל כָּל־הָ⁠עֵדָ֖ה יִקְצֹ֑ף וַ⁠אֲחֵי⁠כֶם֙ כָּל־בֵּ֣ית יִשְׂרָאֵ֔ל יִבְכּוּ֙ אֶת־הַ⁠שְּׂרֵפָ֔ה אֲשֶׁ֖ר שָׂרַ֥ף יְהוָֽה׃","wa⁠yò֣̇ʼmer mòşě֣h ʼeֽl-ʼahàrò֡n ẇ⁠lĕ⁠ʼelĕʻázár֩ ẇ⁠lĕ⁠ʼiֽyţámá֨r ׀ bá̇ná֜y⁠w rֽáʼşé̌y⁠ke֥m ʼal-ţi̇pĕrá֣ʻẇ ׀ ẇ⁠bigĕdéy⁠ke֤m lòֽʼ-ţipĕrò֨mẇ֙ wĕ⁠lò֣ʼ ţámu֔ţẇ wĕ⁠ʻa֥l ká̇l-há⁠ʻédá֖h yiqĕẕò֑p wa⁠ʼàẖéy⁠kem֙ ká̇l-bé֣̇yţ yişĕ̂ráʼé֔l yibĕk̇ẇ֙ ʼeţ-ha⁠şĕ̇̂répá֔h ʼàşě֖r şá̂ra֥p yĕhwáֽh׃"],[10,7,"וּ⁠מִ⁠פֶּתַח֩ אֹ֨הֶל מוֹעֵ֜ד לֹ֤א תֵֽצְאוּ֙ פֶּן־תָּמֻ֔תוּ כִּי־שֶׁ֛מֶן מִשְׁחַ֥ת יְהוָ֖ה עֲלֵי⁠כֶ֑ם וַֽ⁠יַּעֲשׂ֖וּ כִּ⁠דְבַ֥ר מֹשֶֽׁה׃פ","ẇ⁠mi⁠pėţaẖ֩ ʼò֨hel mwòʻé֜d lò֤ʼ ţéֽẕĕʼẇ֙ pėn-ţá̇mu֔ţẇ ki̇y-şě֛men mişĕ̌ẖa֥ţ yĕhwá֖h ʻàléy⁠ke֑m waֽ⁠yȧʻàş֖̂ẇ ki̇⁠dĕba֥r mòşěֽh׃p"],[10,8,"וַ⁠יְדַבֵּ֣ר יְהוָ֔ה אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹֽר׃","wa⁠yĕdabé֣̇r yĕhwá֔h ʼeֽl-ʼahàrò֖n lé⁠ʼmòֽr׃"],[10,9,"יַ֣יִן וְ⁠שֵׁכָ֞ר אַל־תֵּ֣שְׁתְּ ׀ אַתָּ֣ה ׀ וּ⁠בָנֶ֣י⁠ךָ אִתָּ֗⁠ךְ בְּ⁠בֹאֲ⁠כֶ֛ם אֶל־אֹ֥הֶל מוֹעֵ֖ד וְ⁠לֹ֣א תָמֻ֑תוּ חֻקַּ֥ת עוֹלָ֖ם לְ⁠דֹרֹתֵי⁠כֶֽם׃","ya֣yin wĕ⁠şé̌ká֞r ʼal-ţé֣̇şĕ̌ţĕ̇ ׀ ʼaţá֣̇h ׀ ẇ⁠báne֣y⁠ká ʼiţá̇֗⁠kĕ bĕ̇⁠bòʼà⁠ke֛m ʼel-ʼò֥hel mwòʻé֖d wĕ⁠lò֣ʼ ţámu֑ţẇ ẖuqȧ֥ţ ʻwòlá֖m lĕ⁠dòròţéy⁠keֽm׃"],[10,10,"וּֽ⁠לֲ⁠הַבְדִּ֔יל בֵּ֥ין הַ⁠קֹּ֖דֶשׁ וּ⁠בֵ֣ין הַ⁠חֹ֑ל וּ⁠בֵ֥ין הַ⁠טָּמֵ֖א וּ⁠בֵ֥ין הַ⁠טָּהֽוֹר׃","ẇֽ⁠là⁠habĕdi̇֔yl bé֥̇yn ha⁠qò֖̇deş̌ ẇ⁠bé֣yn ha⁠ẖò֑l ẇ⁠bé֥yn ha⁠tá̇mé֖ʼ ẇ⁠bé֥yn ha⁠tá̇hֽwòr׃"],[10,11,"וּ⁠לְ⁠הוֹרֹ֖ת אֶת־בְּנֵ֣י יִשְׂרָאֵ֑ל אֵ֚ת כָּל־הַ֣⁠חֻקִּ֔ים אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אֲלֵי⁠הֶ֖ם בְּ⁠יַד־מֹשֶֽׁה׃פ","ẇ⁠lĕ⁠hwòrò֖ţ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֑l ʼé֚ţ ká̇l-ha֣⁠ẖuqi̇֔ym ʼàşě֨r di̇bė֧r yĕhwá֛h ʼàléy⁠he֖m bĕ̇⁠yad-mòşěֽh׃p"],[10,12,"וַ⁠יְדַבֵּ֨ר מֹשֶׁ֜ה אֶֽל־אַהֲרֹ֗ן וְ⁠אֶ֣ל אֶ֠לְעָזָר וְ⁠אֶל־אִ֨יתָמָ֥ר ׀ בָּנָי⁠ו֮ הַ⁠נּֽוֹתָרִים֒ קְח֣וּ אֶת־הַ⁠מִּנְחָ֗ה הַ⁠נּוֹתֶ֨רֶת֙ מֵ⁠אִשֵּׁ֣י יְהוָ֔ה וְ⁠אִכְל֥וּ⁠הָ מַצּ֖וֹת אֵ֣צֶל הַ⁠מִּזְבֵּ֑חַ כִּ֛י קֹ֥דֶשׁ קָֽדָשִׁ֖ים הִֽוא׃","wa⁠yĕdabé̇֨r mòşě֜h ʼeֽl-ʼahàrò֗n wĕ⁠ʼe֣l ʼe֠lĕʻázár wĕ⁠ʼel-ʼi֨yţámá֥r ׀ bá̇náy⁠w֮ ha⁠ṅֽwòţáriym֒ qĕẖ֣ẇ ʼeţ-ha⁠mi̇nĕẖá֗h ha⁠ṅwòţe֨reţ֙ mé⁠ʼişé֣̇̌y yĕhwá֔h wĕ⁠ʼikĕl֥ẇ⁠há maẕ֖̇wòţ ʼé֣ẕel ha⁠mi̇zĕbé֑̇ẖa ki֛̇y qò֥deş̌ qáֽdáşǐ֖ym hiֽwʼ׃"],[10,13,"וַ⁠אֲכַלְתֶּ֤ם אֹתָ⁠הּ֙ בְּ⁠מָק֣וֹם קָדֹ֔שׁ כִּ֣י חָקְ⁠ךָ֤ וְ⁠חָק־בָּנֶ֨י⁠ךָ֙ הִ֔וא מֵ⁠אִשֵּׁ֖י יְהוָ֑ה כִּי־כֵ֖ן צֻוֵּֽיתִי׃","wa⁠ʼàkalĕţė֤m ʼòţá⁠ḣ֙ bĕ̇⁠máq֣wòm qádò֔ş̌ ki֣̇y ẖáqĕ⁠ká֤ wĕ⁠ẖáq-bá̇ne֨y⁠ká֙ hi֔wʼ mé⁠ʼişé֖̇̌y yĕhwá֑h ki̇y-ké֖n ẕuwéֽ̇yţiy׃"],[10,14,"וְ⁠אֵת֩ חֲזֵ֨ה הַ⁠תְּנוּפָ֜ה וְ⁠אֵ֣ת ׀ שׁ֣וֹק הַ⁠תְּרוּמָ֗ה תֹּֽאכְלוּ֙ בְּ⁠מָק֣וֹם טָה֔וֹר אַתָּ֕ה וּ⁠בָנֶ֥י⁠ךָ וּ⁠בְנֹתֶ֖י⁠ךָ אִתָּ֑⁠ךְ כִּֽי־חָקְ⁠ךָ֤ וְ⁠חָק־בָּנֶ֨י⁠ךָ֙ נִתְּנ֔וּ מִ⁠זִּבְחֵ֥י שַׁלְמֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʼéţ֩ ẖàzé֨h ha⁠ţĕ̇nẇpá֜h wĕ⁠ʼé֣ţ ׀ ş֣̌wòq ha⁠ţĕ̇rẇmá֗h ţòֽ̇ʼkĕlẇ֙ bĕ̇⁠máq֣wòm táh֔wòr ʼaţá̇֕h ẇ⁠báne֥y⁠ká ẇ⁠bĕnòţe֖y⁠ká ʼiţá֑̇⁠kĕ kiֽ̇y-ẖáqĕ⁠ká֤ wĕ⁠ẖáq-bá̇ne֨y⁠ká֙ niţĕ̇n֔ẇ mi⁠zi̇bĕẖé֥y şǎlĕmé֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[10,15,"שׁ֣וֹק הַ⁠תְּרוּמָ֞ה וַ⁠חֲזֵ֣ה הַ⁠תְּנוּפָ֗ה עַ֣ל אִשֵּׁ֤י הַ⁠חֲלָבִים֙ יָבִ֔יאוּ לְ⁠הָנִ֥יף תְּנוּפָ֖ה לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠הָיָ֨ה לְ⁠ךָ֜ וּ⁠לְ⁠בָנֶ֤י⁠ךָ אִתְּ⁠ךָ֙ לְ⁠חָק־עוֹלָ֔ם כַּ⁠אֲשֶׁ֖ר צִוָּ֥ה יְהוָֽה׃","ş֣̌wòq ha⁠ţĕ̇rẇmá֞h wa⁠ẖàzé֣h ha⁠ţĕ̇nẇpá֗h ʻa֣l ʼişé֤̇̌y ha⁠ẖàlábiym֙ yábi֔yʼẇ lĕ⁠háni֥yp ţĕ̇nẇpá֖h li⁠pĕné֣y yĕhwá֑h wĕ⁠háyá֨h lĕ⁠ká֜ ẇ⁠lĕ⁠báne֤y⁠ká ʼiţĕ̇⁠ká֙ lĕ⁠ẖáq-ʻwòlá֔m kȧ⁠ʼàşě֖r ẕiwá֥̇h yĕhwáֽh׃"],[10,16,"וְ⁠אֵ֣ת ׀ שְׂעִ֣יר הַֽ⁠חַטָּ֗את דָּרֹ֥שׁ דָּרַ֛שׁ מֹשֶׁ֖ה וְ⁠הִנֵּ֣ה שֹׂרָ֑ף וַ֠⁠יִּקְצֹף עַל־אֶלְעָזָ֤ר וְ⁠עַל־אִֽיתָמָר֙ בְּנֵ֣י אַהֲרֹ֔ן הַ⁠נּוֹתָרִ֖ם לֵ⁠אמֹֽר׃","wĕ⁠ʼé֣ţ ׀ şĕ̂ʻi֣yr haֽ⁠ẖatá̇֗ʼţ dá̇rò֥ş̌ dá̇ra֛ş̌ mòşě֖h wĕ⁠hiné֣̇h şò̂rá֑p wa֠⁠yi̇qĕẕòp ʻal-ʼelĕʻázá֤r wĕ⁠ʻal-ʼiֽyţámár֙ bĕ̇né֣y ʼahàrò֔n ha⁠ṅwòţári֖m lé⁠ʼmòֽr׃"],[10,17,"מַדּ֗וּעַ לֹֽא־אֲכַלְתֶּ֤ם אֶת־הַֽ⁠חַטָּאת֙ בִּ⁠מְק֣וֹם הַ⁠קֹּ֔דֶשׁ כִּ֛י קֹ֥דֶשׁ קָֽדָשִׁ֖ים הִ֑וא וְ⁠אֹתָ֣⁠הּ ׀ נָתַ֣ן לָ⁠כֶ֗ם לָ⁠שֵׂאת֙ אֶת־עֲוֺ֣ן הָ⁠עֵדָ֔ה לְ⁠כַפֵּ֥ר עֲלֵי⁠הֶ֖ם לִ⁠פְנֵ֥י יְהוָֽה׃","maḋ֗ẇʻa lòֽʼ-ʼàkalĕţė֤m ʼeţ-haֽ⁠ẖatá̇ʼţ֙ bi̇⁠mĕq֣wòm ha⁠qò̇֔deş̌ ki֛̇y qò֥deş̌ qáֽdáşǐ֖ym hi֑wʼ wĕ⁠ʼòţá֣⁠ḣ ׀ náţa֣n lá⁠ke֗m lá⁠şé̂ʼţ֙ ʼeţ-ʻàwֺ֣n há⁠ʻédá֔h lĕ⁠kapé֥̇r ʻàléy⁠he֖m li⁠pĕné֥y yĕhwáֽh׃"],[10,18,"הֵ֚ן לֹא־הוּבָ֣א אֶת־דָּמָ֔⁠הּ אֶל־הַ⁠קֹּ֖דֶשׁ פְּנִ֑ימָה אָכ֨וֹל תֹּאכְל֥וּ אֹתָ֛⁠הּ בַּ⁠קֹּ֖דֶשׁ כַּ⁠אֲשֶׁ֥ר צִוֵּֽיתִי׃","hé֚n lòʼ-hẇbá֣ʼ ʼeţ-dá̇má֔⁠ḣ ʼel-ha⁠qò֖̇deş̌ pĕ̇ni֑ymáh ʼák֨wòl ţò̇ʼkĕl֥ẇ ʼòţá֛⁠ḣ bȧ⁠qò֖̇deş̌ kȧ⁠ʼàşě֥r ẕiwéֽ̇yţiy׃"],[10,19,"וַ⁠יְדַבֵּ֨ר אַהֲרֹ֜ן אֶל־מֹשֶׁ֗ה הֵ֣ן הַ֠⁠יּוֹם הִקְרִ֨יבוּ אֶת־חַטָּאתָ֤⁠ם וְ⁠אֶת־עֹֽלָתָ⁠ם֙ לִ⁠פְנֵ֣י יְהוָ֔ה וַ⁠תִּקְרֶ֥אנָה אֹתִ֖⁠י כָּ⁠אֵ֑לֶּה וְ⁠אָכַ֤לְתִּי חַטָּאת֙ הַ⁠יּ֔וֹם הַ⁠יִּיטַ֖ב בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yĕdabé̇֨r ʼahàrò֜n ʼel-mòşě֗h hé֣n ha֠⁠ẏwòm hiqĕri֨ybẇ ʼeţ-ẖatá̇ʼţá֤⁠m wĕ⁠ʼeţ-ʻòֽláţá⁠m֙ li⁠pĕné֣y yĕhwá֔h wa⁠ţi̇qĕre֥ʼnáh ʼòţi֖⁠y ká̇⁠ʼé֑lėh wĕ⁠ʼáka֤lĕţi̇y ẖatá̇ʼţ֙ ha⁠ẏ֔wòm ha⁠yi̇yta֖b bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[10,20,"וַ⁠יִּשְׁמַ֣ע מֹשֶׁ֔ה וַ⁠יִּיטַ֖ב בְּ⁠עֵינָֽי⁠ו׃פ","wa⁠yi̇şĕ̌ma֣ʻ mòşě֔h wa⁠yi̇yta֖b bĕ̇⁠ʻéynáֽy⁠w׃p"],[11,1,"וַ⁠יְדַבֵּ֧ר יְהוָ֛ה אֶל־מֹשֶׁ֥ה וְ⁠אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹ֥ר אֲלֵ⁠הֶֽם׃","wa⁠yĕdabé֧̇r yĕhwá֛h ʼel-mòşě֥h wĕ⁠ʼeֽl-ʼahàrò֖n lé⁠ʼmò֥r ʼàlé⁠heֽm׃"],[11,2,"דַּבְּר֛וּ אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר זֹ֤את הַֽ⁠חַיָּה֙ אֲשֶׁ֣ר תֹּאכְל֔וּ מִ⁠כָּל־הַ⁠בְּהֵמָ֖ה אֲשֶׁ֥ר עַל־הָ⁠אָֽרֶץ׃","dȧbĕ̇r֛ẇ ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r zò֤ʼţ haֽ⁠ẖayá̇h֙ ʼàşě֣r ţò̇ʼkĕl֔ẇ mi⁠ká̇l-ha⁠bĕ̇hémá֖h ʼàşě֥r ʻal-há⁠ʼáֽreẕ׃"],[11,3,"כֹּ֣ל ׀ מַפְרֶ֣סֶת פַּרְסָ֗ה וְ⁠שֹׁסַ֤עַת שֶׁ֨סַע֙ פְּרָסֹ֔ת מַעֲלַ֥ת גֵּרָ֖ה בַּ⁠בְּהֵמָ֑ה אֹתָ֖⁠הּ תֹּאכֵֽלוּ׃","kò֣̇l ׀ mapĕre֣seţ pȧrĕsá֗h wĕ⁠şò̌sa֤ʻaţ şě֨saʻ֙ pĕ̇rásò֔ţ maʻàla֥ţ gé̇rá֖h bȧ⁠bĕ̇hémá֑h ʼòţá֖⁠ḣ ţò̇ʼkéֽlẇ׃"],[11,4,"אַ֤ךְ אֶת־זֶה֙ לֹ֣א תֹֽאכְל֔וּ מִֽ⁠מַּעֲלֵי֙ הַ⁠גֵּרָ֔ה וּ⁠מִ⁠מַּפְרִיסֵ֖י הַ⁠פַּרְסָ֑ה אֶֽת־הַ֠⁠גָּמָל כִּֽי־מַעֲלֵ֨ה גֵרָ֜ה ה֗וּא וּ⁠פַרְסָה֙ אֵינֶ֣⁠נּוּ מַפְרִ֔יס טָמֵ֥א ה֖וּא לָ⁠כֶֽם׃","ʼa֤kĕ ʼeţ-zeh֙ lò֣ʼ ţòֽʼkĕl֔ẇ miֽ⁠mȧʻàléy֙ ha⁠gé̇rá֔h ẇ⁠mi⁠mȧpĕriysé֖y ha⁠pȧrĕsá֑h ʼeֽţ-ha֠⁠gá̇mál kiֽ̇y-maʻàlé֨h gérá֜h h֗ẇʼ ẇ⁠parĕsáh֙ ʼéyne֣⁠ṅẇ mapĕri֔ys támé֥ʼ h֖ẇʼ lá⁠keֽm׃"],[11,5,"וְ⁠אֶת־הַ⁠שָּׁפָ֗ן כִּֽי־מַעֲלֵ֤ה גֵרָה֙ ה֔וּא וּ⁠פַרְסָ֖ה לֹ֣א יַפְרִ֑יס טָמֵ֥א ה֖וּא לָ⁠כֶֽם׃","wĕ⁠ʼeţ-ha⁠şá̇̌pá֗n kiֽ̇y-maʻàlé֤h géráh֙ h֔ẇʼ ẇ⁠parĕsá֖h lò֣ʼ yapĕri֑ys támé֥ʼ h֖ẇʼ lá⁠keֽm׃"],[11,6,"וְ⁠אֶת־הָ⁠אַרְנֶ֗בֶת כִּֽי־מַעֲלַ֤ת גֵּרָה֙ הִ֔וא וּ⁠פַרְסָ֖ה לֹ֣א הִפְרִ֑יסָה טְמֵאָ֥ה הִ֖וא לָ⁠כֶֽם׃","wĕ⁠ʼeţ-há⁠ʼarĕne֗beţ kiֽ̇y-maʻàla֤ţ gé̇ráh֙ hi֔wʼ ẇ⁠parĕsá֖h lò֣ʼ hipĕri֑ysáh tĕméʼá֥h hi֖wʼ lá⁠keֽm׃"],[11,7,"וְ⁠אֶת־הַ֠⁠חֲזִיר כִּֽי־מַפְרִ֨יס פַּרְסָ֜ה ה֗וּא וְ⁠שֹׁסַ֥ע שֶׁ֨סַע֙ פַּרְסָ֔ה וְ⁠ה֖וּא גֵּרָ֣ה לֹֽא־יִגָּ֑ר טָמֵ֥א ה֖וּא לָ⁠כֶֽם׃","wĕ⁠ʼeţ-ha֠⁠ẖàziyr kiֽ̇y-mapĕri֨ys pȧrĕsá֜h h֗ẇʼ wĕ⁠şò̌sa֥ʻ şě֨saʻ֙ pȧrĕsá֔h wĕ⁠h֖ẇʼ gé̇rá֣h lòֽʼ-yigá֑̇r támé֥ʼ h֖ẇʼ lá⁠keֽm׃"],[11,8,"מִ⁠בְּשָׂרָ⁠ם֙ לֹ֣א תֹאכֵ֔לוּ וּ⁠בְ⁠נִבְלָתָ֖⁠ם לֹ֣א תִגָּ֑עוּ טְמֵאִ֥ים הֵ֖ם לָ⁠כֶֽם׃","mi⁠bĕ̇şá̂rá⁠m֙ lò֣ʼ ţòʼké֔lẇ ẇ⁠bĕ⁠nibĕláţá֖⁠m lò֣ʼ ţigá֑̇ʻẇ tĕméʼi֥ym hé֖m lá⁠keֽm׃"],[11,9,"אֶת־זֶה֙ תֹּֽאכְל֔וּ מִ⁠כֹּ֖ל אֲשֶׁ֣ר בַּ⁠מָּ֑יִם כֹּ֣ל אֲשֶׁר־ל⁠וֹ֩ סְנַפִּ֨יר וְ⁠קַשְׂקֶ֜שֶׂת בַּ⁠מַּ֗יִם בַּ⁠יַּמִּ֛ים וּ⁠בַ⁠נְּחָלִ֖ים אֹתָ֥⁠ם תֹּאכֵֽלוּ׃","ʼeţ-zeh֙ ţòֽ̇ʼkĕl֔ẇ mi⁠kò֖̇l ʼàşě֣r bȧ⁠má֑̇yim kò֣̇l ʼàşěr-l⁠wò֩ sĕnapi̇֨yr wĕ⁠qaşĕ̂qe֜şêţ bȧ⁠mȧ֗yim bȧ⁠yȧmi֛̇ym ẇ⁠ba⁠nĕ̇ẖáli֖ym ʼòţá֥⁠m ţò̇ʼkéֽlẇ׃"],[11,10,"וְ⁠כֹל֩ אֲשֶׁ֨ר אֵֽין־ל֜⁠וֹ סְנַפִּ֣יר וְ⁠קַשְׂקֶ֗שֶׂת בַּ⁠יַּמִּים֙ וּ⁠בַ⁠נְּחָלִ֔ים מִ⁠כֹּל֙ שֶׁ֣רֶץ הַ⁠מַּ֔יִם וּ⁠מִ⁠כֹּ֛ל נֶ֥פֶשׁ הַ⁠חַיָּ֖ה אֲשֶׁ֣ר בַּ⁠מָּ֑יִם שֶׁ֥קֶץ הֵ֖ם לָ⁠כֶֽם׃","wĕ⁠kòl֩ ʼàşě֨r ʼéֽyn-l֜⁠wò sĕnapi֣̇yr wĕ⁠qaşĕ̂qe֗şêţ bȧ⁠yȧmi̇ym֙ ẇ⁠ba⁠nĕ̇ẖáli֔ym mi⁠kò̇l֙ şě֣reẕ ha⁠mȧ֔yim ẇ⁠mi⁠kò֛̇l ne֥peş̌ ha⁠ẖayá֖̇h ʼàşě֣r bȧ⁠má֑̇yim şě֥qeẕ hé֖m lá⁠keֽm׃"],[11,11,"וְ⁠שֶׁ֖קֶץ יִהְי֣וּ לָ⁠כֶ֑ם מִ⁠בְּשָׂרָ⁠ם֙ לֹ֣א תֹאכֵ֔לוּ וְ⁠אֶת־נִבְלָתָ֖⁠ם תְּשַׁקֵּֽצוּ׃","wĕ⁠şě֖qeẕ yihĕy֣ẇ lá⁠ke֑m mi⁠bĕ̇şá̂rá⁠m֙ lò֣ʼ ţòʼké֔lẇ wĕ⁠ʼeţ-nibĕláţá֖⁠m ţĕ̇şǎqéֽ̇ẕẇ׃"],[11,12,"כֹּ֣ל אֲשֶׁ֥ר אֵֽין־ל֛⁠וֹ סְנַפִּ֥יר וְ⁠קַשְׂקֶ֖שֶׂת בַּ⁠מָּ֑יִם שֶׁ֥קֶץ ה֖וּא לָ⁠כֶֽם׃","kò֣̇l ʼàşě֥r ʼéֽyn-l֛⁠wò sĕnapi֥̇yr wĕ⁠qaşĕ̂qe֖şêţ bȧ⁠má֑̇yim şě֥qeẕ h֖ẇʼ lá⁠keֽm׃"],[11,13,"וְ⁠אֶת־אֵ֨לֶּה֙ תְּשַׁקְּצ֣וּ מִן־הָ⁠ע֔וֹף לֹ֥א יֵאָכְל֖וּ שֶׁ֣קֶץ הֵ֑ם אֶת־הַ⁠נֶּ֨שֶׁר֙ וְ⁠אֶת־הַ⁠פֶּ֔רֶס וְ⁠אֵ֖ת הָ⁠עָזְנִיָּֽה׃","wĕ⁠ʼeţ-ʼé֨lėh֙ ţĕ̇şǎqĕ̇ẕ֣ẇ min-há⁠ʻ֔wòp lò֥ʼ yéʼákĕl֖ẇ şě֣qeẕ hé֑m ʼeţ-ha⁠nė֨şěr֙ wĕ⁠ʼeţ-ha⁠pė֔res wĕ⁠ʼé֖ţ há⁠ʻázĕniyáֽ̇h׃"],[11,14,"וְ⁠אֶת־הַ֨⁠דָּאָ֔ה וְ⁠אֶת־הָ⁠אַיָּ֖ה לְ⁠מִינָֽ⁠הּ׃","wĕ⁠ʼeţ-ha֨⁠dá̇ʼá֔h wĕ⁠ʼeţ-há⁠ʼayá֖̇h lĕ⁠miynáֽ⁠ḣ׃"],[11,15,"אֵ֥ת כָּל־עֹרֵ֖ב לְ⁠מִינֽ⁠וֹ׃","ʼé֥ţ ká̇l-ʻòré֖b lĕ⁠miynֽ⁠wò׃"],[11,16,"וְ⁠אֵת֙ בַּ֣ת הַֽ⁠יַּעֲנָ֔ה וְ⁠אֶת־הַ⁠תַּחְמָ֖ס וְ⁠אֶת־הַ⁠שָּׁ֑חַף וְ⁠אֶת־הַ⁠נֵּ֖ץ לְ⁠מִינֵֽ⁠הוּ׃","wĕ⁠ʼéţ֙ bȧ֣ţ haֽ⁠yȧʻàná֔h wĕ⁠ʼeţ-ha⁠ţȧẖĕmá֖s wĕ⁠ʼeţ-ha⁠şá֑̇̌ẖap wĕ⁠ʼeţ-ha⁠né֖̇ẕ lĕ⁠miynéֽ⁠hẇ׃"],[11,17,"וְ⁠אֶת־הַ⁠כּ֥וֹס וְ⁠אֶת־הַ⁠שָּׁלָ֖ךְ וְ⁠אֶת־הַ⁠יַּנְשֽׁוּף׃","wĕ⁠ʼeţ-ha⁠k֥̇wòs wĕ⁠ʼeţ-ha⁠şá̇̌lá֖kĕ wĕ⁠ʼeţ-ha⁠yȧnĕşֽ̌ẇp׃"],[11,18,"וְ⁠אֶת־הַ⁠תִּנְשֶׁ֥מֶת וְ⁠אֶת־הַ⁠קָּאָ֖ת וְ⁠אֶת־הָ⁠רָחָֽם׃","wĕ⁠ʼeţ-ha⁠ţi̇nĕşě֥meţ wĕ⁠ʼeţ-ha⁠qá̇ʼá֖ţ wĕ⁠ʼeţ-há⁠ráẖáֽm׃"],[11,19,"וְ⁠אֵת֙ הַ⁠חֲסִידָ֔ה הָ⁠אֲנָפָ֖ה לְ⁠מִינָ֑⁠הּ וְ⁠אֶת־הַ⁠דּוּכִיפַ֖ת וְ⁠אֶת־הָ⁠עֲטַלֵּֽף׃","wĕ⁠ʼéţ֙ ha⁠ẖàsiydá֔h há⁠ʼànápá֖h lĕ⁠miyná֑⁠ḣ wĕ⁠ʼeţ-ha⁠ḋẇkiypa֖ţ wĕ⁠ʼeţ-há⁠ʻàtaléֽ̇p׃"],[11,20,"כֹּ֚ל שֶׁ֣רֶץ הָ⁠ע֔וֹף הַ⁠הֹלֵ֖ךְ עַל־אַרְבַּ֑ע שֶׁ֥קֶץ ה֖וּא לָ⁠כֶֽם׃ס","kò֚̇l şě֣reẕ há⁠ʻ֔wòp ha⁠hòlé֖kĕ ʻal-ʼarĕbȧ֑ʻ şě֥qeẕ h֖ẇʼ lá⁠keֽm׃s"],[11,21,"אַ֤ךְ אֶת־זֶה֙ תֹּֽאכְל֔וּ מִ⁠כֹּל֙ שֶׁ֣רֶץ הָ⁠ע֔וֹף הַ⁠הֹלֵ֖ךְ עַל־אַרְבַּ֑ע אֲשֶׁר־לא כְרָעַ֨יִם֙ מִ⁠מַּ֣עַל לְ⁠רַגְלָ֔י⁠ו לְ⁠נַתֵּ֥ר בָּ⁠הֵ֖ן עַל־הָ⁠אָֽרֶץ׃","ʼa֤kĕ ʼeţ-zeh֙ ţòֽ̇ʼkĕl֔ẇ mi⁠kò̇l֙ şě֣reẕ há⁠ʻ֔wòp ha⁠hòlé֖kĕ ʻal-ʼarĕbȧ֑ʻ ʼàşěr-lʼ kĕráʻa֨yim֙ mi⁠mȧ֣ʻal lĕ⁠ragĕlá֔y⁠w lĕ⁠naţé֥̇r bá̇⁠hé֖n ʻal-há⁠ʼáֽreẕ׃"],[11,22,"אֶת־אֵ֤לֶּה מֵ⁠הֶם֙ תֹּאכֵ֔לוּ אֶת־הָֽ⁠אַרְבֶּ֣ה לְ⁠מִינ֔⁠וֹ וְ⁠אֶת־הַ⁠סָּלְעָ֖ם לְ⁠מִינֵ֑⁠הוּ וְ⁠אֶת־הַ⁠חַרְגֹּ֣ל לְ⁠מִינֵ֔⁠הוּ וְ⁠אֶת־הֶ⁠חָגָ֖ב לְ⁠מִינֵֽ⁠הוּ׃","ʼeţ-ʼé֤lėh mé⁠hem֙ ţò̇ʼké֔lẇ ʼeţ-hֽá⁠ʼarĕbė֣h lĕ⁠miyn֔⁠wò wĕ⁠ʼeţ-ha⁠sá̇lĕʻá֖m lĕ⁠miyné֑⁠hẇ wĕ⁠ʼeţ-ha⁠ẖarĕgò֣̇l lĕ⁠miyné֔⁠hẇ wĕ⁠ʼeţ-he⁠ẖágá֖b lĕ⁠miynéֽ⁠hẇ׃"],[11,23,"וְ⁠כֹל֙ שֶׁ֣רֶץ הָ⁠ע֔וֹף אֲשֶׁר־ל֖⁠וֹ אַרְבַּ֣ע רַגְלָ֑יִם שֶׁ֥קֶץ ה֖וּא לָ⁠כֶֽם׃","wĕ⁠kòl֙ şě֣reẕ há⁠ʻ֔wòp ʼàşěr-l֖⁠wò ʼarĕbȧ֣ʻ ragĕlá֑yim şě֥qeẕ h֖ẇʼ lá⁠keֽm׃"],[11,24,"וּ⁠לְ⁠אֵ֖לֶּה תִּטַּמָּ֑אוּ כָּל־הַ⁠נֹּגֵ֥עַ בְּ⁠נִבְלָתָ֖⁠ם יִטְמָ֥א עַד־הָ⁠עָֽרֶב׃","ẇ⁠lĕ⁠ʼé֖lėh ţi̇tȧmá֑̇ʼẇ ká̇l-ha⁠nò̇gé֥ʻa bĕ̇⁠nibĕláţá֖⁠m yitĕmá֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,25,"וְ⁠כָל־הַ⁠נֹּשֵׂ֖א מִ⁠נִּבְלָתָ֑⁠ם יְכַבֵּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kál-ha⁠nò̇şé֖̂ʼ mi⁠ni̇bĕláţá֑⁠m yĕkabé֥̇s bĕ̇gádá֖y⁠w wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,26,"לְֽ⁠כָל־הַ⁠בְּהֵמָ֡ה אֲשֶׁ֣ר הִוא֩ מַפְרֶ֨סֶת פַּרְסָ֜ה וְ⁠שֶׁ֣סַע ׀ אֵינֶ֣⁠נָּה שֹׁסַ֗עַת וְ⁠גֵרָה֙ אֵינֶ֣⁠נָּה מַעֲלָ֔ה טְמֵאִ֥ים הֵ֖ם לָ⁠כֶ֑ם כָּל־הַ⁠נֹּגֵ֥עַ בָּ⁠הֶ֖ם יִטְמָֽא׃","lĕֽ⁠kál-ha⁠bĕ̇hémá֡h ʼàşě֣r hiwʼ֩ mapĕre֨seţ pȧrĕsá֜h wĕ⁠şě֣saʻ ׀ ʼéyne֣⁠ná̇h şò̌sa֗ʻaţ wĕ⁠géráh֙ ʼéyne֣⁠ná̇h maʻàlá֔h tĕméʼi֥ym hé֖m lá⁠ke֑m ká̇l-ha⁠nò̇gé֥ʻa bá̇⁠he֖m yitĕmáֽʼ׃"],[11,27,"וְ⁠כֹ֣ל ׀ הוֹלֵ֣ךְ עַל־כַּפָּ֗י⁠ו בְּ⁠כָל־הַֽ⁠חַיָּה֙ הַ⁠הֹלֶ֣כֶת עַל־אַרְבַּ֔ע טְמֵאִ֥ים הֵ֖ם לָ⁠כֶ֑ם כָּל־הַ⁠נֹּגֵ֥עַ בְּ⁠נִבְלָתָ֖⁠ם יִטְמָ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kò֣l ׀ hwòlé֣kĕ ʻal-kȧpá̇֗y⁠w bĕ̇⁠kál-haֽ⁠ẖayá̇h֙ ha⁠hòle֣keţ ʻal-ʼarĕbȧ֔ʻ tĕméʼi֥ym hé֖m lá⁠ke֑m ká̇l-ha⁠nò̇gé֥ʻa bĕ̇⁠nibĕláţá֖⁠m yitĕmá֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,28,"וְ⁠הַ⁠נֹּשֵׂא֙ אֶת־נִבְלָתָ֔⁠ם יְכַבֵּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָמֵ֣א עַד־הָ⁠עָ֑רֶב טְמֵאִ֥ים הֵ֖מָּה לָ⁠כֶֽם׃ס","wĕ⁠ha⁠nò̇şé̂ʼ֙ ʼeţ-nibĕláţá֔⁠m yĕkabé֥̇s bĕ̇gádá֖y⁠w wĕ⁠támé֣ʼ ʻad-há⁠ʻá֑reb tĕméʼi֥ym hé֖má̇h lá⁠keֽm׃s"],[11,29,"וְ⁠זֶ֤ה לָ⁠כֶם֙ הַ⁠טָּמֵ֔א בַּ⁠שֶּׁ֖רֶץ הַ⁠שֹּׁרֵ֣ץ עַל־הָ⁠אָ֑רֶץ הַ⁠חֹ֥לֶד וְ⁠הָ⁠עַכְבָּ֖ר וְ⁠הַ⁠צָּ֥ב לְ⁠מִינֵֽ⁠הוּ׃","wĕ⁠ze֤h lá⁠kem֙ ha⁠tá̇mé֔ʼ bȧ⁠şė֖̌reẕ ha⁠şò̇̌ré֣ẕ ʻal-há⁠ʼá֑reẕ ha⁠ẖò֥led wĕ⁠há⁠ʻakĕbá֖̇r wĕ⁠ha⁠ẕá֥̇b lĕ⁠miynéֽ⁠hẇ׃"],[11,30,"וְ⁠הָ⁠אֲנָקָ֥ה וְ⁠הַ⁠כֹּ֖חַ וְ⁠הַ⁠לְּטָאָ֑ה וְ⁠הַ⁠חֹ֖מֶט וְ⁠הַ⁠תִּנְשָֽׁמֶת׃","wĕ⁠há⁠ʼànáqá֥h wĕ⁠ha⁠kò֖̇ẖa wĕ⁠ha⁠lĕ̇táʼá֑h wĕ⁠ha⁠ẖò֖met wĕ⁠ha⁠ţi̇nĕşáֽ̌meţ׃"],[11,31,"אֵ֛לֶּה הַ⁠טְּמֵאִ֥ים לָ⁠כֶ֖ם בְּ⁠כָל־הַ⁠שָּׁ֑רֶץ כָּל־הַ⁠נֹּגֵ֧עַ בָּ⁠הֶ֛ם בְּ⁠מֹתָ֖⁠ם יִטְמָ֥א עַד־הָ⁠עָֽרֶב׃","ʼé֛lėh ha⁠tĕ̇méʼi֥ym lá⁠ke֖m bĕ̇⁠kál-ha⁠şá֑̇̌reẕ ká̇l-ha⁠nò̇gé֧ʻa bá̇⁠he֛m bĕ̇⁠mòţá֖⁠m yitĕmá֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,32,"וְ⁠כֹ֣ל אֲשֶׁר־יִפֹּל־עָלָי⁠ו֩ מֵ⁠הֶ֨ם ׀ בְּ⁠מֹתָ֜⁠ם יִטְמָ֗א מִ⁠כָּל־כְּלִי־עֵץ֙ א֣וֹ בֶ֤גֶד אוֹ־עוֹר֙ א֣וֹ שָׂ֔ק כָּל־כְּלִ֕י אֲשֶׁר־יֵעָשֶׂ֥ה מְלָאכָ֖ה בָּ⁠הֶ֑ם בַּ⁠מַּ֧יִם יוּבָ֛א וְ⁠טָמֵ֥א עַד־הָ⁠עֶ֖רֶב וְ⁠טָהֵֽר׃","wĕ⁠kò֣l ʼàşěr-yipò̇l-ʻáláy⁠w֩ mé⁠he֨m ׀ bĕ̇⁠mòţá֜⁠m yitĕmá֗ʼ mi⁠ká̇l-kĕ̇liy-ʻéẕ֙ ʼ֣wò be֤ged ʼwò-ʻwòr֙ ʼ֣wò şá̂֔q ká̇l-kĕ̇li֕y ʼàşěr-yéʻáşê֥h mĕláʼká֖h bá̇⁠he֑m bȧ⁠mȧ֧yim yẇbá֛ʼ wĕ⁠támé֥ʼ ʻad-há⁠ʻe֖reb wĕ⁠táhéֽr׃"],[11,33,"וְ⁠כָל־כְּלִי־חֶ֔רֶשׂ אֲשֶׁר־יִפֹּ֥ל מֵ⁠הֶ֖ם אֶל־תּוֹכ֑⁠וֹ כֹּ֣ל אֲשֶׁ֧ר בְּ⁠תוֹכ֛⁠וֹ יִטְמָ֖א וְ⁠אֹת֥⁠וֹ תִשְׁבֹּֽרוּ׃","wĕ⁠kál-kĕ̇liy-ẖe֔reş̂ ʼàşěr-yipò֥̇l mé⁠he֖m ʼel-ţ̇wòk֑⁠wò kò֣̇l ʼàşě֧r bĕ̇⁠ţwòk֛⁠wò yitĕmá֖ʼ wĕ⁠ʼòţ֥⁠wò ţişĕ̌bòֽ̇rẇ׃"],[11,34,"מִ⁠כָּל־הָ⁠אֹ֜כֶל אֲשֶׁ֣ר יֵאָכֵ֗ל אֲשֶׁ֨ר יָב֥וֹא עָלָ֛י⁠ו מַ֖יִם יִטְמָ֑א וְ⁠כָל־מַשְׁקֶה֙ אֲשֶׁ֣ר יִשָּׁתֶ֔ה בְּ⁠כָל־כְּלִ֖י יִטְמָֽא׃","mi⁠ká̇l-há⁠ʼò֜kel ʼàşě֣r yéʼáké֗l ʼàşě֨r yáb֥wòʼ ʻálá֛y⁠w ma֖yim yitĕmá֑ʼ wĕ⁠kál-maşĕ̌qeh֙ ʼàşě֣r yişá̇̌ţe֔h bĕ̇⁠kál-kĕ̇li֖y yitĕmáֽʼ׃"],[11,35,"וְ֠⁠כֹל אֲשֶׁר־יִפֹּ֨ל מִ⁠נִּבְלָתָ֥⁠ם ׀ עָלָי⁠ו֮ יִטְמָא֒ תַּנּ֧וּר וְ⁠כִירַ֛יִם יֻתָּ֖ץ טְמֵאִ֣ים הֵ֑ם וּ⁠טְמֵאִ֖ים יִהְי֥וּ לָ⁠כֶֽם׃","wĕ֠⁠kòl ʼàşěr-yipò̇֨l mi⁠ni̇bĕláţá֥⁠m ׀ ʻáláy⁠w֮ yitĕmáʼ֒ ţȧṅ֧ẇr wĕ⁠kiyra֛yim yuţá֖̇ẕ tĕméʼi֣ym hé֑m ẇ⁠tĕméʼi֖ym yihĕy֥ẇ lá⁠keֽm׃"],[11,36,"אַ֣ךְ מַעְיָ֥ן וּ⁠ב֛וֹר מִקְוֵה־מַ֖יִם יִהְיֶ֣ה טָה֑וֹר וְ⁠נֹגֵ֥עַ בְּ⁠נִבְלָתָ֖⁠ם יִטְמָֽא׃","ʼa֣kĕ maʻĕyá֥n ẇ⁠b֛wòr miqĕwéh-ma֖yim yihĕye֣h táh֑wòr wĕ⁠nògé֥ʻa bĕ̇⁠nibĕláţá֖⁠m yitĕmáֽʼ׃"],[11,37,"וְ⁠כִ֤י יִפֹּל֙ מִ⁠נִּבְלָתָ֔⁠ם עַל־כָּל־זֶ֥רַע זֵר֖וּעַ אֲשֶׁ֣ר יִזָּרֵ֑עַ טָה֖וֹר הֽוּא׃","wĕ⁠ki֤y yipò̇l֙ mi⁠ni̇bĕláţá֔⁠m ʻal-ká̇l-ze֥raʻ zér֖ẇʻa ʼàşě֣r yizá̇ré֑ʻa táh֖wòr hֽẇʼ׃"],[11,38,"וְ⁠כִ֤י יֻתַּן־מַ֨יִם֙ עַל־זֶ֔רַע וְ⁠נָפַ֥ל מִ⁠נִּבְלָתָ֖⁠ם עָלָ֑י⁠ו טָמֵ֥א ה֖וּא לָ⁠כֶֽם׃ס","wĕ⁠ki֤y yuţȧn-ma֨yim֙ ʻal-ze֔raʻ wĕ⁠nápa֥l mi⁠ni̇bĕláţá֖⁠m ʻálá֑y⁠w támé֥ʼ h֖ẇʼ lá⁠keֽm׃s"],[11,39,"וְ⁠כִ֤י יָמוּת֙ מִן־הַ⁠בְּהֵמָ֔ה אֲשֶׁר־הִ֥יא לָ⁠כֶ֖ם לְ⁠אָכְלָ֑ה הַ⁠נֹּגֵ֥עַ בְּ⁠נִבְלָתָ֖⁠הּ יִטְמָ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ki֤y yámẇţ֙ min-ha⁠bĕ̇hémá֔h ʼàşěr-hi֥yʼ lá⁠ke֖m lĕ⁠ʼákĕlá֑h ha⁠nò̇gé֥ʻa bĕ̇⁠nibĕláţá֖⁠ḣ yitĕmá֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,40,"וְ⁠הָֽ⁠אֹכֵל֙ מִ⁠נִּבְלָתָ֔⁠הּ יְכַבֵּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָמֵ֣א עַד־הָ⁠עָ֑רֶב וְ⁠הַ⁠נֹּשֵׂא֙ אֶת־נִבְלָתָ֔⁠הּ יְכַבֵּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠háֽ⁠ʼòkél֙ mi⁠ni̇bĕláţá֔⁠ḣ yĕkabé֥̇s bĕ̇gádá֖y⁠w wĕ⁠támé֣ʼ ʻad-há⁠ʻá֑reb wĕ⁠ha⁠nò̇şé̂ʼ֙ ʼeţ-nibĕláţá֔⁠ḣ yĕkabé֥̇s bĕ̇gádá֖y⁠w wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[11,41,"וְ⁠כָל־הַ⁠שֶּׁ֖רֶץ הַ⁠שֹּׁרֵ֣ץ עַל־הָ⁠אָ֑רֶץ שֶׁ֥קֶץ ה֖וּא לֹ֥א יֵאָכֵֽל׃","wĕ⁠kál-ha⁠şė֖̌reẕ ha⁠şò̇̌ré֣ẕ ʻal-há⁠ʼá֑reẕ şě֥qeẕ h֖ẇʼ lò֥ʼ yéʼákéֽl׃"],[11,42,"כֹּל֩ הוֹלֵ֨ךְ עַל־גָּח֜וֹן וְ⁠כֹ֣ל ׀ הוֹלֵ֣ךְ עַל־אַרְבַּ֗ע עַ֚ד כָּל־מַרְבֵּ֣ה רַגְלַ֔יִם לְ⁠כָל־הַ⁠שֶּׁ֖רֶץ הַ⁠שֹּׁרֵ֣ץ עַל־הָ⁠אָ֑רֶץ לֹ֥א תֹאכְל֖וּ⁠ם כִּי־שֶׁ֥קֶץ הֵֽם׃","kò̇l֩ hwòlé֨kĕ ʻal-gá̇ẖ֜wòn wĕ⁠kò֣l ׀ hwòlé֣kĕ ʻal-ʼarĕbȧ֗ʻ ʻa֚d ká̇l-marĕbé֣̇h ragĕla֔yim lĕ⁠kál-ha⁠şė֖̌reẕ ha⁠şò̇̌ré֣ẕ ʻal-há⁠ʼá֑reẕ lò֥ʼ ţòʼkĕl֖ẇ⁠m ki̇y-şě֥qeẕ héֽm׃"],[11,43,"אַל־תְּשַׁקְּצוּ֙ אֶת־נַפְשֹׁ֣תֵי⁠כֶ֔ם בְּ⁠כָל־הַ⁠שֶּׁ֖רֶץ הַ⁠שֹּׁרֵ֑ץ וְ⁠לֹ֤א תִֽטַּמְּאוּ֙ בָּ⁠הֶ֔ם וְ⁠נִטְמֵתֶ֖ם בָּֽ⁠ם׃","ʼal-ţĕ̇şǎqĕ̇ẕẇ֙ ʼeţ-napĕşò֣̌ţéy⁠ke֔m bĕ̇⁠kál-ha⁠şė֖̌reẕ ha⁠şò̇̌ré֑ẕ wĕ⁠lò֤ʼ ţiֽtȧmĕ̇ʼẇ֙ bá̇⁠he֔m wĕ⁠nitĕméţe֖m báֽ̇⁠m׃"],[11,44,"כִּ֣י אֲנִ֣י יְהוָה֮ אֱלֹֽהֵי⁠כֶם֒ וְ⁠הִתְקַדִּשְׁתֶּם֙ וִ⁠הְיִיתֶ֣ם קְדֹשִׁ֔ים כִּ֥י קָד֖וֹשׁ אָ֑נִי וְ⁠לֹ֤א תְטַמְּאוּ֙ אֶת־נַפְשֹׁ֣תֵי⁠כֶ֔ם בְּ⁠כָל־הַ⁠שֶּׁ֖רֶץ הָ⁠רֹמֵ֥שׂ עַל־הָ⁠אָֽרֶץ׃","ki֣̇y ʼàni֣y yĕhwáh֮ ʼèlòֽhéy⁠kem֒ wĕ⁠hiţĕqadi̇şĕ̌ţėm֙ wi⁠hĕyiyţe֣m qĕdòşǐ֔ym ki֥̇y qád֖wòş̌ ʼá֑niy wĕ⁠lò֤ʼ ţĕtamĕ̇ʼẇ֙ ʼeţ-napĕşò֣̌ţéy⁠ke֔m bĕ̇⁠kál-ha⁠şė֖̌reẕ há⁠ròmé֥ş̂ ʻal-há⁠ʼáֽreẕ׃"],[11,45,"כִּ֣י ׀ אֲנִ֣י יְהוָ֗ה הַֽ⁠מַּעֲלֶ֤ה אֶתְ⁠כֶם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם לִ⁠הְיֹ֥ת לָ⁠כֶ֖ם לֵ⁠אלֹהִ֑ים וִ⁠הְיִיתֶ֣ם קְדֹשִׁ֔ים כִּ֥י קָד֖וֹשׁ אָֽנִי׃","ki֣̇y ׀ ʼàni֣y yĕhwá֗h haֽ⁠mȧʻàle֤h ʼeţĕ⁠kem֙ mé⁠ʼe֣reẕ miẕĕra֔yim li⁠hĕyò֥ţ lá⁠ke֖m lé⁠ʼlòhi֑ym wi⁠hĕyiyţe֣m qĕdòşǐ֔ym ki֥̇y qád֖wòş̌ ʼáֽniy׃"],[11,46,"זֹ֣את תּוֹרַ֤ת הַ⁠בְּהֵמָה֙ וְ⁠הָ⁠ע֔וֹף וְ⁠כֹל֙ נֶ֣פֶשׁ הַֽ⁠חַיָּ֔ה הָ⁠רֹמֶ֖שֶׂת בַּ⁠מָּ֑יִם וּ⁠לְ⁠כָל־נֶ֖פֶשׁ הַ⁠שֹּׁרֶ֥צֶת עַל־הָ⁠אָֽרֶץ׃","zò֣ʼţ ţ̇wòra֤ţ ha⁠bĕ̇hémáh֙ wĕ⁠há⁠ʻ֔wòp wĕ⁠kòl֙ ne֣peş̌ haֽ⁠ẖayá̇֔h há⁠ròme֖şêţ bȧ⁠má֑̇yim ẇ⁠lĕ⁠kál-ne֖peş̌ ha⁠şò̇̌re֥ẕeţ ʻal-há⁠ʼáֽreẕ׃"],[11,47,"לְ⁠הַבְדִּ֕יל בֵּ֥ין הַ⁠טָּמֵ֖א וּ⁠בֵ֣ין הַ⁠טָּהֹ֑ר וּ⁠בֵ֤ין הַֽ⁠חַיָּה֙ הַֽ⁠נֶּאֱכֶ֔לֶת וּ⁠בֵין֙ הַֽ⁠חַיָּ֔ה אֲשֶׁ֖ר לֹ֥א תֵאָכֵֽל׃פ","lĕ⁠habĕdi̇֕yl bé֥̇yn ha⁠tá̇mé֖ʼ ẇ⁠bé֣yn ha⁠tá̇hò֑r ẇ⁠bé֤yn haֽ⁠ẖayá̇h֙ haֽ⁠nėʼèke֔leţ ẇ⁠béyn֙ haֽ⁠ẖayá̇֔h ʼàşě֖r lò֥ʼ ţéʼákéֽl׃p"],[12,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[12,2,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר אִשָּׁה֙ כִּ֣י תַזְרִ֔יעַ וְ⁠יָלְדָ֖ה זָכָ֑ר וְ⁠טָֽמְאָה֙ שִׁבְעַ֣ת יָמִ֔ים כִּ⁠ימֵ֛י נִדַּ֥ת דְּוֺתָ֖⁠הּ תִּטְמָֽא׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ lé⁠ʼmò֔r ʼişá̇̌h֙ ki֣̇y ţazĕri֔yʻa wĕ⁠yálĕdá֖h záká֑r wĕ⁠táֽmĕʼáh֙ şǐbĕʻa֣ţ yámi֔ym ki̇⁠ymé֛y nidȧ֥ţ dĕ̇wֺţá֖⁠ḣ ţi̇tĕmáֽʼ׃"],[12,3,"וּ⁠בַ⁠יּ֖וֹם הַ⁠שְּׁמִינִ֑י יִמּ֖וֹל בְּשַׂ֥ר עָרְלָתֽ⁠וֹ׃","ẇ⁠ba⁠ẏ֖wòm ha⁠şĕ̇̌miyni֑y yiṁ֖wòl bĕ̇şâ֥r ʻárĕláţֽ⁠wò׃"],[12,4,"וּ⁠שְׁלֹשִׁ֥ים יוֹם֙ וּ⁠שְׁלֹ֣שֶׁת יָמִ֔ים תֵּשֵׁ֖ב בִּ⁠דְמֵ֣י טָהֳרָ֑ה בְּ⁠כָל־קֹ֣דֶשׁ לֹֽא־תִגָּ֗ע וְ⁠אֶל־הַ⁠מִּקְדָּשׁ֙ לֹ֣א תָבֹ֔א עַד־מְלֹ֖את יְמֵ֥י טָהֳרָֽ⁠הּ׃","ẇ⁠şĕ̌lòşǐ֥ym ywòm֙ ẇ⁠şĕ̌lò֣şěţ yámi֔ym ţé̇şé֖̌b bi̇⁠dĕmé֣y táhorá֑h bĕ̇⁠kál-qò֣deş̌ lòֽʼ-ţigá̇֗ʻ wĕ⁠ʼel-ha⁠mi̇qĕdá̇ş̌֙ lò֣ʼ ţábò֔ʼ ʻad-mĕlò֖ʼţ yĕmé֥y táhoráֽ⁠ḣ׃"],[12,5,"וְ⁠אִם־נְקֵבָ֣ה תֵלֵ֔ד וְ⁠טָמְאָ֥ה שְׁבֻעַ֖יִם כְּ⁠נִדָּתָ֑⁠הּ וְ⁠שִׁשִּׁ֥ים יוֹם֙ וְ⁠שֵׁ֣שֶׁת יָמִ֔ים תֵּשֵׁ֖ב עַל־דְּמֵ֥י טָהֳרָֽה׃","wĕ⁠ʼim-nĕqébá֣h ţélé֔d wĕ⁠támĕʼá֥h şĕ̌buʻa֖yim kĕ̇⁠nidá̇ţá֑⁠ḣ wĕ⁠şǐşi֥̇̌ym ywòm֙ wĕ⁠şé֣̌şěţ yámi֔ym ţé̇şé֖̌b ʻal-dĕ̇mé֥y táhoráֽh׃"],[12,6,"וּ⁠בִ⁠מְלֹ֣את ׀ יְמֵ֣י טָהֳרָ֗⁠הּ לְ⁠בֵן֮ א֣וֹ לְ⁠בַת֒ תָּבִ֞יא כֶּ֤בֶשׂ בֶּן־שְׁנָת⁠וֹ֙ לְ⁠עֹלָ֔ה וּ⁠בֶן־יוֹנָ֥ה אוֹ־תֹ֖ר לְ⁠חַטָּ֑את אֶל־פֶּ֥תַח אֹֽהֶל־מוֹעֵ֖ד אֶל־הַ⁠כֹּהֵֽן׃","ẇ⁠bi⁠mĕlò֣ʼţ ׀ yĕmé֣y táhorá֗⁠ḣ lĕ⁠bén֮ ʼ֣wò lĕ⁠baţ֒ ţá̇bi֞yʼ kė֤beş̂ bėn-şĕ̌náţ⁠wò֙ lĕ⁠ʻòlá֔h ẇ⁠ben-ywòná֥h ʼwò-ţò֖r lĕ⁠ẖatá֑̇ʼţ ʼel-pė֥ţaẖ ʼòֽhel-mwòʻé֖d ʼel-ha⁠kò̇héֽn׃"],[12,7,"וְ⁠הִקְרִיב֞⁠וֹ לִ⁠פְנֵ֤י יְהוָה֙ וְ⁠כִפֶּ֣ר עָלֶ֔י⁠הָ וְ⁠טָהֲרָ֖ה מִ⁠מְּקֹ֣ר דָּמֶ֑י⁠הָ זֹ֤את תּוֹרַת֙ הַ⁠יֹּלֶ֔דֶת לַ⁠זָּכָ֖ר א֥וֹ לַ⁠נְּקֵבָֽה׃","wĕ⁠hiqĕriyb֞⁠wò li⁠pĕné֤y yĕhwáh֙ wĕ⁠kipė֣r ʻále֔y⁠há wĕ⁠táhàrá֖h mi⁠mĕ̇qò֣r dá̇me֑y⁠há zò֤ʼţ ţ̇wòraţ֙ ha⁠yò̇le֔deţ la⁠zá̇ká֖r ʼ֥wò la⁠nĕ̇qébáֽh׃"],[12,8,"וְ⁠אִם־לֹ֨א תִמְצָ֣א יָדָ⁠הּ֮ דֵּ֣י שֶׂה֒ וְ⁠לָקְחָ֣ה שְׁתֵּֽי־תֹרִ֗ים א֤וֹ שְׁנֵי֙ בְּנֵ֣י יוֹנָ֔ה אֶחָ֥ד לְ⁠עֹלָ֖ה וְ⁠אֶחָ֣ד לְ⁠חַטָּ֑את וְ⁠כִפֶּ֥ר עָלֶ֛י⁠הָ הַ⁠כֹּהֵ֖ן וְ⁠טָהֵֽרָה׃פ","wĕ⁠ʼim-lò֨ʼ ţimĕẕá֣ʼ yádá⁠ḣ֮ dé֣̇y şêh֒ wĕ⁠láqĕẖá֣h şĕ̌ţéֽ̇y-ţòri֗ym ʼ֤wò şĕ̌néy֙ bĕ̇né֣y ywòná֔h ʼeẖá֥d lĕ⁠ʻòlá֖h wĕ⁠ʼeẖá֣d lĕ⁠ẖatá֑̇ʼţ wĕ⁠kipė֥r ʻále֛y⁠há ha⁠kò̇hé֖n wĕ⁠táhéֽráh׃p"],[13,1,"וַ⁠יְדַבֵּ֣ר יְהוָ֔ה אֶל־מֹשֶׁ֥ה וְ⁠אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹֽר׃","wa⁠yĕdabé֣̇r yĕhwá֔h ʼel-mòşě֥h wĕ⁠ʼeֽl-ʼahàrò֖n lé⁠ʼmòֽr׃"],[13,2,"אָדָ֗ם כִּֽי־יִהְיֶ֤ה בְ⁠עוֹר־בְּשָׂר⁠וֹ֙ שְׂאֵ֤ת אֽוֹ־סַפַּ֨חַת֙ א֣וֹ בַהֶ֔רֶת וְ⁠הָיָ֥ה בְ⁠עוֹר־בְּשָׂר֖⁠וֹ לְ⁠נֶ֣גַע צָרָ֑עַת וְ⁠הוּבָא֙ אֶל־אַהֲרֹ֣ן הַ⁠כֹּהֵ֔ן א֛וֹ אֶל־אַחַ֥ד מִ⁠בָּנָ֖י⁠ו הַ⁠כֹּהֲנִֽים׃","ʼádá֗m kiֽ̇y-yihĕye֤h bĕ⁠ʻwòr-bĕ̇şá̂r⁠wò֙ şĕ̂ʼé֤ţ ʼֽwò-sapȧ֨ẖaţ֙ ʼ֣wò bahe֔reţ wĕ⁠háyá֥h bĕ⁠ʻwòr-bĕ̇şá̂r֖⁠wò lĕ⁠ne֣gaʻ ẕárá֑ʻaţ wĕ⁠hẇbáʼ֙ ʼel-ʼahàrò֣n ha⁠kò̇hé֔n ʼ֛wò ʼel-ʼaẖa֥d mi⁠bá̇ná֖y⁠w ha⁠kò̇hàniֽym׃"],[13,3,"וְ⁠רָאָ֣ה הַ⁠כֹּהֵ֣ן אֶת־הַ⁠נֶּ֣גַע בְּ⁠עֽוֹר־הַ֠⁠בָּשָׂר וְ⁠שֵׂעָ֨ר בַּ⁠נֶּ֜גַע הָפַ֣ךְ ׀ לָבָ֗ן וּ⁠מַרְאֵ֤ה הַ⁠נֶּ֨גַע֙ עָמֹק֙ מֵ⁠ע֣וֹר בְּשָׂר֔⁠וֹ נֶ֥גַע צָרַ֖עַת ה֑וּא וְ⁠רָאָ֥⁠הוּ הַ⁠כֹּהֵ֖ן וְ⁠טִמֵּ֥א אֹתֽ⁠וֹ׃","wĕ⁠ráʼá֣h ha⁠kò̇hé֣n ʼeţ-ha⁠nė֣gaʻ bĕ̇⁠ʻֽwòr-ha֠⁠bá̇şá̂r wĕ⁠şé̂ʻá֨r bȧ⁠nė֜gaʻ hápa֣kĕ ׀ lábá֗n ẇ⁠marĕʼé֤h ha⁠nė֨gaʻ֙ ʻámòq֙ mé⁠ʻ֣wòr bĕ̇şá̂r֔⁠wò ne֥gaʻ ẕára֖ʻaţ h֑ẇʼ wĕ⁠ráʼá֥⁠hẇ ha⁠kò̇hé֖n wĕ⁠timé֥̇ʼ ʼòţֽ⁠wò׃"],[13,4,"וְ⁠אִם־בַּהֶרֶת֩ לְבָנָ֨ה הִ֜וא בְּ⁠ע֣וֹר בְּשָׂר֗⁠וֹ וְ⁠עָמֹק֙ אֵין־מַרְאֶ֣⁠הָ מִן־הָ⁠ע֔וֹר וּ⁠שְׂעָרָ֖⁠ה לֹא־הָפַ֣ךְ לָבָ֑ן וְ⁠הִסְגִּ֧יר הַ⁠כֹּהֵ֛ן אֶת־הַ⁠נֶּ֖גַע שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠ʼim-bȧhereţ֩ lĕbáná֨h hi֜wʼ bĕ̇⁠ʻ֣wòr bĕ̇şá̂r֗⁠wò wĕ⁠ʻámòq֙ ʼéyn-marĕʼe֣⁠há min-há⁠ʻ֔wòr ẇ⁠şĕ̂ʻárá֖⁠h lòʼ-hápa֣kĕ lábá֑n wĕ⁠hisĕgi֧̇yr ha⁠kò̇hé֛n ʼeţ-ha⁠nė֖gaʻ şǐbĕʻa֥ţ yámiֽym׃"],[13,5,"וְ⁠רָאָ֣⁠הוּ הַ⁠כֹּהֵן֮ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִי֒ וְ⁠הִנֵּ֤ה הַ⁠נֶּ֨גַע֙ עָמַ֣ד בְּ⁠עֵינָ֔י⁠ו לֹֽא־פָשָׂ֥ה הַ⁠נֶּ֖גַע בָּ⁠ע֑וֹר וְ⁠הִסְגִּיר֧⁠וֹ הַ⁠כֹּהֵ֛ן שִׁבְעַ֥ת יָמִ֖ים שֵׁנִֽית׃","wĕ⁠ráʼá֣⁠hẇ ha⁠kò̇hén֮ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻiy֒ wĕ⁠hiné֤̇h ha⁠nė֨gaʻ֙ ʻáma֣d bĕ̇⁠ʻéyná֔y⁠w lòֽʼ-páşá֥̂h ha⁠nė֖gaʻ bá̇⁠ʻ֑wòr wĕ⁠hisĕgi̇yr֧⁠wò ha⁠kò̇hé֛n şǐbĕʻa֥ţ yámi֖ym şé̌niֽyţ׃"],[13,6,"וְ⁠רָאָה֩ הַ⁠כֹּהֵ֨ן אֹת֜⁠וֹ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִי֮ שֵׁנִית֒ וְ⁠הִנֵּה֙ כֵּהָ֣ה הַ⁠נֶּ֔גַע וְ⁠לֹא־פָשָׂ֥ה הַ⁠נֶּ֖גַע בָּ⁠ע֑וֹר וְ⁠טִהֲר֤⁠וֹ הַ⁠כֹּהֵן֙ מִסְפַּ֣חַת הִ֔יא וְ⁠כִבֶּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָהֵֽר׃","wĕ⁠ráʼáh֩ ha⁠kò̇hé֨n ʼòţ֜⁠wò bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻiy֮ şé̌niyţ֒ wĕ⁠hiné̇h֙ ké̇há֣h ha⁠nė֔gaʻ wĕ⁠lòʼ-páşá֥̂h ha⁠nė֖gaʻ bá̇⁠ʻ֑wòr wĕ⁠tihàr֤⁠wò ha⁠kò̇hén֙ misĕpȧ֣ẖaţ hi֔yʼ wĕ⁠kibė֥s bĕ̇gádá֖y⁠w wĕ⁠táhéֽr׃"],[13,7,"וְ⁠אִם־פָּשֹׂ֨ה תִפְשֶׂ֤ה הַ⁠מִּסְפַּ֨חַת֙ בָּ⁠ע֔וֹר אַחֲרֵ֧י הֵרָאֹת֛⁠וֹ אֶל־הַ⁠כֹּהֵ֖ן לְ⁠טָהֳרָת֑⁠וֹ וְ⁠נִרְאָ֥ה שֵׁנִ֖ית אֶל־הַ⁠כֹּהֵֽן׃","wĕ⁠ʼim-pá̇şò̂֨h ţipĕşê֤h ha⁠mi̇sĕpȧ֨ẖaţ֙ bá̇⁠ʻ֔wòr ʼaẖàré֧y héráʼòţ֛⁠wò ʼel-ha⁠kò̇hé֖n lĕ⁠táhoráţ֑⁠wò wĕ⁠nirĕʼá֥h şé̌ni֖yţ ʼel-ha⁠kò̇héֽn׃"],[13,8,"וְ⁠רָאָה֙ הַ⁠כֹּהֵ֔ן וְ⁠הִנֵּ֛ה פָּשְׂתָ֥ה הַ⁠מִּסְפַּ֖חַת בָּ⁠ע֑וֹר וְ⁠טִמְּא֥⁠וֹ הַ⁠כֹּהֵ֖ן צָרַ֥עַת הִֽוא׃פ","wĕ⁠ráʼáh֙ ha⁠kò̇hé֔n wĕ⁠hiné֛̇h pá̇şĕ̂ţá֥h ha⁠mi̇sĕpȧ֖ẖaţ bá̇⁠ʻ֑wòr wĕ⁠timĕ̇ʼ֥⁠wò ha⁠kò̇hé֖n ẕára֥ʻaţ hiֽwʼ׃p"],[13,9,"נֶ֣גַע צָרַ֔עַת כִּ֥י תִהְיֶ֖ה בְּ⁠אָדָ֑ם וְ⁠הוּבָ֖א אֶל־הַ⁠כֹּהֵֽן׃","ne֣gaʻ ẕára֔ʻaţ ki֥̇y ţihĕye֖h bĕ̇⁠ʼádá֑m wĕ⁠hẇbá֖ʼ ʼel-ha⁠kò̇héֽn׃"],[13,10,"וְ⁠רָאָ֣ה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֤ה שְׂאֵת־לְבָנָה֙ בָּ⁠ע֔וֹר וְ⁠הִ֕יא הָפְכָ֖ה שֵׂעָ֣ר לָבָ֑ן וּ⁠מִֽחְיַ֛ת בָּשָׂ֥ר חַ֖י בַּ⁠שְׂאֵֽת׃","wĕ⁠ráʼá֣h ha⁠kò̇hé֗n wĕ⁠hiné֤̇h şĕ̂ʼéţ-lĕbánáh֙ bá̇⁠ʻ֔wòr wĕ⁠hi֕yʼ hápĕká֖h şé̂ʻá֣r lábá֑n ẇ⁠miֽẖĕya֛ţ bá̇şá֥̂r ẖa֖y bȧ⁠şĕ̂ʼéֽţ׃"],[13,11,"צָרַ֨עַת נוֹשֶׁ֤נֶת הִוא֙ בְּ⁠ע֣וֹר בְּשָׂר֔⁠וֹ וְ⁠טִמְּא֖⁠וֹ הַ⁠כֹּהֵ֑ן לֹ֣א יַסְגִּרֶ֔⁠נּוּ כִּ֥י טָמֵ֖א הֽוּא׃","ẕára֨ʻaţ nwòşě֤neţ hiwʼ֙ bĕ̇⁠ʻ֣wòr bĕ̇şá̂r֔⁠wò wĕ⁠timĕ̇ʼ֖⁠wò ha⁠kò̇hé֑n lò֣ʼ yasĕgi̇re֔⁠ṅẇ ki֥̇y támé֖ʼ hֽẇʼ׃"],[13,12,"וְ⁠אִם־פָּר֨וֹחַ תִּפְרַ֤ח הַ⁠צָּרַ֨עַת֙ בָּ⁠ע֔וֹר וְ⁠כִסְּתָ֣ה הַ⁠צָּרַ֗עַת אֵ֚ת כָּל־ע֣וֹר הַ⁠נֶּ֔גַע מֵ⁠רֹאשׁ֖⁠וֹ וְ⁠עַד־רַגְלָ֑י⁠ו לְ⁠כָל־מַרְאֵ֖ה עֵינֵ֥י הַ⁠כֹּהֵֽן׃","wĕ⁠ʼim-pá̇r֨wòẖa ţi̇pĕra֤ẖ ha⁠ẕá̇ra֨ʻaţ֙ bá̇⁠ʻ֔wòr wĕ⁠kisĕ̇ţá֣h ha⁠ẕá̇ra֗ʻaţ ʼé֚ţ ká̇l-ʻ֣wòr ha⁠nė֔gaʻ mé⁠ròʼş֖̌⁠wò wĕ⁠ʻad-ragĕlá֑y⁠w lĕ⁠kál-marĕʼé֖h ʻéyné֥y ha⁠kò̇héֽn׃"],[13,13,"וְ⁠רָאָ֣ה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֨ה כִסְּתָ֤ה הַ⁠צָּרַ֨עַת֙ אֶת־כָּל־בְּשָׂר֔⁠וֹ וְ⁠טִהַ֖ר אֶת־הַ⁠נָּ֑גַע כֻּלּ֛⁠וֹ הָפַ֥ךְ לָבָ֖ן טָה֥וֹר הֽוּא׃","wĕ⁠ráʼá֣h ha⁠kò̇hé֗n wĕ⁠hiné̇֨h kisĕ̇ţá֤h ha⁠ẕá̇ra֨ʻaţ֙ ʼeţ-ká̇l-bĕ̇şá̂r֔⁠wò wĕ⁠tiha֖r ʼeţ-ha⁠ná֑̇gaʻ ku̇l֛̇⁠wò hápa֥kĕ lábá֖n táh֥wòr hֽẇʼ׃"],[13,14,"וּ⁠בְ⁠י֨וֹם הֵרָא֥וֹת בּ֛⁠וֹ בָּשָׂ֥ר חַ֖י יִטְמָֽא׃","ẇ⁠bĕ⁠y֨wòm héráʼ֥wòţ ḃ֛⁠wò bá̇şá֥̂r ẖa֖y yitĕmáֽʼ׃"],[13,15,"וְ⁠רָאָ֧ה הַ⁠כֹּהֵ֛ן אֶת־הַ⁠בָּשָׂ֥ר הַ⁠חַ֖י וְ⁠טִמְּא֑⁠וֹ הַ⁠בָּשָׂ֥ר הַ⁠חַ֛י טָמֵ֥א ה֖וּא צָרַ֥עַת הֽוּא׃","wĕ⁠ráʼá֧h ha⁠kò̇hé֛n ʼeţ-ha⁠bá̇şá֥̂r ha⁠ẖa֖y wĕ⁠timĕ̇ʼ֑⁠wò ha⁠bá̇şá֥̂r ha⁠ẖa֛y támé֥ʼ h֖ẇʼ ẕára֥ʻaţ hֽẇʼ׃"],[13,16,"א֣וֹ כִ֥י יָשׁ֛וּב הַ⁠בָּשָׂ֥ר הַ⁠חַ֖י וְ⁠נֶהְפַּ֣ךְ לְ⁠לָבָ֑ן וּ⁠בָ֖א אֶל־הַ⁠כֹּהֵֽן׃","ʼ֣wò ki֥y yáş֛̌ẇb ha⁠bá̇şá֥̂r ha⁠ẖa֖y wĕ⁠nehĕpȧ֣kĕ lĕ⁠lábá֑n ẇ⁠bá֖ʼ ʼel-ha⁠kò̇héֽn׃"],[13,17,"וְ⁠רָאָ֨⁠הוּ֙ הַ⁠כֹּהֵ֔ן וְ⁠הִנֵּ֛ה נֶהְפַּ֥ךְ הַ⁠נֶּ֖גַע לְ⁠לָבָ֑ן וְ⁠טִהַ֧ר הַ⁠כֹּהֵ֛ן אֶת־הַ⁠נֶּ֖גַע טָה֥וֹר הֽוּא׃פ","wĕ⁠ráʼá֨⁠hẇ֙ ha⁠kò̇hé֔n wĕ⁠hiné֛̇h nehĕpȧ֥kĕ ha⁠nė֖gaʻ lĕ⁠lábá֑n wĕ⁠tiha֧r ha⁠kò̇hé֛n ʼeţ-ha⁠nė֖gaʻ táh֥wòr hֽẇʼ׃p"],[13,18,"וּ⁠בָשָׂ֕ר כִּֽי־יִהְיֶ֥ה בֽ⁠וֹ־בְ⁠עֹר֖⁠וֹ שְׁחִ֑ין וְ⁠נִרְפָּֽא׃","ẇ⁠báşá̂֕r kiֽ̇y-yihĕye֥h bֽ⁠wò-bĕ⁠ʻòr֖⁠wò şĕ̌ẖi֑yn wĕ⁠nirĕpáֽ̇ʼ׃"],[13,19,"וְ⁠הָיָ֞ה בִּ⁠מְק֤וֹם הַ⁠שְּׁחִין֙ שְׂאֵ֣ת לְבָנָ֔ה א֥וֹ בַהֶ֖רֶת לְבָנָ֣ה אֲדַמְדָּ֑מֶת וְ⁠נִרְאָ֖ה אֶל־הַ⁠כֹּהֵֽן׃","wĕ⁠háyá֞h bi̇⁠mĕq֤wòm ha⁠şĕ̇̌ẖiyn֙ şĕ̂ʼé֣ţ lĕbáná֔h ʼ֥wò bahe֖reţ lĕbáná֣h ʼàdamĕdá֑̇meţ wĕ⁠nirĕʼá֖h ʼel-ha⁠kò̇héֽn׃"],[13,20,"וְ⁠רָאָ֣ה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֤ה מַרְאֶ֨⁠הָ֙ שָׁפָ֣ל מִן־הָ⁠ע֔וֹר וּ⁠שְׂעָרָ֖⁠הּ הָפַ֣ךְ לָבָ֑ן וְ⁠טִמְּא֧⁠וֹ הַ⁠כֹּהֵ֛ן נֶֽגַע־צָרַ֥עַת הִ֖וא בַּ⁠שְּׁחִ֥ין פָּרָֽחָה׃","wĕ⁠ráʼá֣h ha⁠kò̇hé֗n wĕ⁠hiné֤̇h marĕʼe֨⁠há֙ şá̌pá֣l min-há⁠ʻ֔wòr ẇ⁠şĕ̂ʻárá֖⁠ḣ hápa֣kĕ lábá֑n wĕ⁠timĕ̇ʼ֧⁠wò ha⁠kò̇hé֛n neֽgaʻ-ẕára֥ʻaţ hi֖wʼ bȧ⁠şĕ̇̌ẖi֥yn pá̇ráֽẖáh׃"],[13,21,"וְ⁠אִ֣ם ׀ יִרְאֶ֣⁠נָּה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֤ה אֵֽין־בָּ⁠הּ֙ שֵׂעָ֣ר לָבָ֔ן וּ⁠שְׁפָלָ֥ה אֵינֶ֛⁠נָּה מִן־הָ⁠ע֖וֹר וְ⁠הִ֣יא כֵהָ֑ה וְ⁠הִסְגִּיר֥⁠וֹ הַ⁠כֹּהֵ֖ן שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠ʼi֣m ׀ yirĕʼe֣⁠ná̇h ha⁠kò̇hé֗n wĕ⁠hiné֤̇h ʼéֽyn-bá̇⁠ḣ֙ şé̂ʻá֣r lábá֔n ẇ⁠şĕ̌pálá֥h ʼéyne֛⁠ná̇h min-há⁠ʻ֖wòr wĕ⁠hi֣yʼ kéhá֑h wĕ⁠hisĕgi̇yr֥⁠wò ha⁠kò̇hé֖n şǐbĕʻa֥ţ yámiֽym׃"],[13,22,"וְ⁠אִם־פָּשֹׂ֥ה תִפְשֶׂ֖ה בָּ⁠ע֑וֹר וְ⁠טִמֵּ֧א הַ⁠כֹּהֵ֛ן אֹת֖⁠וֹ נֶ֥גַע הִֽוא׃","wĕ⁠ʼim-pá̇şò֥̂h ţipĕşê֖h bá̇⁠ʻ֑wòr wĕ⁠timé֧̇ʼ ha⁠kò̇hé֛n ʼòţ֖⁠wò ne֥gaʻ hiֽwʼ׃"],[13,23,"וְ⁠אִם־תַּחְתֶּ֜י⁠הָ תַּעֲמֹ֤ד הַ⁠בַּהֶ֨רֶת֙ לֹ֣א פָשָׂ֔תָה צָרֶ֥בֶת הַ⁠שְּׁחִ֖ין הִ֑וא וְ⁠טִהֲר֖⁠וֹ הַ⁠כֹּהֵֽן׃ס","wĕ⁠ʼim-ţȧẖĕţė֜y⁠há ţȧʻàmò֤d ha⁠bȧhe֨reţ֙ lò֣ʼ páşá̂֔ţáh ẕáre֥beţ ha⁠şĕ̇̌ẖi֖yn hi֑wʼ wĕ⁠tihàr֖⁠wò ha⁠kò̇héֽn׃s"],[13,24,"א֣וֹ בָשָׂ֔ר כִּֽי־יִהְיֶ֥ה בְ⁠עֹר֖⁠וֹ מִכְוַת־אֵ֑שׁ וְֽ⁠הָיְתָ֞ה מִֽחְיַ֣ת הַ⁠מִּכְוָ֗ה בַּהֶ֛רֶת לְבָנָ֥ה אֲדַמְדֶּ֖מֶת א֥וֹ לְבָנָֽה׃","ʼ֣wò báşá̂֔r kiֽ̇y-yihĕye֥h bĕ⁠ʻòr֖⁠wò mikĕwaţ-ʼé֑ş̌ wĕֽ⁠háyĕţá֞h miֽẖĕya֣ţ ha⁠mi̇kĕwá֗h bȧhe֛reţ lĕbáná֥h ʼàdamĕdė֖meţ ʼ֥wò lĕbánáֽh׃"],[13,25,"וְ⁠רָאָ֣ה אֹתָ֣⁠הּ הַ⁠כֹּהֵ֡ן וְ⁠הִנֵּ֣ה נֶהְפַּךְ֩ שֵׂעָ֨ר לָבָ֜ן בַּ⁠בַּהֶ֗רֶת וּ⁠מַרְאֶ֨⁠הָ֙ עָמֹ֣ק מִן־הָ⁠ע֔וֹר צָרַ֣עַת הִ֔וא בַּ⁠מִּכְוָ֖ה פָּרָ֑חָה וְ⁠טִמֵּ֤א אֹת⁠וֹ֙ הַ⁠כֹּהֵ֔ן נֶ֥גַע צָרַ֖עַת הִֽוא׃","wĕ⁠ráʼá֣h ʼòţá֣⁠ḣ ha⁠kò̇hé֡n wĕ⁠hiné֣̇h nehĕpȧkĕ֩ şé̂ʻá֨r lábá֜n bȧ⁠bȧhe֗reţ ẇ⁠marĕʼe֨⁠há֙ ʻámò֣q min-há⁠ʻ֔wòr ẕára֣ʻaţ hi֔wʼ bȧ⁠mi̇kĕwá֖h pá̇rá֑ẖáh wĕ⁠timé֤̇ʼ ʼòţ⁠wò֙ ha⁠kò̇hé֔n ne֥gaʻ ẕára֖ʻaţ hiֽwʼ׃"],[13,26,"וְ⁠אִ֣ם ׀ יִרְאֶ֣⁠נָּה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֤ה אֵֽין־בַּ⁠בֶּהֶ֨רֶת֙ שֵׂעָ֣ר לָבָ֔ן וּ⁠שְׁפָלָ֥ה אֵינֶ֛⁠נָּה מִן־הָ⁠ע֖וֹר וְ⁠הִ֣וא כֵהָ֑ה וְ⁠הִסְגִּיר֥⁠וֹ הַ⁠כֹּהֵ֖ן שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠ʼi֣m ׀ yirĕʼe֣⁠ná̇h ha⁠kò̇hé֗n wĕ⁠hiné֤̇h ʼéֽyn-bȧ⁠bėhe֨reţ֙ şé̂ʻá֣r lábá֔n ẇ⁠şĕ̌pálá֥h ʼéyne֛⁠ná̇h min-há⁠ʻ֖wòr wĕ⁠hi֣wʼ kéhá֑h wĕ⁠hisĕgi̇yr֥⁠wò ha⁠kò̇hé֖n şǐbĕʻa֥ţ yámiֽym׃"],[13,27,"וְ⁠רָאָ֥⁠הוּ הַ⁠כֹּהֵ֖ן בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֑י אִם־פָּשֹׂ֤ה תִפְשֶׂה֙ בָּ⁠ע֔וֹר וְ⁠טִמֵּ֤א הַ⁠כֹּהֵן֙ אֹת֔⁠וֹ נֶ֥גַע צָרַ֖עַת הִֽוא׃","wĕ⁠ráʼá֥⁠hẇ ha⁠kò̇hé֖n bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֑y ʼim-pá̇şò֤̂h ţipĕşêh֙ bá̇⁠ʻ֔wòr wĕ⁠timé֤̇ʼ ha⁠kò̇hén֙ ʼòţ֔⁠wò ne֥gaʻ ẕára֖ʻaţ hiֽwʼ׃"],[13,28,"וְ⁠אִם־תַּחְתֶּי⁠הָ֩ תַעֲמֹ֨ד הַ⁠בַּהֶ֜רֶת לֹא־פָשְׂתָ֤ה בָ⁠עוֹר֙ וְ⁠הִ֣וא כֵהָ֔ה שְׂאֵ֥ת הַ⁠מִּכְוָ֖ה הִ֑וא וְ⁠טִֽהֲר⁠וֹ֙ הַ⁠כֹּהֵ֔ן כִּֽי־צָרֶ֥בֶת הַ⁠מִּכְוָ֖ה הִֽוא׃פ","wĕ⁠ʼim-ţȧẖĕţėy⁠há֩ ţaʻàmò֨d ha⁠bȧhe֜reţ lòʼ-páşĕ̂ţá֤h bá⁠ʻwòr֙ wĕ⁠hi֣wʼ kéhá֔h şĕ̂ʼé֥ţ ha⁠mi̇kĕwá֖h hi֑wʼ wĕ⁠tiֽhàr⁠wò֙ ha⁠kò̇hé֔n kiֽ̇y-ẕáre֥beţ ha⁠mi̇kĕwá֖h hiֽwʼ׃p"],[13,29,"וְ⁠אִישׁ֙ א֣וֹ אִשָּׁ֔ה כִּֽי־יִהְיֶ֥ה ב֖⁠וֹ נָ֑גַע בְּ⁠רֹ֖אשׁ א֥וֹ בְ⁠זָקָֽן׃","wĕ⁠ʼiyş̌֙ ʼ֣wò ʼişá̇̌֔h kiֽ̇y-yihĕye֥h b֖⁠wò ná֑gaʻ bĕ̇⁠rò֖ʼş̌ ʼ֥wò bĕ⁠záqáֽn׃"],[13,30,"וְ⁠רָאָ֨ה הַ⁠כֹּהֵ֜ן אֶת־הַ⁠נֶּ֗גַע וְ⁠הִנֵּ֤ה מַרְאֵ֨⁠הוּ֙ עָמֹ֣ק מִן־הָ⁠ע֔וֹר וּ⁠ב֛⁠וֹ שֵׂעָ֥ר צָהֹ֖ב דָּ֑ק וְ⁠טִמֵּ֨א אֹת֤⁠וֹ הַ⁠כֹּהֵן֙ נֶ֣תֶק ה֔וּא צָרַ֧עַת הָ⁠רֹ֛אשׁ א֥וֹ הַ⁠זָּקָ֖ן הֽוּא׃","wĕ⁠ráʼá֨h ha⁠kò̇hé֜n ʼeţ-ha⁠nė֗gaʻ wĕ⁠hiné֤̇h marĕʼé֨⁠hẇ֙ ʻámò֣q min-há⁠ʻ֔wòr ẇ⁠b֛⁠wò şé̂ʻá֥r ẕáhò֖b dá֑̇q wĕ⁠timé̇֨ʼ ʼòţ֤⁠wò ha⁠kò̇hén֙ ne֣ţeq h֔ẇʼ ẕára֧ʻaţ há⁠rò֛ʼş̌ ʼ֥wò ha⁠zá̇qá֖n hֽẇʼ׃"],[13,31,"וְ⁠כִֽי־יִרְאֶ֨ה הַ⁠כֹּהֵ֜ן אֶת־נֶ֣גַע הַ⁠נֶּ֗תֶק וְ⁠הִנֵּ֤ה אֵין־מַרְאֵ֨⁠הוּ֙ עָמֹ֣ק מִן־הָ⁠ע֔וֹר וְ⁠שֵׂעָ֥ר שָׁחֹ֖ר אֵ֣ין בּ֑⁠וֹ וְ⁠הִסְגִּ֧יר הַ⁠כֹּהֵ֛ן אֶת־נֶ֥גַע הַ⁠נֶּ֖תֶק שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠kiֽy-yirĕʼe֨h ha⁠kò̇hé֜n ʼeţ-ne֣gaʻ ha⁠nė֗ţeq wĕ⁠hiné֤̇h ʼéyn-marĕʼé֨⁠hẇ֙ ʻámò֣q min-há⁠ʻ֔wòr wĕ⁠şé̂ʻá֥r şá̌ẖò֖r ʼé֣yn ḃ֑⁠wò wĕ⁠hisĕgi֧̇yr ha⁠kò̇hé֛n ʼeţ-ne֥gaʻ ha⁠nė֖ţeq şǐbĕʻa֥ţ yámiֽym׃"],[13,32,"וְ⁠רָאָ֨ה הַ⁠כֹּהֵ֣ן אֶת־הַ⁠נֶּגַע֮ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִי֒ וְ⁠הִנֵּה֙ לֹא־פָשָׂ֣ה הַ⁠נֶּ֔תֶק וְ⁠לֹא־הָ֥יָה ב֖⁠וֹ שֵׂעָ֣ר צָהֹ֑ב וּ⁠מַרְאֵ֣ה הַ⁠נֶּ֔תֶק אֵ֥ין עָמֹ֖ק מִן־הָ⁠עֽוֹר׃","wĕ⁠ráʼá֨h ha⁠kò̇hé֣n ʼeţ-ha⁠nėgaʻ֮ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻiy֒ wĕ⁠hiné̇h֙ lòʼ-páşá֣̂h ha⁠nė֔ţeq wĕ⁠lòʼ-há֥yáh b֖⁠wò şé̂ʻá֣r ẕáhò֑b ẇ⁠marĕʼé֣h ha⁠nė֔ţeq ʼé֥yn ʻámò֖q min-há⁠ʻֽwòr׃"],[13,33,"וְ⁠הִ֨תְגַּלָּ֔ח וְ⁠אֶת־הַ⁠נֶּ֖תֶק לֹ֣א יְגַלֵּ֑חַ וְ⁠הִסְגִּ֨יר הַ⁠כֹּהֵ֧ן אֶת־הַ⁠נֶּ֛תֶק שִׁבְעַ֥ת יָמִ֖ים שֵׁנִֽית׃","wĕ⁠hi֨ţĕgȧlá̇֔ẖ wĕ⁠ʼeţ-ha⁠nė֖ţeq lò֣ʼ yĕgalé֑̇ẖa wĕ⁠hisĕgi̇֨yr ha⁠kò̇hé֧n ʼeţ-ha⁠nė֛ţeq şǐbĕʻa֥ţ yámi֖ym şé̌niֽyţ׃"],[13,34,"וְ⁠רָאָה֩ הַ⁠כֹּהֵ֨ן אֶת־הַ⁠נֶּ֜תֶק בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י וְ֠⁠הִנֵּה לֹא־פָשָׂ֤ה הַ⁠נֶּ֨תֶק֙ בָּ⁠ע֔וֹר וּ⁠מַרְאֵ֕⁠הוּ אֵינֶ֥⁠נּוּ עָמֹ֖ק מִן־הָ⁠ע֑וֹר וְ⁠טִהַ֤ר אֹת⁠וֹ֙ הַ⁠כֹּהֵ֔ן וְ⁠כִבֶּ֥ס בְּגָדָ֖י⁠ו וְ⁠טָהֵֽר׃","wĕ⁠ráʼáh֩ ha⁠kò̇hé֨n ʼeţ-ha⁠nė֜ţeq bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y wĕ֠⁠hiné̇h lòʼ-páşá֤̂h ha⁠nė֨ţeq֙ bá̇⁠ʻ֔wòr ẇ⁠marĕʼé֕⁠hẇ ʼéyne֥⁠ṅẇ ʻámò֖q min-há⁠ʻ֑wòr wĕ⁠tiha֤r ʼòţ⁠wò֙ ha⁠kò̇hé֔n wĕ⁠kibė֥s bĕ̇gádá֖y⁠w wĕ⁠táhéֽr׃"],[13,35,"וְ⁠אִם־פָּשֹׂ֥ה יִפְשֶׂ֛ה הַ⁠נֶּ֖תֶק בָּ⁠ע֑וֹר אַחֲרֵ֖י טָהֳרָתֽ⁠וֹ׃","wĕ⁠ʼim-pá̇şò֥̂h yipĕşê֛h ha⁠nė֖ţeq bá̇⁠ʻ֑wòr ʼaẖàré֖y táhoráţֽ⁠wò׃"],[13,36,"וְ⁠רָאָ֨⁠הוּ֙ הַ⁠כֹּהֵ֔ן וְ⁠הִנֵּ֛ה פָּשָׂ֥ה הַ⁠נֶּ֖תֶק בָּ⁠ע֑וֹר לֹֽא־יְבַקֵּ֧ר הַ⁠כֹּהֵ֛ן לַ⁠שֵּׂעָ֥ר הַ⁠צָּהֹ֖ב טָמֵ֥א הֽוּא׃","wĕ⁠ráʼá֨⁠hẇ֙ ha⁠kò̇hé֔n wĕ⁠hiné֛̇h pá̇şá֥̂h ha⁠nė֖ţeq bá̇⁠ʻ֑wòr lòֽʼ-yĕbaqé֧̇r ha⁠kò̇hé֛n la⁠şé̇̂ʻá֥r ha⁠ẕá̇hò֖b támé֥ʼ hֽẇʼ׃"],[13,37,"וְ⁠אִם־בְּ⁠עֵינָי⁠ו֩ עָמַ֨ד הַ⁠נֶּ֜תֶק וְ⁠שֵׂעָ֨ר שָׁחֹ֧ר צָֽמַח־בּ֛⁠וֹ נִרְפָּ֥א הַ⁠נֶּ֖תֶק טָה֣וֹר ה֑וּא וְ⁠טִהֲר֖⁠וֹ הַ⁠כֹּהֵֽן׃ס","wĕ⁠ʼim-bĕ̇⁠ʻéynáy⁠w֩ ʻáma֨d ha⁠nė֜ţeq wĕ⁠şé̂ʻá֨r şá̌ẖò֧r ẕáֽmaẖ-ḃ֛⁠wò nirĕpá֥̇ʼ ha⁠nė֖ţeq táh֣wòr h֑ẇʼ wĕ⁠tihàr֖⁠wò ha⁠kò̇héֽn׃s"],[13,38,"וְ⁠אִישׁ֙ אֽוֹ־אִשָּׁ֔ה כִּֽי־יִהְיֶ֥ה בְ⁠עוֹר־בְּשָׂרָ֖⁠ם בֶּהָרֹ֑ת בֶּהָרֹ֖ת לְבָנֹֽת׃","wĕ⁠ʼiyş̌֙ ʼֽwò-ʼişá̇̌֔h kiֽ̇y-yihĕye֥h bĕ⁠ʻwòr-bĕ̇şá̂rá֖⁠m bėhárò֑ţ bėhárò֖ţ lĕbánòֽţ׃"],[13,39,"וְ⁠רָאָ֣ה הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֧ה בְ⁠עוֹר־בְּשָׂרָ֛⁠ם בֶּהָרֹ֖ת כֵּה֣וֹת לְבָנֹ֑ת בֹּ֥הַק ה֛וּא פָּרַ֥ח בָּ⁠ע֖וֹר טָה֥וֹר הֽוּא׃ס","wĕ⁠ráʼá֣h ha⁠kò̇hé֗n wĕ⁠hiné֧̇h bĕ⁠ʻwòr-bĕ̇şá̂rá֛⁠m bėhárò֖ţ ké̇h֣wòţ lĕbánò֑ţ bò֥̇haq h֛ẇʼ pá̇ra֥ẖ bá̇⁠ʻ֖wòr táh֥wòr hֽẇʼ׃s"],[13,40,"וְ⁠אִ֕ישׁ כִּ֥י יִמָּרֵ֖ט רֹאשׁ֑⁠וֹ קֵרֵ֥חַ ה֖וּא טָה֥וֹר הֽוּא׃","wĕ⁠ʼi֕yş̌ ki֥̇y yimá̇ré֖t ròʼş֑̌⁠wò qéré֥ẖa h֖ẇʼ táh֥wòr hֽẇʼ׃"],[13,41,"וְ⁠אִם֙ מִ⁠פְּאַ֣ת פָּנָ֔י⁠ו יִמָּרֵ֖ט רֹאשׁ֑⁠וֹ גִּבֵּ֥חַ ה֖וּא טָה֥וֹר הֽוּא׃","wĕ⁠ʼim֙ mi⁠pĕ̇ʼa֣ţ pá̇ná֔y⁠w yimá̇ré֖t ròʼş֑̌⁠wò gi̇bé֥̇ẖa h֖ẇʼ táh֥wòr hֽẇʼ׃"],[13,42,"וְ⁠כִֽי־יִהְיֶ֤ה בַ⁠קָּרַ֨חַת֙ א֣וֹ בַ⁠גַּבַּ֔חַת נֶ֖גַע לָבָ֣ן אֲדַמְדָּ֑ם צָרַ֤עַת פֹּרַ֨חַת֙ הִ֔וא בְּ⁠קָרַחְתּ֖⁠וֹ א֥וֹ בְ⁠גַבַּחְתּֽ⁠וֹ׃","wĕ⁠kiֽy-yihĕye֤h ba⁠qá̇ra֨ẖaţ֙ ʼ֣wò ba⁠gȧbȧ֔ẖaţ ne֖gaʻ lábá֣n ʼàdamĕdá֑̇m ẕára֤ʻaţ pò̇ra֨ẖaţ֙ hi֔wʼ bĕ̇⁠qáraẖĕţ֖̇⁠wò ʼ֥wò bĕ⁠gabȧẖĕţֽ̇⁠wò׃"],[13,43,"וְ⁠רָאָ֨ה אֹת֜⁠וֹ הַ⁠כֹּהֵ֗ן וְ⁠הִנֵּ֤ה שְׂאֵת־הַ⁠נֶּ֨גַע֙ לְבָנָ֣ה אֲדַמְדֶּ֔מֶת בְּ⁠קָרַחְתּ֖⁠וֹ א֣וֹ בְ⁠גַבַּחְתּ֑⁠וֹ כְּ⁠מַרְאֵ֥ה צָרַ֖עַת ע֥וֹר בָּשָֽׂר׃","wĕ⁠ráʼá֨h ʼòţ֜⁠wò ha⁠kò̇hé֗n wĕ⁠hiné֤̇h şĕ̂ʼéţ-ha⁠nė֨gaʻ֙ lĕbáná֣h ʼàdamĕdė֔meţ bĕ̇⁠qáraẖĕţ֖̇⁠wò ʼ֣wò bĕ⁠gabȧẖĕţ֑̇⁠wò kĕ̇⁠marĕʼé֥h ẕára֖ʻaţ ʻ֥wòr bá̇şáֽ̂r׃"],[13,44,"אִישׁ־צָר֥וּעַ ה֖וּא טָמֵ֣א ה֑וּא טַמֵּ֧א יְטַמְּאֶ֛⁠נּוּ הַ⁠כֹּהֵ֖ן בְּ⁠רֹאשׁ֥⁠וֹ נִגְעֽ⁠וֹ׃","ʼiyş̌-ẕár֥ẇʻa h֖ẇʼ támé֣ʼ h֑ẇʼ tamé֧̇ʼ yĕtamĕ̇ʼe֛⁠ṅẇ ha⁠kò̇hé֖n bĕ̇⁠ròʼş֥̌⁠wò nigĕʻֽ⁠wò׃"],[13,45,"וְ⁠הַ⁠צָּר֜וּעַ אֲשֶׁר־בּ֣⁠וֹ הַ⁠נֶּ֗גַע בְּגָדָ֞י⁠ו יִהְי֤וּ פְרֻמִים֙ וְ⁠רֹאשׁ⁠וֹ֙ יִהְיֶ֣ה פָר֔וּעַ וְ⁠עַל־שָׂפָ֖ם יַעְטֶ֑ה וְ⁠טָמֵ֥א ׀ טָמֵ֖א יִקְרָֽא׃","wĕ⁠ha⁠ẕá̇r֜ẇʻa ʼàşěr-ḃ֣⁠wò ha⁠nė֗gaʻ bĕ̇gádá֞y⁠w yihĕy֤ẇ pĕrumiym֙ wĕ⁠ròʼş̌⁠wò֙ yihĕye֣h pár֔ẇʻa wĕ⁠ʻal-şá̂pá֖m yaʻĕte֑h wĕ⁠támé֥ʼ ׀ támé֖ʼ yiqĕráֽʼ׃"],[13,46,"כָּל־יְמֵ֞י אֲשֶׁ֨ר הַ⁠נֶּ֥גַע בּ֛⁠וֹ יִטְמָ֖א טָמֵ֣א ה֑וּא בָּדָ֣ד יֵשֵׁ֔ב מִ⁠ח֥וּץ לַֽ⁠מַּחֲנֶ֖ה מוֹשָׁבֽ⁠וֹ׃ס","ká̇l-yĕmé֞y ʼàşě֨r ha⁠nė֥gaʻ ḃ֛⁠wò yitĕmá֖ʼ támé֣ʼ h֑ẇʼ bá̇dá֣d yéşé̌֔b mi⁠ẖ֥ẇẕ laֽ⁠mȧẖàne֖h mwòşá̌bֽ⁠wò׃s"],[13,47,"וְ⁠הַ⁠בֶּ֕גֶד כִּֽי־יִהְיֶ֥ה ב֖⁠וֹ נֶ֣גַע צָרָ֑עַת בְּ⁠בֶ֣גֶד צֶ֔מֶר א֖וֹ בְּ⁠בֶ֥גֶד פִּשְׁתִּֽים׃","wĕ⁠ha⁠bė֕ged kiֽ̇y-yihĕye֥h b֖⁠wò ne֣gaʻ ẕárá֑ʻaţ bĕ̇⁠be֣ged ẕe֔mer ʼ֖wò bĕ̇⁠be֥ged pi̇şĕ̌ţiֽ̇ym׃"],[13,48,"א֤וֹ בִֽ⁠שְׁתִי֙ א֣וֹ בְ⁠עֵ֔רֶב לַ⁠פִּשְׁתִּ֖ים וְ⁠לַ⁠צָּ֑מֶר א֣וֹ בְ⁠ע֔וֹר א֖וֹ בְּ⁠כָל־מְלֶ֥אכֶת עֽוֹר׃","ʼ֤wò biֽ⁠şĕ̌ţiy֙ ʼ֣wò bĕ⁠ʻé֔reb la⁠pi̇şĕ̌ţi֖̇ym wĕ⁠la⁠ẕá֑̇mer ʼ֣wò bĕ⁠ʻ֔wòr ʼ֖wò bĕ̇⁠kál-mĕle֥ʼkeţ ʻֽwòr׃"],[13,49,"וְ⁠הָיָ֨ה הַ⁠נֶּ֜גַע יְרַקְרַ֣ק ׀ א֣וֹ אֲדַמְדָּ֗ם בַּ⁠בֶּגֶד֩ א֨וֹ בָ⁠ע֜וֹר אֽוֹ־בַ⁠שְּׁתִ֤י אוֹ־בָ⁠עֵ֨רֶב֙ א֣וֹ בְ⁠כָל־כְּלִי־ע֔וֹר נֶ֥גַע צָרַ֖עַת ה֑וּא וְ⁠הָרְאָ֖ה אֶת־הַ⁠כֹּהֵֽן׃","wĕ⁠háyá֨h ha⁠nė֜gaʻ yĕraqĕra֣q ׀ ʼ֣wò ʼàdamĕdá̇֗m bȧ⁠bėged֩ ʼ֨wò bá⁠ʻ֜wòr ʼֽwò-ba⁠şĕ̇̌ţi֤y ʼwò-bá⁠ʻé֨reb֙ ʼ֣wò bĕ⁠kál-kĕ̇liy-ʻ֔wòr ne֥gaʻ ẕára֖ʻaţ h֑ẇʼ wĕ⁠hárĕʼá֖h ʼeţ-ha⁠kò̇héֽn׃"],[13,50,"וְ⁠רָאָ֥ה הַ⁠כֹּהֵ֖ן אֶת־הַ⁠נָּ֑גַע וְ⁠הִסְגִּ֥יר אֶת־הַ⁠נֶּ֖גַע שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠ráʼá֥h ha⁠kò̇hé֖n ʼeţ-ha⁠ná֑̇gaʻ wĕ⁠hisĕgi֥̇yr ʼeţ-ha⁠nė֖gaʻ şǐbĕʻa֥ţ yámiֽym׃"],[13,51,"וְ⁠רָאָ֨ה אֶת־הַ⁠נֶּ֜גַע בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י כִּֽי־פָשָׂ֤ה הַ⁠נֶּ֨גַע֙ בַּ֠⁠בֶּגֶד אֽוֹ־בַ⁠שְּׁתִ֤י אֽוֹ־בָ⁠עֵ֨רֶב֙ א֣וֹ בָ⁠ע֔וֹר לְ⁠כֹ֛ל אֲשֶׁר־יֵעָשֶׂ֥ה הָ⁠ע֖וֹר לִ⁠מְלָאכָ֑ה צָרַ֧עַת מַמְאֶ֛רֶת הַ⁠נֶּ֖גַע טָמֵ֥א הֽוּא׃","wĕ⁠ráʼá֨h ʼeţ-ha⁠nė֜gaʻ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y kiֽ̇y-páşá֤̂h ha⁠nė֨gaʻ֙ bȧ֠⁠bėged ʼֽwò-ba⁠şĕ̇̌ţi֤y ʼֽwò-bá⁠ʻé֨reb֙ ʼ֣wò bá⁠ʻ֔wòr lĕ⁠kò֛l ʼàşěr-yéʻáşê֥h há⁠ʻ֖wòr li⁠mĕláʼká֑h ẕára֧ʻaţ mamĕʼe֛reţ ha⁠nė֖gaʻ támé֥ʼ hֽẇʼ׃"],[13,52,"וְ⁠שָׂרַ֨ף אֶת־הַ⁠בֶּ֜גֶד א֥וֹ אֶֽת־הַ⁠שְּׁתִ֣י ׀ א֣וֹ אֶת־הָ⁠עֵ֗רֶב בַּ⁠צֶּ֨מֶר֙ א֣וֹ בַ⁠פִּשְׁתִּ֔ים א֚וֹ אֶת־כָּל־כְּלִ֣י הָ⁠ע֔וֹר אֲשֶׁר־יִהְיֶ֥ה ב֖⁠וֹ הַ⁠נָּ֑גַע כִּֽי־צָרַ֤עַת מַמְאֶ֨רֶת֙ הִ֔וא בָּ⁠אֵ֖שׁ תִּשָּׂרֵֽף׃","wĕ⁠şá̂ra֨p ʼeţ-ha⁠bė֜ged ʼ֥wò ʼeֽţ-ha⁠şĕ̇̌ţi֣y ׀ ʼ֣wò ʼeţ-há⁠ʻé֗reb bȧ⁠ẕė֨mer֙ ʼ֣wò ba⁠pi̇şĕ̌ţi̇֔ym ʼ֚wò ʼeţ-ká̇l-kĕ̇li֣y há⁠ʻ֔wòr ʼàşěr-yihĕye֥h b֖⁠wò ha⁠ná֑̇gaʻ kiֽ̇y-ẕára֤ʻaţ mamĕʼe֨reţ֙ hi֔wʼ bá̇⁠ʼé֖ş̌ ţi̇şá̇̂réֽp׃"],[13,53,"וְ⁠אִם֮ יִרְאֶ֣ה הַ⁠כֹּהֵן֒ וְ⁠הִנֵּה֙ לֹא־פָשָׂ֣ה הַ⁠נֶּ֔גַע בַּ⁠בֶּ֕גֶד א֥וֹ בַ⁠שְּׁתִ֖י א֣וֹ בָ⁠עֵ֑רֶב א֖וֹ בְּ⁠כָל־כְּלִי־עֽוֹר׃","wĕ⁠ʼim֮ yirĕʼe֣h ha⁠kò̇hén֒ wĕ⁠hiné̇h֙ lòʼ-páşá֣̂h ha⁠nė֔gaʻ bȧ⁠bė֕ged ʼ֥wò ba⁠şĕ̇̌ţi֖y ʼ֣wò bá⁠ʻé֑reb ʼ֖wò bĕ̇⁠kál-kĕ̇liy-ʻֽwòr׃"],[13,54,"וְ⁠צִוָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠כִ֨בְּס֔וּ אֵ֥ת אֲשֶׁר־בּ֖⁠וֹ הַ⁠נָּ֑גַע וְ⁠הִסְגִּיר֥⁠וֹ שִׁבְעַת־יָמִ֖ים שֵׁנִֽית׃","wĕ⁠ẕiwá̇h֙ ha⁠kò̇hé֔n wĕ⁠ki֨bĕ̇s֔ẇ ʼé֥ţ ʼàşěr-ḃ֖⁠wò ha⁠ná֑̇gaʻ wĕ⁠hisĕgi̇yr֥⁠wò şǐbĕʻaţ-yámi֖ym şé̌niֽyţ׃"],[13,55,"וְ⁠רָאָ֨ה הַ⁠כֹּהֵ֜ן אַחֲרֵ֣י ׀ הֻכַּבֵּ֣ס אֶת־הַ⁠נֶּ֗גַע וְ֠⁠הִנֵּה לֹֽא־הָפַ֨ךְ הַ⁠נֶּ֤גַע אֶת־עֵינ⁠וֹ֙ וְ⁠הַ⁠נֶּ֣גַע לֹֽא־פָשָׂ֔ה טָמֵ֣א ה֔וּא בָּ⁠אֵ֖שׁ תִּשְׂרְפֶ֑⁠נּוּ פְּחֶ֣תֶת הִ֔וא בְּ⁠קָרַחְתּ֖⁠וֹ א֥וֹ בְ⁠גַבַּחְתּֽ⁠וֹ׃","wĕ⁠ráʼá֨h ha⁠kò̇hé֜n ʼaẖàré֣y ׀ hukȧbé֣̇s ʼeţ-ha⁠nė֗gaʻ wĕ֠⁠hiné̇h lòֽʼ-hápa֨kĕ ha⁠nė֤gaʻ ʼeţ-ʻéyn⁠wò֙ wĕ⁠ha⁠nė֣gaʻ lòֽʼ-páşá̂֔h támé֣ʼ h֔ẇʼ bá̇⁠ʼé֖ş̌ ţi̇şĕ̂rĕpe֑⁠ṅẇ pĕ̇ẖe֣ţeţ hi֔wʼ bĕ̇⁠qáraẖĕţ֖̇⁠wò ʼ֥wò bĕ⁠gabȧẖĕţֽ̇⁠wò׃"],[13,56,"וְ⁠אִם֮ רָאָ֣ה הַ⁠כֹּהֵן֒ וְ⁠הִנֵּה֙ כֵּהָ֣ה הַ⁠נֶּ֔גַע אַחֲרֵ֖י הֻכַּבֵּ֣ס אֹת֑⁠וֹ וְ⁠קָרַ֣ע אֹת֗⁠וֹ מִן־הַ⁠בֶּ֨גֶד֙ א֣וֹ מִן־הָ⁠ע֔וֹר א֥וֹ מִן־הַ⁠שְּׁתִ֖י א֥וֹ מִן־הָ⁠עֵֽרֶב׃","wĕ⁠ʼim֮ ráʼá֣h ha⁠kò̇hén֒ wĕ⁠hiné̇h֙ ké̇há֣h ha⁠nė֔gaʻ ʼaẖàré֖y hukȧbé֣̇s ʼòţ֑⁠wò wĕ⁠qára֣ʻ ʼòţ֗⁠wò min-ha⁠bė֨ged֙ ʼ֣wò min-há⁠ʻ֔wòr ʼ֥wò min-ha⁠şĕ̇̌ţi֖y ʼ֥wò min-há⁠ʻéֽreb׃"],[13,57,"וְ⁠אִם־תֵּרָאֶ֨ה ע֜וֹד בַּ֠⁠בֶּגֶד אֽוֹ־בַ⁠שְּׁתִ֤י אֽוֹ־בָ⁠עֵ֨רֶב֙ א֣וֹ בְ⁠כָל־כְּלִי־ע֔וֹר פֹּרַ֖חַת הִ֑וא בָּ⁠אֵ֣שׁ תִּשְׂרְפֶ֔⁠נּוּ אֵ֥ת אֲשֶׁר־בּ֖⁠וֹ הַ⁠נָּֽגַע׃","wĕ⁠ʼim-ţé̇ráʼe֨h ʻ֜wòd bȧ֠⁠bėged ʼֽwò-ba⁠şĕ̇̌ţi֤y ʼֽwò-bá⁠ʻé֨reb֙ ʼ֣wò bĕ⁠kál-kĕ̇liy-ʻ֔wòr pò̇ra֖ẖaţ hi֑wʼ bá̇⁠ʼé֣ş̌ ţi̇şĕ̂rĕpe֔⁠ṅẇ ʼé֥ţ ʼàşěr-ḃ֖⁠wò ha⁠náֽ̇gaʻ׃"],[13,58,"וְ⁠הַ⁠בֶּ֡גֶד אֽוֹ־הַ⁠שְּׁתִ֨י אוֹ־הָ⁠עֵ֜רֶב אֽוֹ־כָל־כְּלִ֤י הָ⁠עוֹר֙ אֲשֶׁ֣ר תְּכַבֵּ֔ס וְ⁠סָ֥ר מֵ⁠הֶ֖ם הַ⁠נָּ֑גַע וְ⁠כֻבַּ֥ס שֵׁנִ֖ית וְ⁠טָהֵֽר׃","wĕ⁠ha⁠bė֡ged ʼֽwò-ha⁠şĕ̇̌ţi֨y ʼwò-há⁠ʻé֜reb ʼֽwò-kál-kĕ̇li֤y há⁠ʻwòr֙ ʼàşě֣r ţĕ̇kabé̇֔s wĕ⁠sá֥r mé⁠he֖m ha⁠ná֑̇gaʻ wĕ⁠kubȧ֥s şé̌ni֖yţ wĕ⁠táhéֽr׃"],[13,59,"זֹ֠את תּוֹרַ֨ת נֶֽגַע־צָרַ֜עַת בֶּ֥גֶד הַ⁠צֶּ֣מֶר ׀ א֣וֹ הַ⁠פִּשְׁתִּ֗ים א֤וֹ הַ⁠שְּׁתִי֙ א֣וֹ הָ⁠עֵ֔רֶב א֖וֹ כָּל־כְּלִי־ע֑וֹר לְ⁠טַהֲר֖⁠וֹ א֥וֹ לְ⁠טַמְּאֽ⁠וֹ׃פ","zò֠ʼţ ţ̇wòra֨ţ neֽgaʻ-ẕára֜ʻaţ bė֥ged ha⁠ẕė֣mer ׀ ʼ֣wò ha⁠pi̇şĕ̌ţi̇֗ym ʼ֤wò ha⁠şĕ̇̌ţiy֙ ʼ֣wò há⁠ʻé֔reb ʼ֖wò ká̇l-kĕ̇liy-ʻ֑wòr lĕ⁠tahàr֖⁠wò ʼ֥wò lĕ⁠tamĕ̇ʼֽ⁠wò׃p"],[14,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[14,2,"זֹ֤את תִּֽהְיֶה֙ תּוֹרַ֣ת הַ⁠מְּצֹרָ֔ע בְּ⁠י֖וֹם טָהֳרָת֑⁠וֹ וְ⁠הוּבָ֖א אֶל־הַ⁠כֹּהֵֽן׃","zò֤ʼţ ţiֽ̇hĕyeh֙ ţ̇wòra֣ţ ha⁠mĕ̇ẕòrá֔ʻ bĕ̇⁠y֖wòm táhoráţ֑⁠wò wĕ⁠hẇbá֖ʼ ʼel-ha⁠kò̇héֽn׃"],[14,3,"וְ⁠יָצָא֙ הַ⁠כֹּהֵ֔ן אֶל־מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶ֑ה וְ⁠רָאָה֙ הַ⁠כֹּהֵ֔ן וְ⁠הִנֵּ֛ה נִרְפָּ֥א נֶֽגַע־הַ⁠צָּרַ֖עַת מִן־הַ⁠צָּרֽוּעַ׃","wĕ⁠yáẕáʼ֙ ha⁠kò̇hé֔n ʼel-mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàne֑h wĕ⁠ráʼáh֙ ha⁠kò̇hé֔n wĕ⁠hiné֛̇h nirĕpá֥̇ʼ neֽgaʻ-ha⁠ẕá̇ra֖ʻaţ min-ha⁠ẕá̇rֽẇʻa׃"],[14,4,"וְ⁠צִוָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠לָקַ֧ח לַ⁠מִּטַּהֵ֛ר שְׁתֵּֽי־צִפֳּרִ֥ים חַיּ֖וֹת טְהֹר֑וֹת וְ⁠עֵ֣ץ אֶ֔רֶז וּ⁠שְׁנִ֥י תוֹלַ֖עַת וְ⁠אֵזֹֽב׃","wĕ⁠ẕiwá̇h֙ ha⁠kò̇hé֔n wĕ⁠láqa֧ẖ la⁠mi̇tȧhé֛r şĕ̌ţéֽ̇y-ẕipȯri֥ym ẖaẏ֖wòţ tĕhòr֑wòţ wĕ⁠ʻé֣ẕ ʼe֔rez ẇ⁠şĕ̌ni֥y ţwòla֖ʻaţ wĕ⁠ʼézòֽb׃"],[14,5,"וְ⁠צִוָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠שָׁחַ֖ט אֶת־הַ⁠צִּפּ֣וֹר הָ⁠אֶחָ֑ת אֶל־כְּלִי־חֶ֖רֶשׂ עַל־מַ֥יִם חַיִּֽים׃","wĕ⁠ẕiwá̇h֙ ha⁠kò̇hé֔n wĕ⁠şá̌ẖa֖t ʼeţ-ha⁠ẕi̇ṗ֣wòr há⁠ʼeẖá֑ţ ʼel-kĕ̇liy-ẖe֖reş̂ ʻal-ma֥yim ẖayiֽ̇ym׃"],[14,6,"אֶת־הַ⁠צִּפֹּ֤ר הַֽ⁠חַיָּה֙ יִקַּ֣ח אֹתָ֔⁠הּ וְ⁠אֶת־עֵ֥ץ הָ⁠אֶ֛רֶז וְ⁠אֶת־שְׁנִ֥י הַ⁠תּוֹלַ֖עַת וְ⁠אֶת־הָ⁠אֵזֹ֑ב וְ⁠טָבַ֨ל אוֹתָ֜⁠ם וְ⁠אֵ֣ת ׀ הַ⁠צִּפֹּ֣ר הַֽ⁠חַיָּ֗ה בְּ⁠דַם֙ הַ⁠צִּפֹּ֣ר הַ⁠שְּׁחֻטָ֔ה עַ֖ל הַ⁠מַּ֥יִם הַֽ⁠חַיִּֽים׃","ʼeţ-ha⁠ẕi̇pò֤̇r haֽ⁠ẖayá̇h֙ yiqȧ֣ẖ ʼòţá֔⁠ḣ wĕ⁠ʼeţ-ʻé֥ẕ há⁠ʼe֛rez wĕ⁠ʼeţ-şĕ̌ni֥y ha⁠ţ̇wòla֖ʻaţ wĕ⁠ʼeţ-há⁠ʼézò֑b wĕ⁠tába֨l ʼwòţá֜⁠m wĕ⁠ʼé֣ţ ׀ ha⁠ẕi̇pò֣̇r hֽa⁠ẖayá̇֗h bĕ̇⁠dam֙ ha⁠ẕi̇pò֣̇r ha⁠şĕ̇̌ẖutá֔h ʻa֖l ha⁠mȧ֥yim hֽa⁠ẖayiֽ̇ym׃"],[14,7,"וְ⁠הִזָּ֗ה עַ֧ל הַ⁠מִּטַּהֵ֛ר מִן־הַ⁠צָּרַ֖עַת שֶׁ֣בַע פְּעָמִ֑ים וְ⁠טִ֣הֲר֔⁠וֹ וְ⁠שִׁלַּ֛ח אֶת־הַ⁠צִּפֹּ֥ר הַֽ⁠חַיָּ֖ה עַל־פְּנֵ֥י הַ⁠שָּׂדֶֽה׃","wĕ⁠hizá̇֗h ʻa֧l ha⁠mi̇tȧhé֛r min-ha⁠ẕá̇ra֖ʻaţ şě֣baʻ pĕ̇ʻámi֑ym wĕ⁠ti֣hàr֔⁠wò wĕ⁠şǐlȧ֛ẖ ʼeţ-ha⁠ẕi̇pò֥̇r haֽ⁠ẖayá֖̇h ʻal-pĕ̇né֥y ha⁠şá̇̂deֽh׃"],[14,8,"וְ⁠כִבֶּס֩ הַ⁠מִּטַּהֵ֨ר אֶת־בְּגָדָ֜י⁠ו וְ⁠גִלַּ֣ח אֶת־כָּל־שְׂעָר֗⁠וֹ וְ⁠רָחַ֤ץ בַּ⁠מַּ֨יִם֙ וְ⁠טָהֵ֔ר וְ⁠אַחַ֖ר יָב֣וֹא אֶל־הַֽ⁠מַּחֲנֶ֑ה וְ⁠יָשַׁ֛ב מִ⁠ח֥וּץ לְ⁠אָהֳל֖⁠וֹ שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠kibės֩ ha⁠mi̇tȧhé֨r ʼeţ-bĕ̇gádá֜y⁠w wĕ⁠gilȧ֣ẖ ʼeţ-ká̇l-şĕ̂ʻár֗⁠wò wĕ⁠ráẖa֤ẕ bȧ⁠mȧ֨yim֙ wĕ⁠táhé֔r wĕ⁠ʼaẖa֖r yáb֣wòʼ ʼel-haֽ⁠mȧẖàne֑h wĕ⁠yáşǎ֛b mi⁠ẖ֥ẇẕ lĕ⁠ʼáhol֖⁠wò şǐbĕʻa֥ţ yámiֽym׃"],[14,9,"וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠שְּׁבִיעִ֜י יְגַלַּ֣ח אֶת־כָּל־שְׂעָר֗⁠וֹ אֶת־רֹאשׁ֤⁠וֹ וְ⁠אֶת־זְקָנ⁠וֹ֙ וְ⁠אֵת֙ גַּבֹּ֣ת עֵינָ֔י⁠ו וְ⁠אֶת־כָּל־שְׂעָר֖⁠וֹ יְגַלֵּ֑חַ וְ⁠כִבֶּ֣ס אֶת־בְּגָדָ֗י⁠ו וְ⁠רָחַ֧ץ אֶת־בְּשָׂר֛⁠וֹ בַּ⁠מַּ֖יִם וְ⁠טָהֵֽר׃","wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠şĕ̇̌biyʻi֜y yĕgalȧ֣ẖ ʼeţ-ká̇l-şĕ̂ʻár֗⁠wò ʼeţ-ròʼş֤̌⁠wò wĕ⁠ʼeţ-zĕqán⁠wò֙ wĕ⁠ʼéţ֙ gȧbò֣̇ţ ʻéyná֔y⁠w wĕ⁠ʼeţ-ká̇l-şĕ̂ʻár֖⁠wò yĕgalé֑̇ẖa wĕ⁠kibė֣s ʼeţ-bĕ̇gádá֗y⁠w wĕ⁠ráẖa֧ẕ ʼeţ-bĕ̇şá̂r֛⁠wò bȧ⁠mȧ֖yim wĕ⁠táhéֽr׃"],[14,10,"וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁמִינִ֗י יִקַּ֤ח שְׁנֵֽי־כְבָשִׂים֙ תְּמִימִ֔ים וְ⁠כַבְשָׂ֥ה אַחַ֛ת בַּת־שְׁנָתָ֖⁠הּ תְּמִימָ֑ה וּ⁠שְׁלֹשָׁ֣ה עֶשְׂרֹנִ֗ים סֹ֤לֶת מִנְחָה֙ בְּלוּלָ֣ה בַ⁠שֶּׁ֔מֶן וְ⁠לֹ֥ג אֶחָ֖ד שָֽׁמֶן׃","ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌miyni֗y yiqȧ֤ẖ şĕ̌néֽy-kĕbáşîym֙ ţĕ̇miymi֔ym wĕ⁠kabĕşá֥̂h ʼaẖa֛ţ bȧţ-şĕ̌náţá֖⁠ḣ ţĕ̇miymá֑h ẇ⁠şĕ̌lòşá֣̌h ʻeşĕ̂ròni֗ym sò֤leţ minĕẖáh֙ bĕ̇lẇlá֣h ba⁠şė̌֔men wĕ⁠lò֥g ʼeẖá֖d şáֽ̌men׃"],[14,11,"וְ⁠הֶעֱמִ֞יד הַ⁠כֹּהֵ֣ן הַֽ⁠מְטַהֵ֗ר אֵ֛ת הָ⁠אִ֥ישׁ הַ⁠מִּטַּהֵ֖ר וְ⁠אֹתָ֑⁠ם לִ⁠פְנֵ֣י יְהוָ֔ה פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠heʻèmi֞yd ha⁠kò̇hé֣n haֽ⁠mĕtahé֗r ʼé֛ţ há⁠ʼi֥yş̌ ha⁠mi̇tȧhé֖r wĕ⁠ʼòţá֑⁠m li⁠pĕné֣y yĕhwá֔h pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[14,12,"וְ⁠לָקַ֨ח הַ⁠כֹּהֵ֜ן אֶת־הַ⁠כֶּ֣בֶשׂ הָ⁠אֶחָ֗ד וְ⁠הִקְרִ֥יב אֹת֛⁠וֹ לְ⁠אָשָׁ֖ם וְ⁠אֶת־לֹ֣ג הַ⁠שָּׁ֑מֶן וְ⁠הֵנִ֥יף אֹתָ֛⁠ם תְּנוּפָ֖ה לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠láqa֨ẖ ha⁠kò̇hé֜n ʼeţ-ha⁠kė֣beş̂ há⁠ʼeẖá֗d wĕ⁠hiqĕri֥yb ʼòţ֛⁠wò lĕ⁠ʼáşá֖̌m wĕ⁠ʼeţ-lò֣g ha⁠şá֑̇̌men wĕ⁠héni֥yp ʼòţá֛⁠m ţĕ̇nẇpá֖h li⁠pĕné֥y yĕhwáֽh׃"],[14,13,"וְ⁠שָׁחַ֣ט אֶת־הַ⁠כֶּ֗בֶשׂ בִּ֠⁠מְקוֹם אֲשֶׁ֨ר יִשְׁחַ֧ט אֶת־הַֽ⁠חַטָּ֛את וְ⁠אֶת־הָ⁠עֹלָ֖ה בִּ⁠מְק֣וֹם הַ⁠קֹּ֑דֶשׁ כִּ֡י כַּ֠⁠חַטָּאת הָ⁠אָשָׁ֥ם הוּא֙ לַ⁠כֹּהֵ֔ן קֹ֥דֶשׁ קָֽדָשִׁ֖ים הֽוּא׃","wĕ⁠şá̌ẖa֣t ʼeţ-ha⁠kė֗beş̂ bi̇֠⁠mĕqwòm ʼàşě֨r yişĕ̌ẖa֧t ʼeţ-haֽ⁠ẖatá֛̇ʼţ wĕ⁠ʼeţ-há⁠ʻòlá֖h bi̇⁠mĕq֣wòm ha⁠qò֑̇deş̌ ki̇֡y kȧ֠⁠ẖatá̇ʼţ há⁠ʼáşá֥̌m hẇʼ֙ la⁠kò̇hé֔n qò֥deş̌ qֽádáşǐ֖ym hֽẇʼ׃"],[14,14,"וְ⁠לָקַ֣ח הַ⁠כֹּהֵן֮ מִ⁠דַּ֣ם הָ⁠אָשָׁם֒ וְ⁠נָתַן֙ הַ⁠כֹּהֵ֔ן עַל־תְּנ֛וּךְ אֹ֥זֶן הַ⁠מִּטַּהֵ֖ר הַ⁠יְמָנִ֑ית וְ⁠עַל־בֹּ֤הֶן יָד⁠וֹ֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְל֖⁠וֹ הַ⁠יְמָנִֽית׃","wĕ⁠láqa֣ẖ ha⁠kò̇hén֮ mi⁠dȧ֣m há⁠ʼáşá̌m֒ wĕ⁠náţan֙ ha⁠kò̇hé֔n ʻal-ţĕ̇n֛ẇkĕ ʼò֥zen ha⁠mi̇tȧhé֖r ha⁠yĕmáni֑yţ wĕ⁠ʻal-bò֤̇hen yád⁠wò֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕl֖⁠wò ha⁠yĕmániֽyţ׃"],[14,15,"וְ⁠לָקַ֥ח הַ⁠כֹּהֵ֖ן מִ⁠לֹּ֣ג הַ⁠שָּׁ֑מֶן וְ⁠יָצַ֛ק עַל־כַּ֥ף הַ⁠כֹּהֵ֖ן הַ⁠שְּׂמָאלִֽית׃","wĕ⁠láqa֥ẖ ha⁠kò̇hé֖n mi⁠lò֣̇g ha⁠şá֑̇̌men wĕ⁠yáẕa֛q ʻal-kȧ֥p ha⁠kò̇hé֖n ha⁠şĕ̇̂máʼliֽyţ׃"],[14,16,"וְ⁠טָבַ֤ל הַ⁠כֹּהֵן֙ אֶת־אֶצְבָּע֣⁠וֹ הַ⁠יְמָנִ֔ית מִן־הַ⁠שֶּׁ֕מֶן אֲשֶׁ֥ר עַל־כַּפּ֖⁠וֹ הַ⁠שְּׂמָאלִ֑ית וְ⁠הִזָּ֨ה מִן־הַ⁠שֶּׁ֧מֶן בְּ⁠אֶצְבָּע֛⁠וֹ שֶׁ֥בַע פְּעָמִ֖ים לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠tába֤l ha⁠kò̇hén֙ ʼeţ-ʼeẕĕbá̇ʻ֣⁠wò ha⁠yĕmáni֔yţ min-ha⁠şė̌֕men ʼàşě֥r ʻal-kȧṗ֖⁠wò ha⁠şĕ̇̂máʼli֑yţ wĕ⁠hizá̇֨h min-ha⁠şė֧̌men bĕ̇⁠ʼeẕĕbá̇ʻ֛⁠wò şě֥baʻ pĕ̇ʻámi֖ym li⁠pĕné֥y yĕhwáֽh׃"],[14,17,"וּ⁠מִ⁠יֶּ֨תֶר הַ⁠שֶּׁ֜מֶן אֲשֶׁ֣ר עַל־כַּפּ֗⁠וֹ יִתֵּ֤ן הַ⁠כֹּהֵן֙ עַל־תְּנ֞וּךְ אֹ֤זֶן הַ⁠מִּטַּהֵר֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֤הֶן יָד⁠וֹ֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְל֖⁠וֹ הַ⁠יְמָנִ֑ית עַ֖ל דַּ֥ם הָ⁠אָשָֽׁם׃","ẇ⁠mi⁠yė֨ţer ha⁠şė̌֜men ʼàşě֣r ʻal-kȧṗ֗⁠wò yiţé֤̇n ha⁠kò̇hén֙ ʻal-ţĕ̇n֞ẇkĕ ʼò֤zen ha⁠mi̇tȧhér֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֤̇hen yád⁠wò֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕl֖⁠wò ha⁠yĕmáni֑yţ ʻa֖l dȧ֥m há⁠ʼáşáֽ̌m׃"],[14,18,"וְ⁠הַ⁠נּוֹתָ֗ר בַּ⁠שֶּׁ֨מֶן֙ אֲשֶׁר֙ עַל־כַּ֣ף הַ⁠כֹּהֵ֔ן יִתֵּ֖ן עַל־רֹ֣אשׁ הַ⁠מִּטַּהֵ֑ר וְ⁠כִפֶּ֥ר עָלָ֛י⁠ו הַ⁠כֹּהֵ֖ן לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠ha⁠ṅwòţá֗r bȧ⁠şė̌֨men֙ ʼàşěr֙ ʻal-kȧ֣p ha⁠kò̇hé֔n yiţé֖̇n ʻal-rò֣ʼş̌ ha⁠mi̇tȧhé֑r wĕ⁠kipė֥r ʻálá֛y⁠w ha⁠kò̇hé֖n li⁠pĕné֥y yĕhwáֽh׃"],[14,19,"וְ⁠עָשָׂ֤ה הַ⁠כֹּהֵן֙ אֶת־הַ֣⁠חַטָּ֔את וְ⁠כִפֶּ֕ר עַל־הַ⁠מִּטַּהֵ֖ר מִ⁠טֻּמְאָת֑⁠וֹ וְ⁠אַחַ֖ר יִשְׁחַ֥ט אֶת־הָ⁠עֹלָֽה׃","wĕ⁠ʻáşá֤̂h ha⁠kò̇hén֙ ʼeţ-ha֣⁠ẖatá̇֔ʼţ wĕ⁠kipė֕r ʻal-ha⁠mi̇tȧhé֖r mi⁠tu̇mĕʼáţ֑⁠wò wĕ⁠ʼaẖa֖r yişĕ̌ẖa֥t ʼeţ-há⁠ʻòláֽh׃"],[14,20,"וְ⁠הֶעֱלָ֧ה הַ⁠כֹּהֵ֛ן אֶת־הָ⁠עֹלָ֥ה וְ⁠אֶת־הַ⁠מִּנְחָ֖ה הַ⁠מִּזְבֵּ֑חָ⁠ה וְ⁠כִפֶּ֥ר עָלָ֛י⁠ו הַ⁠כֹּהֵ֖ן וְ⁠טָהֵֽר׃ס","wĕ⁠heʻèlá֧h ha⁠kò̇hé֛n ʼeţ-há⁠ʻòlá֥h wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֖h ha⁠mi̇zĕbé֑̇ẖá⁠h wĕ⁠kipė֥r ʻálá֛y⁠w ha⁠kò̇hé֖n wĕ⁠táhéֽr׃s"],[14,21,"וְ⁠אִם־דַּ֣ל ה֗וּא וְ⁠אֵ֣ין יָד⁠וֹ֮ מַשֶּׂגֶת֒ וְ֠⁠לָקַח כֶּ֣בֶשׂ אֶחָ֥ד אָשָׁ֛ם לִ⁠תְנוּפָ֖ה לְ⁠כַפֵּ֣ר עָלָ֑י⁠ו וְ⁠עִשָּׂר֨וֹן סֹ֜לֶת אֶחָ֨ד בָּל֥וּל בַּ⁠שֶּׁ֛מֶן לְ⁠מִנְחָ֖ה וְ⁠לֹ֥ג שָֽׁמֶן׃","wĕ⁠ʼim-dȧ֣l h֗ẇʼ wĕ⁠ʼé֣yn yád⁠wò֮ maşė̂geţ֒ wĕ֠⁠láqaẖ kė֣beş̂ ʼeẖá֥d ʼáşá֛̌m li⁠ţĕnẇpá֖h lĕ⁠kapé֣̇r ʻálá֑y⁠w wĕ⁠ʻişá̇̂r֨wòn sò֜leţ ʼeẖá֨d bá̇l֥ẇl bȧ⁠şė֛̌men lĕ⁠minĕẖá֖h wĕ⁠lò֥g şáֽ̌men׃"],[14,22,"וּ⁠שְׁתֵּ֣י תֹרִ֗ים א֤וֹ שְׁנֵי֙ בְּנֵ֣י יוֹנָ֔ה אֲשֶׁ֥ר תַּשִּׂ֖יג יָד֑⁠וֹ וְ⁠הָיָ֤ה אֶחָד֙ חַטָּ֔את וְ⁠הָ⁠אֶחָ֖ד עֹלָֽה׃","ẇ⁠şĕ̌ţé֣̇y ţòri֗ym ʼ֤wò şĕ̌néy֙ bĕ̇né֣y ywòná֔h ʼàşě֥r ţȧşi֖̇̂yg yád֑⁠wò wĕ⁠háyá֤h ʼeẖád֙ ẖatá̇֔ʼţ wĕ⁠há⁠ʼeẖá֖d ʻòláֽh׃"],[14,23,"וְ⁠הֵבִ֨יא אֹתָ֜⁠ם בַּ⁠יּ֧וֹם הַ⁠שְּׁמִינִ֛י לְ⁠טָהֳרָת֖⁠וֹ אֶל־הַ⁠כֹּהֵ֑ן אֶל־פֶּ֥תַח אֹֽהֶל־מוֹעֵ֖ד לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠hébi֨yʼ ʼòţá֜⁠m bȧ⁠ẏ֧wòm ha⁠şĕ̇̌miyni֛y lĕ⁠táhoráţ֖⁠wò ʼel-ha⁠kò̇hé֑n ʼel-pė֥ţaẖ ʼòֽhel-mwòʻé֖d li⁠pĕné֥y yĕhwáֽh׃"],[14,24,"וְ⁠לָקַ֧ח הַ⁠כֹּהֵ֛ן אֶת־כֶּ֥בֶשׂ הָ⁠אָשָׁ֖ם וְ⁠אֶת־לֹ֣ג הַ⁠שָּׁ֑מֶן וְ⁠הֵנִ֨יף אֹתָ֧⁠ם הַ⁠כֹּהֵ֛ן תְּנוּפָ֖ה לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠láqa֧ẖ ha⁠kò̇hé֛n ʼeţ-kė֥beş̂ há⁠ʼáşá֖̌m wĕ⁠ʼeţ-lò֣g ha⁠şá֑̇̌men wĕ⁠héni֨yp ʼòţá֧⁠m ha⁠kò̇hé֛n ţĕ̇nẇpá֖h li⁠pĕné֥y yĕhwáֽh׃"],[14,25,"וְ⁠שָׁחַט֮ אֶת־כֶּ֣בֶשׂ הָֽ⁠אָשָׁם֒ וְ⁠לָקַ֤ח הַ⁠כֹּהֵן֙ מִ⁠דַּ֣ם הָֽ⁠אָשָׁ֔ם וְ⁠נָתַ֛ן עַל־תְּנ֥וּךְ אֹֽזֶן־הַ⁠מִּטַּהֵ֖ר הַ⁠יְמָנִ֑ית וְ⁠עַל־בֹּ֤הֶן יָד⁠וֹ֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְל֖⁠וֹ הַ⁠יְמָנִֽית׃","wĕ⁠şá̌ẖat֮ ʼeţ-kė֣beş̂ háֽ⁠ʼáşá̌m֒ wĕ⁠láqa֤ẖ ha⁠kò̇hén֙ mi⁠dȧ֣m háֽ⁠ʼáşá̌֔m wĕ⁠náţa֛n ʻal-ţĕ̇n֥ẇkĕ ʼòֽzen-ha⁠mi̇tȧhé֖r ha⁠yĕmáni֑yţ wĕ⁠ʻal-bò֤̇hen yád⁠wò֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕl֖⁠wò ha⁠yĕmániֽyţ׃"],[14,26,"וּ⁠מִן־הַ⁠שֶּׁ֖מֶן יִצֹ֣ק הַ⁠כֹּהֵ֑ן עַל־כַּ֥ף הַ⁠כֹּהֵ֖ן הַ⁠שְּׂמָאלִֽית׃","ẇ⁠min-ha⁠şė֖̌men yiẕò֣q ha⁠kò̇hé֑n ʻal-kȧ֥p ha⁠kò̇hé֖n ha⁠şĕ̇̂máʼliֽyţ׃"],[14,27,"וְ⁠הִזָּ֤ה הַ⁠כֹּהֵן֙ בְּ⁠אֶצְבָּע֣⁠וֹ הַ⁠יְמָנִ֔ית מִן־הַ⁠שֶּׁ֕מֶן אֲשֶׁ֥ר עַל־כַּפּ֖⁠וֹ הַ⁠שְּׂמָאלִ֑ית שֶׁ֥בַע פְּעָמִ֖ים לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠hizá֤̇h ha⁠kò̇hén֙ bĕ̇⁠ʼeẕĕbá̇ʻ֣⁠wò ha⁠yĕmáni֔yţ min-ha⁠şė̌֕men ʼàşě֥r ʻal-kȧṗ֖⁠wò ha⁠şĕ̇̂máʼli֑yţ şě֥baʻ pĕ̇ʻámi֖ym li⁠pĕné֥y yĕhwáֽh׃"],[14,28,"וְ⁠נָתַ֨ן הַ⁠כֹּהֵ֜ן מִן־הַ⁠שֶּׁ֣מֶן ׀ אֲשֶׁ֣ר עַל־כַּפּ֗⁠וֹ עַל־תְּנ֞וּךְ אֹ֤זֶן הַ⁠מִּטַּהֵר֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֤הֶן יָד⁠וֹ֙ הַ⁠יְמָנִ֔ית וְ⁠עַל־בֹּ֥הֶן רַגְל֖⁠וֹ הַ⁠יְמָנִ֑ית עַל־מְק֖וֹם דַּ֥ם הָ⁠אָשָֽׁם׃","wĕ⁠náţa֨n ha⁠kò̇hé֜n min-ha⁠şė֣̌men ׀ ʼàşě֣r ʻal-kȧṗ֗⁠wò ʻal-ţĕ̇n֞ẇkĕ ʼò֤zen ha⁠mi̇tȧhér֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֤̇hen yád⁠wò֙ ha⁠yĕmáni֔yţ wĕ⁠ʻal-bò֥̇hen ragĕl֖⁠wò ha⁠yĕmáni֑yţ ʻal-mĕq֖wòm dȧ֥m há⁠ʼáşáֽ̌m׃"],[14,29,"וְ⁠הַ⁠נּוֹתָ֗ר מִן־הַ⁠שֶּׁ֨מֶן֙ אֲשֶׁר֙ עַל־כַּ֣ף הַ⁠כֹּהֵ֔ן יִתֵּ֖ן עַל־רֹ֣אשׁ הַ⁠מִּטַּהֵ֑ר לְ⁠כַפֵּ֥ר עָלָ֖י⁠ו לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠ha⁠ṅwòţá֗r min-ha⁠şė̌֨men֙ ʼàşěr֙ ʻal-kȧ֣p ha⁠kò̇hé֔n yiţé֖̇n ʻal-rò֣ʼş̌ ha⁠mi̇tȧhé֑r lĕ⁠kapé֥̇r ʻálá֖y⁠w li⁠pĕné֥y yĕhwáֽh׃"],[14,30,"וְ⁠עָשָׂ֤ה אֶת־הָֽ⁠אֶחָד֙ מִן־הַ⁠תֹּרִ֔ים א֖וֹ מִן־בְּנֵ֣י הַ⁠יּוֹנָ֑ה מֵ⁠אֲשֶׁ֥ר תַּשִּׂ֖יג יָדֽ⁠וֹ׃","wĕ⁠ʻáşá֤̂h ʼeţ-háֽ⁠ʼeẖád֙ min-ha⁠ţò̇ri֔ym ʼ֖wò min-bĕ̇né֣y ha⁠ẏwòná֑h mé⁠ʼàşě֥r ţȧşi֖̇̂yg yádֽ⁠wò׃"],[14,31,"אֵ֣ת אֲשֶׁר־תַּשִּׂ֞יג יָד֗⁠וֹ אֶת־הָ⁠אֶחָ֥ד חַטָּ֛את וְ⁠אֶת־הָ⁠אֶחָ֥ד עֹלָ֖ה עַל־הַ⁠מִּנְחָ֑ה וְ⁠כִפֶּ֧ר הַ⁠כֹּהֵ֛ן עַ֥ל הַ⁠מִּטַּהֵ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","ʼé֣ţ ʼàşěr-ţȧşi̇̂֞yg yád֗⁠wò ʼeţ-há⁠ʼeẖá֥d ẖatá֛̇ʼţ wĕ⁠ʼeţ-há⁠ʼeẖá֥d ʻòlá֖h ʻal-ha⁠mi̇nĕẖá֑h wĕ⁠kipė֧r ha⁠kò̇hé֛n ʻa֥l ha⁠mi̇tȧhé֖r li⁠pĕné֥y yĕhwáֽh׃"],[14,32,"זֹ֣את תּוֹרַ֔ת אֲשֶׁר־בּ֖⁠וֹ נֶ֣גַע צָרָ֑עַת אֲשֶׁ֛ר לֹֽא־תַשִּׂ֥יג יָד֖⁠וֹ בְּ⁠טָהֳרָתֽ⁠וֹ׃פ","zò֣ʼţ ţ̇wòra֔ţ ʼàşěr-ḃ֖⁠wò ne֣gaʻ ẕárá֑ʻaţ ʼàşě֛r lòֽʼ-ţaşi֥̇̂yg yád֖⁠wò bĕ̇⁠táhoráţֽ⁠wò׃p"],[14,33,"וַ⁠יְדַבֵּ֣ר יְהוָ֔ה אֶל־מֹשֶׁ֥ה וְ⁠אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹֽר׃","wa⁠yĕdabé֣̇r yĕhwá֔h ʼel-mòşě֥h wĕ⁠ʼeֽl-ʼahàrò֖n lé⁠ʼmòֽr׃"],[14,34,"כִּ֤י תָבֹ֨אוּ֙ אֶל־אֶ֣רֶץ כְּנַ֔עַן אֲשֶׁ֥ר אֲנִ֛י נֹתֵ֥ן לָ⁠כֶ֖ם לַ⁠אֲחֻזָּ֑ה וְ⁠נָתַתִּי֙ נֶ֣גַע צָרַ֔עַת בְּ⁠בֵ֖ית אֶ֥רֶץ אֲחֻזַּתְ⁠כֶֽם׃","ki֤̇y ţábò֨ʼẇ֙ ʼel-ʼe֣reẕ kĕ̇na֔ʻan ʼàşě֥r ʼàni֛y nòţé֥n lá⁠ke֖m la⁠ʼàẖuzá֑̇h wĕ⁠náţaţi̇y֙ ne֣gaʻ ẕára֔ʻaţ bĕ̇⁠bé֖yţ ʼe֥reẕ ʼàẖuzȧţĕ⁠keֽm׃"],[14,35,"וּ⁠בָא֙ אֲשֶׁר־ל֣⁠וֹ הַ⁠בַּ֔יִת וְ⁠הִגִּ֥יד לַ⁠כֹּהֵ֖ן לֵ⁠אמֹ֑ר כְּ⁠נֶ֕גַע נִרְאָ֥ה לִ֖⁠י בַּ⁠בָּֽיִת׃","ẇ⁠báʼ֙ ʼàşěr-l֣⁠wò ha⁠bȧ֔yiţ wĕ⁠higi֥̇yd la⁠kò̇hé֖n lé⁠ʼmò֑r kĕ̇⁠ne֕gaʻ nirĕʼá֥h li֖⁠y bȧ⁠báֽ̇yiţ׃"],[14,36,"וְ⁠צִוָּ֨ה הַ⁠כֹּהֵ֜ן וּ⁠פִנּ֣וּ אֶת־הַ⁠בַּ֗יִת בְּ⁠טֶ֨רֶם יָבֹ֤א הַ⁠כֹּהֵן֙ לִ⁠רְא֣וֹת אֶת־הַ⁠נֶּ֔גַע וְ⁠לֹ֥א יִטְמָ֖א כָּל־אֲשֶׁ֣ר בַּ⁠בָּ֑יִת וְ⁠אַ֥חַר כֵּ֛ן יָבֹ֥א הַ⁠כֹּהֵ֖ן לִ⁠רְא֥וֹת אֶת־הַ⁠בָּֽיִת׃","wĕ⁠ẕiwá̇֨h ha⁠kò̇hé֜n ẇ⁠piṅ֣ẇ ʼeţ-ha⁠bȧ֗yiţ bĕ̇⁠te֨rem yábò֤ʼ ha⁠kò̇hén֙ li⁠rĕʼ֣wòţ ʼeţ-ha⁠nė֔gaʻ wĕ⁠lò֥ʼ yitĕmá֖ʼ ká̇l-ʼàşě֣r bȧ⁠bá֑̇yiţ wĕ⁠ʼa֥ẖar ké֛̇n yábò֥ʼ ha⁠kò̇hé֖n li⁠rĕʼ֥wòţ ʼeţ-ha⁠báֽ̇yiţ׃"],[14,37,"וְ⁠רָאָ֣ה אֶת־הַ⁠נֶּ֗גַע וְ⁠הִנֵּ֤ה הַ⁠נֶּ֨גַע֙ בְּ⁠קִירֹ֣ת הַ⁠בַּ֔יִת שְׁקַֽעֲרוּרֹת֙ יְרַקְרַקֹּ֔ת א֖וֹ אֲדַמְדַּמֹּ֑ת וּ⁠מַרְאֵי⁠הֶ֥ן שָׁפָ֖ל מִן־הַ⁠קִּֽיר׃","wĕ⁠ráʼá֣h ʼeţ-ha⁠nė֗gaʻ wĕ⁠hiné֤̇h ha⁠nė֨gaʻ֙ bĕ̇⁠qiyrò֣ţ ha⁠bȧ֔yiţ şĕ̌qaֽʻàrẇròţ֙ yĕraqĕraqò̇֔ţ ʼ֖wò ʼàdamĕdȧmò֑̇ţ ẇ⁠marĕʼéy⁠he֥n şá̌pá֖l min-ha⁠qiֽ̇yr׃"],[14,38,"וְ⁠יָצָ֧א הַ⁠כֹּהֵ֛ן מִן־הַ⁠בַּ֖יִת אֶל־פֶּ֣תַח הַ⁠בָּ֑יִת וְ⁠הִסְגִּ֥יר אֶת־הַ⁠בַּ֖יִת שִׁבְעַ֥ת יָמִֽים׃","wĕ⁠yáẕá֧ʼ ha⁠kò̇hé֛n min-ha⁠bȧ֖yiţ ʼel-pė֣ţaẖ ha⁠bá֑̇yiţ wĕ⁠hisĕgi֥̇yr ʼeţ-ha⁠bȧ֖yiţ şǐbĕʻa֥ţ yámiֽym׃"],[14,39,"וְ⁠שָׁ֥ב הַ⁠כֹּהֵ֖ן בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֑י וְ⁠רָאָ֕ה וְ⁠הִנֵּ֛ה פָּשָׂ֥ה הַ⁠נֶּ֖גַע בְּ⁠קִירֹ֥ת הַ⁠בָּֽיִת׃","wĕ⁠şá֥̌b ha⁠kò̇hé֖n bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֑y wĕ⁠ráʼá֕h wĕ⁠hiné֛̇h pá̇şá֥̂h ha⁠nė֖gaʻ bĕ̇⁠qiyrò֥ţ ha⁠báֽ̇yiţ׃"],[14,40,"וְ⁠צִוָּה֙ הַ⁠כֹּהֵ֔ן וְ⁠חִלְּצוּ֙ אֶת־הָ֣⁠אֲבָנִ֔ים אֲשֶׁ֥ר בָּ⁠הֵ֖ן הַ⁠נָּ֑גַע וְ⁠הִשְׁלִ֤יכוּ אֶתְ⁠הֶן֙ אֶל־מִ⁠ח֣וּץ לָ⁠עִ֔יר אֶל־מָק֖וֹם טָמֵֽא׃","wĕ⁠ẕiwá̇h֙ ha⁠kò̇hé֔n wĕ⁠ẖilĕ̇ẕẇ֙ ʼeţ-há֣⁠ʼàbáni֔ym ʼàşě֥r bá̇⁠hé֖n ha⁠ná֑̇gaʻ wĕ⁠hişĕ̌li֤ykẇ ʼeţĕ⁠hen֙ ʼel-mi⁠ẖ֣ẇẕ lá⁠ʻi֔yr ʼel-máq֖wòm táméֽʼ׃"],[14,41,"וְ⁠אֶת־הַ⁠בַּ֛יִת יַקְצִ֥עַ מִ⁠בַּ֖יִת סָבִ֑יב וְ⁠שָׁפְכ֗וּ אֶת־הֶֽ⁠עָפָר֙ אֲשֶׁ֣ר הִקְצ֔וּ אֶל־מִ⁠ח֣וּץ לָ⁠עִ֔יר אֶל־מָק֖וֹם טָמֵֽא׃","wĕ⁠ʼeţ-ha⁠bȧ֛yiţ yaqĕẕi֥ʻa mi⁠bȧ֖yiţ sábi֑yb wĕ⁠şá̌pĕk֗ẇ ʼeţ-heֽ⁠ʻápár֙ ʼàşě֣r hiqĕẕ֔ẇ ʼel-mi⁠ẖ֣ẇẕ lá⁠ʻi֔yr ʼel-máq֖wòm táméֽʼ׃"],[14,42,"וְ⁠לָקְחוּ֙ אֲבָנִ֣ים אֲחֵר֔וֹת וְ⁠הֵבִ֖יאוּ אֶל־תַּ֣חַת הָ⁠אֲבָנִ֑ים וְ⁠עָפָ֥ר אַחֵ֛ר יִקַּ֖ח וְ⁠טָ֥ח אֶת־הַ⁠בָּֽיִת׃","wĕ⁠láqĕẖẇ֙ ʼàbáni֣ym ʼàẖér֔wòţ wĕ⁠hébi֖yʼẇ ʼel-ţȧ֣ẖaţ há⁠ʼàbáni֑ym wĕ⁠ʻápá֥r ʼaẖé֛r yiqȧ֖ẖ wĕ⁠tá֥ẖ ʼeţ-ha⁠báֽ̇yiţ׃"],[14,43,"וְ⁠אִם־יָשׁ֤וּב הַ⁠נֶּ֨גַע֙ וּ⁠פָרַ֣ח בַּ⁠בַּ֔יִת אַחַ֖ר חִלֵּ֣ץ אֶת־הָ⁠אֲבָנִ֑ים וְ⁠אַחֲרֵ֛י הִקְצ֥וֹת אֶת־הַ⁠בַּ֖יִת וְ⁠אַחֲרֵ֥י הִטּֽוֹחַ׃","wĕ⁠ʼim-yáş֤̌ẇb ha⁠nė֨gaʻ֙ ẇ⁠pára֣ẖ bȧ⁠bȧ֔yiţ ʼaẖa֖r ẖilé֣̇ẕ ʼeţ-há⁠ʼàbáni֑ym wĕ⁠ʼaẖàré֛y hiqĕẕ֥wòţ ʼeţ-ha⁠bȧ֖yiţ wĕ⁠ʼaẖàré֥y hiṫֽwòẖa׃"],[14,44,"וּ⁠בָא֙ הַ⁠כֹּהֵ֔ן וְ⁠רָאָ֕ה וְ⁠הִנֵּ֛ה פָּשָׂ֥ה הַ⁠נֶּ֖גַע בַּ⁠בָּ֑יִת צָרַ֨עַת מַמְאֶ֥רֶת הִ֛וא בַּ⁠בַּ֖יִת טָמֵ֥א הֽוּא׃","ẇ⁠báʼ֙ ha⁠kò̇hé֔n wĕ⁠ráʼá֕h wĕ⁠hiné֛̇h pá̇şá֥̂h ha⁠nė֖gaʻ bȧ⁠bá֑̇yiţ ẕára֨ʻaţ mamĕʼe֥reţ hi֛wʼ bȧ⁠bȧ֖yiţ támé֥ʼ hֽẇʼ׃"],[14,45,"וְ⁠נָתַ֣ץ אֶת־הַ⁠בַּ֗יִת אֶת־אֲבָנָי⁠ו֙ וְ⁠אֶת־עֵצָ֔י⁠ו וְ⁠אֵ֖ת כָּל־עֲפַ֣ר הַ⁠בָּ֑יִת וְ⁠הוֹצִיא֙ אֶל־מִ⁠ח֣וּץ לָ⁠עִ֔יר אֶל־מָק֖וֹם טָמֵֽא׃","wĕ⁠náţa֣ẕ ʼeţ-ha⁠bȧ֗yiţ ʼeţ-ʼàbánáy⁠w֙ wĕ⁠ʼeţ-ʻéẕá֔y⁠w wĕ⁠ʼé֖ţ ká̇l-ʻàpa֣r ha⁠bá֑̇yiţ wĕ⁠hwòẕiyʼ֙ ʼel-mi⁠ẖ֣ẇẕ lá⁠ʻi֔yr ʼel-máq֖wòm táméֽʼ׃"],[14,46,"וְ⁠הַ⁠בָּא֙ אֶל־הַ⁠בַּ֔יִת כָּל־יְמֵ֖י הִסְגִּ֣יר אֹת֑⁠וֹ יִטְמָ֖א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ha⁠bá̇ʼ֙ ʼel-ha⁠bȧ֔yiţ ká̇l-yĕmé֖y hisĕgi֣̇yr ʼòţ֑⁠wò yitĕmá֖ʼ ʻad-há⁠ʻáֽreb׃"],[14,47,"וְ⁠הַ⁠שֹּׁכֵ֣ב בַּ⁠בַּ֔יִת יְכַבֵּ֖ס אֶת־בְּגָדָ֑י⁠ו וְ⁠הָ⁠אֹכֵ֣ל בַּ⁠בַּ֔יִת יְכַבֵּ֖ס אֶת־בְּגָדָֽי⁠ו׃","wĕ⁠ha⁠şò̇̌ké֣b bȧ⁠bȧ֔yiţ yĕkabé֖̇s ʼeţ-bĕ̇gádá֑y⁠w wĕ⁠há⁠ʼòké֣l bȧ⁠bȧ֔yiţ yĕkabé֖̇s ʼeţ-bĕ̇gádáֽy⁠w׃"],[14,48,"וְ⁠אִם־בֹּ֨א יָבֹ֜א הַ⁠כֹּהֵ֗ן וְ⁠רָאָה֙ וְ֠⁠הִנֵּה לֹא־פָשָׂ֤ה הַ⁠נֶּ֨גַע֙ בַּ⁠בַּ֔יִת אַחֲרֵ֖י הִטֹּ֣חַ אֶת־הַ⁠בָּ֑יִת וְ⁠טִהַ֤ר הַ⁠כֹּהֵן֙ אֶת־הַ⁠בַּ֔יִת כִּ֥י נִרְפָּ֖א הַ⁠נָּֽגַע׃","wĕ⁠ʼim-bò̇֨ʼ yábò֜ʼ ha⁠kò̇hé֗n wĕ⁠ráʼáh֙ wĕ֠⁠hiné̇h lòʼ-páşá֤̂h ha⁠nė֨gaʻ֙ bȧ⁠bȧ֔yiţ ʼaẖàré֖y hitò֣̇ẖa ʼeţ-ha⁠bá֑̇yiţ wĕ⁠tiha֤r ha⁠kò̇hén֙ ʼeţ-ha⁠bȧ֔yiţ ki֥̇y nirĕpá֖̇ʼ ha⁠náֽ̇gaʻ׃"],[14,49,"וְ⁠לָקַ֛ח לְ⁠חַטֵּ֥א אֶת־הַ⁠בַּ֖יִת שְׁתֵּ֣י צִפֳּרִ֑ים וְ⁠עֵ֣ץ אֶ֔רֶז וּ⁠שְׁנִ֥י תוֹלַ֖עַת וְ⁠אֵזֹֽב׃","wĕ⁠láqa֛ẖ lĕ⁠ẖaté֥̇ʼ ʼeţ-ha⁠bȧ֖yiţ şĕ̌ţé֣̇y ẕipȯri֑ym wĕ⁠ʻé֣ẕ ʼe֔rez ẇ⁠şĕ̌ni֥y ţwòla֖ʻaţ wĕ⁠ʼézòֽb׃"],[14,50,"וְ⁠שָׁחַ֖ט אֶת־הַ⁠צִּפֹּ֣ר הָ⁠אֶחָ֑ת אֶל־כְּלִי־חֶ֖רֶשׂ עַל־מַ֥יִם חַיִּֽים׃","wĕ⁠şá̌ẖa֖t ʼeţ-ha⁠ẕi̇pò֣̇r há⁠ʼeẖá֑ţ ʼel-kĕ̇liy-ẖe֖reş̂ ʻal-ma֥yim ẖayiֽ̇ym׃"],[14,51,"וְ⁠לָקַ֣ח אֶת־עֵֽץ־הָ֠⁠אֶרֶז וְ⁠אֶת־הָ֨⁠אֵזֹ֜ב וְ⁠אֵ֣ת ׀ שְׁנִ֣י הַ⁠תּוֹלַ֗עַת וְ⁠אֵת֮ הַ⁠צִּפֹּ֣ר הַֽ⁠חַיָּה֒ וְ⁠טָבַ֣ל אֹתָ֗⁠ם בְּ⁠דַם֙ הַ⁠צִּפֹּ֣ר הַ⁠שְּׁחוּטָ֔ה וּ⁠בַ⁠מַּ֖יִם הַֽ⁠חַיִּ֑ים וְ⁠הִזָּ֥ה אֶל־הַ⁠בַּ֖יִת שֶׁ֥בַע פְּעָמִֽים׃","wĕ⁠láqa֣ẖ ʼeţ-ʻéֽẕ-há֠⁠ʼerez wĕ⁠ʼeţ-há֨⁠ʼézò֜b wĕ⁠ʼé֣ţ ׀ şĕ̌ni֣y ha⁠ţ̇wòla֗ʻaţ wĕ⁠ʼéţ֮ ha⁠ẕi̇pò֣̇r hֽa⁠ẖayá̇h֒ wĕ⁠tába֣l ʼòţá֗⁠m bĕ̇⁠dam֙ ha⁠ẕi̇pò֣̇r ha⁠şĕ̇̌ẖẇtá֔h ẇ⁠ba⁠mȧ֖yim haֽ⁠ẖayi֑̇ym wĕ⁠hizá֥̇h ʼel-ha⁠bȧ֖yiţ şě֥baʻ pĕ̇ʻámiֽym׃"],[14,52,"וְ⁠חִטֵּ֣א אֶת־הַ⁠בַּ֔יִת בְּ⁠דַם֙ הַ⁠צִּפּ֔וֹר וּ⁠בַ⁠מַּ֖יִם הַֽ⁠חַיִּ֑ים וּ⁠בַ⁠צִּפֹּ֣ר הַ⁠חַיָּ֗ה וּ⁠בְ⁠עֵ֥ץ הָ⁠אֶ֛רֶז וּ⁠בָ⁠אֵזֹ֖ב וּ⁠בִ⁠שְׁנִ֥י הַ⁠תּוֹלָֽעַת׃","wĕ⁠ẖité֣̇ʼ ʼeţ-ha⁠bȧ֔yiţ bĕ̇⁠dam֙ ha⁠ẕi̇ṗ֔wòr ẇ⁠ba⁠mȧ֖yim haֽ⁠ẖayi֑̇ym ẇ⁠ba⁠ẕi̇pò֣̇r ha⁠ẖayá̇֗h ẇ⁠bĕ⁠ʻé֥ẕ há⁠ʼe֛rez ẇ⁠bá⁠ʼézò֖b ẇ⁠bi⁠şĕ̌ni֥y ha⁠ţ̇wòláֽʻaţ׃"],[14,53,"וְ⁠שִׁלַּ֞ח אֶת־הַ⁠צִּפֹּ֧ר הַֽ⁠חַיָּ֛ה אֶל־מִ⁠ח֥וּץ לָ⁠עִ֖יר אֶל־פְּנֵ֣י הַ⁠שָּׂדֶ֑ה וְ⁠כִפֶּ֥ר עַל־הַ⁠בַּ֖יִת וְ⁠טָהֵֽר׃","wĕ⁠şǐlȧ֞ẖ ʼeţ-ha⁠ẕi̇pò֧̇r haֽ⁠ẖayá֛̇h ʼel-mi⁠ẖ֥ẇẕ lá⁠ʻi֖yr ʼel-pĕ̇né֣y ha⁠şá̇̂de֑h wĕ⁠kipė֥r ʻal-ha⁠bȧ֖yiţ wĕ⁠táhéֽr׃"],[14,54,"זֹ֖את הַ⁠תּוֹרָ֑ה לְ⁠כָל־נֶ֥גַע הַ⁠צָּרַ֖עַת וְ⁠לַ⁠נָּֽתֶק׃","zò֖ʼţ ha⁠ţ̇wòrá֑h lĕ⁠kál-ne֥gaʻ ha⁠ẕá̇ra֖ʻaţ wĕ⁠la⁠náֽ̇ţeq׃"],[14,55,"וּ⁠לְ⁠צָרַ֥עַת הַ⁠בֶּ֖גֶד וְ⁠לַ⁠בָּֽיִת׃","ẇ⁠lĕ⁠ẕára֥ʻaţ ha⁠bė֖ged wĕ⁠la⁠báֽ̇yiţ׃"],[14,56,"וְ⁠לַ⁠שְׂאֵ֥ת וְ⁠לַ⁠סַּפַּ֖חַת וְ⁠לַ⁠בֶּהָֽרֶת׃","wĕ⁠la⁠şĕ̂ʼé֥ţ wĕ⁠la⁠sȧpȧ֖ẖaţ wĕ⁠la⁠bėháֽreţ׃"],[14,57,"לְ⁠הוֹרֹ֕ת בְּ⁠י֥וֹם הַ⁠טָּמֵ֖א וּ⁠בְ⁠י֣וֹם הַ⁠טָּהֹ֑ר זֹ֥את תּוֹרַ֖ת הַ⁠צָּרָֽעַת׃ס","lĕ⁠hwòrò֕ţ bĕ̇⁠y֥wòm ha⁠tá̇mé֖ʼ ẇ⁠bĕ⁠y֣wòm ha⁠tá̇hò֑r zò֥ʼţ ţ̇wòra֖ţ ha⁠ẕá̇ráֽʻaţ׃s"],[15,1,"וַ⁠יְדַבֵּ֣ר יְהוָ֔ה אֶל־מֹשֶׁ֥ה וְ⁠אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹֽר׃","wa⁠yĕdabé֣̇r yĕhwá֔h ʼel-mòşě֥h wĕ⁠ʼeֽl-ʼahàrò֖n lé⁠ʼmòֽr׃"],[15,2,"דַּבְּרוּ֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠אֲמַרְתֶּ֖ם אֲלֵ⁠הֶ֑ם אִ֣ישׁ אִ֗ישׁ כִּ֤י יִהְיֶה֙ זָ֣ב מִ⁠בְּשָׂר֔⁠וֹ זוֹב֖⁠וֹ טָמֵ֥א הֽוּא׃","dȧbĕ̇rẇ֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠ʼàmarĕţė֖m ʼàlé⁠he֑m ʼi֣yş̌ ʼi֗yş̌ ki֤̇y yihĕyeh֙ zá֣b mi⁠bĕ̇şá̂r֔⁠wò zwòb֖⁠wò támé֥ʼ hֽẇʼ׃"],[15,3,"וְ⁠זֹ֛את תִּהְיֶ֥ה טֻמְאָת֖⁠וֹ בְּ⁠זוֹב֑⁠וֹ רָ֣ר בְּשָׂר֞⁠וֹ אֶת־זוֹב֗⁠וֹ אֽוֹ־הֶחְתִּ֤ים בְּשָׂר⁠וֹ֙ מִ⁠זּוֹב֔⁠וֹ טֻמְאָת֖⁠וֹ הִֽוא׃","wĕ⁠zò֛ʼţ ţi̇hĕye֥h tumĕʼáţ֖⁠wò bĕ̇⁠zwòb֑⁠wò rá֣r bĕ̇şá̂r֞⁠wò ʼeţ-zwòb֗⁠wò ʼֽwò-heẖĕţi֤̇ym bĕ̇şá̂r⁠wò֙ mi⁠żwòb֔⁠wò tumĕʼáţ֖⁠wò hiֽwʼ׃"],[15,4,"כָּל־הַ⁠מִּשְׁכָּ֗ב אֲשֶׁ֨ר יִשְׁכַּ֥ב עָלָ֛י⁠ו הַ⁠זָּ֖ב יִטְמָ֑א וְ⁠כָֽל־הַ⁠כְּלִ֛י אֲשֶׁר־יֵשֵׁ֥ב עָלָ֖י⁠ו יִטְמָֽא׃","ká̇l-ha⁠mi̇şĕ̌ká̇֗b ʼàşě֨r yişĕ̌kȧ֥b ʻálá֛y⁠w ha⁠zá֖̇b yitĕmá֑ʼ wĕ⁠káֽl-ha⁠kĕ̇li֛y ʼàşěr-yéşé֥̌b ʻálá֖y⁠w yitĕmáֽʼ׃"],[15,5,"וְ⁠אִ֕ישׁ אֲשֶׁ֥ר יִגַּ֖ע בְּ⁠מִשְׁכָּב֑⁠וֹ יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ʼi֕yş̌ ʼàşě֥r yigȧ֖ʻ bĕ̇⁠mişĕ̌ká̇b֑⁠wò yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,6,"וְ⁠הַ⁠יֹּשֵׁב֙ עַֽל־הַ⁠כְּלִ֔י אֲשֶׁר־יֵשֵׁ֥ב עָלָ֖י⁠ו הַ⁠זָּ֑ב יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ha⁠yò̇şé̌b֙ ʻaֽl-ha⁠kĕ̇li֔y ʼàşěr-yéşé֥̌b ʻálá֖y⁠w ha⁠zá֑̇b yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,7,"וְ⁠הַ⁠נֹּגֵ֖עַ בִּ⁠בְשַׂ֣ר הַ⁠זָּ֑ב יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ha⁠nò̇gé֖ʻa bi̇⁠bĕşâ֣r ha⁠zá֑̇b yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,8,"וְ⁠כִֽי־יָרֹ֛ק הַ⁠זָּ֖ב בַּ⁠טָּה֑וֹר וְ⁠כִבֶּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kiֽy-yárò֛q ha⁠zá֖̇b bȧ⁠tá̇h֑wòr wĕ⁠kibė֧s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,9,"וְ⁠כָל־הַ⁠מֶּרְכָּ֗ב אֲשֶׁ֨ר יִרְכַּ֥ב עָלָ֛י⁠ו הַ⁠זָּ֖ב יִטְמָֽא׃","wĕ⁠kál-ha⁠mėrĕká̇֗b ʼàşě֨r yirĕkȧ֥b ʻálá֛y⁠w ha⁠zá֖̇b yitĕmáֽʼ׃"],[15,10,"וְ⁠כָל־הַ⁠נֹּגֵ֗עַ בְּ⁠כֹל֙ אֲשֶׁ֣ר יִהְיֶ֣ה תַחְתָּ֔י⁠ו יִטְמָ֖א עַד־הָ⁠עָ֑רֶב וְ⁠הַ⁠נּוֹשֵׂ֣א אוֹתָ֔⁠ם יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kál-ha⁠nò̇gé֗ʻa bĕ̇⁠kòl֙ ʼàşě֣r yihĕye֣h ţaẖĕţá̇֔y⁠w yitĕmá֖ʼ ʻad-há⁠ʻá֑reb wĕ⁠ha⁠ṅwòşé֣̂ʼ ʼwòţá֔⁠m yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,11,"וְ⁠כֹ֨ל אֲשֶׁ֤ר יִגַּע־בּ⁠וֹ֙ הַ⁠זָּ֔ב וְ⁠יָדָ֖י⁠ו לֹא־שָׁטַ֣ף בַּ⁠מָּ֑יִם וְ⁠כִבֶּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kò֨l ʼàşě֤r yigȧʻ-ḃ⁠wò֙ ha⁠zá̇֔b wĕ⁠yádá֖y⁠w lòʼ-şá̌ta֣p bȧ⁠má֑̇yim wĕ⁠kibė֧s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,12,"וּ⁠כְלִי־חֶ֛רֶשׂ אֲשֶׁר־יִגַּע־בּ֥⁠וֹ הַ⁠זָּ֖ב יִשָּׁבֵ֑ר וְ⁠כָל־כְּלִי־עֵ֔ץ יִשָּׁטֵ֖ף בַּ⁠מָּֽיִם׃","ẇ⁠kĕliy-ẖe֛reş̂ ʼàşěr-yigȧʻ-ḃ֥⁠wò ha⁠zá֖̇b yişá̇̌bé֑r wĕ⁠kál-kĕ̇liy-ʻé֔ẕ yişá̇̌té֖p bȧ⁠máֽ̇yim׃"],[15,13,"וְ⁠כִֽי־יִטְהַ֤ר הַ⁠זָּב֙ מִ⁠זּוֹב֔⁠וֹ וְ⁠סָ֨פַר ל֜⁠וֹ שִׁבְעַ֥ת יָמִ֛ים לְ⁠טָהֳרָת֖⁠וֹ וְ⁠כִבֶּ֣ס בְּגָדָ֑י⁠ו וְ⁠רָחַ֧ץ בְּשָׂר֛⁠וֹ בְּ⁠מַ֥יִם חַיִּ֖ים וְ⁠טָהֵֽר׃","wĕ⁠kiֽy-yitĕha֤r ha⁠zá̇b֙ mi⁠żwòb֔⁠wò wĕ⁠sá֨par l֜⁠wò şǐbĕʻa֥ţ yámi֛ym lĕ⁠táhoráţ֖⁠wò wĕ⁠kibė֣s bĕ̇gádá֑y⁠w wĕ⁠ráẖa֧ẕ bĕ̇şá̂r֛⁠wò bĕ̇⁠ma֥yim ẖayi֖̇ym wĕ⁠táhéֽr׃"],[15,14,"וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁמִינִ֗י יִֽקַּֽח־ל⁠וֹ֙ שְׁתֵּ֣י תֹרִ֔ים א֥וֹ שְׁנֵ֖י בְּנֵ֣י יוֹנָ֑ה וּ⁠בָ֣א ׀ לִ⁠פְנֵ֣י יְהוָ֗ה אֶל־פֶּ֨תַח֙ אֹ֣הֶל מוֹעֵ֔ד וּ⁠נְתָנָ֖⁠ם אֶל־הַ⁠כֹּהֵֽן׃","ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌miyni֗y yiֽqȧֽẖ-l⁠wò֙ şĕ̌ţé֣̇y ţòri֔ym ʼ֥wò şĕ̌né֖y bĕ̇né֣y ywòná֑h ẇ⁠bá֣ʼ ׀ li⁠pĕné֣y yĕhwá֗h ʼel-pė֨ţaẖ֙ ʼò֣hel mwòʻé֔d ẇ⁠nĕţáná֖⁠m ʼel-ha⁠kò̇héֽn׃"],[15,15,"וְ⁠עָשָׂ֤ה אֹתָ⁠ם֙ הַ⁠כֹּהֵ֔ן אֶחָ֣ד חַטָּ֔את וְ⁠הָ⁠אֶחָ֖ד עֹלָ֑ה וְ⁠כִפֶּ֨ר עָלָ֧י⁠ו הַ⁠כֹּהֵ֛ן לִ⁠פְנֵ֥י יְהוָ֖ה מִ⁠זּוֹבֽ⁠וֹ׃ס","wĕ⁠ʻáşá֤̂h ʼòţá⁠m֙ ha⁠kò̇hé֔n ʼeẖá֣d ẖatá̇֔ʼţ wĕ⁠há⁠ʼeẖá֖d ʻòlá֑h wĕ⁠kipė֨r ʻálá֧y⁠w ha⁠kò̇hé֛n li⁠pĕné֥y yĕhwá֖h mi⁠żwòbֽ⁠wò׃s"],[15,16,"וְ⁠אִ֕ישׁ כִּֽי־תֵצֵ֥א מִמֶּ֖⁠נּוּ שִׁכְבַת־זָ֑רַע וְ⁠רָחַ֥ץ בַּ⁠מַּ֛יִם אֶת־כָּל־בְּשָׂר֖⁠וֹ וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ʼi֕yş̌ kiֽ̇y-ţéẕé֥ʼ mimė֖⁠ṅẇ şǐkĕbaţ-zá֑raʻ wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֛yim ʼeţ-ká̇l-bĕ̇şá̂r֖⁠wò wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,17,"וְ⁠כָל־בֶּ֣גֶד וְ⁠כָל־ע֔וֹר אֲשֶׁר־יִהְיֶ֥ה עָלָ֖י⁠ו שִׁכְבַת־זָ֑רַע וְ⁠כֻבַּ֥ס בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃פ","wĕ⁠kál-bė֣ged wĕ⁠kál-ʻ֔wòr ʼàşěr-yihĕye֥h ʻálá֖y⁠w şǐkĕbaţ-zá֑raʻ wĕ⁠kubȧ֥s bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃p"],[15,18,"וְ⁠אִשָּׁ֕ה אֲשֶׁ֨ר יִשְׁכַּ֥ב אִ֛ישׁ אֹתָ֖⁠הּ שִׁכְבַת־זָ֑רַע וְ⁠רָחֲצ֣וּ בַ⁠מַּ֔יִם וְ⁠טָמְא֖וּ עַד־הָ⁠עָֽרֶב׃","wĕ⁠ʼişá̇̌֕h ʼàşě֨r yişĕ̌kȧ֥b ʼi֛yş̌ ʼòţá֖⁠ḣ şǐkĕbaţ-zá֑raʻ wĕ⁠ráẖàẕ֣ẇ ba⁠mȧ֔yim wĕ⁠támĕʼ֖ẇ ʻad-há⁠ʻáֽreb׃"],[15,19,"וְ⁠אִשָּׁה֙ כִּֽי־תִהְיֶ֣ה זָבָ֔ה דָּ֛ם יִהְיֶ֥ה זֹבָ֖⁠הּ בִּ⁠בְשָׂרָ֑⁠הּ שִׁבְעַ֤ת יָמִים֙ תִּהְיֶ֣ה בְ⁠נִדָּתָ֔⁠הּ וְ⁠כָל־הַ⁠נֹּגֵ֥עַ בָּ֖⁠הּ יִטְמָ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ʼişá̇̌h֙ kiֽ̇y-ţihĕye֣h zábá֔h dá֛̇m yihĕye֥h zòbá֖⁠ḣ bi̇⁠bĕşá̂rá֑⁠ḣ şǐbĕʻa֤ţ yámiym֙ ţi̇hĕye֣h bĕ⁠nidá̇ţá֔⁠ḣ wĕ⁠kál-ha⁠nò̇gé֥ʻa bá֖̇⁠ḣ yitĕmá֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,20,"וְ⁠כֹל֩ אֲשֶׁ֨ר תִּשְׁכַּ֥ב עָלָ֛י⁠ו בְּ⁠נִדָּתָ֖⁠הּ יִטְמָ֑א וְ⁠כֹ֛ל אֲשֶׁר־תֵּשֵׁ֥ב עָלָ֖י⁠ו יִטְמָֽא׃","wĕ⁠kòl֩ ʼàşě֨r ţi̇şĕ̌kȧ֥b ʻálá֛y⁠w bĕ̇⁠nidá̇ţá֖⁠ḣ yitĕmá֑ʼ wĕ⁠kò֛l ʼàşěr-ţé̇şé֥̌b ʻálá֖y⁠w yitĕmáֽʼ׃"],[15,21,"וְ⁠כָל־הַ⁠נֹּגֵ֖עַ בְּ⁠מִשְׁכָּבָ֑⁠הּ יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kál-ha⁠nò̇gé֖ʻa bĕ̇⁠mişĕ̌ká̇bá֑⁠ḣ yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,22,"וְ⁠כָל־הַ⁠נֹּגֵ֔עַ בְּ⁠כָל־כְּלִ֖י אֲשֶׁר־תֵּשֵׁ֣ב עָלָ֑י⁠ו יְכַבֵּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kál-ha⁠nò̇gé֔ʻa bĕ̇⁠kál-kĕ̇li֖y ʼàşěr-ţé̇şé֣̌b ʻálá֑y⁠w yĕkabé֧̇s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,23,"וְ⁠אִ֨ם עַֽל־הַ⁠מִּשְׁכָּ֜ב ה֗וּא א֧וֹ עַֽל־הַ⁠כְּלִ֛י אֲשֶׁר־הִ֥וא יֹשֶֽׁבֶת־עָלָ֖י⁠ו בְּ⁠נָגְע⁠וֹ־ב֑⁠וֹ יִטְמָ֖א עַד־הָ⁠עָֽרֶב׃","wĕ⁠ʼi֨m ʻaֽl-ha⁠mi̇şĕ̌ká̇֜b h֗ẇʼ ʼ֧wò ʻaֽl-ha⁠kĕ̇li֛y ʼàşěr-hi֥wʼ yòşěֽbeţ-ʻálá֖y⁠w bĕ̇⁠nágĕʻ⁠wò-b֑⁠wò yitĕmá֖ʼ ʻad-há⁠ʻáֽreb׃"],[15,24,"וְ⁠אִ֡ם שָׁכֹב֩ יִשְׁכַּ֨ב אִ֜ישׁ אֹתָ֗⁠הּ וּ⁠תְהִ֤י נִדָּתָ⁠הּ֙ עָלָ֔י⁠ו וְ⁠טָמֵ֖א שִׁבְעַ֣ת יָמִ֑ים וְ⁠כָל־הַ⁠מִּשְׁכָּ֛ב אֲשֶׁר־יִשְׁכַּ֥ב עָלָ֖י⁠ו יִטְמָֽא׃פ","wĕ⁠ʼi֡m şá̌kòb֩ yişĕ̌kȧ֨b ʼi֜yş̌ ʼòţá֗⁠ḣ ẇ⁠ţĕhi֤y nidá̇ţá⁠ḣ֙ ʻálá֔y⁠w wĕ⁠támé֖ʼ şǐbĕʻa֣ţ yámi֑ym wĕ⁠kál-ha⁠mi̇şĕ̌ká֛̇b ʼàşěr-yişĕ̌kȧ֥b ʻálá֖y⁠w yitĕmáֽʼ׃p"],[15,25,"וְ⁠אִשָּׁ֡ה כִּֽי־יָזוּב֩ ז֨וֹב דָּמָ֜⁠הּ יָמִ֣ים רַבִּ֗ים בְּ⁠לֹא֙ עֶת־נִדָּתָ֔⁠הּ א֥וֹ כִֽי־תָז֖וּב עַל־נִדָּתָ֑⁠הּ כָּל־יְמֵ֞י ז֣וֹב טֻמְאָתָ֗⁠הּ כִּ⁠ימֵ֧י נִדָּתָ֛⁠הּ תִּהְיֶ֖ה טְמֵאָ֥ה הִֽוא׃","wĕ⁠ʼişá̇̌֡h kiֽ̇y-yázẇb֩ z֨wòb dá̇má֜⁠ḣ yámi֣ym rabi̇֗ym bĕ̇⁠lòʼ֙ ʻeţ-nidá̇ţá֔⁠ḣ ʼ֥wò kiֽy-ţáz֖ẇb ʻal-nidá̇ţá֑⁠ḣ ká̇l-yĕmé֞y z֣wòb tumĕʼáţá֗⁠ḣ ki̇⁠ymé֧y nidá̇ţá֛⁠ḣ ţi̇hĕye֖h tĕméʼá֥h hiֽwʼ׃"],[15,26,"כָּל־הַ⁠מִּשְׁכָּ֞ב אֲשֶׁר־תִּשְׁכַּ֤ב עָלָי⁠ו֙ כָּל־יְמֵ֣י זוֹבָ֔⁠הּ כְּ⁠מִשְׁכַּ֥ב נִדָּתָ֖⁠הּ יִֽהְיֶה־לָּ֑⁠הּ וְ⁠כָֽל־הַ⁠כְּלִי֙ אֲשֶׁ֣ר תֵּשֵׁ֣ב עָלָ֔י⁠ו טָמֵ֣א יִהְיֶ֔ה כְּ⁠טֻמְאַ֖ת נִדָּתָֽ⁠הּ׃","ká̇l-ha⁠mi̇şĕ̌ká̇֞b ʼàşěr-ţi̇şĕ̌kȧ֤b ʻáláy⁠w֙ ká̇l-yĕmé֣y zwòbá֔⁠ḣ kĕ̇⁠mişĕ̌kȧ֥b nidá̇ţá֖⁠ḣ yiֽhĕyeh-lá֑̇⁠ḣ wĕ⁠káֽl-ha⁠kĕ̇liy֙ ʼàşě֣r ţé̇şé֣̌b ʻálá֔y⁠w támé֣ʼ yihĕye֔h kĕ̇⁠tumĕʼa֖ţ nidá̇ţáֽ⁠ḣ׃"],[15,27,"וְ⁠כָל־הַ⁠נּוֹגֵ֥עַ בָּ֖⁠ם יִטְמָ֑א וְ⁠כִבֶּ֧ס בְּגָדָ֛י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֖יִם וְ⁠טָמֵ֥א עַד־הָ⁠עָֽרֶב׃","wĕ⁠kál-ha⁠ṅwògé֥ʻa bá֖̇⁠m yitĕmá֑ʼ wĕ⁠kibė֧s bĕ̇gádá֛y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֖yim wĕ⁠támé֥ʼ ʻad-há⁠ʻáֽreb׃"],[15,28,"וְ⁠אִֽם־טָהֲרָ֖ה מִ⁠זּוֹבָ֑⁠הּ וְ⁠סָ֥פְרָה לָּ֛⁠הּ שִׁבְעַ֥ת יָמִ֖ים וְ⁠אַחַ֥ר תִּטְהָֽר׃","wĕ⁠ʼiֽm-táhàrá֖h mi⁠żwòbá֑⁠ḣ wĕ⁠sá֥pĕráh lá֛̇⁠ḣ şǐbĕʻa֥ţ yámi֖ym wĕ⁠ʼaẖa֥r ţi̇tĕháֽr׃"],[15,29,"וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁמִינִ֗י תִּֽקַּֽח־לָ⁠הּ֙ שְׁתֵּ֣י תֹרִ֔ים א֥וֹ שְׁנֵ֖י בְּנֵ֣י יוֹנָ֑ה וְ⁠הֵבִיאָ֤ה אוֹתָ⁠ם֙ אֶל־הַ⁠כֹּהֵ֔ן אֶל־פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌miyni֗y ţiֽ̇qȧֽẖ-lá⁠ḣ֙ şĕ̌ţé֣̇y ţòri֔ym ʼ֥wò şĕ̌né֖y bĕ̇né֣y ywòná֑h wĕ⁠hébiyʼá֤h ʼwòţá⁠m֙ ʼel-ha⁠kò̇hé֔n ʼel-pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[15,30,"וְ⁠עָשָׂ֤ה הַ⁠כֹּהֵן֙ אֶת־הָ⁠אֶחָ֣ד חַטָּ֔את וְ⁠אֶת־הָ⁠אֶחָ֖ד עֹלָ֑ה וְ⁠כִפֶּ֨ר עָלֶ֤י⁠הָ הַ⁠כֹּהֵן֙ לִ⁠פְנֵ֣י יְהוָ֔ה מִ⁠זּ֖וֹב טֻמְאָתָֽ⁠הּ׃","wĕ⁠ʻáşá֤̂h ha⁠kò̇hén֙ ʼeţ-há⁠ʼeẖá֣d ẖatá̇֔ʼţ wĕ⁠ʼeţ-há⁠ʼeẖá֖d ʻòlá֑h wĕ⁠kipė֨r ʻále֤y⁠há ha⁠kò̇hén֙ li⁠pĕné֣y yĕhwá֔h mi⁠ż֖wòb tumĕʼáţáֽ⁠ḣ׃"],[15,31,"וְ⁠הִזַּרְתֶּ֥ם אֶת־בְּנֵי־יִשְׂרָאֵ֖ל מִ⁠טֻּמְאָתָ֑⁠ם וְ⁠לֹ֤א יָמֻ֨תוּ֙ בְּ⁠טֻמְאָתָ֔⁠ם בְּ⁠טַמְּאָ֥⁠ם אֶת־מִשְׁכָּנִ֖⁠י אֲשֶׁ֥ר בְּ⁠תוֹכָֽ⁠ם׃","wĕ⁠hizȧrĕţė֥m ʼeţ-bĕ̇néy-yişĕ̂ráʼé֖l mi⁠tu̇mĕʼáţá֑⁠m wĕ⁠lò֤ʼ yámu֨ţẇ֙ bĕ̇⁠tumĕʼáţá֔⁠m bĕ̇⁠tamĕ̇ʼá֥⁠m ʼeţ-mişĕ̌ká̇ni֖⁠y ʼàşě֥r bĕ̇⁠ţwòkáֽ⁠m׃"],[15,32,"זֹ֥את תּוֹרַ֖ת הַ⁠זָּ֑ב וַ⁠אֲשֶׁ֨ר תֵּצֵ֥א מִמֶּ֛⁠נּוּ שִׁכְבַת־זֶ֖רַע לְ⁠טָמְאָה־בָֽ⁠הּ׃","zò֥ʼţ ţ̇wòra֖ţ ha⁠zá֑̇b wa⁠ʼàşě֨r ţé̇ẕé֥ʼ mimė֛⁠ṅẇ şǐkĕbaţ-ze֖raʻ lĕ⁠támĕʼáh-báֽ⁠ḣ׃"],[15,33,"וְ⁠הַ⁠דָּוָה֙ בְּ⁠נִדָּתָ֔⁠הּ וְ⁠הַ⁠זָּב֙ אֶת־זוֹב֔⁠וֹ לַ⁠זָּכָ֖ר וְ⁠לַ⁠נְּקֵבָ֑ה וּ⁠לְ⁠אִ֕ישׁ אֲשֶׁ֥ר יִשְׁכַּ֖ב עִם־טְמֵאָֽה׃פ","wĕ⁠ha⁠dá̇wáh֙ bĕ̇⁠nidá̇ţá֔⁠ḣ wĕ⁠ha⁠zá̇b֙ ʼeţ-zwòb֔⁠wò la⁠zá̇ká֖r wĕ⁠la⁠nĕ̇qébá֑h ẇ⁠lĕ⁠ʼi֕yş̌ ʼàşě֥r yişĕ̌kȧ֖b ʻim-tĕméʼáֽh׃p"],[16,1,"וַ⁠יְדַבֵּ֤ר יְהוָה֙ אֶל־מֹשֶׁ֔ה אַחֲרֵ֣י מ֔וֹת שְׁנֵ֖י בְּנֵ֣י אַהֲרֹ֑ן בְּ⁠קָרְבָתָ֥⁠ם לִ⁠פְנֵי־יְהוָ֖ה וַ⁠יָּמֻֽתוּ׃","wa⁠yĕdabé֤̇r yĕhwáh֙ ʼel-mòşě֔h ʼaẖàré֣y m֔wòţ şĕ̌né֖y bĕ̇né֣y ʼahàrò֑n bĕ̇⁠qárĕbáţá֥⁠m li⁠pĕnéy-yĕhwá֖h wa⁠yá̇muֽţẇ׃"],[16,2,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה דַּבֵּר֮ אֶל־אַהֲרֹ֣ן אָחִי⁠ךָ֒ וְ⁠אַל־יָבֹ֤א בְ⁠כָל־עֵת֙ אֶל־הַ⁠קֹּ֔דֶשׁ מִ⁠בֵּ֖ית לַ⁠פָּרֹ֑כֶת אֶל־פְּנֵ֨י הַ⁠כַּפֹּ֜רֶת אֲשֶׁ֤ר עַל־הָ⁠אָרֹן֙ וְ⁠לֹ֣א יָמ֔וּת כִּ֚י בֶּֽ⁠עָנָ֔ן אֵרָאֶ֖ה עַל־הַ⁠כַּפֹּֽרֶת׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h dȧbé̇r֮ ʼel-ʼahàrò֣n ʼáẖiy⁠ká֒ wĕ⁠ʼal-yábò֤ʼ bĕ⁠kál-ʻéţ֙ ʼel-ha⁠qò̇֔deş̌ mi⁠bé֖̇yţ la⁠pá̇rò֑keţ ʼel-pĕ̇né֨y ha⁠kȧpò̇֜reţ ʼàşě֤r ʻal-há⁠ʼáròn֙ wĕ⁠lò֣ʼ yám֔ẇţ ki֚̇y bėֽ⁠ʻáná֔n ʼéráʼe֖h ʻal-ha⁠kȧpòֽ̇reţ׃"],[16,3,"בְּ⁠זֹ֛את יָבֹ֥א אַהֲרֹ֖ן אֶל־הַ⁠קֹּ֑דֶשׁ בְּ⁠פַ֧ר בֶּן־בָּקָ֛ר לְ⁠חַטָּ֖את וְ⁠אַ֥יִל לְ⁠עֹלָֽה׃","bĕ̇⁠zò֛ʼţ yábò֥ʼ ʼahàrò֖n ʼel-ha⁠qò֑̇deş̌ bĕ̇⁠pa֧r bėn-bá̇qá֛r lĕ⁠ẖatá֖̇ʼţ wĕ⁠ʼa֥yil lĕ⁠ʻòláֽh׃"],[16,4,"כְּתֹֽנֶת־בַּ֨ד קֹ֜דֶשׁ יִלְבָּ֗שׁ וּ⁠מִֽכְנְסֵי־בַד֮ יִהְי֣וּ עַל־בְּשָׂר⁠וֹ֒ וּ⁠בְ⁠אַבְנֵ֥ט בַּד֙ יַחְגֹּ֔ר וּ⁠בְ⁠מִצְנֶ֥פֶת בַּ֖ד יִצְנֹ֑ף בִּגְדֵי־קֹ֣דֶשׁ הֵ֔ם וְ⁠רָחַ֥ץ בַּ⁠מַּ֛יִם אֶת־בְּשָׂר֖⁠וֹ וּ⁠לְבֵשָֽׁ⁠ם׃","kĕ̇ţòֽneţ-bȧ֨d qò֜deş̌ yilĕbá̇֗ş̌ ẇ⁠miֽkĕnĕséy-bad֮ yihĕy֣ẇ ʻal-bĕ̇şá̂r⁠wò֒ ẇ⁠bĕ⁠ʼabĕné֥t bȧd֙ yaẖĕgò̇֔r ẇ⁠bĕ⁠miẕĕne֥peţ bȧ֖d yiẕĕnò֑p bi̇gĕdéy-qò֣deş̌ hé֔m wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֛yim ʼeţ-bĕ̇şá̂r֖⁠wò ẇ⁠lĕbéşáֽ̌⁠m׃"],[16,5,"וּ⁠מֵ⁠אֵ֗ת עֲדַת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל יִקַּ֛ח שְׁנֵֽי־שְׂעִירֵ֥י עִזִּ֖ים לְ⁠חַטָּ֑את וְ⁠אַ֥יִל אֶחָ֖ד לְ⁠עֹלָֽה׃","ẇ⁠mé⁠ʼé֗ţ ʻàdaţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l yiqȧ֛ẖ şĕ̌néֽy-şĕ̂ʻiyré֥y ʻizi֖̇ym lĕ⁠ẖatá֑̇ʼţ wĕ⁠ʼa֥yil ʼeẖá֖d lĕ⁠ʻòláֽh׃"],[16,6,"וְ⁠הִקְרִ֧יב אַהֲרֹ֛ן אֶת־פַּ֥ר הַ⁠חַטָּ֖את אֲשֶׁר־ל֑⁠וֹ וְ⁠כִפֶּ֥ר בַּעֲד֖⁠וֹ וּ⁠בְעַ֥ד בֵּיתֽ⁠וֹ׃","wĕ⁠hiqĕri֧yb ʼahàrò֛n ʼeţ-pȧ֥r ha⁠ẖatá֖̇ʼţ ʼàşěr-l֑⁠wò wĕ⁠kipė֥r bȧʻàd֖⁠wò ẇ⁠bĕʻa֥d bé̇yţֽ⁠wò׃"],[16,7,"וְ⁠לָקַ֖ח אֶת־שְׁנֵ֣י הַ⁠שְּׂעִירִ֑ם וְ⁠הֶעֱמִ֤יד אֹתָ⁠ם֙ לִ⁠פְנֵ֣י יְהוָ֔ה פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠láqa֖ẖ ʼeţ-şĕ̌né֣y ha⁠şĕ̇̂ʻiyri֑m wĕ⁠heʻèmi֤yd ʼòţá⁠m֙ li⁠pĕné֣y yĕhwá֔h pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[16,8,"וְ⁠נָתַ֧ן אַהֲרֹ֛ן עַל־שְׁנֵ֥י הַ⁠שְּׂעִירִ֖ם גּוֹרָל֑וֹת גּוֹרָ֤ל אֶחָד֙ לַ⁠יהוָ֔ה וְ⁠גוֹרָ֥ל אֶחָ֖ד לַ⁠עֲזָאזֵֽל׃","wĕ⁠náţa֧n ʼahàrò֛n ʻal-şĕ̌né֥y ha⁠şĕ̇̂ʻiyri֖m ġwòrál֑wòţ ġwòrá֤l ʼeẖád֙ la⁠yhwá֔h wĕ⁠gwòrá֥l ʼeẖá֖d la⁠ʻàzáʼzéֽl׃"],[16,9,"וְ⁠הִקְרִ֤יב אַהֲרֹן֙ אֶת־הַ⁠שָּׂעִ֔יר אֲשֶׁ֨ר עָלָ֥ה עָלָ֛י⁠ו הַ⁠גּוֹרָ֖ל לַ⁠יהוָ֑ה וְ⁠עָשָׂ֖⁠הוּ חַטָּֽאת׃","wĕ⁠hiqĕri֤yb ʼahàròn֙ ʼeţ-ha⁠şá̇̂ʻi֔yr ʼàşě֨r ʻálá֥h ʻálá֛y⁠w ha⁠ġwòrá֖l la⁠yhwá֑h wĕ⁠ʻáşá֖̂⁠hẇ ẖatáֽ̇ʼţ׃"],[16,10,"וְ⁠הַ⁠שָּׂעִ֗יר אֲשֶׁר֩ עָלָ֨ה עָלָ֤י⁠ו הַ⁠גּוֹרָל֙ לַ⁠עֲזָאזֵ֔ל יָֽעֳמַד־חַ֛י לִ⁠פְנֵ֥י יְהוָ֖ה לְ⁠כַפֵּ֣ר עָלָ֑י⁠ו לְ⁠שַׁלַּ֥ח אֹת֛⁠וֹ לַ⁠עֲזָאזֵ֖ל הַ⁠מִּדְבָּֽרָ⁠ה׃","wĕ⁠ha⁠şá̇̂ʻi֗yr ʼàşěr֩ ʻálá֨h ʻálá֤y⁠w ha⁠ġwòrál֙ la⁠ʻàzáʼzé֔l yáֽʻomad-ẖa֛y li⁠pĕné֥y yĕhwá֖h lĕ⁠kapé֣̇r ʻálá֑y⁠w lĕ⁠şǎlȧ֥ẖ ʼòţ֛⁠wò la⁠ʻàzáʼzé֖l ha⁠mi̇dĕbáֽ̇rá⁠h׃"],[16,11,"וְ⁠הִקְרִ֨יב אַהֲרֹ֜ן אֶת־פַּ֤ר הַֽ⁠חַטָּאת֙ אֲשֶׁר־ל֔⁠וֹ וְ⁠כִפֶּ֥ר בַּֽעֲד֖⁠וֹ וּ⁠בְעַ֣ד בֵּית֑⁠וֹ וְ⁠שָׁחַ֛ט אֶת־פַּ֥ר הַֽ⁠חַטָּ֖את אֲשֶׁר־לֽ⁠וֹ׃","wĕ⁠hiqĕri֨yb ʼahàrò֜n ʼeţ-pȧ֤r haֽ⁠ẖatá̇ʼţ֙ ʼàşěr-l֔⁠wò wĕ⁠kipė֥r bȧֽʻàd֖⁠wò ẇ⁠bĕʻa֣d bé̇yţ֑⁠wò wĕ⁠şá̌ẖa֛t ʼeţ-pȧ֥r hֽa⁠ẖatá֖̇ʼţ ʼàşěr-lֽ⁠wò׃"],[16,12,"וְ⁠לָקַ֣ח מְלֹֽא־הַ֠⁠מַּחְתָּה גַּֽחֲלֵי־אֵ֞שׁ מֵ⁠עַ֤ל הַ⁠מִּזְבֵּ֨חַ֙ מִ⁠לִּ⁠פְנֵ֣י יְהוָ֔ה וּ⁠מְלֹ֣א חָפְנָ֔י⁠ו קְטֹ֥רֶת סַמִּ֖ים דַּקָּ֑ה וְ⁠הֵבִ֖יא מִ⁠בֵּ֥ית לַ⁠פָּרֹֽכֶת׃","wĕ⁠láqa֣ẖ mĕlòֽʼ-ha֠⁠mȧẖĕţá̇h gȧֽẖàléy-ʼé֞ş̌ mé⁠ʻa֤l ha⁠mi̇zĕbé̇֨ẖa֙ mi⁠li̇⁠pĕné֣y yĕhwá֔h ẇ⁠mĕlò֣ʼ ẖápĕná֔y⁠w qĕtò֥reţ sami֖̇ym dȧqá֑̇h wĕ⁠hébi֖yʼ mi⁠bé֥̇yţ la⁠pá̇ròֽkeţ׃"],[16,13,"וְ⁠נָתַ֧ן אֶֽת־הַ⁠קְּטֹ֛רֶת עַל־הָ⁠אֵ֖שׁ לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠כִסָּ֣ה ׀ עֲנַ֣ן הַ⁠קְּטֹ֗רֶת אֶת־הַ⁠כַּפֹּ֛רֶת אֲשֶׁ֥ר עַל־הָ⁠עֵד֖וּת וְ⁠לֹ֥א יָמֽוּת׃","wĕ⁠náţa֧n ʼeֽţ-ha⁠qĕ̇tò֛reţ ʻal-há⁠ʼé֖ş̌ li⁠pĕné֣y yĕhwá֑h wĕ⁠kisá֣̇h ׀ ʻàna֣n ha⁠qĕ̇tò֗reţ ʼeţ-ha⁠kȧpò֛̇reţ ʼàşě֥r ʻal-há⁠ʻéd֖ẇţ wĕ⁠lò֥ʼ yámֽẇţ׃"],[16,14,"וְ⁠לָקַח֙ מִ⁠דַּ֣ם הַ⁠פָּ֔ר וְ⁠הִזָּ֧ה בְ⁠אֶצְבָּע֛⁠וֹ עַל־פְּנֵ֥י הַ⁠כַּפֹּ֖רֶת קֵ֑דְמָ⁠ה וְ⁠לִ⁠פְנֵ֣י הַ⁠כַּפֹּ֗רֶת יַזֶּ֧ה שֶֽׁבַע־פְּעָמִ֛ים מִן־הַ⁠דָּ֖ם בְּ⁠אֶצְבָּעֽ⁠וֹ׃","wĕ⁠láqaẖ֙ mi⁠dȧ֣m ha⁠pá̇֔r wĕ⁠hizá֧̇h bĕ⁠ʼeẕĕbá̇ʻ֛⁠wò ʻal-pĕ̇né֥y ha⁠kȧpò֖̇reţ qé֑dĕmá⁠h wĕ⁠li⁠pĕné֣y ha⁠kȧpò̇֗reţ yazė֧h şěֽbaʻ-pĕ̇ʻámi֛ym min-ha⁠dá֖̇m bĕ̇⁠ʼeẕĕbá̇ʻֽ⁠wò׃"],[16,15,"וְ⁠שָׁחַ֞ט אֶת־שְׂעִ֤יר הַֽ⁠חַטָּאת֙ אֲשֶׁ֣ר לָ⁠עָ֔ם וְ⁠הֵבִיא֙ אֶת־דָּמ֔⁠וֹ אֶל־מִ⁠בֵּ֖ית לַ⁠פָּרֹ֑כֶת וְ⁠עָשָׂ֣ה אֶת־דָּמ֗⁠וֹ כַּ⁠אֲשֶׁ֤ר עָשָׂה֙ לְ⁠דַ֣ם הַ⁠פָּ֔ר וְ⁠הִזָּ֥ה אֹת֛⁠וֹ עַל־הַ⁠כַּפֹּ֖רֶת וְ⁠לִ⁠פְנֵ֥י הַ⁠כַּפֹּֽרֶת׃","wĕ⁠şá̌ẖa֞t ʼeţ-şĕ̂ʻi֤yr haֽ⁠ẖatá̇ʼţ֙ ʼàşě֣r lá⁠ʻá֔m wĕ⁠hébiyʼ֙ ʼeţ-dá̇m֔⁠wò ʼel-mi⁠bé֖̇yţ la⁠pá̇rò֑keţ wĕ⁠ʻáşá֣̂h ʼeţ-dá̇m֗⁠wò kȧ⁠ʼàşě֤r ʻáşá̂h֙ lĕ⁠da֣m ha⁠pá̇֔r wĕ⁠hizá֥̇h ʼòţ֛⁠wò ʻal-ha⁠kȧpò֖̇reţ wĕ⁠li⁠pĕné֥y ha⁠kȧpòֽ̇reţ׃"],[16,16,"וְ⁠כִפֶּ֣ר עַל־הַ⁠קֹּ֗דֶשׁ מִ⁠טֻּמְאֹת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וּ⁠מִ⁠פִּשְׁעֵי⁠הֶ֖ם לְ⁠כָל־חַטֹּאתָ֑⁠ם וְ⁠כֵ֤ן יַעֲשֶׂה֙ לְ⁠אֹ֣הֶל מוֹעֵ֔ד הַ⁠שֹּׁכֵ֣ן אִתָּ֔⁠ם בְּ⁠ת֖וֹךְ טֻמְאֹתָֽ⁠ם׃","wĕ⁠kipė֣r ʻal-ha⁠qò̇֗deş̌ mi⁠tu̇mĕʼòţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ẇ⁠mi⁠pi̇şĕ̌ʻéy⁠he֖m lĕ⁠kál-ẖatò̇ʼţá֑⁠m wĕ⁠ké֤n yaʻàşêh֙ lĕ⁠ʼò֣hel mwòʻé֔d ha⁠şò̇̌ké֣n ʼiţá̇֔⁠m bĕ̇⁠ţ֖wòkĕ tumĕʼòţáֽ⁠m׃"],[16,17,"וְ⁠כָל־אָדָ֞ם לֹא־יִהְיֶ֣ה ׀ בְּ⁠אֹ֣הֶל מוֹעֵ֗ד בְּ⁠בֹא֛⁠וֹ לְ⁠כַפֵּ֥ר בַּ⁠קֹּ֖דֶשׁ עַד־צֵאת֑⁠וֹ וְ⁠כִפֶּ֤ר בַּעֲד⁠וֹ֙ וּ⁠בְעַ֣ד בֵּית֔⁠וֹ וּ⁠בְעַ֖ד כָּל־קְהַ֥ל יִשְׂרָאֵֽל׃","wĕ⁠kál-ʼádá֞m lòʼ-yihĕye֣h ׀ bĕ̇⁠ʼò֣hel mwòʻé֗d bĕ̇⁠bòʼ֛⁠wò lĕ⁠kapé֥̇r bȧ⁠qò֖̇deş̌ ʻad-ẕéʼţ֑⁠wò wĕ⁠kipė֤r bȧʻàd⁠wò֙ ẇ⁠bĕʻa֣d bé̇yţ֔⁠wò ẇ⁠bĕʻa֖d ká̇l-qĕha֥l yişĕ̂ráʼéֽl׃"],[16,18,"וְ⁠יָצָ֗א אֶל־הַ⁠מִּזְבֵּ֛חַ אֲשֶׁ֥ר לִ⁠פְנֵֽי־יְהוָ֖ה וְ⁠כִפֶּ֣ר עָלָ֑י⁠ו וְ⁠לָקַ֞ח מִ⁠דַּ֤ם הַ⁠פָּר֙ וּ⁠מִ⁠דַּ֣ם הַ⁠שָּׂעִ֔יר וְ⁠נָתַ֛ן עַל־קַרְנ֥וֹת הַ⁠מִּזְבֵּ֖חַ סָבִֽיב׃","wĕ⁠yáẕá֗ʼ ʼel-ha⁠mi̇zĕbé֛̇ẖa ʼàşě֥r li⁠pĕnéֽy-yĕhwá֖h wĕ⁠kipė֣r ʻálá֑y⁠w wĕ⁠láqa֞ẖ mi⁠dȧ֤m ha⁠pá̇r֙ ẇ⁠mi⁠dȧ֣m ha⁠şá̇̂ʻi֔yr wĕ⁠náţa֛n ʻal-qarĕn֥wòţ ha⁠mi̇zĕbé֖̇ẖa sábiֽyb׃"],[16,19,"וְ⁠הִזָּ֨ה עָלָ֧י⁠ו מִן־הַ⁠דָּ֛ם בְּ⁠אֶצְבָּע֖⁠וֹ שֶׁ֣בַע פְּעָמִ֑ים וְ⁠טִהֲר֣⁠וֹ וְ⁠קִדְּשׁ֔⁠וֹ מִ⁠טֻּמְאֹ֖ת בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠hizá̇֨h ʻálá֧y⁠w min-ha⁠dá֛̇m bĕ̇⁠ʼeẕĕbá̇ʻ֖⁠wò şě֣baʻ pĕ̇ʻámi֑ym wĕ⁠tihàr֣⁠wò wĕ⁠qidĕ̇ş̌֔⁠wò mi⁠tu̇mĕʼò֖ţ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[16,20,"וְ⁠כִלָּה֙ מִ⁠כַּפֵּ֣ר אֶת־הַ⁠קֹּ֔דֶשׁ וְ⁠אֶת־אֹ֥הֶל מוֹעֵ֖ד וְ⁠אֶת־הַ⁠מִּזְבֵּ֑חַ וְ⁠הִקְרִ֖יב אֶת־הַ⁠שָּׂעִ֥יר הֶ⁠חָֽי׃","wĕ⁠kilá̇h֙ mi⁠kȧpé֣̇r ʼeţ-ha⁠qò̇֔deş̌ wĕ⁠ʼeţ-ʼò֥hel mwòʻé֖d wĕ⁠ʼeţ-ha⁠mi̇zĕbé֑̇ẖa wĕ⁠hiqĕri֖yb ʼeţ-ha⁠şá̇̂ʻi֥yr he⁠ẖáֽy׃"],[16,21,"וְ⁠סָמַ֨ךְ אַהֲרֹ֜ן אֶת־שְׁתֵּ֣י יד⁠ו עַ֨ל רֹ֣אשׁ הַ⁠שָּׂעִיר֮ הַ⁠חַי֒ וְ⁠הִתְוַדָּ֣ה עָלָ֗י⁠ו אֶת־כָּל־עֲוֺנֹת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠אֶת־כָּל־פִּשְׁעֵי⁠הֶ֖ם לְ⁠כָל־חַטֹּאתָ֑⁠ם וְ⁠נָתַ֤ן אֹתָ⁠ם֙ עַל־רֹ֣אשׁ הַ⁠שָּׂעִ֔יר וְ⁠שִׁלַּ֛ח בְּ⁠יַד־אִ֥ישׁ עִתִּ֖י הַ⁠מִּדְבָּֽרָ⁠ה׃","wĕ⁠sáma֨kĕ ʼahàrò֜n ʼeţ-şĕ̌ţé֣̇y yd⁠w ʻa֨l rò֣ʼş̌ ha⁠şá̇̂ʻiyr֮ ha⁠ẖay֒ wĕ⁠hiţĕwadá֣̇h ʻálá֗y⁠w ʼeţ-ká̇l-ʻàwֺnòţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠ʼeţ-ká̇l-pi̇şĕ̌ʻéy⁠he֖m lĕ⁠kál-ẖatò̇ʼţá֑⁠m wĕ⁠náţa֤n ʼòţá⁠m֙ ʻal-rò֣ʼş̌ ha⁠şá̇̂ʻi֔yr wĕ⁠şǐlȧ֛ẖ bĕ̇⁠yad-ʼi֥yş̌ ʻiţi֖̇y ha⁠mi̇dĕbáֽ̇rá⁠h׃"],[16,22,"וְ⁠נָשָׂ֨א הַ⁠שָּׂעִ֥יר עָלָ֛י⁠ו אֶת־כָּל־עֲוֺנֹתָ֖⁠ם אֶל־אֶ֣רֶץ גְּזֵרָ֑ה וְ⁠שִׁלַּ֥ח אֶת־הַ⁠שָּׂעִ֖יר בַּ⁠מִּדְבָּֽר׃","wĕ⁠náşá̂֨ʼ ha⁠şá̇̂ʻi֥yr ʻálá֛y⁠w ʼeţ-ká̇l-ʻàwֺnòţá֖⁠m ʼel-ʼe֣reẕ gĕ̇zérá֑h wĕ⁠şǐlȧ֥ẖ ʼeţ-ha⁠şá̇̂ʻi֖yr bȧ⁠mi̇dĕbáֽ̇r׃"],[16,23,"וּ⁠בָ֤א אַהֲרֹן֙ אֶל־אֹ֣הֶל מוֹעֵ֔ד וּ⁠פָשַׁט֙ אֶת־בִּגְדֵ֣י הַ⁠בָּ֔ד אֲשֶׁ֥ר לָבַ֖שׁ בְּ⁠בֹא֣⁠וֹ אֶל־הַ⁠קֹּ֑דֶשׁ וְ⁠הִנִּיחָ֖⁠ם שָֽׁם׃","ẇ⁠bá֤ʼ ʼahàròn֙ ʼel-ʼò֣hel mwòʻé֔d ẇ⁠páşǎt֙ ʼeţ-bi̇gĕdé֣y ha⁠bá̇֔d ʼàşě֥r lába֖ş̌ bĕ̇⁠bòʼ֣⁠wò ʼel-ha⁠qò֑̇deş̌ wĕ⁠hini̇yẖá֖⁠m şáֽ̌m׃"],[16,24,"וְ⁠רָחַ֨ץ אֶת־בְּשָׂר֤⁠וֹ בַ⁠מַּ֨יִם֙ בְּ⁠מָק֣וֹם קָד֔וֹשׁ וְ⁠לָבַ֖שׁ אֶת־בְּגָדָ֑י⁠ו וְ⁠יָצָ֗א וְ⁠עָשָׂ֤ה אֶת־עֹֽלָת⁠וֹ֙ וְ⁠אֶת־עֹלַ֣ת הָ⁠עָ֔ם וְ⁠כִפֶּ֥ר בַּעֲד֖⁠וֹ וּ⁠בְעַ֥ד הָ⁠עָֽם׃","wĕ⁠ráẖa֨ẕ ʼeţ-bĕ̇şá̂r֤⁠wò ba⁠mȧ֨yim֙ bĕ̇⁠máq֣wòm qád֔wòş̌ wĕ⁠lába֖ş̌ ʼeţ-bĕ̇gádá֑y⁠w wĕ⁠yáẕá֗ʼ wĕ⁠ʻáşá֤̂h ʼeţ-ʻòֽláţ⁠wò֙ wĕ⁠ʼeţ-ʻòla֣ţ há⁠ʻá֔m wĕ⁠kipė֥r bȧʻàd֖⁠wò ẇ⁠bĕʻa֥d há⁠ʻáֽm׃"],[16,25,"וְ⁠אֵ֛ת חֵ֥לֶב הַֽ⁠חַטָּ֖את יַקְטִ֥יר הַ⁠מִּזְבֵּֽחָ⁠ה׃","wĕ⁠ʼé֛ţ ẖé֥leb haֽ⁠ẖatá֖̇ʼţ yaqĕti֥yr ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[16,26,"וְ⁠הַֽ⁠מְשַׁלֵּ֤חַ אֶת־הַ⁠שָּׂעִיר֙ לַֽ⁠עֲזָאזֵ֔ל יְכַבֵּ֣ס בְּגָדָ֔י⁠ו וְ⁠רָחַ֥ץ אֶת־בְּשָׂר֖⁠וֹ בַּ⁠מָּ֑יִם וְ⁠אַחֲרֵי־כֵ֖ן יָב֥וֹא אֶל־הַֽ⁠מַּחֲנֶֽה׃","wĕ⁠haֽ⁠mĕşǎlé֤̇ẖa ʼeţ-ha⁠şá̇̂ʻiyr֙ laֽ⁠ʻàzáʼzé֔l yĕkabé֣̇s bĕ̇gádá֔y⁠w wĕ⁠ráẖa֥ẕ ʼeţ-bĕ̇şá̂r֖⁠wò bȧ⁠má֑̇yim wĕ⁠ʼaẖàréy-ké֖n yáb֥wòʼ ʼel-haֽ⁠mȧẖàneֽh׃"],[16,27,"וְ⁠אֵת֩ פַּ֨ר הַֽ⁠חַטָּ֜את וְ⁠אֵ֣ת ׀ שְׂעִ֣יר הַֽ⁠חַטָּ֗את אֲשֶׁ֨ר הוּבָ֤א אֶת־דָּמָ⁠ם֙ לְ⁠כַפֵּ֣ר בַּ⁠קֹּ֔דֶשׁ יוֹצִ֖יא אֶל־מִ⁠ח֣וּץ לַֽ⁠מַּחֲנֶ֑ה וְ⁠שָׂרְפ֣וּ בָ⁠אֵ֔שׁ אֶת־עֹרֹתָ֥⁠ם וְ⁠אֶת־בְּשָׂרָ֖⁠ם וְ⁠אֶת־פִּרְשָֽׁ⁠ם׃","wĕ⁠ʼéţ֩ pȧ֨r hֽa⁠ẖatá̇֜ʼţ wĕ⁠ʼé֣ţ ׀ şĕ̂ʻi֣yr haֽ⁠ẖatá̇֗ʼţ ʼàşě֨r hẇbá֤ʼ ʼeţ-dá̇má⁠m֙ lĕ⁠kapé֣̇r bȧ⁠qò̇֔deş̌ ywòẕi֖yʼ ʼel-mi⁠ẖ֣ẇẕ laֽ⁠mȧẖàne֑h wĕ⁠şá̂rĕp֣ẇ bá⁠ʼé֔ş̌ ʼeţ-ʻòròţá֥⁠m wĕ⁠ʼeţ-bĕ̇şá̂rá֖⁠m wĕ⁠ʼeţ-pi̇rĕşáֽ̌⁠m׃"],[16,28,"וְ⁠הַ⁠שֹּׂרֵ֣ף אֹתָ֔⁠ם יְכַבֵּ֣ס בְּגָדָ֔י⁠ו וְ⁠רָחַ֥ץ אֶת־בְּשָׂר֖⁠וֹ בַּ⁠מָּ֑יִם וְ⁠אַחֲרֵי־כֵ֖ן יָב֥וֹא אֶל־הַֽ⁠מַּחֲנֶֽה׃","wĕ⁠ha⁠şò̇̂ré֣p ʼòţá֔⁠m yĕkabé֣̇s bĕ̇gádá֔y⁠w wĕ⁠ráẖa֥ẕ ʼeţ-bĕ̇şá̂r֖⁠wò bȧ⁠má֑̇yim wĕ⁠ʼaẖàréy-ké֖n yáb֥wòʼ ʼel-haֽ⁠mȧẖàneֽh׃"],[16,29,"וְ⁠הָיְתָ֥ה לָ⁠כֶ֖ם לְ⁠חֻקַּ֣ת עוֹלָ֑ם בַּ⁠חֹ֣דֶשׁ הַ֠⁠שְּׁבִיעִי בֶּֽ⁠עָשׂ֨וֹר לַ⁠חֹ֜דֶשׁ תְּעַנּ֣וּ אֶת־נַפְשֹֽׁתֵי⁠כֶ֗ם וְ⁠כָל־מְלָאכָה֙ לֹ֣א תַעֲשׂ֔וּ הָֽ⁠אֶזְרָ֔ח וְ⁠הַ⁠גֵּ֖ר הַ⁠גָּ֥ר בְּ⁠תוֹכְ⁠כֶֽם׃","wĕ⁠háyĕţá֥h lá⁠ke֖m lĕ⁠ẖuqȧ֣ţ ʻwòlá֑m bȧ⁠ẖò֣deş̌ ha֠⁠şĕ̇̌biyʻiy bėֽ⁠ʻáş̂֨wòr la⁠ẖò֜deş̌ ţĕ̇ʻaṅ֣ẇ ʼeţ-napĕşòֽ̌ţéy⁠ke֗m wĕ⁠kál-mĕláʼkáh֙ lò֣ʼ ţaʻàş̂֔ẇ háֽ⁠ʼezĕrá֔ẖ wĕ⁠ha⁠gé֖̇r ha⁠gá֥̇r bĕ̇⁠ţwòkĕ⁠keֽm׃"],[16,30,"כִּֽי־בַ⁠יּ֥וֹם הַ⁠זֶּ֛ה יְכַפֵּ֥ר עֲלֵי⁠כֶ֖ם לְ⁠טַהֵ֣ר אֶתְ⁠כֶ֑ם מִ⁠כֹּל֙ חַטֹּ֣אתֵי⁠כֶ֔ם לִ⁠פְנֵ֥י יְהוָ֖ה תִּטְהָֽרוּ׃","kiֽ̇y-ba⁠ẏ֥wòm ha⁠zė֛h yĕkapé֥̇r ʻàléy⁠ke֖m lĕ⁠tahé֣r ʼeţĕ⁠ke֑m mi⁠kò̇l֙ ẖatò֣̇ʼţéy⁠ke֔m li⁠pĕné֥y yĕhwá֖h ţi̇tĕháֽrẇ׃"],[16,31,"שַׁבַּ֨ת שַׁבָּת֥וֹן הִיא֙ לָ⁠כֶ֔ם וְ⁠עִנִּיתֶ֖ם אֶת־נַפְשֹׁתֵי⁠כֶ֑ם חֻקַּ֖ת עוֹלָֽם׃","şǎbȧ֨ţ şǎbá̇ţ֥wòn hiyʼ֙ lá⁠ke֔m wĕ⁠ʻini̇yţe֖m ʼeţ-napĕşò̌ţéy⁠ke֑m ẖuqȧ֖ţ ʻwòláֽm׃"],[16,32,"וְ⁠כִפֶּ֨ר הַ⁠כֹּהֵ֜ן אֲשֶׁר־יִמְשַׁ֣ח אֹת֗⁠וֹ וַ⁠אֲשֶׁ֤ר יְמַלֵּא֙ אֶת־יָד֔⁠וֹ לְ⁠כַהֵ֖ן תַּ֣חַת אָבִ֑י⁠ו וְ⁠לָבַ֛שׁ אֶת־בִּגְדֵ֥י הַ⁠בָּ֖ד בִּגְדֵ֥י הַ⁠קֹּֽדֶשׁ׃","wĕ⁠kipė֨r ha⁠kò̇hé֜n ʼàşěr-yimĕşǎ֣ẖ ʼòţ֗⁠wò wa⁠ʼàşě֤r yĕmalé̇ʼ֙ ʼeţ-yád֔⁠wò lĕ⁠kahé֖n ţȧ֣ẖaţ ʼábi֑y⁠w wĕ⁠lába֛ş̌ ʼeţ-bi̇gĕdé֥y ha⁠bá֖̇d bi̇gĕdé֥y ha⁠qòֽ̇deş̌׃"],[16,33,"וְ⁠כִפֶּר֙ אֶת־מִקְדַּ֣שׁ הַ⁠קֹּ֔דֶשׁ וְ⁠אֶת־אֹ֧הֶל מוֹעֵ֛ד וְ⁠אֶת־הַ⁠מִּזְבֵּ֖חַ יְכַפֵּ֑ר וְ⁠עַ֧ל הַ⁠כֹּהֲנִ֛ים וְ⁠עַל־כָּל־עַ֥ם הַ⁠קָּהָ֖ל יְכַפֵּֽר׃","wĕ⁠kipėr֙ ʼeţ-miqĕdȧ֣ş̌ ha⁠qò̇֔deş̌ wĕ⁠ʼeţ-ʼò֧hel mwòʻé֛d wĕ⁠ʼeţ-ha⁠mi̇zĕbé֖̇ẖa yĕkapé֑̇r wĕ⁠ʻa֧l ha⁠kò̇hàni֛ym wĕ⁠ʻal-ká̇l-ʻa֥m ha⁠qá̇há֖l yĕkapéֽ̇r׃"],[16,34,"וְ⁠הָֽיְתָה־זֹּ֨את לָ⁠כֶ֜ם לְ⁠חֻקַּ֣ת עוֹלָ֗ם לְ⁠כַפֵּ֞ר עַל־בְּנֵ֤י יִשְׂרָאֵל֙ מִ⁠כָּל־חַטֹּאתָ֔⁠ם אַחַ֖ת בַּ⁠שָּׁנָ֑ה וַ⁠יַּ֕עַשׂ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃פ","wĕ⁠háֽyĕţáh-zò̇֨ʼţ lá⁠ke֜m lĕ⁠ẖuqȧ֣ţ ʻwòlá֗m lĕ⁠kapé̇֞r ʻal-bĕ̇né֤y yişĕ̂ráʼél֙ mi⁠ká̇l-ẖatò̇ʼţá֔⁠m ʼaẖa֖ţ bȧ⁠şá̇̌ná֑h wa⁠yȧ֕ʻaş̂ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃p"],[17,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[17,2,"דַּבֵּ֨ר אֶֽל־אַהֲרֹ֜ן וְ⁠אֶל־בָּנָ֗י⁠ו וְ⁠אֶל֙ כָּל־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠אָמַרְתָּ֖ אֲלֵי⁠הֶ֑ם זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה לֵ⁠אמֹֽר׃","dȧbé̇֨r ʼeֽl-ʼahàrò֜n wĕ⁠ʼel-bá̇ná֗y⁠w wĕ⁠ʼel֙ ká̇l-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠ʼámarĕţá֖̇ ʼàléy⁠he֑m ze֣h ha⁠dá̇bá֔r ʼàşěr-ẕiwá֥̇h yĕhwá֖h lé⁠ʼmòֽr׃"],[17,3,"אִ֥ישׁ אִישׁ֙ מִ⁠בֵּ֣ית יִשְׂרָאֵ֔ל אֲשֶׁ֨ר יִשְׁחַ֜ט שׁ֥וֹר אוֹ־כֶ֛שֶׂב אוֹ־עֵ֖ז בַּֽ⁠מַּחֲנֶ֑ה א֚וֹ אֲשֶׁ֣ר יִשְׁחַ֔ט מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶֽה׃","ʼi֥yş̌ ʼiyş̌֙ mi⁠bé֣̇yţ yişĕ̂ráʼé֔l ʼàşě֨r yişĕ̌ẖa֜t ş֥̌wòr ʼwò-ke֛şêb ʼwò-ʻé֖z bȧֽ⁠mȧẖàne֑h ʼ֚wò ʼàşě֣r yişĕ̌ẖa֔t mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàneֽh׃"],[17,4,"וְ⁠אֶל־פֶּ֜תַח אֹ֣הֶל מוֹעֵד֮ לֹ֣א הֱבִיא⁠וֹ֒ לְ⁠הַקְרִ֤יב קָרְבָּן֙ לַֽ⁠יהוָ֔ה לִ⁠פְנֵ֖י מִשְׁכַּ֣ן יְהוָ֑ה דָּ֣ם יֵחָשֵׁ֞ב לָ⁠אִ֤ישׁ הַ⁠הוּא֙ דָּ֣ם שָׁפָ֔ךְ וְ⁠נִכְרַ֛ת הָ⁠אִ֥ישׁ הַ⁠ה֖וּא מִ⁠קֶּ֥רֶב עַמּֽ⁠וֹ׃","wĕ⁠ʼel-pė֜ţaẖ ʼò֣hel mwòʻéd֮ lò֣ʼ hèbiyʼ⁠wò֒ lĕ⁠haqĕri֤yb qárĕbá̇n֙ laֽ⁠yhwá֔h li⁠pĕné֖y mişĕ̌kȧ֣n yĕhwá֑h dá֣̇m yéẖáşé̌֞b lá⁠ʼi֤yş̌ ha⁠hẇʼ֙ dá֣̇m şá̌pá֔kĕ wĕ⁠nikĕra֛ţ há⁠ʼi֥yş̌ ha⁠h֖ẇʼ mi⁠qė֥reb ʻaṁֽ⁠wò׃"],[17,5,"לְמַעַן֩ אֲשֶׁ֨ר יָבִ֜יאוּ בְּנֵ֣י יִשְׂרָאֵ֗ל אֶֽת־זִבְחֵי⁠הֶם֮ אֲשֶׁ֣ר הֵ֣ם זֹבְחִים֮ עַל־פְּנֵ֣י הַ⁠שָּׂדֶה֒ וֶֽ⁠הֱבִיאֻ֣⁠ם לַֽ⁠יהוָ֗ה אֶל־פֶּ֛תַח אֹ֥הֶל מוֹעֵ֖ד אֶל־הַ⁠כֹּהֵ֑ן וְ⁠זָ֨בְח֜וּ זִבְחֵ֧י שְׁלָמִ֛ים לַֽ⁠יהוָ֖ה אוֹתָֽ⁠ם׃","lĕmaʻan֩ ʼàşě֨r yábi֜yʼẇ bĕ̇né֣y yişĕ̂ráʼé֗l ʼeֽţ-zibĕẖéy⁠hem֮ ʼàşě֣r hé֣m zòbĕẖiym֮ ʻal-pĕ̇né֣y ha⁠şá̇̂deh֒ wֽe⁠hèbiyʼu֣⁠m laֽ⁠yhwá֗h ʼel-pė֛ţaẖ ʼò֥hel mwòʻé֖d ʼel-ha⁠kò̇hé֑n wĕ⁠zá֨bĕẖ֜ẇ zibĕẖé֧y şĕ̌lámi֛ym laֽ⁠yhwá֖h ʼwòţáֽ⁠m׃"],[17,6,"וְ⁠זָרַ֨ק הַ⁠כֹּהֵ֤ן אֶת־הַ⁠דָּם֙ עַל־מִזְבַּ֣ח יְהוָ֔ה פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד וְ⁠הִקְטִ֣יר הַ⁠חֵ֔לֶב לְ⁠רֵ֥יחַ נִיחֹ֖חַ לַ⁠יהוָֽה׃","wĕ⁠zára֨q ha⁠kò̇hé֤n ʼeţ-ha⁠dá̇m֙ ʻal-mizĕbȧ֣ẖ yĕhwá֔h pė֖ţaẖ ʼò֣hel mwòʻé֑d wĕ⁠hiqĕti֣yr ha⁠ẖé֔leb lĕ⁠ré֥yẖa niyẖò֖ẖa la⁠yhwáֽh׃"],[17,7,"וְ⁠לֹא־יִזְבְּח֥וּ עוֹד֙ אֶת־זִבְחֵי⁠הֶ֔ם לַ⁠שְּׂעִירִ֕ם אֲשֶׁ֛ר הֵ֥ם זֹנִ֖ים אַחֲרֵי⁠הֶ֑ם חֻקַּ֥ת עוֹלָ֛ם תִּֽהְיֶה־זֹּ֥את לָ⁠הֶ֖ם לְ⁠דֹרֹתָֽ⁠ם׃","wĕ⁠lòʼ-yizĕbĕ̇ẖ֥ẇ ʻwòd֙ ʼeţ-zibĕẖéy⁠he֔m la⁠şĕ̇̂ʻiyri֕m ʼàşě֛r hé֥m zòni֖ym ʼaẖàréy⁠he֑m ẖuqȧ֥ţ ʻwòlá֛m ţiֽ̇hĕyeh-zò֥̇ʼţ lá⁠he֖m lĕ⁠dòròţáֽ⁠m׃"],[17,8,"וַ⁠אֲלֵ⁠הֶ֣ם תֹּאמַ֔ר אִ֥ישׁ אִישׁ֙ מִ⁠בֵּ֣ית יִשְׂרָאֵ֔ל וּ⁠מִן־הַ⁠גֵּ֖ר אֲשֶׁר־יָג֣וּר בְּ⁠תוֹכָ֑⁠ם אֲשֶׁר־יַעֲלֶ֥ה עֹלָ֖ה אוֹ־זָֽבַח׃","wa⁠ʼàlé⁠he֣m ţò̇ʼma֔r ʼi֥yş̌ ʼiyş̌֙ mi⁠bé֣̇yţ yişĕ̂ráʼé֔l ẇ⁠min-ha⁠gé֖̇r ʼàşěr-yág֣ẇr bĕ̇⁠ţwòká֑⁠m ʼàşěr-yaʻàle֥h ʻòlá֖h ʼwò-záֽbaẖ׃"],[17,9,"וְ⁠אֶל־פֶּ֜תַח אֹ֤הֶל מוֹעֵד֙ לֹ֣א יְבִיאֶ֔⁠נּוּ לַ⁠עֲשׂ֥וֹת אֹת֖⁠וֹ לַ⁠יהוָ֑ה וְ⁠נִכְרַ֛ת הָ⁠אִ֥ישׁ הַ⁠ה֖וּא מֵ⁠עַמָּֽי⁠ו׃","wĕ⁠ʼel-pė֜ţaẖ ʼò֤hel mwòʻéd֙ lò֣ʼ yĕbiyʼe֔⁠ṅẇ la⁠ʻàş֥̂wòţ ʼòţ֖⁠wò la⁠yhwá֑h wĕ⁠nikĕra֛ţ há⁠ʼi֥yş̌ ha⁠h֖ẇʼ mé⁠ʻamáֽ̇y⁠w׃"],[17,10,"וְ⁠אִ֨ישׁ אִ֜ישׁ מִ⁠בֵּ֣ית יִשְׂרָאֵ֗ל וּ⁠מִן־הַ⁠גֵּר֙ הַ⁠גָּ֣ר בְּ⁠תוֹכָ֔⁠ם אֲשֶׁ֥ר יֹאכַ֖ל כָּל־דָּ֑ם וְ⁠נָתַתִּ֣י פָנַ֗⁠י בַּ⁠נֶּ֨פֶשׁ֙ הָ⁠אֹכֶ֣לֶת אֶת־הַ⁠דָּ֔ם וְ⁠הִכְרַתִּ֥י אֹתָ֖⁠הּ מִ⁠קֶּ֥רֶב עַמָּֽ⁠הּ׃","wĕ⁠ʼi֨yş̌ ʼi֜yş̌ mi⁠bé֣̇yţ yişĕ̂ráʼé֗l ẇ⁠min-ha⁠gé̇r֙ ha⁠gá֣̇r bĕ̇⁠ţwòká֔⁠m ʼàşě֥r yòʼka֖l ká̇l-dá֑̇m wĕ⁠náţaţi֣̇y pána֗⁠y bȧ⁠nė֨peş̌֙ há⁠ʼòke֣leţ ʼeţ-ha⁠dá̇֔m wĕ⁠hikĕraţi֥̇y ʼòţá֖⁠ḣ mi⁠qė֥reb ʻamáֽ̇⁠ḣ׃"],[17,11,"כִּ֣י נֶ֣פֶשׁ הַ⁠בָּשָׂר֮ בַּ⁠דָּ֣ם הִוא֒ וַ⁠אֲנִ֞י נְתַתִּ֤י⁠ו לָ⁠כֶם֙ עַל־הַ⁠מִּזְבֵּ֔חַ לְ⁠כַפֵּ֖ר עַל־נַפְשֹׁתֵי⁠כֶ֑ם כִּֽי־הַ⁠דָּ֥ם ה֖וּא בַּ⁠נֶּ֥פֶשׁ יְכַפֵּֽר׃","ki֣̇y ne֣peş̌ ha⁠bá̇şá̂r֮ bȧ⁠dá֣̇m hiwʼ֒ wa⁠ʼàni֞y nĕţaţi֤̇y⁠w lá⁠kem֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa lĕ⁠kapé֖̇r ʻal-napĕşò̌ţéy⁠ke֑m kiֽ̇y-ha⁠dá֥̇m h֖ẇʼ bȧ⁠nė֥peş̌ yĕkapéֽ̇r׃"],[17,12,"עַל־כֵּ֤ן אָמַ֨רְתִּי֙ לִ⁠בְנֵ֣י יִשְׂרָאֵ֔ל כָּל־נֶ֥פֶשׁ מִ⁠כֶּ֖ם לֹא־תֹ֣אכַל דָּ֑ם וְ⁠הַ⁠גֵּ֛ר הַ⁠גָּ֥ר בְּ⁠תוֹכְ⁠כֶ֖ם לֹא־יֹ֥אכַל דָּֽם׃ס","ʻal-ké֤̇n ʼáma֨rĕţi̇y֙ li⁠bĕné֣y yişĕ̂ráʼé֔l ká̇l-ne֥peş̌ mi⁠kė֖m lòʼ-ţò֣ʼkal dá֑̇m wĕ⁠ha⁠gé֛̇r ha⁠gá֥̇r bĕ̇⁠ţwòkĕ⁠ke֖m lòʼ-yò֥ʼkal dáֽ̇m׃s"],[17,13,"וְ⁠אִ֨ישׁ אִ֜ישׁ מִ⁠בְּנֵ֣י יִשְׂרָאֵ֗ל וּ⁠מִן־הַ⁠גֵּר֙ הַ⁠גָּ֣ר בְּ⁠תוֹכָ֔⁠ם אֲשֶׁ֨ר יָצ֜וּד צֵ֥יד חַיָּ֛ה אוֹ־ע֖וֹף אֲשֶׁ֣ר יֵאָכֵ֑ל וְ⁠שָׁפַךְ֙ אֶת־דָּמ֔⁠וֹ וְ⁠כִסָּ֖⁠הוּ בֶּ⁠עָפָֽר׃","wĕ⁠ʼi֨yş̌ ʼi֜yş̌ mi⁠bĕ̇né֣y yişĕ̂ráʼé֗l ẇ⁠min-ha⁠gé̇r֙ ha⁠gá֣̇r bĕ̇⁠ţwòká֔⁠m ʼàşě֨r yáẕ֜ẇd ẕé֥yd ẖayá֛̇h ʼwò-ʻ֖wòp ʼàşě֣r yéʼáké֑l wĕ⁠şá̌pakĕ֙ ʼeţ-dá̇m֔⁠wò wĕ⁠kisá֖̇⁠hẇ bė⁠ʻápáֽr׃"],[17,14,"כִּֽי־נֶ֣פֶשׁ כָּל־בָּשָׂ֗ר דָּמ֣⁠וֹ בְ⁠נַפְשׁ⁠וֹ֮ הוּא֒ וָֽ⁠אֹמַר֙ לִ⁠בְנֵ֣י יִשְׂרָאֵ֔ל דַּ֥ם כָּל־בָּשָׂ֖ר לֹ֣א תֹאכֵ֑לוּ כִּ֣י נֶ֤פֶשׁ כָּל־בָּשָׂר֙ דָּמ֣⁠וֹ הִ֔וא כָּל־אֹכְלָ֖י⁠ו יִכָּרֵֽת׃","kiֽ̇y-ne֣peş̌ ká̇l-bá̇şá̂֗r dá̇m֣⁠wò bĕ⁠napĕş̌⁠wò֮ hẇʼ֒ wáֽ⁠ʼòmar֙ li⁠bĕné֣y yişĕ̂ráʼé֔l dȧ֥m ká̇l-bá̇şá֖̂r lò֣ʼ ţòʼké֑lẇ ki֣̇y ne֤peş̌ ká̇l-bá̇şá̂r֙ dá̇m֣⁠wò hi֔wʼ ká̇l-ʼòkĕlá֖y⁠w yiká̇réֽţ׃"],[17,15,"וְ⁠כָל־נֶ֗פֶשׁ אֲשֶׁ֨ר תֹּאכַ֤ל נְבֵלָה֙ וּ⁠טְרֵפָ֔ה בָּ⁠אֶזְרָ֖ח וּ⁠בַ⁠גֵּ֑ר וְ⁠כִבֶּ֨ס בְּגָדָ֜י⁠ו וְ⁠רָחַ֥ץ בַּ⁠מַּ֛יִם וְ⁠טָמֵ֥א עַד־הָ⁠עֶ֖רֶב וְ⁠טָהֵֽר׃","wĕ⁠kál-ne֗peş̌ ʼàşě֨r ţò̇ʼka֤l nĕbéláh֙ ẇ⁠tĕrépá֔h bá̇⁠ʼezĕrá֖ẖ ẇ⁠ba⁠gé֑̇r wĕ⁠kibė֨s bĕ̇gádá֜y⁠w wĕ⁠ráẖa֥ẕ bȧ⁠mȧ֛yim wĕ⁠támé֥ʼ ʻad-há⁠ʻe֖reb wĕ⁠táhéֽr׃"],[17,16,"וְ⁠אִם֙ לֹ֣א יְכַבֵּ֔ס וּ⁠בְשָׂר֖⁠וֹ לֹ֣א יִרְחָ֑ץ וְ⁠נָשָׂ֖א עֲוֺנֽ⁠וֹ׃פ","wĕ⁠ʼim֙ lò֣ʼ yĕkabé̇֔s ẇ⁠bĕşá̂r֖⁠wò lò֣ʼ yirĕẖá֑ẕ wĕ⁠náşá֖̂ʼ ʻàwֺnֽ⁠wò׃p"],[18,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[18,2,"דַּבֵּר֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠אָמַרְתָּ֖ אֲלֵ⁠הֶ֑ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","dȧbé̇r֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠ʼámarĕţá֖̇ ʼàlé⁠he֑m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[18,3,"כְּ⁠מַעֲשֵׂ֧ה אֶֽרֶץ־מִצְרַ֛יִם אֲשֶׁ֥ר יְשַׁבְתֶּם־בָּ֖⁠הּ לֹ֣א תַעֲשׂ֑וּ וּ⁠כְ⁠מַעֲשֵׂ֣ה אֶֽרֶץ־כְּנַ֡עַן אֲשֶׁ֣ר אֲנִי֩ מֵבִ֨יא אֶתְ⁠כֶ֥ם שָׁ֨מָּ⁠ה֙ לֹ֣א תַעֲשׂ֔וּ וּ⁠בְ⁠חֻקֹּתֵי⁠הֶ֖ם לֹ֥א תֵלֵֽכוּ׃","kĕ̇⁠maʻàşé֧̂h ʼeֽreẕ-miẕĕra֛yim ʼàşě֥r yĕşǎbĕţėm-bá֖̇⁠ḣ lò֣ʼ ţaʻàş֑̂ẇ ẇ⁠kĕ⁠maʻàşé֣̂h ʼeֽreẕ-kĕ̇na֡ʻan ʼàşě֣r ʼàniy֩ mébi֨yʼ ʼeţĕ⁠ke֥m şá̌֨má̇⁠h֙ lò֣ʼ ţaʻàş̂֔ẇ ẇ⁠bĕ⁠ẖuqò̇ţéy⁠he֖m lò֥ʼ ţéléֽkẇ׃"],[18,4,"אֶת־מִשְׁפָּטַ֧⁠י תַּעֲשׂ֛וּ וְ⁠אֶת־חֻקֹּתַ֥⁠י תִּשְׁמְר֖וּ לָ⁠לֶ֣כֶת בָּ⁠הֶ֑ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ʼeţ-mişĕ̌pá̇ta֧⁠y ţȧʻàş֛̂ẇ wĕ⁠ʼeţ-ẖuqò̇ţa֥⁠y ţi̇şĕ̌mĕr֖ẇ lá⁠le֣keţ bá̇⁠he֑m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[18,5,"וּ⁠שְׁמַרְתֶּ֤ם אֶת־חֻקֹּתַ⁠י֙ וְ⁠אֶת־מִשְׁפָּטַ֔⁠י אֲשֶׁ֨ר יַעֲשֶׂ֥ה אֹתָ֛⁠ם הָ⁠אָדָ֖ם וָ⁠חַ֣י בָּ⁠הֶ֑ם אֲנִ֖י יְהוָֽה׃ס","ẇ⁠şĕ̌marĕţė֤m ʼeţ-ẖuqò̇ţa⁠y֙ wĕ⁠ʼeţ-mişĕ̌pá̇ta֔⁠y ʼàşě֨r yaʻàşê֥h ʼòţá֛⁠m há⁠ʼádá֖m wá⁠ẖa֣y bá̇⁠he֑m ʼàni֖y yĕhwáֽh׃s"],[18,6,"אִ֥ישׁ אִישׁ֙ אֶל־כָּל־שְׁאֵ֣ר בְּשָׂר֔⁠וֹ לֹ֥א תִקְרְב֖וּ לְ⁠גַלּ֣וֹת עֶרְוָ֑ה אֲנִ֖י יְהוָֽה׃ס","ʼi֥yş̌ ʼiyş̌֙ ʼel-ká̇l-şĕ̌ʼé֣r bĕ̇şá̂r֔⁠wò lò֥ʼ ţiqĕrĕb֖ẇ lĕ⁠gal֣̇wòţ ʻerĕwá֑h ʼàni֖y yĕhwáֽh׃s"],[18,7,"עֶרְוַ֥ת אָבִ֛י⁠ךָ וְ⁠עֶרְוַ֥ת אִמְּ⁠ךָ֖ לֹ֣א תְגַלֵּ֑ה אִמְּ⁠ךָ֣ הִ֔וא לֹ֥א תְגַלֶּ֖ה עֶרְוָתָֽ⁠הּ׃ס","ʻerĕwa֥ţ ʼábi֛y⁠ká wĕ⁠ʻerĕwa֥ţ ʼimĕ̇⁠ká֖ lò֣ʼ ţĕgalé֑̇h ʼimĕ̇⁠ká֣ hi֔wʼ lò֥ʼ ţĕgalė֖h ʻerĕwáţáֽ⁠ḣ׃s"],[18,8,"עֶרְוַ֥ת אֵֽשֶׁת־אָבִ֖י⁠ךָ לֹ֣א תְגַלֵּ֑ה עֶרְוַ֥ת אָבִ֖י⁠ךָ הִֽוא׃ס","ʻerĕwa֥ţ ʼéֽşěţ-ʼábi֖y⁠ká lò֣ʼ ţĕgalé֑̇h ʻerĕwa֥ţ ʼábi֖y⁠ká hiֽwʼ׃s"],[18,9,"עֶרְוַ֨ת אֲחֽוֹתְ⁠ךָ֤ בַת־אָבִ֨י⁠ךָ֙ א֣וֹ בַת־אִמֶּ֔⁠ךָ מוֹלֶ֣דֶת בַּ֔יִת א֖וֹ מוֹלֶ֣דֶת ח֑וּץ לֹ֥א תְגַלֶּ֖ה עֶרְוָתָֽ⁠ן׃ס","ʻerĕwa֨ţ ʼàẖֽwòţĕ⁠ká֤ baţ-ʼábi֨y⁠ká֙ ʼ֣wò baţ-ʼimė֔⁠ká mwòle֣deţ bȧ֔yiţ ʼ֖wò mwòle֣deţ ẖ֑ẇẕ lò֥ʼ ţĕgalė֖h ʻerĕwáţáֽ⁠n׃s"],[18,10,"עֶרְוַ֤ת בַּת־בִּנְ⁠ךָ֙ א֣וֹ בַֽת־בִּתְּ⁠ךָ֔ לֹ֥א תְגַלֶּ֖ה עֶרְוָתָ֑⁠ן כִּ֥י עֶרְוָתְ⁠ךָ֖ הֵֽנָּה׃ס","ʻerĕwa֤ţ bȧţ-bi̇nĕ⁠ká֙ ʼ֣wò baֽţ-bi̇ţĕ̇⁠ká֔ lò֥ʼ ţĕgalė֖h ʻerĕwáţá֑⁠n ki֥̇y ʻerĕwáţĕ⁠ká֖ héֽná̇h׃s"],[18,11,"עֶרְוַ֨ת בַּת־אֵ֤שֶׁת אָבִ֨י⁠ךָ֙ מוֹלֶ֣דֶת אָבִ֔י⁠ךָ אֲחוֹתְ⁠ךָ֖ הִ֑וא לֹ֥א תְגַלֶּ֖ה עֶרְוָתָֽ⁠הּ׃ס","ʻerĕwa֨ţ bȧţ-ʼé֤şěţ ʼábi֨y⁠ká֙ mwòle֣deţ ʼábi֔y⁠ká ʼàẖwòţĕ⁠ká֖ hi֑wʼ lò֥ʼ ţĕgalė֖h ʻerĕwáţáֽ⁠ḣ׃s"],[18,12,"עֶרְוַ֥ת אֲחוֹת־אָבִ֖י⁠ךָ לֹ֣א תְגַלֵּ֑ה שְׁאֵ֥ר אָבִ֖י⁠ךָ הִֽוא׃ס","ʻerĕwa֥ţ ʼàẖwòţ-ʼábi֖y⁠ká lò֣ʼ ţĕgalé֑̇h şĕ̌ʼé֥r ʼábi֖y⁠ká hiֽwʼ׃s"],[18,13,"עֶרְוַ֥ת אֲחֽוֹת־אִמְּ⁠ךָ֖ לֹ֣א תְגַלֵּ֑ה כִּֽי־שְׁאֵ֥ר אִמְּ⁠ךָ֖ הִֽוא׃ס","ʻerĕwa֥ţ ʼàẖֽwòţ-ʼimĕ̇⁠ká֖ lò֣ʼ ţĕgalé֑̇h kiֽ̇y-şĕ̌ʼé֥r ʼimĕ̇⁠ká֖ hiֽwʼ׃s"],[18,14,"עֶרְוַ֥ת אֲחִֽי־אָבִ֖י⁠ךָ לֹ֣א תְגַלֵּ֑ה אֶל־אִשְׁתּ⁠וֹ֙ לֹ֣א תִקְרָ֔ב דֹּדָֽתְ⁠ךָ֖ הִֽוא׃ס","ʻerĕwa֥ţ ʼàẖiֽy-ʼábi֖y⁠ká lò֣ʼ ţĕgalé֑̇h ʼel-ʼişĕ̌ţ̇⁠wò֙ lò֣ʼ ţiqĕrá֔b dò̇dáֽţĕ⁠ká֖ hiֽwʼ׃s"],[18,15,"עֶרְוַ֥ת כַּלָּֽתְ⁠ךָ֖ לֹ֣א תְגַלֵּ֑ה אֵ֤שֶׁת בִּנְ⁠ךָ֙ הִ֔וא לֹ֥א תְגַלֶּ֖ה עֶרְוָתָֽ⁠הּ׃ס","ʻerĕwa֥ţ kȧláֽ̇ţĕ⁠ká֖ lò֣ʼ ţĕgalé֑̇h ʼé֤şěţ bi̇nĕ⁠ká֙ hi֔wʼ lò֥ʼ ţĕgalė֖h ʻerĕwáţáֽ⁠ḣ׃s"],[18,16,"עֶרְוַ֥ת אֵֽשֶׁת־אָחִ֖י⁠ךָ לֹ֣א תְגַלֵּ֑ה עֶרְוַ֥ת אָחִ֖י⁠ךָ הִֽוא׃ס","ʻerĕwa֥ţ ʼéֽşěţ-ʼáẖi֖y⁠ká lò֣ʼ ţĕgalé֑̇h ʻerĕwa֥ţ ʼáẖi֖y⁠ká hiֽwʼ׃s"],[18,17,"עֶרְוַ֥ת אִשָּׁ֛ה וּ⁠בִתָּ֖⁠הּ לֹ֣א תְגַלֵּ֑ה אֶֽת־בַּת־בְּנָ֞⁠הּ וְ⁠אֶת־בַּת־בִּתָּ֗⁠הּ לֹ֤א תִקַּח֙ לְ⁠גַלּ֣וֹת עֶרְוָתָ֔⁠הּ שַׁאֲרָ֥ה הֵ֖נָּה זִמָּ֥ה הִֽוא","ʻerĕwa֥ţ ʼişá֛̇̌h ẇ⁠biţá֖̇⁠ḣ lò֣ʼ ţĕgalé֑̇h ʼeֽţ-bȧţ-bĕ̇ná֞⁠ḣ wĕ⁠ʼeţ-bȧţ-bi̇ţá̇֗⁠ḣ lò֤ʼ ţiqȧẖ֙ lĕ⁠gal֣̇wòţ ʻerĕwáţá֔⁠ḣ şǎʼàrá֥h hé֖ná̇h zimá֥̇h hiֽwʼ"],[18,18,"וְ⁠אִשָּׁ֥ה אֶל־אֲחֹתָ֖⁠הּ לֹ֣א תִקָּ֑ח לִ⁠צְרֹ֗ר לְ⁠גַלּ֧וֹת עֶרְוָתָ֛⁠הּ עָלֶ֖י⁠הָ בְּ⁠חַיֶּֽי⁠הָ׃","wĕ⁠ʼişá֥̇̌h ʼel-ʼàẖòţá֖⁠ḣ lò֣ʼ ţiqá֑̇ẖ li⁠ẕĕrò֗r lĕ⁠gal֧̇wòţ ʻerĕwáţá֛⁠ḣ ʻále֖y⁠há bĕ̇⁠ẖayėֽy⁠há׃"],[18,19,"וְ⁠אֶל־אִשָּׁ֖ה בְּ⁠נִדַּ֣ת טֻמְאָתָ֑⁠הּ לֹ֣א תִקְרַ֔ב לְ⁠גַלּ֖וֹת עֶרְוָתָֽ⁠הּ׃","wĕ⁠ʼel-ʼişá֖̇̌h bĕ̇⁠nidȧ֣ţ tumĕʼáţá֑⁠ḣ lò֣ʼ ţiqĕra֔b lĕ⁠gal֖̇wòţ ʻerĕwáţáֽ⁠ḣ׃"],[18,20,"וְ⁠אֶל־אֵ֨שֶׁת֙ עֲמִֽיתְ⁠ךָ֔ לֹא־תִתֵּ֥ן שְׁכָבְתְּ⁠ךָ֖ לְ⁠זָ֑רַע לְ⁠טָמְאָה־בָֽ⁠הּ׃","wĕ⁠ʼel-ʼé֨şěţ֙ ʻàmiֽyţĕ⁠ká֔ lòʼ-ţiţé֥̇n şĕ̌kábĕţĕ̇⁠ká֖ lĕ⁠zá֑raʻ lĕ⁠támĕʼáh-báֽ⁠ḣ׃"],[18,21,"וּ⁠מִֽ⁠זַּרְעֲ⁠ךָ֥ לֹא־תִתֵּ֖ן לְ⁠הַעֲבִ֣יר לַ⁠מֹּ֑לֶךְ וְ⁠לֹ֧א תְחַלֵּ֛ל אֶת־שֵׁ֥ם אֱלֹהֶ֖י⁠ךָ אֲנִ֥י יְהוָֽה׃","ẇ⁠miֽ⁠zȧrĕʻà⁠ká֥ lòʼ-ţiţé֖̇n lĕ⁠haʻàbi֣yr la⁠mò֑̇lekĕ wĕ⁠lò֧ʼ ţĕẖalé֛̇l ʼeţ-şé֥̌m ʼèlòhe֖y⁠ká ʼàni֥y yĕhwáֽh׃"],[18,22,"וְ⁠אֶ֨ת־זָכָ֔ר לֹ֥א תִשְׁכַּ֖ב מִשְׁכְּבֵ֣י אִשָּׁ֑ה תּוֹעֵבָ֖ה הִֽוא׃","wĕ⁠ʼe֨ţ-záká֔r lò֥ʼ ţişĕ̌kȧ֖b mişĕ̌kĕ̇bé֣y ʼişá֑̇̌h ţ̇wòʻébá֖h hiֽwʼ׃"],[18,23,"וּ⁠בְ⁠כָל־בְּהֵמָ֛ה לֹא־תִתֵּ֥ן שְׁכָבְתְּ⁠ךָ֖ לְ⁠טָמְאָה־בָ֑⁠הּ וְ⁠אִשָּׁ֗ה לֹֽא־תַעֲמֹ֞ד לִ⁠פְנֵ֧י בְהֵמָ֛ה לְ⁠רִבְעָ֖⁠הּ תֶּ֥בֶל הֽוּא׃","ẇ⁠bĕ⁠kál-bĕ̇hémá֛h lòʼ-ţiţé֥̇n şĕ̌kábĕţĕ̇⁠ká֖ lĕ⁠támĕʼáh-bá֑⁠ḣ wĕ⁠ʼişá̇̌֗h lòֽʼ-ţaʻàmò֞d li⁠pĕné֧y bĕhémá֛h lĕ⁠ribĕʻá֖⁠ḣ ţė֥bel hֽẇʼ׃"],[18,24,"אַל־תִּֽטַּמְּא֖וּ בְּ⁠כָל־אֵ֑לֶּה כִּ֤י בְ⁠כָל־אֵ֨לֶּה֙ נִטְמְא֣וּ הַ⁠גּוֹיִ֔ם אֲשֶׁר־אֲנִ֥י מְשַׁלֵּ֖חַ מִ⁠פְּנֵי⁠כֶֽם׃","ʼal-ţiֽ̇tȧmĕ̇ʼ֖ẇ bĕ̇⁠kál-ʼé֑lėh ki֤̇y bĕ⁠kál-ʼé֨lėh֙ nitĕmĕʼ֣ẇ ha⁠ġwòyi֔m ʼàşěr-ʼàni֥y mĕşǎlé֖̇ẖa mi⁠pĕ̇néy⁠keֽm׃"],[18,25,"וַ⁠תִּטְמָ֣א הָ⁠אָ֔רֶץ וָ⁠אֶפְקֹ֥ד עֲוֺנָ֖⁠הּ עָלֶ֑י⁠הָ וַ⁠תָּקִ֥א הָ⁠אָ֖רֶץ אֶת־יֹשְׁבֶֽי⁠הָ׃","wa⁠ţi̇tĕmá֣ʼ há⁠ʼá֔reẕ wá⁠ʼepĕqò֥d ʻàwֺná֖⁠ḣ ʻále֑y⁠há wa⁠ţá̇qi֥ʼ há⁠ʼá֖reẕ ʼeţ-yòşĕ̌beֽy⁠há׃"],[18,26,"וּ⁠שְׁמַרְתֶּ֣ם אַתֶּ֗ם אֶת־חֻקֹּתַ⁠י֙ וְ⁠אֶת־מִשְׁפָּטַ֔⁠י וְ⁠לֹ֣א תַעֲשׂ֔וּ מִ⁠כֹּ֥ל הַ⁠תּוֹעֵבֹ֖ת הָ⁠אֵ֑לֶּה הָֽ⁠אֶזְרָ֔ח וְ⁠הַ⁠גֵּ֖ר הַ⁠גָּ֥ר בְּ⁠תוֹכְ⁠כֶֽם׃","ẇ⁠şĕ̌marĕţė֣m ʼaţė֗m ʼeţ-ẖuqò̇ţa⁠y֙ wĕ⁠ʼeţ-mişĕ̌pá̇ta֔⁠y wĕ⁠lò֣ʼ ţaʻàş̂֔ẇ mi⁠kò֥̇l ha⁠ţ̇wòʻébò֖ţ há⁠ʼé֑lėh háֽ⁠ʼezĕrá֔ẖ wĕ⁠ha⁠gé֖̇r ha⁠gá֥̇r bĕ̇⁠ţwòkĕ⁠keֽm׃"],[18,27,"כִּ֚י אֶת־כָּל־הַ⁠תּוֹעֵבֹ֣ת הָ⁠אֵ֔ל עָשׂ֥וּ אַנְשֵֽׁי־הָ⁠אָ֖רֶץ אֲשֶׁ֣ר לִ⁠פְנֵי⁠כֶ֑ם וַ⁠תִּטְמָ֖א הָ⁠אָֽרֶץ׃","ki֚̇y ʼeţ-ká̇l-ha⁠ţ̇wòʻébò֣ţ há⁠ʼé֔l ʻáş֥̂ẇ ʼanĕşéֽ̌y-há⁠ʼá֖reẕ ʼàşě֣r li⁠pĕnéy⁠ke֑m wa⁠ţi̇tĕmá֖ʼ há⁠ʼáֽreẕ׃"],[18,28,"וְ⁠לֹֽא־תָקִ֤יא הָ⁠אָ֨רֶץ֙ אֶתְ⁠כֶ֔ם בְּ⁠טַֽמַּאֲ⁠כֶ֖ם אֹתָ֑⁠הּ כַּ⁠אֲשֶׁ֥ר קָאָ֛ה אֶת־הַ⁠גּ֖וֹי אֲשֶׁ֥ר לִ⁠פְנֵי⁠כֶֽם׃","wĕ⁠lòֽʼ-ţáqi֤yʼ há⁠ʼá֨reẕ֙ ʼeţĕ⁠ke֔m bĕ̇⁠taֽmȧʼà⁠ke֖m ʼòţá֑⁠ḣ kȧ⁠ʼàşě֥r qáʼá֛h ʼeţ-ha⁠ġ֖wòy ʼàşě֥r li⁠pĕnéy⁠keֽm׃"],[18,29,"כִּ֚י כָּל־אֲשֶׁ֣ר יַעֲשֶׂ֔ה מִ⁠כֹּ֥ל הַ⁠תּוֹעֵב֖וֹת הָ⁠אֵ֑לֶּה וְ⁠נִכְרְת֛וּ הַ⁠נְּפָשׁ֥וֹת הָ⁠עֹשֹׂ֖ת מִ⁠קֶּ֥רֶב עַמָּֽ⁠ם׃","ki֚̇y ká̇l-ʼàşě֣r yaʻàşê֔h mi⁠kò֥̇l ha⁠ţ̇wòʻéb֖wòţ há⁠ʼé֑lėh wĕ⁠nikĕrĕţ֛ẇ ha⁠nĕ̇páş֥̌wòţ há⁠ʻòşò֖̂ţ mi⁠qė֥reb ʻamáֽ̇⁠m׃"],[18,30,"וּ⁠שְׁמַרְתֶּ֣ם אֶת־מִשְׁמַרְתִּ֗⁠י לְ⁠בִלְתִּ֨י עֲשׂ֜וֹת מֵ⁠חֻקּ֤וֹת הַ⁠תּֽוֹעֵבֹת֙ אֲשֶׁ֣ר נַעֲשׂ֣וּ לִ⁠פְנֵי⁠כֶ֔ם וְ⁠לֹ֥א תִֽטַּמְּא֖וּ בָּ⁠הֶ֑ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃פ","ẇ⁠şĕ̌marĕţė֣m ʼeţ-mişĕ̌marĕţi̇֗⁠y lĕ⁠bilĕţi̇֨y ʻàş̂֜wòţ mé⁠ẖuq֤̇wòţ ha⁠ţֽ̇wòʻébòţ֙ ʼàşě֣r naʻàş֣̂ẇ li⁠pĕnéy⁠ke֔m wĕ⁠lò֥ʼ ţiֽtȧmĕ̇ʼ֖ẇ bá̇⁠he֑m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃p"],[19,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr"],[19,2,"דַּבֵּ֞ר אֶל־כָּל־עֲדַ֧ת בְּנֵי־יִשְׂרָאֵ֛ל וְ⁠אָמַרְתָּ֥ אֲלֵ⁠הֶ֖ם קְדֹשִׁ֣ים תִּהְי֑וּ כִּ֣י קָד֔וֹשׁ אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","dȧbé̇֞r ʼel-ká̇l-ʻàda֧ţ bĕ̇néy-yişĕ̂ráʼé֛l wĕ⁠ʼámarĕţá֥̇ ʼàlé⁠he֖m qĕdòşǐ֣ym ţi̇hĕy֑ẇ ki֣̇y qád֔wòş̌ ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,3,"אִ֣ישׁ אִמּ֤⁠וֹ וְ⁠אָבִי⁠ו֙ תִּירָ֔אוּ וְ⁠אֶת־שַׁבְּתֹתַ֖⁠י תִּשְׁמֹ֑רוּ אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ʼi֣yş̌ ʼiṁ֤⁠wò wĕ⁠ʼábiy⁠w֙ ţi̇yrá֔ʼẇ wĕ⁠ʼeţ-şǎbĕ̇ţòţa֖⁠y ţi̇şĕ̌mò֑rẇ ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,4,"אַל־תִּפְנוּ֙ אֶל־הָ֣⁠אֱלִילִ֔ים וֵֽ⁠אלֹהֵי֙ מַסֵּכָ֔ה לֹ֥א תַעֲשׂ֖וּ לָ⁠כֶ֑ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ʼal-ţi̇pĕnẇ֙ ʼel-há֣⁠ʼèliyli֔ym wéֽ⁠ʼlòhéy֙ masé̇ká֔h lò֥ʼ ţaʻàş֖̂ẇ lá⁠ke֑m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,5,"וְ⁠כִ֧י תִזְבְּח֛וּ זֶ֥בַח שְׁלָמִ֖ים לַ⁠יהוָ֑ה לִֽ⁠רְצֹנְ⁠כֶ֖ם תִּזְבָּחֻֽ⁠הוּ׃","wĕ⁠ki֧y ţizĕbĕ̇ẖ֛ẇ ze֥baẖ şĕ̌lámi֖ym la⁠yhwá֑h liֽ⁠rĕẕònĕ⁠ke֖m ţi̇zĕbá̇ẖuֽ⁠hẇ׃"],[19,6,"בְּ⁠י֧וֹם זִבְחֲ⁠כֶ֛ם יֵאָכֵ֖ל וּ⁠מִֽ⁠מָּחֳרָ֑ת וְ⁠הַ⁠נּוֹתָר֙ עַד־י֣וֹם הַ⁠שְּׁלִישִׁ֔י בָּ⁠אֵ֖שׁ יִשָּׂרֵֽף׃","bĕ̇⁠y֧wòm zibĕẖà⁠ke֛m yéʼáké֖l ẇ⁠miֽ⁠má̇ẖorá֑ţ wĕ⁠ha⁠ṅwòţár֙ ʻad-y֣wòm ha⁠şĕ̇̌liyşǐ֔y bá̇⁠ʼé֖ş̌ yişá̇̂réֽp׃"],[19,7,"וְ⁠אִ֛ם הֵאָכֹ֥ל יֵאָכֵ֖ל בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י פִּגּ֥וּל ה֖וּא לֹ֥א יֵרָצֶֽה׃","wĕ⁠ʼi֛m héʼákò֥l yéʼáké֖l bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y pi̇ġ֥ẇl h֖ẇʼ lò֥ʼ yéráẕeֽh׃"],[19,8,"וְ⁠אֹֽכְלָי⁠ו֙ עֲוֺנ֣⁠וֹ יִשָּׂ֔א כִּֽי־אֶת־קֹ֥דֶשׁ יְהוָ֖ה חִלֵּ֑ל וְ⁠נִכְרְתָ֛ה הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מֵ⁠עַמֶּֽי⁠הָ׃","wĕ⁠ʼòֽkĕláy⁠w֙ ʻàwֺn֣⁠wò yişá̇̂֔ʼ kiֽ̇y-ʼeţ-qò֥deş̌ yĕhwá֖h ẖilé֑̇l wĕ⁠nikĕrĕţá֛h ha⁠nė֥peş̌ ha⁠hi֖wʼ mé⁠ʻamėֽy⁠há׃"],[19,9,"וּֽ⁠בְ⁠קֻצְרְ⁠כֶם֙ אֶת־קְצִ֣יר אַרְצְ⁠כֶ֔ם לֹ֧א תְכַלֶּ֛ה פְּאַ֥ת שָׂדְ⁠ךָ֖ לִ⁠קְצֹ֑ר וְ⁠לֶ֥קֶט קְצִֽירְ⁠ךָ֖ לֹ֥א תְלַקֵּֽט׃","ẇֽ⁠bĕ⁠quẕĕrĕ⁠kem֙ ʼeţ-qĕẕi֣yr ʼarĕẕĕ⁠ke֔m lò֧ʼ ţĕkalė֛h pĕ̇ʼa֥ţ şá̂dĕ⁠ká֖ li⁠qĕẕò֑r wĕ⁠le֥qet qĕẕiֽyrĕ⁠ká֖ lò֥ʼ ţĕlaqéֽ̇t׃"],[19,10,"וְ⁠כַרְמְ⁠ךָ֙ לֹ֣א תְעוֹלֵ֔ל וּ⁠פֶ֥רֶט כַּרְמְ⁠ךָ֖ לֹ֣א תְלַקֵּ֑ט לֶֽ⁠עָנִ֤י וְ⁠לַ⁠גֵּר֙ תַּעֲזֹ֣ב אֹתָ֔⁠ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠karĕmĕ⁠ká֙ lò֣ʼ ţĕʻwòlé֔l ẇ⁠pe֥ret kȧrĕmĕ⁠ká֖ lò֣ʼ ţĕlaqé֑̇t leֽ⁠ʻáni֤y wĕ⁠la⁠gé̇r֙ ţȧʻàzò֣b ʼòţá֔⁠m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,11,"לֹ֖א תִּגְנֹ֑בוּ וְ⁠לֹא־תְכַחֲשׁ֥וּ וְ⁠לֹֽא־תְשַׁקְּר֖וּ אִ֥ישׁ בַּ⁠עֲמִיתֽ⁠וֹ׃","lò֖ʼ ţi̇gĕnò֑bẇ wĕ⁠lòʼ-ţĕkaẖàş֥̌ẇ wĕ⁠lòֽʼ-ţĕşǎqĕ̇r֖ẇ ʼi֥yş̌ bȧ⁠ʻàmiyţֽ⁠wò׃"],[19,12,"וְ⁠לֹֽא־תִשָּׁבְע֥וּ בִ⁠שְׁמִ֖⁠י לַ⁠שָּׁ֑קֶר וְ⁠חִלַּלְתָּ֛ אֶת־שֵׁ֥ם אֱלֹהֶ֖י⁠ךָ אֲנִ֥י יְהוָֽה׃","wĕ⁠lòֽʼ-ţişá̇̌bĕʻ֥ẇ bi⁠şĕ̌mi֖⁠y la⁠şá֑̇̌qer wĕ⁠ẖilȧlĕţá֛̇ ʼeţ-şé֥̌m ʼèlòhe֖y⁠ká ʼàni֥y yĕhwáֽh׃"],[19,13,"לֹֽא־תַעֲשֹׁ֥ק אֶת־רֵֽעֲ⁠ךָ֖ וְ⁠לֹ֣א תִגְזֹ֑ל לֹֽא־תָלִ֞ין פְּעֻלַּ֥ת שָׂכִ֛יר אִתְּ⁠ךָ֖ עַד־בֹּֽקֶר׃","lòֽʼ-ţaʻàşò֥̌q ʼeţ-réֽʻà⁠ká֖ wĕ⁠lò֣ʼ ţigĕzò֑l lòֽʼ-ţáli֞yn pĕ̇ʻulȧ֥ţ şá̂ki֛yr ʼiţĕ̇⁠ká֖ ʻad-bòֽ̇qer׃"],[19,14,"לֹא־תְקַלֵּ֣ל חֵרֵ֔שׁ וְ⁠לִ⁠פְנֵ֣י עִוֵּ֔ר לֹ֥א תִתֵּ֖ן מִכְשֹׁ֑ל וְ⁠יָרֵ֥אתָ מֵּ⁠אֱלֹהֶ֖י⁠ךָ אֲנִ֥י יְהוָֽה׃","lòʼ-ţĕqalé֣̇l ẖéré֔ş̌ wĕ⁠li⁠pĕné֣y ʻiwé̇֔r lò֥ʼ ţiţé֖̇n mikĕşò֑̌l wĕ⁠yáré֥ʼţá mé̇⁠ʼèlòhe֖y⁠ká ʼàni֥y yĕhwáֽh׃"],[19,15,"לֹא־תַעֲשׂ֥וּ עָ֨וֶל֙ בַּ⁠מִּשְׁפָּ֔ט לֹא־תִשָּׂ֣א פְנֵי־דָ֔ל וְ⁠לֹ֥א תֶהְדַּ֖ר פְּנֵ֣י גָד֑וֹל בְּ⁠צֶ֖דֶק תִּשְׁפֹּ֥ט עֲמִיתֶֽ⁠ךָ׃","lòʼ-ţaʻàş֥̂ẇ ʻá֨wel֙ bȧ⁠mi̇şĕ̌pá̇֔t lòʼ-ţişá֣̇̂ʼ pĕnéy-dá֔l wĕ⁠lò֥ʼ ţehĕdȧ֖r pĕ̇né֣y gád֑wòl bĕ̇⁠ẕe֖deq ţi̇şĕ̌pò֥̇t ʻàmiyţeֽ⁠ká׃"],[19,16,"לֹא־תֵלֵ֤ךְ רָכִיל֙ בְּ⁠עַמֶּ֔י⁠ךָ לֹ֥א תַעֲמֹ֖ד עַל־דַּ֣ם רֵעֶ֑⁠ךָ אֲנִ֖י יְהוָֽה׃","lòʼ-ţélé֤kĕ rákiyl֙ bĕ̇⁠ʻamė֔y⁠ká lò֥ʼ ţaʻàmò֖d ʻal-dȧ֣m réʻe֑⁠ká ʼàni֖y yĕhwáֽh׃"],[19,17,"לֹֽא־תִשְׂנָ֥א אֶת־אָחִ֖י⁠ךָ בִּ⁠לְבָבֶ֑⁠ךָ הוֹכֵ֤חַ תּוֹכִ֨יחַ֙ אֶת־עֲמִיתֶ֔⁠ךָ וְ⁠לֹא־תִשָּׂ֥א עָלָ֖י⁠ו חֵֽטְא׃","lòֽʼ-ţişĕ̂ná֥ʼ ʼeţ-ʼáẖi֖y⁠ká bi̇⁠lĕbábe֑⁠ká hwòké֤ẖa ţ̇wòki֨yẖa֙ ʼeţ-ʻàmiyţe֔⁠ká wĕ⁠lòʼ-ţişá֥̇̂ʼ ʻálá֖y⁠w ẖéֽtĕʼ׃"],[19,18,"לֹֽא־תִקֹּ֤ם וְ⁠לֹֽא־תִטֹּר֙ אֶת־בְּנֵ֣י עַמֶּ֔⁠ךָ וְ⁠אָֽהַבְתָּ֥ לְ⁠רֵעֲ⁠ךָ֖ כָּמ֑וֹ⁠ךָ אֲנִ֖י יְהוָֽה׃","lòֽʼ-ţiqò֤̇m wĕ⁠lòֽʼ-ţitò̇r֙ ʼeţ-bĕ̇né֣y ʻamė֔⁠ká wĕ⁠ʼáֽhabĕţá֥̇ lĕ⁠réʻà⁠ká֖ ká̇m֑wò⁠ká ʼàni֖y yĕhwáֽh׃"],[19,19,"אֶֽת־חֻקֹּתַ⁠י֮ תִּשְׁמֹרוּ֒ בְּהֶמְתְּ⁠ךָ֙ לֹא־תַרְבִּ֣יעַ כִּלְאַ֔יִם שָׂדְ⁠ךָ֖ לֹא־תִזְרַ֣ע כִּלְאָ֑יִם וּ⁠בֶ֤גֶד כִּלְאַ֨יִם֙ שַֽׁעַטְנֵ֔ז לֹ֥א יַעֲלֶ֖ה עָלֶֽי⁠ךָ׃פ","ʼeֽţ-ẖuqò̇ţa⁠y֮ ţi̇şĕ̌mòrẇ֒ bĕ̇hemĕţĕ̇⁠ká֙ lòʼ-ţarĕbi֣̇yʻa ki̇lĕʼa֔yim şá̂dĕ⁠ká֖ lòʼ-ţizĕra֣ʻ ki̇lĕʼá֑yim ẇ⁠be֤ged ki̇lĕʼa֨yim֙ şֽ̌aʻatĕné֔z lò֥ʼ yaʻàle֖h ʻáleֽy⁠ká׃p"],[19,20,"וְ֠⁠אִישׁ כִּֽי־יִשְׁכַּ֨ב אֶת־אִשָּׁ֜ה שִׁכְבַת־זֶ֗רַע וְ⁠הִ֤וא שִׁפְחָה֙ נֶחֱרֶ֣פֶת לְ⁠אִ֔ישׁ וְ⁠הָפְדֵּה֙ לֹ֣א נִפְדָּ֔תָה א֥וֹ חֻפְשָׁ֖ה לֹ֣א נִתַּן־לָ֑⁠הּ בִּקֹּ֧רֶת תִּהְיֶ֛ה לֹ֥א יוּמְת֖וּ כִּי־לֹ֥א חֻפָּֽשָׁה׃","wĕ֠⁠ʼiyş̌ kiֽ̇y-yişĕ̌kȧ֨b ʼeţ-ʼişá̇̌֜h şǐkĕbaţ-ze֗raʻ wĕ⁠hi֤wʼ şǐpĕẖáh֙ neẖère֣peţ lĕ⁠ʼi֔yş̌ wĕ⁠hápĕdé̇h֙ lò֣ʼ nipĕdá̇֔ţáh ʼ֥wò ẖupĕşá֖̌h lò֣ʼ niţȧn-lá֑⁠ḣ bi̇qò֧̇reţ ţi̇hĕye֛h lò֥ʼ yẇmĕţ֖ẇ ki̇y-lò֥ʼ ẖupáֽ̇şá̌h׃"],[19,21,"וְ⁠הֵבִ֤יא אֶת־אֲשָׁמ⁠וֹ֙ לַֽ⁠יהוָ֔ה אֶל־פֶּ֖תַח אֹ֣הֶל מוֹעֵ֑ד אֵ֖יל אָשָֽׁם׃","wĕ⁠hébi֤yʼ ʼeţ-ʼàşá̌m⁠wò֙ laֽ⁠yhwá֔h ʼel-pė֖ţaẖ ʼò֣hel mwòʻé֑d ʼé֖yl ʼáşáֽ̌m׃"],[19,22,"וְ⁠כִפֶּר֩ עָלָ֨י⁠ו הַ⁠כֹּהֵ֜ן בְּ⁠אֵ֤יל הָֽ⁠אָשָׁם֙ לִ⁠פְנֵ֣י יְהוָ֔ה עַל־חַטָּאת֖⁠וֹ אֲשֶׁ֣ר חָטָ֑א וְ⁠נִסְלַ֣ח ל֔⁠וֹ מֵ⁠חַטָּאת֖⁠וֹ אֲשֶׁ֥ר חָטָֽא׃פ","wĕ⁠kipėr֩ ʻálá֨y⁠w ha⁠kò̇hé֜n bĕ̇⁠ʼé֤yl háֽ⁠ʼáşá̌m֙ li⁠pĕné֣y yĕhwá֔h ʻal-ẖatá̇ʼţ֖⁠wò ʼàşě֣r ẖátá֑ʼ wĕ⁠nisĕla֣ẖ l֔⁠wò mé⁠ẖatá̇ʼţ֖⁠wò ʼàşě֥r ẖátáֽʼ׃p"],[19,23,"וְ⁠כִי־תָבֹ֣אוּ אֶל־הָ⁠אָ֗רֶץ וּ⁠נְטַעְתֶּם֙ כָּל־עֵ֣ץ מַאֲכָ֔ל וַ⁠עֲרַלְתֶּ֥ם עָרְלָת֖⁠וֹ אֶת־פִּרְי֑⁠וֹ שָׁלֹ֣שׁ שָׁנִ֗ים יִהְיֶ֥ה לָ⁠כֶ֛ם עֲרֵלִ֖ים לֹ֥א יֵאָכֵֽל׃","wĕ⁠kiy-ţábò֣ʼẇ ʼel-há⁠ʼá֗reẕ ẇ⁠nĕtaʻĕţėm֙ ká̇l-ʻé֣ẕ maʼàká֔l wa⁠ʻàralĕţė֥m ʻárĕláţ֖⁠wò ʼeţ-pi̇rĕy֑⁠wò şá̌lò֣ş̌ şá̌ni֗ym yihĕye֥h lá⁠ke֛m ʻàréli֖ym lò֥ʼ yéʼákéֽl׃"],[19,24,"וּ⁠בַ⁠שָּׁנָה֙ הָ⁠רְבִיעִ֔ת יִהְיֶ֖ה כָּל־פִּרְי֑⁠וֹ קֹ֥דֶשׁ הִלּוּלִ֖ים לַ⁠יהוָֽה׃","ẇ⁠ba⁠şá̇̌náh֙ há⁠rĕbiyʻi֔ţ yihĕye֖h ká̇l-pi̇rĕy֑⁠wò qò֥deş̌ hil̇ẇli֖ym la⁠yhwáֽh׃"],[19,25,"וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠חֲמִישִׁ֗ת תֹּֽאכְלוּ֙ אֶת־פִּרְי֔⁠וֹ לְ⁠הוֹסִ֥יף לָ⁠כֶ֖ם תְּבוּאָת֑⁠וֹ אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ẇ⁠ba⁠şá̇̌ná֣h ha⁠ẖàmiyşǐ֗ţ ţòֽ̇ʼkĕlẇ֙ ʼeţ-pi̇rĕy֔⁠wò lĕ⁠hwòsi֥yp lá⁠ke֖m ţĕ̇bẇʼáţ֑⁠wò ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,26,"לֹ֥א תֹאכְל֖וּ עַל־הַ⁠דָּ֑ם לֹ֥א תְנַחֲשׁ֖וּ וְ⁠לֹ֥א תְעוֹנֵֽנוּ׃","lò֥ʼ ţòʼkĕl֖ẇ ʻal-ha⁠dá֑̇m lò֥ʼ ţĕnaẖàş֖̌ẇ wĕ⁠lò֥ʼ ţĕʻwònéֽnẇ׃"],[19,27,"לֹ֣א תַקִּ֔פוּ פְּאַ֖ת רֹאשְׁ⁠כֶ֑ם וְ⁠לֹ֣א תַשְׁחִ֔ית אֵ֖ת פְּאַ֥ת זְקָנֶֽ⁠ךָ׃","lò֣ʼ ţaqi̇֔pẇ pĕ̇ʼa֖ţ ròʼşĕ̌⁠ke֑m wĕ⁠lò֣ʼ ţaşĕ̌ẖi֔yţ ʼé֖ţ pĕ̇ʼa֥ţ zĕqáneֽ⁠ká׃"],[19,28,"וְ⁠שֶׂ֣רֶט לָ⁠נֶ֗פֶשׁ לֹ֤א תִתְּנוּ֙ בִּ⁠בְשַׂרְ⁠כֶ֔ם וּ⁠כְתֹ֣בֶת קַֽעֲקַ֔ע לֹ֥א תִתְּנ֖וּ בָּ⁠כֶ֑ם אֲנִ֖י יְהוָֽה׃","wĕ⁠şê֣ret lá⁠ne֗peş̌ lò֤ʼ ţiţĕ̇nẇ֙ bi̇⁠bĕşârĕ⁠ke֔m ẇ⁠kĕţò֣beţ qֽaʻàqa֔ʻ lò֥ʼ ţiţĕ̇n֖ẇ bá̇⁠ke֑m ʼàni֖y yĕhwáֽh׃"],[19,29,"אַל־תְּחַלֵּ֥ל אֶֽת־בִּתְּ⁠ךָ֖ לְ⁠הַזְנוֹתָ֑⁠הּ וְ⁠לֹא־תִזְנֶ֣ה הָ⁠אָ֔רֶץ וּ⁠מָלְאָ֥ה הָ⁠אָ֖רֶץ זִמָּֽה׃","ʼal-ţĕ̇ẖalé֥̇l ʼeֽţ-bi̇ţĕ̇⁠ká֖ lĕ⁠hazĕnwòţá֑⁠ḣ wĕ⁠lòʼ-ţizĕne֣h há⁠ʼá֔reẕ ẇ⁠málĕʼá֥h há⁠ʼá֖reẕ zimáֽ̇h׃"],[19,30,"אֶת־שַׁבְּתֹתַ֣⁠י תִּשְׁמֹ֔רוּ וּ⁠מִקְדָּשִׁ֖⁠י תִּירָ֑אוּ אֲנִ֖י יְהוָֽה׃","ʼeţ-şǎbĕ̇ţòţa֣⁠y ţi̇şĕ̌mò֔rẇ ẇ⁠miqĕdá̇şǐ֖⁠y ţi̇yrá֑ʼẇ ʼàni֖y yĕhwáֽh׃"],[19,31,"אַל־תִּפְנ֤וּ אֶל־הָ⁠אֹבֹת֙ וְ⁠אֶל־הַ⁠יִּדְּעֹנִ֔ים אַל־תְּבַקְשׁ֖וּ לְ⁠טָמְאָ֣ה בָ⁠הֶ֑ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ʼal-ţi̇pĕn֤ẇ ʼel-há⁠ʼòbòţ֙ wĕ⁠ʼel-ha⁠yi̇dĕ̇ʻòni֔ym ʼal-ţĕ̇baqĕş֖̌ẇ lĕ⁠támĕʼá֣h bá⁠he֑m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,32,"מִ⁠פְּנֵ֤י שֵׂיבָה֙ תָּק֔וּם וְ⁠הָדַרְתָּ֖ פְּנֵ֣י זָקֵ֑ן וְ⁠יָרֵ֥אתָ מֵּ⁠אֱלֹהֶ֖י⁠ךָ אֲנִ֥י יְהוָֽה׃פ","mi⁠pĕ̇né֤y şé̂ybáh֙ ţá̇q֔ẇm wĕ⁠hádarĕţá֖̇ pĕ̇né֣y záqé֑n wĕ⁠yáré֥ʼţá mé̇⁠ʼèlòhe֖y⁠ká ʼàni֥y yĕhwáֽh׃p"],[19,33,"וְ⁠כִֽי־יָג֧וּר אִתְּ⁠ךָ֛ גֵּ֖ר בְּ⁠אַרְצְ⁠כֶ֑ם לֹ֥א תוֹנ֖וּ אֹתֽ⁠וֹ׃","wĕ⁠kiֽy-yág֧ẇr ʼiţĕ̇⁠ká֛ gé֖̇r bĕ̇⁠ʼarĕẕĕ⁠ke֑m lò֥ʼ ţwòn֖ẇ ʼòţֽ⁠wò׃"],[19,34,"כְּ⁠אֶזְרָ֣ח מִ⁠כֶּם֩ יִהְיֶ֨ה לָ⁠כֶ֜ם הַ⁠גֵּ֣ר ׀ הַ⁠גָּ֣ר אִתְּ⁠כֶ֗ם וְ⁠אָהַבְתָּ֥ ל⁠וֹ֙ כָּמ֔וֹ⁠ךָ כִּֽי־גֵרִ֥ים הֱיִיתֶ֖ם בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","kĕ̇⁠ʼezĕrá֣ẖ mi⁠kėm֩ yihĕye֨h lá⁠ke֜m ha⁠gé֣̇r ׀ ha⁠gá֣̇r ʼiţĕ̇⁠ke֗m wĕ⁠ʼáhabĕţá֥̇ l⁠wò֙ ká̇m֔wò⁠ká kiֽ̇y-géri֥ym hèyiyţe֖m bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[19,35,"לֹא־תַעֲשׂ֥וּ עָ֖וֶל בַּ⁠מִּשְׁפָּ֑ט בַּ⁠מִּדָּ֕ה בַּ⁠מִּשְׁקָ֖ל וּ⁠בַ⁠מְּשׂוּרָֽה׃","lòʼ-ţaʻàş֥̂ẇ ʻá֖wel bȧ⁠mi̇şĕ̌pá֑̇t bȧ⁠mi̇dá̇֕h bȧ⁠mi̇şĕ̌qá֖l ẇ⁠ba⁠mĕ̇ş̂ẇráֽh׃"],[19,36,"מֹ֧אזְנֵי צֶ֣דֶק אַבְנֵי־צֶ֗דֶק אֵ֥יפַת צֶ֛דֶק וְ⁠הִ֥ין צֶ֖דֶק יִהְיֶ֣ה לָ⁠כֶ֑ם אֲנִי֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם אֲשֶׁר־הוֹצֵ֥אתִי אֶתְ⁠כֶ֖ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","mò֧ʼzĕnéy ẕe֣deq ʼabĕnéy-ẕe֗deq ʼé֥ypaţ ẕe֛deq wĕ⁠hi֥yn ẕe֖deq yihĕye֣h lá⁠ke֑m ʼàniy֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ʼàşěr-hwòẕé֥ʼţiy ʼeţĕ⁠ke֖m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[19,37,"וּ⁠שְׁמַרְתֶּ֤ם אֶת־כָּל־חֻקֹּתַ⁠י֙ וְ⁠אֶת־כָּל־מִשְׁפָּטַ֔⁠י וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם אֲנִ֖י יְהוָֽה׃פ","ẇ⁠şĕ̌marĕţė֤m ʼeţ-ká̇l-ẖuqò̇ţa⁠y֙ wĕ⁠ʼeţ-ká̇l-mişĕ̌pá̇ta֔⁠y wa⁠ʻàşîyţe֖m ʼòţá֑⁠m ʼàni֖y yĕhwáֽh׃p"],[20,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[20,2,"וְ⁠אֶל־בְּנֵ֣י יִשְׂרָאֵ֘ל תֹּאמַר֒ אִ֣ישׁ אִישׁ֩ מִ⁠בְּנֵ֨י יִשְׂרָאֵ֜ל וּ⁠מִן־הַ⁠גֵּ֣ר ׀ הַ⁠גָּ֣ר בְּ⁠יִשְׂרָאֵ֗ל אֲשֶׁ֨ר יִתֵּ֧ן מִ⁠זַּרְע֛⁠וֹ לַ⁠מֹּ֖לֶךְ מ֣וֹת יוּמָ֑ת עַ֥ם הָ⁠אָ֖רֶץ יִרְגְּמֻ֥⁠הוּ בָ⁠אָֽבֶן׃","wĕ⁠ʼel-bĕ̇né֣y yişĕ̂ráʼé֘l ţò̇ʼmar֒ ʼi֣yş̌ ʼiyş̌֩ mi⁠bĕ̇né֨y yişĕ̂ráʼé֜l ẇ⁠min-ha⁠gé֣̇r ׀ ha⁠gá֣̇r bĕ̇⁠yişĕ̂ráʼé֗l ʼàşě֨r yiţé֧̇n mi⁠zȧrĕʻ֛⁠wò la⁠mò֖̇lekĕ m֣wòţ yẇmá֑ţ ʻa֥m há⁠ʼá֖reẕ yirĕgĕ̇mu֥⁠hẇ bá⁠ʼáֽben׃"],[20,3,"וַ⁠אֲנִ֞י אֶתֵּ֤ן אֶת־פָּנַ⁠י֙ בָּ⁠אִ֣ישׁ הַ⁠ה֔וּא וְ⁠הִכְרַתִּ֥י אֹת֖⁠וֹ מִ⁠קֶּ֣רֶב עַמּ֑⁠וֹ כִּ֤י מִ⁠זַּרְע⁠וֹ֙ נָתַ֣ן לַ⁠מֹּ֔לֶךְ לְמַ֗עַן טַמֵּא֙ אֶת־מִקְדָּשִׁ֔⁠י וּ⁠לְ⁠חַלֵּ֖ל אֶת־שֵׁ֥ם קָדְשִֽׁ⁠י׃","wa⁠ʼàni֞y ʼeţé֤̇n ʼeţ-pá̇na⁠y֙ bá̇⁠ʼi֣yş̌ ha⁠h֔ẇʼ wĕ⁠hikĕraţi֥̇y ʼòţ֖⁠wò mi⁠qė֣reb ʻaṁ֑⁠wò ki֤̇y mi⁠zȧrĕʻ⁠wò֙ náţa֣n la⁠mò̇֔lekĕ lĕma֗ʻan tamé̇ʼ֙ ʼeţ-miqĕdá̇şǐ֔⁠y ẇ⁠lĕ⁠ẖalé֖̇l ʼeţ-şé֥̌m qádĕşǐֽ⁠y׃"],[20,4,"וְ⁠אִ֡ם הַעְלֵ֣ם יַעְלִימֽוּ֩ עַ֨ם הָ⁠אָ֜רֶץ אֶת־עֵֽינֵי⁠הֶם֙ מִן־הָ⁠אִ֣ישׁ הַ⁠ה֔וּא בְּ⁠תִתּ֥⁠וֹ מִ⁠זַּרְע֖⁠וֹ לַ⁠מֹּ֑לֶךְ לְ⁠בִלְתִּ֖י הָמִ֥ית אֹתֽ⁠וֹ׃","wĕ⁠ʼi֡m haʻĕlé֣m yaʻĕliymֽẇ֩ ʻa֨m há⁠ʼá֜reẕ ʼeţ-ʻéֽynéy⁠hem֙ min-há⁠ʼi֣yş̌ ha⁠h֔ẇʼ bĕ̇⁠ţiţ֥̇⁠wò mi⁠zȧrĕʻ֖⁠wò la⁠mò֑̇lekĕ lĕ⁠bilĕţi֖̇y hámi֥yţ ʼòţֽ⁠wò׃"],[20,5,"וְ⁠שַׂמְתִּ֨י אֲנִ֧י אֶת־פָּנַ֛⁠י בָּ⁠אִ֥ישׁ הַ⁠ה֖וּא וּ⁠בְ⁠מִשְׁפַּחְתּ֑⁠וֹ וְ⁠הִכְרַתִּ֨י אֹת֜⁠וֹ וְ⁠אֵ֣ת ׀ כָּל־הַ⁠זֹּנִ֣ים אַחֲרָ֗י⁠ו לִ⁠זְנ֛וֹת אַחֲרֵ֥י הַ⁠מֹּ֖לֶךְ מִ⁠קֶּ֥רֶב עַמָּֽ⁠ם׃","wĕ⁠şâmĕţi̇֨y ʼàni֧y ʼeţ-pá̇na֛⁠y bá̇⁠ʼi֥yş̌ ha⁠h֖ẇʼ ẇ⁠bĕ⁠mişĕ̌pȧẖĕţ֑̇⁠wò wĕ⁠hikĕraţi̇֨y ʼòţ֜⁠wò wĕ⁠ʼé֣ţ ׀ ká̇l-ha⁠zò̇ni֣ym ʼaẖàrá֗y⁠w li⁠zĕn֛wòţ ʼaẖàré֥y ha⁠mò֖̇lekĕ mi⁠qė֥reb ʻamáֽ̇⁠m׃"],[20,6,"וְ⁠הַ⁠נֶּ֗פֶשׁ אֲשֶׁ֨ר תִּפְנֶ֤ה אֶל־הָֽ⁠אֹבֹת֙ וְ⁠אֶל־הַ⁠יִּדְּעֹנִ֔ים לִ⁠זְנ֖וֹת אַחֲרֵי⁠הֶ֑ם וְ⁠נָתַתִּ֤י אֶת־פָּנַ⁠י֙ בַּ⁠נֶּ֣פֶשׁ הַ⁠הִ֔וא וְ⁠הִכְרַתִּ֥י אֹת֖⁠וֹ מִ⁠קֶּ֥רֶב עַמּֽ⁠וֹ׃","wĕ⁠ha⁠nė֗peş̌ ʼàşě֨r ţi̇pĕne֤h ʼel-háֽ⁠ʼòbòţ֙ wĕ⁠ʼel-ha⁠yi̇dĕ̇ʻòni֔ym li⁠zĕn֖wòţ ʼaẖàréy⁠he֑m wĕ⁠náţaţi֤̇y ʼeţ-pá̇na⁠y֙ bȧ⁠nė֣peş̌ ha⁠hi֔wʼ wĕ⁠hikĕraţi֥̇y ʼòţ֖⁠wò mi⁠qė֥reb ʻaṁֽ⁠wò׃"],[20,7,"וְ⁠הִ֨תְקַדִּשְׁתֶּ֔ם וִ⁠הְיִיתֶ֖ם קְדֹשִׁ֑ים כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠hi֨ţĕqadi̇şĕ̌ţė֔m wi⁠hĕyiyţe֖m qĕdòşǐ֑ym ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[20,8,"וּ⁠שְׁמַרְתֶּם֙ אֶת־חֻקֹּתַ֔⁠י וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם אֲנִ֥י יְהוָ֖ה מְקַדִּשְׁ⁠כֶֽם׃","ẇ⁠şĕ̌marĕţėm֙ ʼeţ-ẖuqò̇ţa֔⁠y wa⁠ʻàşîyţe֖m ʼòţá֑⁠m ʼàni֥y yĕhwá֖h mĕqadi̇şĕ̌⁠keֽm׃"],[20,9,"כִּֽי־אִ֣ישׁ אִ֗ישׁ אֲשֶׁ֨ר יְקַלֵּ֧ל אֶת־אָבִ֛י⁠ו וְ⁠אֶת־אִמּ֖⁠וֹ מ֣וֹת יוּמָ֑ת אָבִ֧י⁠ו וְ⁠אִמּ֛⁠וֹ קִלֵּ֖ל דָּמָ֥י⁠ו בּֽ⁠וֹ׃","kiֽ̇y-ʼi֣yş̌ ʼi֗yş̌ ʼàşě֨r yĕqalé֧̇l ʼeţ-ʼábi֛y⁠w wĕ⁠ʼeţ-ʼiṁ֖⁠wò m֣wòţ yẇmá֑ţ ʼábi֧y⁠w wĕ⁠ʼiṁ֛⁠wò qilé֖̇l dá̇má֥y⁠w ḃֽ⁠wò׃"],[20,10,"וְ⁠אִ֗ישׁ אֲשֶׁ֤ר יִנְאַף֙ אֶת־אֵ֣שֶׁת אִ֔ישׁ אֲשֶׁ֥ר יִנְאַ֖ף אֶת־אֵ֣שֶׁת רֵעֵ֑⁠הוּ מֽוֹת־יוּמַ֥ת הַ⁠נֹּאֵ֖ף וְ⁠הַ⁠נֹּאָֽפֶת׃","wĕ⁠ʼi֗yş̌ ʼàşě֤r yinĕʼap֙ ʼeţ-ʼé֣şěţ ʼi֔yş̌ ʼàşě֥r yinĕʼa֖p ʼeţ-ʼé֣şěţ réʻé֑⁠hẇ mֽwòţ-yẇma֥ţ ha⁠nò̇ʼé֖p wĕ⁠ha⁠nò̇ʼáֽpeţ׃"],[20,11,"וְ⁠אִ֗ישׁ אֲשֶׁ֤ר יִשְׁכַּב֙ אֶת־אֵ֣שֶׁת אָבִ֔י⁠ו עֶרְוַ֥ת אָבִ֖י⁠ו גִּלָּ֑ה מֽוֹת־יוּמְת֥וּ שְׁנֵי⁠הֶ֖ם דְּמֵי⁠הֶ֥ם בָּֽ⁠ם׃","wĕ⁠ʼi֗yş̌ ʼàşě֤r yişĕ̌kȧb֙ ʼeţ-ʼé֣şěţ ʼábi֔y⁠w ʻerĕwa֥ţ ʼábi֖y⁠w gi̇lá֑̇h mֽwòţ-yẇmĕţ֥ẇ şĕ̌néy⁠he֖m dĕ̇méy⁠he֥m báֽ̇⁠m׃"],[20,12,"וְ⁠אִ֗ישׁ אֲשֶׁ֤ר יִשְׁכַּב֙ אֶת־כַּלָּת֔⁠וֹ מ֥וֹת יוּמְת֖וּ שְׁנֵי⁠הֶ֑ם תֶּ֥בֶל עָשׂ֖וּ דְּמֵי⁠הֶ֥ם בָּֽ⁠ם׃","wĕ⁠ʼi֗yş̌ ʼàşě֤r yişĕ̌kȧb֙ ʼeţ-kȧlá̇ţ֔⁠wò m֥wòţ yẇmĕţ֖ẇ şĕ̌néy⁠he֑m ţė֥bel ʻáş֖̂ẇ dĕ̇méy⁠he֥m báֽ̇⁠m׃"],[20,13,"וְ⁠אִ֗ישׁ אֲשֶׁ֨ר יִשְׁכַּ֤ב אֶת־זָכָר֙ מִשְׁכְּבֵ֣י אִשָּׁ֔ה תּוֹעֵבָ֥ה עָשׂ֖וּ שְׁנֵי⁠הֶ֑ם מ֥וֹת יוּמָ֖תוּ דְּמֵי⁠הֶ֥ם בָּֽ⁠ם׃","wĕ⁠ʼi֗yş̌ ʼàşě֨r yişĕ̌kȧ֤b ʼeţ-zákár֙ mişĕ̌kĕ̇bé֣y ʼişá̇̌֔h ţ̇wòʻébá֥h ʻáş֖̂ẇ şĕ̌néy⁠he֑m m֥wòţ yẇmá֖ţẇ dĕ̇méy⁠he֥m báֽ̇⁠m׃"],[20,14,"וְ⁠אִ֗ישׁ אֲשֶׁ֨ר יִקַּ֧ח אֶת־אִשָּׁ֛ה וְ⁠אֶת־אִמָּ֖⁠הּ זִמָּ֣ה הִ֑וא בָּ⁠אֵ֞שׁ יִשְׂרְפ֤וּ אֹת⁠וֹ֙ וְ⁠אֶתְ⁠הֶ֔ן וְ⁠לֹא־תִהְיֶ֥ה זִמָּ֖ה בְּ⁠תוֹכְ⁠כֶֽם׃","wĕ⁠ʼi֗yş̌ ʼàşě֨r yiqȧ֧ẖ ʼeţ-ʼişá֛̇̌h wĕ⁠ʼeţ-ʼimá֖̇⁠ḣ zimá֣̇h hi֑wʼ bá̇⁠ʼé֞ş̌ yişĕ̂rĕp֤ẇ ʼòţ⁠wò֙ wĕ⁠ʼeţĕ⁠he֔n wĕ⁠lòʼ-ţihĕye֥h zimá֖̇h bĕ̇⁠ţwòkĕ⁠keֽm׃"],[20,15,"וְ⁠אִ֗ישׁ אֲשֶׁ֨ר יִתֵּ֧ן שְׁכָבְתּ֛⁠וֹ בִּ⁠בְהֵמָ֖ה מ֣וֹת יוּמָ֑ת וְ⁠אֶת־הַ⁠בְּהֵמָ֖ה תַּהֲרֹֽגוּ׃","wĕ⁠ʼi֗yş̌ ʼàşě֨r yiţé֧̇n şĕ̌kábĕţ֛̇⁠wò bi̇⁠bĕhémá֖h m֣wòţ yẇmá֑ţ wĕ⁠ʼeţ-ha⁠bĕ̇hémá֖h ţȧhàròֽgẇ׃"],[20,16,"וְ⁠אִשָּׁ֗ה אֲשֶׁ֨ר תִּקְרַ֤ב אֶל־כָּל־בְּהֵמָה֙ לְ⁠רִבְעָ֣ה אֹתָ֔⁠הּ וְ⁠הָרַגְתָּ֥ אֶת־הָ⁠אִשָּׁ֖ה וְ⁠אֶת־הַ⁠בְּהֵמָ֑ה מ֥וֹת יוּמָ֖תוּ דְּמֵי⁠הֶ֥ם בָּֽ⁠ם׃","wĕ⁠ʼişá̇̌֗h ʼàşě֨r ţi̇qĕra֤b ʼel-ká̇l-bĕ̇hémáh֙ lĕ⁠ribĕʻá֣h ʼòţá֔⁠ḣ wĕ⁠háragĕţá֥̇ ʼeţ-há⁠ʼişá֖̇̌h wĕ⁠ʼeţ-ha⁠bĕ̇hémá֑h m֥wòţ yẇmá֖ţẇ dĕ̇méy⁠he֥m báֽ̇⁠m׃"],[20,17,"וְ⁠אִ֣ישׁ אֲשֶׁר־יִקַּ֣ח אֶת־אֲחֹת֡⁠וֹ בַּת־אָבִ֣י⁠ו א֣וֹ בַת־אִ֠מּ⁠וֹ וְ⁠רָאָ֨ה אֶת־עֶרְוָתָ֜⁠הּ וְ⁠הִֽיא־תִרְאֶ֤ה אֶת־עֶרְוָת⁠וֹ֙ חֶ֣סֶד ה֔וּא וְ⁠נִ֨כְרְת֔וּ לְ⁠עֵינֵ֖י בְּנֵ֣י עַמָּ֑⁠ם עֶרְוַ֧ת אֲחֹת֛⁠וֹ גִּלָּ֖ה עֲוֺנ֥⁠וֹ יִשָּֽׂא׃","wĕ⁠ʼi֣yş̌ ʼàşěr-yiqȧ֣ẖ ʼeţ-ʼàẖòţ֡⁠wò bȧţ-ʼábi֣y⁠w ʼ֣wò baţ-ʼi֠ṁ⁠wò wĕ⁠ráʼá֨h ʼeţ-ʻerĕwáţá֜⁠ḣ wĕ⁠hiֽyʼ-ţirĕʼe֤h ʼeţ-ʻerĕwáţ⁠wò֙ ẖe֣sed h֔ẇʼ wĕ⁠ni֨kĕrĕţ֔ẇ lĕ⁠ʻéyné֖y bĕ̇né֣y ʻamá֑̇⁠m ʻerĕwa֧ţ ʼàẖòţ֛⁠wò gi̇lá֖̇h ʻàwֺn֥⁠wò yişáֽ̇̂ʼ׃"],[20,18,"וְ֠⁠אִישׁ אֲשֶׁר־יִשְׁכַּ֨ב אֶת־אִשָּׁ֜ה דָּוָ֗ה וְ⁠גִלָּ֤ה אֶת־עֶרְוָתָ⁠הּ֙ אֶת־מְקֹרָ֣⁠הּ הֶֽעֱרָ֔ה וְ⁠הִ֕יא גִּלְּתָ֖ה אֶת־מְק֣וֹר דָּמֶ֑י⁠הָ וְ⁠נִכְרְת֥וּ שְׁנֵי⁠הֶ֖ם מִ⁠קֶּ֥רֶב עַמָּֽ⁠ם׃","wĕ֠⁠ʼiyş̌ ʼàşěr-yişĕ̌kȧ֨b ʼeţ-ʼişá̇̌֜h dá̇wá֗h wĕ⁠gilá֤̇h ʼeţ-ʻerĕwáţá⁠ḣ֙ ʼeţ-mĕqòrá֣⁠ḣ heֽʻèrá֔h wĕ⁠hi֕yʼ gi̇lĕ̇ţá֖h ʼeţ-mĕq֣wòr dá̇me֑y⁠há wĕ⁠nikĕrĕţ֥ẇ şĕ̌néy⁠he֖m mi⁠qė֥reb ʻamáֽ̇⁠m׃"],[20,19,"וְ⁠עֶרְוַ֨ת אֲח֧וֹת אִמְּ⁠ךָ֛ וַ⁠אֲח֥וֹת אָבִ֖י⁠ךָ לֹ֣א תְגַלֵּ֑ה כִּ֧י אֶת־שְׁאֵר֛⁠וֹ הֶעֱרָ֖ה עֲוֺנָ֥⁠ם יִשָּֽׂאוּ׃","wĕ⁠ʻerĕwa֨ţ ʼàẖ֧wòţ ʼimĕ̇⁠ká֛ wa⁠ʼàẖ֥wòţ ʼábi֖y⁠ká lò֣ʼ ţĕgalé֑̇h ki֧̇y ʼeţ-şĕ̌ʼér֛⁠wò heʻèrá֖h ʻàwֺná֥⁠m yişáֽ̇̂ʼẇ׃"],[20,20,"וְ⁠אִ֗ישׁ אֲשֶׁ֤ר יִשְׁכַּב֙ אֶת־דֹּ֣דָת֔⁠וֹ עֶרְוַ֥ת דֹּד֖⁠וֹ גִּלָּ֑ה חֶטְאָ֥⁠ם יִשָּׂ֖אוּ עֲרִירִ֥ים יָמֻֽתוּ׃","wĕ⁠ʼi֗yş̌ ʼàşě֤r yişĕ̌kȧb֙ ʼeţ-dò֣̇dáţ֔⁠wò ʻerĕwa֥ţ dò̇d֖⁠wò gi̇lá֑̇h ẖetĕʼá֥⁠m yişá֖̇̂ʼẇ ʻàriyri֥ym yámuֽţẇ׃"],[20,21,"וְ⁠אִ֗ישׁ אֲשֶׁ֥ר יִקַּ֛ח אֶת־אֵ֥שֶׁת אָחִ֖י⁠ו נִדָּ֣ה הִ֑וא עֶרְוַ֥ת אָחִ֛י⁠ו גִּלָּ֖ה עֲרִירִ֥ים יִהְיֽוּ׃","wĕ⁠ʼi֗yş̌ ʼàşě֥r yiqȧ֛ẖ ʼeţ-ʼé֥şěţ ʼáẖi֖y⁠w nidá֣̇h hi֑wʼ ʻerĕwa֥ţ ʼáẖi֛y⁠w gi̇lá֖̇h ʻàriyri֥ym yihĕyֽẇ׃"],[20,22,"וּ⁠שְׁמַרְתֶּ֤ם אֶת־כָּל־חֻקֹּתַ⁠י֙ וְ⁠אֶת־כָּל־מִשְׁפָּטַ֔⁠י וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם וְ⁠לֹא־תָקִ֤יא אֶתְ⁠כֶם֙ הָ⁠אָ֔רֶץ אֲשֶׁ֨ר אֲנִ֜י מֵבִ֥יא אֶתְ⁠כֶ֛ם שָׁ֖מָּ⁠ה לָ⁠שֶׁ֥בֶת בָּֽ⁠הּ׃","ẇ⁠şĕ̌marĕţė֤m ʼeţ-ká̇l-ẖuqò̇ţa⁠y֙ wĕ⁠ʼeţ-ká̇l-mişĕ̌pá̇ta֔⁠y wa⁠ʻàşîyţe֖m ʼòţá֑⁠m wĕ⁠lòʼ-ţáqi֤yʼ ʼeţĕ⁠kem֙ há⁠ʼá֔reẕ ʼàşě֨r ʼàni֜y mébi֥yʼ ʼeţĕ⁠ke֛m şá֖̌má̇⁠h lá⁠şě֥beţ báֽ̇⁠ḣ׃"],[20,23,"וְ⁠לֹ֤א תֵֽלְכוּ֙ בְּ⁠חֻקֹּ֣ת הַ⁠גּ֔וֹי אֲשֶׁר־אֲנִ֥י מְשַׁלֵּ֖חַ מִ⁠פְּנֵי⁠כֶ֑ם כִּ֤י אֶת־כָּל־אֵ֨לֶּה֙ עָשׂ֔וּ וָ⁠אָקֻ֖ץ בָּֽ⁠ם׃","wĕ⁠lò֤ʼ ţéֽlĕkẇ֙ bĕ̇⁠ẖuqò֣̇ţ ha⁠ġ֔wòy ʼàşěr-ʼàni֥y mĕşǎlé֖̇ẖa mi⁠pĕ̇néy⁠ke֑m ki֤̇y ʼeţ-ká̇l-ʼé֨lėh֙ ʻáş̂֔ẇ wá⁠ʼáqu֖ẕ báֽ̇⁠m׃"],[20,24,"וָ⁠אֹמַ֣ר לָ⁠כֶ֗ם אַתֶּם֮ תִּֽירְשׁ֣וּ אֶת־אַדְמָתָ⁠ם֒ וַ⁠אֲנִ֞י אֶתְּנֶ֤⁠נָּה לָ⁠כֶם֙ לָ⁠רֶ֣שֶׁת אֹתָ֔⁠הּ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָ֑שׁ אֲנִי֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם אֲשֶׁר־הִבְדַּ֥לְתִּי אֶתְ⁠כֶ֖ם מִן־הָֽ⁠עַמִּֽים׃","wá⁠ʼòma֣r lá⁠ke֗m ʼaţėm֮ ţiֽ̇yrĕş֣̌ẇ ʼeţ-ʼadĕmáţá⁠m֒ wa⁠ʼàni֞y ʼeţĕ̇ne֤⁠ná̇h lá⁠kem֙ lá⁠re֣şěţ ʼòţá֔⁠ḣ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbá֑ş̌ ʼàniy֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ʼàşěr-hibĕdȧ֥lĕţi̇y ʼeţĕ⁠ke֖m min-háֽ⁠ʻamiֽ̇ym׃"],[20,25,"וְ⁠הִבְדַּלְתֶּ֞ם בֵּֽין־הַ⁠בְּהֵמָ֤ה הַ⁠טְּהֹרָה֙ לַ⁠טְּמֵאָ֔ה וּ⁠בֵין־הָ⁠ע֥וֹף הַ⁠טָּמֵ֖א לַ⁠טָּהֹ֑ר וְ⁠לֹֽא־תְשַׁקְּצ֨וּ אֶת־נַפְשֹֽׁתֵי⁠כֶ֜ם בַּ⁠בְּהֵמָ֣ה וּ⁠בָ⁠ע֗וֹף וּ⁠בְ⁠כֹל֙ אֲשֶׁ֣ר תִּרְמֹ֣שׂ הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־הִבְדַּ֥לְתִּי לָ⁠כֶ֖ם לְ⁠טַמֵּֽא׃","wĕ⁠hibĕdȧlĕţė֞m béֽ̇yn-ha⁠bĕ̇hémá֤h ha⁠tĕ̇hòráh֙ la⁠tĕ̇méʼá֔h ẇ⁠béyn-há⁠ʻ֥wòp ha⁠tá̇mé֖ʼ la⁠tá̇hò֑r wĕ⁠lòֽʼ-ţĕşǎqĕ̇ẕ֨ẇ ʼeţ-napĕşòֽ̌ţéy⁠ke֜m bȧ⁠bĕ̇hémá֣h ẇ⁠bá⁠ʻ֗wòp ẇ⁠bĕ⁠kòl֙ ʼàşě֣r ţi̇rĕmò֣ş̂ háֽ⁠ʼàdámá֔h ʼàşěr-hibĕdȧ֥lĕţi̇y lá⁠ke֖m lĕ⁠taméֽ̇ʼ׃"],[20,26,"וִ⁠הְיִ֤יתֶם לִ⁠י֙ קְדֹשִׁ֔ים כִּ֥י קָד֖וֹשׁ אֲנִ֣י יְהוָ֑ה וָ⁠אַבְדִּ֥ל אֶתְ⁠כֶ֛ם מִן־הָֽ⁠עַמִּ֖ים לִ⁠הְי֥וֹת לִֽ⁠י׃","wi⁠hĕyi֤yţem li⁠y֙ qĕdòşǐ֔ym ki֥̇y qád֖wòş̌ ʼàni֣y yĕhwá֑h wá⁠ʼabĕdi֥̇l ʼeţĕ⁠ke֛m min-hֽá⁠ʻami֖̇ym li⁠hĕy֥wòţ liֽ⁠y׃"],[20,27,"וְ⁠אִ֣ישׁ אֽוֹ־אִשָּׁ֗ה כִּֽי־יִהְיֶ֨ה בָ⁠הֶ֥ם א֛וֹב א֥וֹ יִדְּעֹנִ֖י מ֣וֹת יוּמָ֑תוּ בָּ⁠אֶ֛בֶן יִרְגְּמ֥וּ אֹתָ֖⁠ם דְּמֵי⁠הֶ֥ם בָּֽ⁠ם׃פ","wĕ⁠ʼi֣yş̌ ʼֽwò-ʼişá̇̌֗h kiֽ̇y-yihĕye֨h bá⁠he֥m ʼ֛wòb ʼ֥wò yidĕ̇ʻòni֖y m֣wòţ yẇmá֑ţẇ bá̇⁠ʼe֛ben yirĕgĕ̇m֥ẇ ʼòţá֖⁠m dĕ̇méy⁠he֥m báֽ̇⁠m׃p"],[21,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה אֱמֹ֥ר אֶל־הַ⁠כֹּהֲנִ֖ים בְּנֵ֣י אַהֲרֹ֑ן וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם לְ⁠נֶ֥פֶשׁ לֹֽא־יִטַּמָּ֖א בְּ⁠עַמָּֽי⁠ו׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h ʼèmò֥r ʼel-ha⁠kò̇hàni֖ym bĕ̇né֣y ʼahàrò֑n wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m lĕ⁠ne֥peş̌ lòֽʼ-yitȧmá֖̇ʼ bĕ̇⁠ʻamáֽ̇y⁠w׃"],[21,2,"כִּ֚י אִם־לִ⁠שְׁאֵר֔⁠וֹ הַ⁠קָּרֹ֖ב אֵלָ֑י⁠ו לְ⁠אִמּ֣⁠וֹ וּ⁠לְ⁠אָבִ֔י⁠ו וְ⁠לִ⁠בְנ֥⁠וֹ וּ⁠לְ⁠בִתּ֖⁠וֹ וּ⁠לְ⁠אָחִֽי⁠ו׃","ki֚̇y ʼim-li⁠şĕ̌ʼér֔⁠wò ha⁠qá̇rò֖b ʼélá֑y⁠w lĕ⁠ʼiṁ֣⁠wò ẇ⁠lĕ⁠ʼábi֔y⁠w wĕ⁠li⁠bĕn֥⁠wò ẇ⁠lĕ⁠biţ֖̇⁠wò ẇ⁠lĕ⁠ʼáẖiֽy⁠w׃"],[21,3,"וְ⁠לַ⁠אֲחֹת֤⁠וֹ הַ⁠בְּתוּלָה֙ הַ⁠קְּרוֹבָ֣ה אֵלָ֔י⁠ו אֲשֶׁ֥ר לֹֽא־הָיְתָ֖ה לְ⁠אִ֑ישׁ לָ֖⁠הּ יִטַּמָּֽא׃","wĕ⁠la⁠ʼàẖòţ֤⁠wò ha⁠bĕ̇ţẇláh֙ ha⁠qĕ̇rwòbá֣h ʼélá֔y⁠w ʼàşě֥r lòֽʼ-háyĕţá֖h lĕ⁠ʼi֑yş̌ lá֖⁠ḣ yitȧmáֽ̇ʼ׃"],[21,4,"לֹ֥א יִטַּמָּ֖א בַּ֣עַל בְּ⁠עַמָּ֑י⁠ו לְ⁠הֵ֖חַלּֽ⁠וֹ׃","lò֥ʼ yitȧmá֖̇ʼ bȧ֣ʻal bĕ̇⁠ʻamá֑̇y⁠w lĕ⁠hé֖ẖalֽ̇⁠wò׃"],[21,5,"לֹֽא־יקרחה קָרְחָה֙ בְּ⁠רֹאשָׁ֔⁠ם וּ⁠פְאַ֥ת זְקָנָ֖⁠ם לֹ֣א יְגַלֵּ֑חוּ וּ⁠בִ֨⁠בְשָׂרָ֔⁠ם לֹ֥א יִשְׂרְט֖וּ שָׂרָֽטֶת׃","lòֽʼ-yqrẖh qárĕẖáh֙ bĕ̇⁠ròʼşá̌֔⁠m ẇ⁠pĕʼa֥ţ zĕqáná֖⁠m lò֣ʼ yĕgalé֑̇ẖẇ ẇ⁠bi֨⁠bĕşá̂rá֔⁠m lò֥ʼ yişĕ̂rĕt֖ẇ şá̂ráֽteţ׃"],[21,6,"קְדֹשִׁ֤ים יִהְיוּ֙ לֵ⁠אלֹ֣הֵי⁠הֶ֔ם וְ⁠לֹ֣א יְחַלְּל֔וּ שֵׁ֖ם אֱלֹהֵי⁠הֶ֑ם כִּי֩ אֶת־אִשֵּׁ֨י יְהוָ֜ה לֶ֧חֶם אֱלֹהֵי⁠הֶ֛ם הֵ֥ם מַקְרִיבִ֖ם וְ⁠הָ֥יוּ קֹֽדֶשׁ׃","qĕdòşǐ֤ym yihĕyẇ֙ lé⁠ʼlò֣héy⁠he֔m wĕ⁠lò֣ʼ yĕẖalĕ̇l֔ẇ şé֖̌m ʼèlòhéy⁠he֑m ki̇y֩ ʼeţ-ʼişé̇̌֨y yĕhwá֜h le֧ẖem ʼèlòhéy⁠he֛m hé֥m maqĕriybi֖m wĕ⁠há֥yẇ qòֽdeş̌׃"],[21,7,"אִשָּׁ֨ה זֹנָ֤ה וַ⁠חֲלָלָה֙ לֹ֣א יִקָּ֔חוּ וְ⁠אִשָּׁ֛ה גְּרוּשָׁ֥ה מֵ⁠אִישָׁ֖⁠הּ לֹ֣א יִקָּ֑חוּ כִּֽי־קָדֹ֥שׁ ה֖וּא לֵ⁠אלֹהָֽי⁠ו׃","ʼişá̇̌֨h zòná֤h wa⁠ẖàláláh֙ lò֣ʼ yiqá̇֔ẖẇ wĕ⁠ʼişá֛̇̌h gĕ̇rẇşá֥̌h mé⁠ʼiyşá֖̌⁠ḣ lò֣ʼ yiqá֑̇ẖẇ kiֽ̇y-qádò֥ş̌ h֖ẇʼ lé⁠ʼlòháֽy⁠w׃"],[21,8,"וְ⁠קִדַּשְׁתּ֔⁠וֹ כִּֽי־אֶת־לֶ֥חֶם אֱלֹהֶ֖י⁠ךָ ה֣וּא מַקְרִ֑יב קָדֹשׁ֙ יִֽהְיֶה־לָּ֔⁠ךְ כִּ֣י קָד֔וֹשׁ אֲנִ֥י יְהוָ֖ה מְקַדִּשְׁ⁠כֶֽם׃","wĕ⁠qidȧşĕ̌ţ̇֔⁠wò kiֽ̇y-ʼeţ-le֥ẖem ʼèlòhe֖y⁠ká h֣ẇʼ maqĕri֑yb qádòş̌֙ yiֽhĕyeh-lá̇֔⁠kĕ ki֣̇y qád֔wòş̌ ʼàni֥y yĕhwá֖h mĕqadi̇şĕ̌⁠keֽm׃"],[21,9,"וּ⁠בַת֙ אִ֣ישׁ כֹּהֵ֔ן כִּ֥י תֵחֵ֖ל לִ⁠זְנ֑וֹת אֶת־אָבִ֨י⁠הָ֙ הִ֣יא מְחַלֶּ֔לֶת בָּ⁠אֵ֖שׁ תִּשָּׂרֵֽף׃ס","ẇ⁠baţ֙ ʼi֣yş̌ kò̇hé֔n ki֥̇y ţéẖé֖l li⁠zĕn֑wòţ ʼeţ-ʼábi֨y⁠há֙ hi֣yʼ mĕẖalė֔leţ bá̇⁠ʼé֖ş̌ ţi̇şá̇̂réֽp׃s"],[21,10,"וְ⁠הַ⁠כֹּהֵן֩ הַ⁠גָּד֨וֹל מֵ⁠אֶחָ֜י⁠ו אֲֽשֶׁר־יוּצַ֥ק עַל־רֹאשׁ֣⁠וֹ ׀ שֶׁ֤מֶן הַ⁠מִּשְׁחָה֙ וּ⁠מִלֵּ֣א אֶת־יָד֔⁠וֹ לִ⁠לְבֹּ֖שׁ אֶת־הַ⁠בְּגָדִ֑ים אֶת־רֹאשׁ⁠וֹ֙ לֹ֣א יִפְרָ֔ע וּ⁠בְגָדָ֖י⁠ו לֹ֥א יִפְרֹֽם׃","wĕ⁠ha⁠kò̇hén֩ ha⁠gá̇d֨wòl mé⁠ʼeẖá֜y⁠w ʼàֽşěr-yẇẕa֥q ʻal-ròʼş֣̌⁠wò ׀ şě֤men ha⁠mi̇şĕ̌ẖáh֙ ẇ⁠milé֣̇ʼ ʼeţ-yád֔⁠wò li⁠lĕbò֖̇ş̌ ʼeţ-ha⁠bĕ̇gádi֑ym ʼeţ-ròʼş̌⁠wò֙ lò֣ʼ yipĕrá֔ʻ ẇ⁠bĕgádá֖y⁠w lò֥ʼ yipĕròֽm׃"],[21,11,"וְ⁠עַ֛ל כָּל־נַפְשֹׁ֥ת מֵ֖ת לֹ֣א יָבֹ֑א לְ⁠אָבִ֥י⁠ו וּ⁠לְ⁠אִמּ֖⁠וֹ לֹ֥א יִטַּמָּֽא׃","wĕ⁠ʻa֛l ká̇l-napĕşò֥̌ţ mé֖ţ lò֣ʼ yábò֑ʼ lĕ⁠ʼábi֥y⁠w ẇ⁠lĕ⁠ʼiṁ֖⁠wò lò֥ʼ yitȧmáֽ̇ʼ׃"],[21,12,"וּ⁠מִן־הַ⁠מִּקְדָּשׁ֙ לֹ֣א יֵצֵ֔א וְ⁠לֹ֣א יְחַלֵּ֔ל אֵ֖ת מִקְדַּ֣שׁ אֱלֹהָ֑י⁠ו כִּ֡י נֵ֠זֶר שֶׁ֣מֶן מִשְׁחַ֧ת אֱלֹהָ֛י⁠ו עָלָ֖י⁠ו אֲנִ֥י יְהוָֽה׃","ẇ⁠min-ha⁠mi̇qĕdá̇ş̌֙ lò֣ʼ yéẕé֔ʼ wĕ⁠lò֣ʼ yĕẖalé̇֔l ʼé֖ţ miqĕdȧ֣ş̌ ʼèlòhá֑y⁠w ki̇֡y né֠zer şě֣men mişĕ̌ẖa֧ţ ʼèlòhá֛y⁠w ʻálá֖y⁠w ʼàni֥y yĕhwáֽh׃"],[21,13,"וְ⁠ה֕וּא אִשָּׁ֥ה בִ⁠בְתוּלֶ֖י⁠הָ יִקָּֽח׃","wĕ⁠h֕ẇʼ ʼişá֥̇̌h bi⁠bĕţẇle֖y⁠há yiqáֽ̇ẖ׃"],[21,14,"אַלְמָנָ֤ה וּ⁠גְרוּשָׁה֙ וַ⁠חֲלָלָ֣ה זֹנָ֔ה אֶת־אֵ֖לֶּה לֹ֣א יִקָּ֑ח כִּ֛י אִם־בְּתוּלָ֥ה מֵ⁠עַמָּ֖י⁠ו יִקַּ֥ח אִשָּֽׁה׃","ʼalĕmáná֤h ẇ⁠gĕrẇşá̌h֙ wa⁠ẖàlálá֣h zòná֔h ʼeţ-ʼé֖lėh lò֣ʼ yiqá֑̇ẖ ki֛̇y ʼim-bĕ̇ţẇlá֥h mé⁠ʻamá֖̇y⁠w yiqȧ֥ẖ ʼişáֽ̇̌h׃"],[21,15,"וְ⁠לֹֽא־יְחַלֵּ֥ל זַרְע֖⁠וֹ בְּ⁠עַמָּ֑י⁠ו כִּ֛י אֲנִ֥י יְהוָ֖ה מְקַדְּשֽׁ⁠וֹ׃פ","wĕ⁠lòֽʼ-yĕẖalé֥̇l zarĕʻ֖⁠wò bĕ̇⁠ʻamá֑̇y⁠w ki֛̇y ʼàni֥y yĕhwá֖h mĕqadĕ̇şֽ̌⁠wò׃p"],[21,16,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[21,17,"דַּבֵּ֥ר אֶֽל־אַהֲרֹ֖ן לֵ⁠אמֹ֑ר אִ֣ישׁ מִֽ⁠זַּרְעֲ⁠ךָ֞ לְ⁠דֹרֹתָ֗⁠ם אֲשֶׁ֨ר יִהְיֶ֥ה ב⁠וֹ֙ מ֔וּם לֹ֣א יִקְרַ֔ב לְ⁠הַקְרִ֖יב לֶ֥חֶם אֱלֹהָֽי⁠ו׃","dȧbé֥̇r ʼeֽl-ʼahàrò֖n lé⁠ʼmò֑r ʼi֣yş̌ miֽ⁠zȧrĕʻà⁠ká֞ lĕ⁠dòròţá֗⁠m ʼàşě֨r yihĕye֥h b⁠wò֙ m֔ẇm lò֣ʼ yiqĕra֔b lĕ⁠haqĕri֖yb le֥ẖem ʼèlòháֽy⁠w׃"],[21,18,"כִּ֥י כָל־אִ֛ישׁ אֲשֶׁר־בּ֥⁠וֹ מ֖וּם לֹ֣א יִקְרָ֑ב אִ֤ישׁ עִוֵּר֙ א֣וֹ פִסֵּ֔חַ א֥וֹ חָרֻ֖ם א֥וֹ שָׂרֽוּעַ׃","ki֥̇y kál-ʼi֛yş̌ ʼàşěr-ḃ֥⁠wò m֖ẇm lò֣ʼ yiqĕrá֑b ʼi֤yş̌ ʻiwé̇r֙ ʼ֣wò pisé̇֔ẖa ʼ֥wò ẖáru֖m ʼ֥wò şá̂rֽẇʻa׃"],[21,19,"א֣וֹ אִ֔ישׁ אֲשֶׁר־יִהְיֶ֥ה ב֖⁠וֹ שֶׁ֣בֶר רָ֑גֶל א֖וֹ שֶׁ֥בֶר יָֽד׃","ʼ֣wò ʼi֔yş̌ ʼàşěr-yihĕye֥h b֖⁠wò şě֣ber rá֑gel ʼ֖wò şě֥ber yáֽd׃"],[21,20,"אֽוֹ־גִבֵּ֣ן אוֹ־דַ֔ק א֖וֹ תְּבַלֻּ֣ל בְּ⁠עֵינ֑⁠וֹ א֤וֹ גָרָב֙ א֣וֹ יַלֶּ֔פֶת א֖וֹ מְר֥וֹחַ אָֽשֶׁךְ׃","ʼֽwò-gibé֣̇n ʼwò-da֔q ʼ֖wò ţĕ̇balu֣̇l bĕ̇⁠ʻéyn֑⁠wò ʼ֤wò gáráb֙ ʼ֣wò yalė֔peţ ʼ֖wò mĕr֥wòẖa ʼáֽşěkĕ׃"],[21,21,"כָּל־אִ֞ישׁ אֲשֶׁר־בּ֣⁠וֹ מ֗וּם מִ⁠זֶּ֨רַע֙ אַהֲרֹ֣ן הַ⁠כֹּהֵ֔ן לֹ֣א יִגַּ֔שׁ לְ⁠הַקְרִ֖יב אֶת־אִשֵּׁ֣י יְהוָ֑ה מ֣וּם בּ֔⁠וֹ אֵ֚ת לֶ֣חֶם אֱלֹהָ֔י⁠ו לֹ֥א יִגַּ֖שׁ לְ⁠הַקְרִֽיב׃","ká̇l-ʼi֞yş̌ ʼàşěr-ḃ֣⁠wò m֗ẇm mi⁠zė֨raʻ֙ ʼahàrò֣n ha⁠kò̇hé֔n lò֣ʼ yigȧ֔ş̌ lĕ⁠haqĕri֖yb ʼeţ-ʼişé֣̇̌y yĕhwá֑h m֣ẇm ḃ֔⁠wò ʼé֚ţ le֣ẖem ʼèlòhá֔y⁠w lò֥ʼ yigȧ֖ş̌ lĕ⁠haqĕriֽyb׃"],[21,22,"לֶ֣חֶם אֱלֹהָ֔י⁠ו מִ⁠קָּדְשֵׁ֖י הַ⁠קֳּדָשִׁ֑ים וּ⁠מִן־הַ⁠קֳּדָשִׁ֖ים יֹאכֵֽל׃","le֣ẖem ʼèlòhá֔y⁠w mi⁠qá̇dĕşé֖̌y ha⁠qȯdáşǐ֑ym ẇ⁠min-ha⁠qȯdáşǐ֖ym yòʼkéֽl׃"],[21,23,"אַ֣ךְ אֶל־הַ⁠פָּרֹ֜כֶת לֹ֣א יָבֹ֗א וְ⁠אֶל־הַ⁠מִּזְבֵּ֛חַ לֹ֥א יִגַּ֖שׁ כִּֽי־מ֣וּם בּ֑⁠וֹ וְ⁠לֹ֤א יְחַלֵּל֙ אֶת־מִקְדָּשַׁ֔⁠י כִּ֛י אֲנִ֥י יְהוָ֖ה מְקַדְּשָֽׁ⁠ם׃","ʼa֣kĕ ʼel-ha⁠pá̇rò֜keţ lò֣ʼ yábò֗ʼ wĕ⁠ʼel-ha⁠mi̇zĕbé֛̇ẖa lò֥ʼ yigȧ֖ş̌ kiֽ̇y-m֣ẇm ḃ֑⁠wò wĕ⁠lò֤ʼ yĕẖalé̇l֙ ʼeţ-miqĕdá̇şǎ֔⁠y ki֛̇y ʼàni֥y yĕhwá֖h mĕqadĕ̇şáֽ̌⁠m׃"],[21,24,"וַ⁠יְדַבֵּ֣ר מֹשֶׁ֔ה אֶֽל־אַהֲרֹ֖ן וְ⁠אֶל־בָּנָ֑י⁠ו וְ⁠אֶֽל־כָּל־בְּנֵ֖י יִשְׂרָאֵֽל׃פ","wa⁠yĕdabé֣̇r mòşě֔h ʼeֽl-ʼahàrò֖n wĕ⁠ʼel-bá̇ná֑y⁠w wĕ⁠ʼeֽl-ká̇l-bĕ̇né֖y yişĕ̂ráʼéֽl׃p"],[22,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[22,2,"דַּבֵּ֨ר אֶֽל־אַהֲרֹ֜ן וְ⁠אֶל־בָּנָ֗י⁠ו וְ⁠יִנָּֽזְרוּ֙ מִ⁠קָּדְשֵׁ֣י בְנֵֽי־יִשְׂרָאֵ֔ל וְ⁠לֹ֥א יְחַלְּל֖וּ אֶת־שֵׁ֣ם קָדְשִׁ֑⁠י אֲשֶׁ֨ר הֵ֧ם מַקְדִּשִׁ֛ים לִ֖⁠י אֲנִ֥י יְהוָֽה׃","dȧbé̇֨r ʼeֽl-ʼahàrò֜n wĕ⁠ʼel-bá̇ná֗y⁠w wĕ⁠yináֽ̇zĕrẇ֙ mi⁠qá̇dĕşé֣̌y bĕnéֽy-yişĕ̂ráʼé֔l wĕ⁠lò֥ʼ yĕẖalĕ̇l֖ẇ ʼeţ-şé֣̌m qádĕşǐ֑⁠y ʼàşě֨r hé֧m maqĕdi̇şǐ֛ym li֖⁠y ʼàni֥y yĕhwáֽh׃"],[22,3,"אֱמֹ֣ר אֲלֵ⁠הֶ֗ם לְ⁠דֹרֹ֨תֵי⁠כֶ֜ם כָּל־אִ֣ישׁ ׀ אֲשֶׁר־יִקְרַ֣ב מִ⁠כָּל־זַרְעֲ⁠כֶ֗ם אֶל־הַ⁠קֳּדָשִׁים֙ אֲשֶׁ֨ר יַקְדִּ֤ישׁוּ בְנֵֽי־יִשְׂרָאֵל֙ לַֽ⁠יהוָ֔ה וְ⁠טֻמְאָת֖⁠וֹ עָלָ֑י⁠ו וְ⁠נִכְרְתָ֞ה הַ⁠נֶּ֧פֶשׁ הַ⁠הִ֛וא מִ⁠לְּ⁠פָנַ֖⁠י אֲנִ֥י יְהוָֽה׃","ʼèmò֣r ʼàlé⁠he֗m lĕ⁠dòrò֨ţéy⁠ke֜m ká̇l-ʼi֣yş̌ ׀ ʼàşěr-yiqĕra֣b mi⁠ká̇l-zarĕʻà⁠ke֗m ʼel-ha⁠qȯdáşǐym֙ ʼàşě֨r yaqĕdi֤̇yş̌ẇ bĕnéֽy-yişĕ̂ráʼél֙ laֽ⁠yhwá֔h wĕ⁠tumĕʼáţ֖⁠wò ʻálá֑y⁠w wĕ⁠nikĕrĕţá֞h ha⁠nė֧peş̌ ha⁠hi֛wʼ mi⁠lĕ̇⁠pána֖⁠y ʼàni֥y yĕhwáֽh׃"],[22,4,"אִ֣ישׁ אִ֞ישׁ מִ⁠זֶּ֣רַע אַהֲרֹ֗ן וְ⁠ה֤וּא צָר֨וּעַ֙ א֣וֹ זָ֔ב בַּ⁠קֳּדָשִׁים֙ לֹ֣א יֹאכַ֔ל עַ֖ד אֲשֶׁ֣ר יִטְהָ֑ר וְ⁠הַ⁠נֹּגֵ֨עַ֙ בְּ⁠כָל־טְמֵא־נֶ֔פֶשׁ א֣וֹ אִ֔ישׁ אֲשֶׁר־תֵּצֵ֥א מִמֶּ֖⁠נּוּ שִׁכְבַת־זָֽרַע׃","ʼi֣yş̌ ʼi֞yş̌ mi⁠zė֣raʻ ʼahàrò֗n wĕ⁠h֤ẇʼ ẕár֨ẇʻa֙ ʼ֣wò zá֔b bȧ⁠qȯdáşǐym֙ lò֣ʼ yòʼka֔l ʻa֖d ʼàşě֣r yitĕhá֑r wĕ⁠ha⁠nò̇gé֨ʻa֙ bĕ̇⁠kál-tĕméʼ-ne֔peş̌ ʼ֣wò ʼi֔yş̌ ʼàşěr-ţé̇ẕé֥ʼ mimė֖⁠ṅẇ şǐkĕbaţ-záֽraʻ׃"],[22,5,"אוֹ־אִישׁ֙ אֲשֶׁ֣ר יִגַּ֔ע בְּ⁠כָל־שֶׁ֖רֶץ אֲשֶׁ֣ר יִטְמָא־ל֑⁠וֹ א֤וֹ בְ⁠אָדָם֙ אֲשֶׁ֣ר יִטְמָא־ל֔⁠וֹ לְ⁠כֹ֖ל טֻמְאָתֽ⁠וֹ׃","ʼwò-ʼiyş̌֙ ʼàşě֣r yigȧ֔ʻ bĕ̇⁠kál-şě֖reẕ ʼàşě֣r yitĕmáʼ-l֑⁠wò ʼ֤wò bĕ⁠ʼádám֙ ʼàşě֣r yitĕmáʼ-l֔⁠wò lĕ⁠kò֖l tumĕʼáţֽ⁠wò׃"],[22,6,"נֶ֚פֶשׁ אֲשֶׁ֣ר תִּגַּע־בּ֔⁠וֹ וְ⁠טָמְאָ֖ה עַד־הָ⁠עָ֑רֶב וְ⁠לֹ֤א יֹאכַל֙ מִן־הַ⁠קֳּדָשִׁ֔ים כִּ֛י אִם־רָחַ֥ץ בְּשָׂר֖⁠וֹ בַּ⁠מָּֽיִם׃","ne֚peş̌ ʼàşě֣r ţi̇gȧʻ-ḃ֔⁠wò wĕ⁠támĕʼá֖h ʻad-há⁠ʻá֑reb wĕ⁠lò֤ʼ yòʼkal֙ min-ha⁠qȯdáşǐ֔ym ki֛̇y ʼim-ráẖa֥ẕ bĕ̇şá̂r֖⁠wò bȧ⁠máֽ̇yim׃"],[22,7,"וּ⁠בָ֥א הַ⁠שֶּׁ֖מֶשׁ וְ⁠טָהֵ֑ר וְ⁠אַחַר֙ יֹאכַ֣ל מִן־הַ⁠קֳּדָשִׁ֔ים כִּ֥י לַחְמ֖⁠וֹ הֽוּא׃","ẇ⁠bá֥ʼ ha⁠şė֖̌meş̌ wĕ⁠táhé֑r wĕ⁠ʼaẖar֙ yòʼka֣l min-ha⁠qȯdáşǐ֔ym ki֥̇y laẖĕm֖⁠wò hֽẇʼ׃"],[22,8,"נְבֵלָ֧ה וּ⁠טְרֵפָ֛ה לֹ֥א יֹאכַ֖ל לְ⁠טָמְאָה־בָ֑⁠הּ אֲנִ֖י יְהוָֽה׃","nĕbélá֧h ẇ⁠tĕrépá֛h lò֥ʼ yòʼka֖l lĕ⁠támĕʼáh-bá֑⁠ḣ ʼàni֖y yĕhwáֽh׃"],[22,9,"וְ⁠שָׁמְר֣וּ אֶת־מִשְׁמַרְתִּ֗⁠י וְ⁠לֹֽא־יִשְׂא֤וּ עָלָי⁠ו֙ חֵ֔טְא וּ⁠מֵ֥תוּ ב֖⁠וֹ כִּ֣י יְחַלְּלֻ֑⁠הוּ אֲנִ֥י יְהוָ֖ה מְקַדְּשָֽׁ⁠ם׃","wĕ⁠şá̌mĕr֣ẇ ʼeţ-mişĕ̌marĕţi̇֗⁠y wĕ⁠lòֽʼ-yişĕ̂ʼ֤ẇ ʻáláy⁠w֙ ẖé֔tĕʼ ẇ⁠mé֥ţẇ b֖⁠wò ki֣̇y yĕẖalĕ̇lu֑⁠hẇ ʼàni֥y yĕhwá֖h mĕqadĕ̇şáֽ̌⁠m׃"],[22,10,"וְ⁠כָל־זָ֖ר לֹא־יֹ֣אכַל קֹ֑דֶשׁ תּוֹשַׁ֥ב כֹּהֵ֛ן וְ⁠שָׂכִ֖יר לֹא־יֹ֥אכַל קֹֽדֶשׁ׃","wĕ⁠kál-zá֖r lòʼ-yò֣ʼkal qò֑deş̌ ţ̇wòşǎ֥b kò̇hé֛n wĕ⁠şá̂ki֖yr lòʼ-yò֥ʼkal qòֽdeş̌׃"],[22,11,"וְ⁠כֹהֵ֗ן כִּֽי־יִקְנֶ֥ה נֶ֨פֶשׁ֙ קִנְיַ֣ן כַּסְפּ֔⁠וֹ ה֖וּא יֹ֣אכַל בּ֑⁠וֹ וִ⁠ילִ֣יד בֵּית֔⁠וֹ הֵ֖ם יֹאכְל֥וּ בְ⁠לַחְמֽ⁠וֹ׃","wĕ⁠kòhé֗n kiֽ̇y-yiqĕne֥h ne֨peş̌֙ qinĕya֣n kȧsĕṗ֔⁠wò h֖ẇʼ yò֣ʼkal ḃ֑⁠wò wi⁠yli֣yd bé̇yţ֔⁠wò hé֖m yòʼkĕl֥ẇ bĕ⁠laẖĕmֽ⁠wò׃"],[22,12,"וּ⁠בַת־כֹּהֵ֔ן כִּ֥י תִהְיֶ֖ה לְ⁠אִ֣ישׁ זָ֑ר הִ֕וא בִּ⁠תְרוּמַ֥ת הַ⁠קֳּדָשִׁ֖ים לֹ֥א תֹאכֵֽל׃","ẇ⁠baţ-kò̇hé֔n ki֥̇y ţihĕye֖h lĕ⁠ʼi֣yş̌ zá֑r hi֕wʼ bi̇⁠ţĕrẇma֥ţ ha⁠qȯdáşǐ֖ym lò֥ʼ ţòʼkéֽl׃"],[22,13,"וּ⁠בַת־כֹּהֵן֩ כִּ֨י תִהְיֶ֜ה אַלְמָנָ֣ה וּ⁠גְרוּשָׁ֗ה וְ⁠זֶרַע֮ אֵ֣ין לָ⁠הּ֒ וְ⁠שָׁבָ֞ה אֶל־בֵּ֤ית אָבִ֨י⁠הָ֙ כִּ⁠נְעוּרֶ֔י⁠הָ מִ⁠לֶּ֥חֶם אָבִ֖י⁠הָ תֹּאכֵ֑ל וְ⁠כָל־זָ֖ר לֹא־יֹ֥אכַל בּֽ⁠וֹ׃ס","ẇ⁠baţ-kò̇hén֩ ki̇֨y ţihĕye֜h ʼalĕmáná֣h ẇ⁠gĕrẇşá̌֗h wĕ⁠zeraʻ֮ ʼé֣yn lá⁠ḣ֒ wĕ⁠şá̌bá֞h ʼel-bé֤̇yţ ʼábi֨y⁠há֙ ki̇⁠nĕʻẇre֔y⁠há mi⁠lė֥ẖem ʼábi֖y⁠há ţò̇ʼké֑l wĕ⁠kál-zá֖r lòʼ-yò֥ʼkal ḃֽ⁠wò׃s"],[22,14,"וְ⁠אִ֕ישׁ כִּֽי־יֹאכַ֥ל קֹ֖דֶשׁ בִּ⁠שְׁגָגָ֑ה וְ⁠יָסַ֤ף חֲמִֽשִׁית⁠וֹ֙ עָלָ֔י⁠ו וְ⁠נָתַ֥ן לַ⁠כֹּהֵ֖ן אֶת־הַ⁠קֹּֽדֶשׁ׃","wĕ⁠ʼi֕yş̌ kiֽ̇y-yòʼka֥l qò֖deş̌ bi̇⁠şĕ̌gágá֑h wĕ⁠yása֤p ẖàmiֽşǐyţ⁠wò֙ ʻálá֔y⁠w wĕ⁠náţa֥n la⁠kò̇hé֖n ʼeţ-ha⁠qòֽ̇deş̌׃"],[22,15,"וְ⁠לֹ֣א יְחַלְּל֔וּ אֶת־קָדְשֵׁ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל אֵ֥ת אֲשֶׁר־יָרִ֖ימוּ לַ⁠יהוָֽה׃","wĕ⁠lò֣ʼ yĕẖalĕ̇l֔ẇ ʼeţ-qádĕşé֖̌y bĕ̇né֣y yişĕ̂ráʼé֑l ʼé֥ţ ʼàşěr-yári֖ymẇ la⁠yhwáֽh׃"],[22,16,"וְ⁠הִשִּׂ֤יאוּ אוֹתָ⁠ם֙ עֲוֺ֣ן אַשְׁמָ֔ה בְּ⁠אָכְלָ֖⁠ם אֶת־קָדְשֵׁי⁠הֶ֑ם כִּ֛י אֲנִ֥י יְהוָ֖ה מְקַדְּשָֽׁ⁠ם׃פ","wĕ⁠hişi֤̇̂yʼẇ ʼwòţá⁠m֙ ʻàwֺ֣n ʼaşĕ̌má֔h bĕ̇⁠ʼákĕlá֖⁠m ʼeţ-qádĕşé̌y⁠he֑m ki֛̇y ʼàni֥y yĕhwá֖h mĕqadĕ̇şáֽ̌⁠m׃p"],[22,17,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[22,18,"דַּבֵּ֨ר אֶֽל־אַהֲרֹ֜ן וְ⁠אֶל־בָּנָ֗י⁠ו וְ⁠אֶל֙ כָּל־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠אָמַרְתָּ֖ אֲלֵ⁠הֶ֑ם אִ֣ישׁ אִישׁ֩ מִ⁠בֵּ֨ית יִשְׂרָאֵ֜ל וּ⁠מִן־הַ⁠גֵּ֣ר בְּ⁠יִשְׂרָאֵ֗ל אֲשֶׁ֨ר יַקְרִ֤יב קָרְבָּנ⁠וֹ֙ לְ⁠כָל־נִדְרֵי⁠הֶם֙ וּ⁠לְ⁠כָל־נִדְבוֹתָ֔⁠ם אֲשֶׁר־יַקְרִ֥יבוּ לַ⁠יהוָ֖ה לְ⁠עֹלָֽה׃","dȧbé̇֨r ʼeֽl-ʼahàrò֜n wĕ⁠ʼel-bá̇ná֗y⁠w wĕ⁠ʼel֙ ká̇l-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠ʼámarĕţá֖̇ ʼàlé⁠he֑m ʼi֣yş̌ ʼiyş̌֩ mi⁠bé̇֨yţ yişĕ̂ráʼé֜l ẇ⁠min-ha⁠gé֣̇r bĕ̇⁠yişĕ̂ráʼé֗l ʼàşě֨r yaqĕri֤yb qárĕbá̇n⁠wò֙ lĕ⁠kál-nidĕréy⁠hem֙ ẇ⁠lĕ⁠kál-nidĕbwòţá֔⁠m ʼàşěr-yaqĕri֥ybẇ la⁠yhwá֖h lĕ⁠ʻòláֽh׃"],[22,19,"לִֽ⁠רְצֹנְ⁠כֶ֑ם תָּמִ֣ים זָכָ֔ר בַּ⁠בָּקָ֕ר בַּ⁠כְּשָׂבִ֖ים וּ⁠בָֽ⁠עִזִּֽים׃","liֽ⁠rĕẕònĕ⁠ke֑m ţá̇mi֣ym záká֔r bȧ⁠bá̇qá֕r bȧ⁠kĕ̇şá̂bi֖ym ẇ⁠báֽ⁠ʻiziֽ̇ym׃"],[22,20,"כֹּ֛ל אֲשֶׁר־בּ֥⁠וֹ מ֖וּם לֹ֣א תַקְרִ֑יבוּ כִּי־לֹ֥א לְ⁠רָצ֖וֹן יִהְיֶ֥ה לָ⁠כֶֽם׃","kò֛̇l ʼàşěr-ḃ֥⁠wò m֖ẇm lò֣ʼ ţaqĕri֑ybẇ ki̇y-lò֥ʼ lĕ⁠ráẕ֖wòn yihĕye֥h lá⁠keֽm׃"],[22,21,"וְ⁠אִ֗ישׁ כִּֽי־יַקְרִ֤יב זֶֽבַח־שְׁלָמִים֙ לַ⁠יהוָ֔ה לְ⁠פַלֵּא־נֶ֨דֶר֙ א֣וֹ לִ⁠נְדָבָ֔ה בַּ⁠בָּקָ֖ר א֣וֹ בַ⁠צֹּ֑אן תָּמִ֤ים יִֽהְיֶה֙ לְ⁠רָצ֔וֹן כָּל־מ֖וּם לֹ֥א יִהְיֶה־בּֽ⁠וֹ׃","wĕ⁠ʼi֗yş̌ kiֽ̇y-yaqĕri֤yb zeֽbaẖ-şĕ̌lámiym֙ la⁠yhwá֔h lĕ⁠palé̇ʼ-ne֨der֙ ʼ֣wò li⁠nĕdábá֔h bȧ⁠bá̇qá֖r ʼ֣wò ba⁠ẕò֑̇ʼn ţá̇mi֤ym yiֽhĕyeh֙ lĕ⁠ráẕ֔wòn ká̇l-m֖ẇm lò֥ʼ yihĕyeh-ḃֽ⁠wò׃"],[22,22,"עַוֶּרֶת֩ א֨וֹ שָׁב֜וּר אוֹ־חָר֣וּץ אֽוֹ־יַבֶּ֗לֶת א֤וֹ גָרָב֙ א֣וֹ יַלֶּ֔פֶת לֹא־תַקְרִ֥יבוּ אֵ֖לֶּה לַ⁠יהוָ֑ה וְ⁠אִשֶּׁ֗ה לֹא־תִתְּנ֥וּ מֵ⁠הֶ֛ם עַל־הַ⁠מִּזְבֵּ֖חַ לַ⁠יהוָֽה׃","ʻawėreţ֩ ʼ֨wò şá̌b֜ẇr ʼwò-ẖár֣ẇẕ ʼֽwò-yabė֗leţ ʼ֤wò gáráb֙ ʼ֣wò yalė֔peţ lòʼ-ţaqĕri֥ybẇ ʼé֖lėh la⁠yhwá֑h wĕ⁠ʼişė̌֗h lòʼ-ţiţĕ̇n֥ẇ mé⁠he֛m ʻal-ha⁠mi̇zĕbé֖̇ẖa la⁠yhwáֽh׃"],[22,23,"וְ⁠שׁ֥וֹר וָ⁠שֶׂ֖ה שָׂר֣וּעַ וְ⁠קָל֑וּט נְדָבָה֙ תַּעֲשֶׂ֣ה אֹת֔⁠וֹ וּ⁠לְ⁠נֵ֖דֶר לֹ֥א יֵרָצֶֽה׃","wĕ⁠ş֥̌wòr wá⁠şê֖h şá̂r֣ẇʻa wĕ⁠qál֑ẇt nĕdábáh֙ ţȧʻàşê֣h ʼòţ֔⁠wò ẇ⁠lĕ⁠né֖der lò֥ʼ yéráẕeֽh׃"],[22,24,"וּ⁠מָע֤וּךְ וְ⁠כָתוּת֙ וְ⁠נָת֣וּק וְ⁠כָר֔וּת לֹ֥א תַקְרִ֖יבוּ לַֽ⁠יהוָ֑ה וּֽ⁠בְ⁠אַרְצְ⁠כֶ֖ם לֹ֥א תַעֲשֽׂוּ׃","ẇ⁠máʻ֤ẇkĕ wĕ⁠káţẇţ֙ wĕ⁠náţ֣ẇq wĕ⁠kár֔ẇţ lò֥ʼ ţaqĕri֖ybẇ laֽ⁠yhwá֑h ẇֽ⁠bĕ⁠ʼarĕẕĕ⁠ke֖m lò֥ʼ ţaʻàşֽ̂ẇ׃"],[22,25,"וּ⁠מִ⁠יַּ֣ד בֶּן־נֵכָ֗ר לֹ֥א תַקְרִ֛יבוּ אֶת־לֶ֥חֶם אֱלֹהֵי⁠כֶ֖ם מִ⁠כָּל־אֵ֑לֶּה כִּ֣י מָשְׁחָתָ֤⁠ם בָּ⁠הֶם֙ מ֣וּם בָּ֔⁠ם לֹ֥א יֵרָצ֖וּ לָ⁠כֶֽם׃פ","ẇ⁠mi⁠yȧ֣d bėn-néká֗r lò֥ʼ ţaqĕri֛ybẇ ʼeţ-le֥ẖem ʼèlòhéy⁠ke֖m mi⁠ká̇l-ʼé֑lėh ki֣̇y máşĕ̌ẖáţá֤⁠m bá̇⁠hem֙ m֣ẇm bá̇֔⁠m lò֥ʼ yéráẕ֖ẇ lá⁠keֽm׃p"],[22,26,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[22,27,"שׁ֣וֹר אוֹ־כֶ֤שֶׂב אוֹ־עֵז֙ כִּ֣י יִוָּלֵ֔ד וְ⁠הָיָ֛ה שִׁבְעַ֥ת יָמִ֖ים תַּ֣חַת אִמּ֑⁠וֹ וּ⁠מִ⁠יּ֤וֹם הַ⁠שְּׁמִינִי֙ וָ⁠הָ֔לְאָה יֵרָצֶ֕ה לְ⁠קָרְבַּ֥ן אִשֶּׁ֖ה לַ⁠יהוָֽה׃","ş֣̌wòr ʼwò-ke֤şêb ʼwò-ʻéz֙ ki֣̇y yiwá̇lé֔d wĕ⁠háyá֛h şǐbĕʻa֥ţ yámi֖ym ţȧ֣ẖaţ ʼiṁ֑⁠wò ẇ⁠mi⁠ẏ֤wòm ha⁠şĕ̇̌miyniy֙ wá⁠há֔lĕʼáh yéráẕe֕h lĕ⁠qárĕbȧ֥n ʼişė֖̌h la⁠yhwáֽh׃"],[22,28,"וְ⁠שׁ֖וֹר אוֹ־שֶׂ֑ה אֹת֣⁠וֹ וְ⁠אֶת־בְּנ֔⁠וֹ לֹ֥א תִשְׁחֲט֖וּ בְּ⁠י֥וֹם אֶחָֽד׃","wĕ⁠ş֖̌wòr ʼwò-şê֑h ʼòţ֣⁠wò wĕ⁠ʼeţ-bĕ̇n֔⁠wò lò֥ʼ ţişĕ̌ẖàt֖ẇ bĕ̇⁠y֥wòm ʼeẖáֽd׃"],[22,29,"וְ⁠כִֽי־תִזְבְּח֥וּ זֶֽבַח־תּוֹדָ֖ה לַ⁠יהוָ֑ה לִֽ⁠רְצֹנְ⁠כֶ֖ם תִּזְבָּֽחוּ׃","wĕ⁠kiֽy-ţizĕbĕ̇ẖ֥ẇ zeֽbaẖ-ţ̇wòdá֖h la⁠yhwá֑h liֽ⁠rĕẕònĕ⁠ke֖m ţi̇zĕbáֽ̇ẖẇ׃"],[22,30,"בַּ⁠יּ֤וֹם הַ⁠הוּא֙ יֵאָכֵ֔ל לֹֽא־תוֹתִ֥ירוּ מִמֶּ֖⁠נּוּ עַד־בֹּ֑קֶר אֲנִ֖י יְהוָֽה׃","bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ yéʼáké֔l lòֽʼ-ţwòţi֥yrẇ mimė֖⁠ṅẇ ʻad-bò֑̇qer ʼàni֖y yĕhwáֽh׃"],[22,31,"וּ⁠שְׁמַרְתֶּם֙ מִצְוֺתַ֔⁠י וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם אֲנִ֖י יְהוָֽה׃","ẇ⁠şĕ̌marĕţėm֙ miẕĕwֺţa֔⁠y wa⁠ʻàşîyţe֖m ʼòţá֑⁠m ʼàni֖y yĕhwáֽh׃"],[22,32,"וְ⁠לֹ֤א תְחַלְּלוּ֙ אֶת־שֵׁ֣ם קָדְשִׁ֔⁠י וְ⁠נִ֨קְדַּשְׁתִּ֔י בְּ⁠ת֖וֹךְ בְּנֵ֣י יִשְׂרָאֵ֑ל אֲנִ֥י יְהוָ֖ה מְקַדִּשְׁ⁠כֶֽם׃","wĕ⁠lò֤ʼ ţĕẖalĕ̇lẇ֙ ʼeţ-şé֣̌m qádĕşǐ֔⁠y wĕ⁠ni֨qĕdȧşĕ̌ţi̇֔y bĕ̇⁠ţ֖wòkĕ bĕ̇né֣y yişĕ̂ráʼé֑l ʼàni֥y yĕhwá֖h mĕqadi̇şĕ̌⁠keֽm׃"],[22,33,"הַ⁠מּוֹצִ֤יא אֶתְ⁠כֶם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם לִ⁠הְי֥וֹת לָ⁠כֶ֖ם לֵ⁠אלֹהִ֑ים אֲנִ֖י יְהוָֽה׃פ","ha⁠ṁwòẕi֤yʼ ʼeţĕ⁠kem֙ mé⁠ʼe֣reẕ miẕĕra֔yim li⁠hĕy֥wòţ lá⁠ke֖m lé⁠ʼlòhi֑ym ʼàni֖y yĕhwáֽh׃p"],[23,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[23,2,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם מוֹעֲדֵ֣י יְהוָ֔ה אֲשֶׁר־תִּקְרְא֥וּ אֹתָ֖⁠ם מִקְרָאֵ֣י קֹ֑דֶשׁ אֵ֥לֶּה הֵ֖ם מוֹעֲדָֽ⁠י׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m mwòʻàdé֣y yĕhwá֔h ʼàşěr-ţi̇qĕrĕʼ֥ẇ ʼòţá֖⁠m miqĕráʼé֣y qò֑deş̌ ʼé֥lėh hé֖m mwòʻàdáֽ⁠y׃"],[23,3,"שֵׁ֣שֶׁת יָמִים֮ תֵּעָשֶׂ֣ה מְלָאכָה֒ וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י שַׁבַּ֤ת שַׁבָּתוֹן֙ מִקְרָא־קֹ֔דֶשׁ כָּל־מְלָאכָ֖ה לֹ֣א תַעֲשׂ֑וּ שַׁבָּ֥ת הִוא֙ לַֽ⁠יהוָ֔ה בְּ⁠כֹ֖ל מֽוֹשְׁבֹתֵי⁠כֶֽם׃פ","şé֣̌şěţ yámiym֮ ţé̇ʻáşê֣h mĕláʼkáh֒ ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y şǎbȧ֤ţ şǎbá̇ţwòn֙ miqĕráʼ-qò֔deş̌ ká̇l-mĕláʼká֖h lò֣ʼ ţaʻàş֑̂ẇ şǎbá֥̇ţ hiwʼ֙ laֽ⁠yhwá֔h bĕ̇⁠kò֖l mֽwòşĕ̌bòţéy⁠keֽm׃p"],[23,4,"אֵ֚לֶּה מוֹעֲדֵ֣י יְהוָ֔ה מִקְרָאֵ֖י קֹ֑דֶשׁ אֲשֶׁר־תִּקְרְא֥וּ אֹתָ֖⁠ם בְּ⁠מוֹעֲדָֽ⁠ם׃","ʼé֚lėh mwòʻàdé֣y yĕhwá֔h miqĕráʼé֖y qò֑deş̌ ʼàşěr-ţi̇qĕrĕʼ֥ẇ ʼòţá֖⁠m bĕ̇⁠mwòʻàdáֽ⁠m׃"],[23,5,"בַּ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֗וֹן בְּ⁠אַרְבָּעָ֥ה עָשָׂ֛ר לַ⁠חֹ֖דֶשׁ בֵּ֣ין הָ⁠עַרְבָּ֑יִם פֶּ֖סַח לַ⁠יהוָֽה׃","bȧ⁠ẖò֣deş̌ há⁠riʼş̌֗wòn bĕ̇⁠ʼarĕbá̇ʻá֥h ʻáşá֛̂r la⁠ẖò֖deş̌ bé֣̇yn há⁠ʻarĕbá֑̇yim pė֖saẖ la⁠yhwáֽh׃"],[23,6,"וּ⁠בַ⁠חֲמִשָּׁ֨ה עָשָׂ֥ר יוֹם֙ לַ⁠חֹ֣דֶשׁ הַ⁠זֶּ֔ה חַ֥ג הַ⁠מַּצּ֖וֹת לַ⁠יהוָ֑ה שִׁבְעַ֥ת יָמִ֖ים מַצּ֥וֹת תֹּאכֵֽלוּ׃","ẇ⁠ba⁠ẖàmişá̇̌֨h ʻáşá֥̂r ywòm֙ la⁠ẖò֣deş̌ ha⁠zė֔h ẖa֥g ha⁠mȧẕ֖̇wòţ la⁠yhwá֑h şǐbĕʻa֥ţ yámi֖ym maẕ֥̇wòţ ţò̇ʼkéֽlẇ׃"],[23,7,"בַּ⁠יּוֹם֙ הָֽ⁠רִאשׁ֔וֹן מִקְרָא־קֹ֖דֶשׁ יִהְיֶ֣ה לָ⁠כֶ֑ם כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֥א תַעֲשֽׂוּ׃","bȧ⁠ẏwòm֙ háֽ⁠riʼş̌֔wòn miqĕráʼ-qò֖deş̌ yihĕye֣h lá⁠ke֑m ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֥ʼ ţaʻàşֽ̂ẇ׃"],[23,8,"וְ⁠הִקְרַבְתֶּ֥ם אִשֶּׁ֛ה לַ⁠יהוָ֖ה שִׁבְעַ֣ת יָמִ֑ים בַּ⁠יּ֤וֹם הַ⁠שְּׁבִיעִי֙ מִקְרָא־קֹ֔דֶשׁ כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֥א תַעֲשֽׂוּ׃פ","wĕ⁠hiqĕrabĕţė֥m ʼişė֛̌h la⁠yhwá֖h şǐbĕʻa֣ţ yámi֑ym bȧ⁠ẏ֤wòm ha⁠şĕ̇̌biyʻiy֙ miqĕráʼ-qò֔deş̌ ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֥ʼ ţaʻàşֽ̂ẇ׃p"],[23,9,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[23,10,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם כִּֽי־תָבֹ֣אוּ אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֤ר אֲנִי֙ נֹתֵ֣ן לָ⁠כֶ֔ם וּ⁠קְצַרְתֶּ֖ם אֶת־קְצִירָ֑⁠הּ וַ⁠הֲבֵאתֶ֥ם אֶת־עֹ֛מֶר רֵאשִׁ֥ית קְצִירְ⁠כֶ֖ם אֶל־הַ⁠כֹּהֵֽן׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m kiֽ̇y-ţábò֣ʼẇ ʼel-há⁠ʼá֗reẕ ʼàşě֤r ʼàniy֙ nòţé֣n lá⁠ke֔m ẇ⁠qĕẕarĕţė֖m ʼeţ-qĕẕiyrá֑⁠ḣ wa⁠hàbéʼţe֥m ʼeţ-ʻò֛mer réʼşǐ֥yţ qĕẕiyrĕ⁠ke֖m ʼel-ha⁠kò̇héֽn׃"],[23,11,"וְ⁠הֵנִ֧יף אֶת־הָ⁠עֹ֛מֶר לִ⁠פְנֵ֥י יְהוָ֖ה לִֽ⁠רְצֹנְ⁠כֶ֑ם מִֽ⁠מָּחֳרַת֙ הַ⁠שַּׁבָּ֔ת יְנִיפֶ֖⁠נּוּ הַ⁠כֹּהֵֽן׃","wĕ⁠héni֧yp ʼeţ-há⁠ʻò֛mer li⁠pĕné֥y yĕhwá֖h liֽ⁠rĕẕònĕ⁠ke֑m miֽ⁠má̇ẖoraţ֙ ha⁠şȧ̌bá̇֔ţ yĕniype֖⁠ṅẇ ha⁠kò̇héֽn׃"],[23,12,"וַ⁠עֲשִׂיתֶ֕ם בְּ⁠י֥וֹם הֲנִֽיפְ⁠כֶ֖ם אֶת־הָ⁠עֹ֑מֶר כֶּ֣בֶשׂ תָּמִ֧ים בֶּן־שְׁנָת֛⁠וֹ לְ⁠עֹלָ֖ה לַ⁠יהוָֽה׃","wa⁠ʻàşîyţe֕m bĕ̇⁠y֥wòm hàniֽypĕ⁠ke֖m ʼeţ-há⁠ʻò֑mer kė֣beş̂ ţá̇mi֧ym bėn-şĕ̌náţ֛⁠wò lĕ⁠ʻòlá֖h la⁠yhwáֽh׃"],[23,13,"וּ⁠מִנְחָת⁠וֹ֩ שְׁנֵ֨י עֶשְׂרֹנִ֜ים סֹ֣לֶת בְּלוּלָ֥ה בַ⁠שֶּׁ֛מֶן אִשֶּׁ֥ה לַ⁠יהוָ֖ה רֵ֣יחַ נִיחֹ֑חַ וְ⁠נִסְכֹּ֥⁠ה יַ֖יִן רְבִיעִ֥ת הַ⁠הִֽין׃","ẇ⁠minĕẖáţ⁠wò֩ şĕ̌né֨y ʻeşĕ̂ròni֜ym sò֣leţ bĕ̇lẇlá֥h ba⁠şė֛̌men ʼişė֥̌h la⁠yhwá֖h ré֣yẖa niyẖò֑ẖa wĕ⁠nisĕkò֥̇⁠h ya֖yin rĕbiyʻi֥ţ ha⁠hiֽyn׃"],[23,14,"וְ⁠לֶחֶם֩ וְ⁠קָלִ֨י וְ⁠כַרְמֶ֜ל לֹ֣א תֹֽאכְל֗וּ עַד־עֶ֨צֶם֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה עַ֚ד הֲבִ֣יאֲ⁠כֶ֔ם אֶת־קָרְבַּ֖ן אֱלֹהֵי⁠כֶ֑ם חֻקַּ֤ת עוֹלָם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם בְּ⁠כֹ֖ל מֹשְׁבֹֽתֵי⁠כֶֽם׃ס","wĕ⁠leẖem֩ wĕ⁠qáli֨y wĕ⁠karĕme֜l lò֣ʼ ţòֽʼkĕl֗ẇ ʻad-ʻe֨ẕem֙ ha⁠ẏ֣wòm ha⁠zė֔h ʻa֚d hàbi֣yʼà⁠ke֔m ʼeţ-qárĕbȧ֖n ʼèlòhéy⁠ke֑m ẖuqȧ֤ţ ʻwòlám֙ lĕ⁠dòrò֣ţéy⁠ke֔m bĕ̇⁠kò֖l mòşĕ̌bòֽţéy⁠keֽm׃s"],[23,15,"וּ⁠סְפַרְתֶּ֤ם לָ⁠כֶם֙ מִ⁠מָּחֳרַ֣ת הַ⁠שַּׁבָּ֔ת מִ⁠יּוֹם֙ הֲבִ֣יאֲ⁠כֶ֔ם אֶת־עֹ֖מֶר הַ⁠תְּנוּפָ֑ה שֶׁ֥בַע שַׁבָּת֖וֹת תְּמִימֹ֥ת תִּהְיֶֽינָה׃","ẇ⁠sĕparĕţė֤m lá⁠kem֙ mi⁠má̇ẖora֣ţ ha⁠şȧ̌bá̇֔ţ mi⁠ẏwòm֙ hàbi֣yʼà⁠ke֔m ʼeţ-ʻò֖mer ha⁠ţĕ̇nẇpá֑h şě֥baʻ şǎbá̇ţ֖wòţ ţĕ̇miymò֥ţ ţi̇hĕyeֽynáh׃"],[23,16,"עַ֣ד מִֽ⁠מָּחֳרַ֤ת הַ⁠שַּׁבָּת֙ הַ⁠שְּׁבִיעִ֔ת תִּסְפְּר֖וּ חֲמִשִּׁ֣ים י֑וֹם וְ⁠הִקְרַבְתֶּ֛ם מִנְחָ֥ה חֲדָשָׁ֖ה לַ⁠יהוָֽה׃","ʻa֣d miֽ⁠má̇ẖora֤ţ ha⁠şȧ̌bá̇ţ֙ ha⁠şĕ̇̌biyʻi֔ţ ţi̇sĕpĕ̇r֖ẇ ẖàmişi֣̇̌ym y֑wòm wĕ⁠hiqĕrabĕţė֛m minĕẖá֥h ẖàdáşá֖̌h la⁠yhwáֽh׃"],[23,17,"מִ⁠מּוֹשְׁבֹ֨תֵי⁠כֶ֜ם תָּבִ֣יאּוּ ׀ לֶ֣חֶם תְּנוּפָ֗ה שְׁ֚תַּיִם שְׁנֵ֣י עֶשְׂרֹנִ֔ים סֹ֣לֶת תִּהְיֶ֔ינָה חָמֵ֖ץ תֵּאָפֶ֑ינָה בִּכּוּרִ֖ים לַֽ⁠יהוָֽה׃","mi⁠ṁwòşĕ̌bò֨ţéy⁠ke֜m ţá̇bi֣yʼ̇ẇ ׀ le֣ẖem ţĕ̇nẇpá֗h şĕ֚̌ţȧyim şĕ̌né֣y ʻeşĕ̂ròni֔ym sò֣leţ ţi̇hĕye֔ynáh ẖámé֖ẕ ţé̇ʼápe֑ynáh bi̇k̇ẇri֖ym lֽa⁠yhwáֽh׃"],[23,18,"וְ⁠הִקְרַבְתֶּ֣ם עַל־הַ⁠לֶּ֗חֶם שִׁבְעַ֨ת כְּבָשִׂ֤ים תְּמִימִם֙ בְּנֵ֣י שָׁנָ֔ה וּ⁠פַ֧ר בֶּן־בָּקָ֛ר אֶחָ֖ד וְ⁠אֵילִ֣ם שְׁנָ֑יִם יִהְי֤וּ עֹלָה֙ לַֽ⁠יהוָ֔ה וּ⁠מִנְחָתָ⁠ם֙ וְ⁠נִסְכֵּי⁠הֶ֔ם אִשֵּׁ֥ה רֵֽיחַ־נִיחֹ֖חַ לַ⁠יהוָֽה׃","wĕ⁠hiqĕrabĕţė֣m ʻal-ha⁠lė֗ẖem şǐbĕʻa֨ţ kĕ̇báşî֤ym ţĕ̇miymim֙ bĕ̇né֣y şá̌ná֔h ẇ⁠pa֧r bėn-bá̇qá֛r ʼeẖá֖d wĕ⁠ʼéyli֣m şĕ̌ná֑yim yihĕy֤ẇ ʻòláh֙ laֽ⁠yhwá֔h ẇ⁠minĕẖáţá⁠m֙ wĕ⁠nisĕké̇y⁠he֔m ʼişé֥̇̌h réֽyẖa-niyẖò֖ẖa la⁠yhwáֽh׃"],[23,19,"וַ⁠עֲשִׂיתֶ֛ם שְׂעִיר־עִזִּ֥ים אֶחָ֖ד לְ⁠חַטָּ֑את וּ⁠שְׁנֵ֧י כְבָשִׂ֛ים בְּנֵ֥י שָׁנָ֖ה לְ⁠זֶ֥בַח שְׁלָמִֽים׃","wa⁠ʻàşîyţe֛m şĕ̂ʻiyr-ʻizi֥̇ym ʼeẖá֖d lĕ⁠ẖatá֑̇ʼţ ẇ⁠şĕ̌né֧y kĕbáşî֛ym bĕ̇né֥y şá̌ná֖h lĕ⁠ze֥baẖ şĕ̌lámiֽym׃"],[23,20,"וְ⁠הֵנִ֣יף הַ⁠כֹּהֵ֣ן ׀ אֹתָ֡⁠ם עַל֩ לֶ֨חֶם הַ⁠בִּכּוּרִ֤ים תְּנוּפָה֙ לִ⁠פְנֵ֣י יְהוָ֔ה עַל־שְׁנֵ֖י כְּבָשִׂ֑ים קֹ֛דֶשׁ יִהְי֥וּ לַ⁠יהוָ֖ה לַ⁠כֹּהֵֽן׃","wĕ⁠héni֣yp ha⁠kò̇hé֣n ׀ ʼòţá֡⁠m ʻal֩ le֨ẖem ha⁠bi̇k̇ẇri֤ym ţĕ̇nẇpáh֙ li⁠pĕné֣y yĕhwá֔h ʻal-şĕ̌né֖y kĕ̇báşî֑ym qò֛deş̌ yihĕy֥ẇ la⁠yhwá֖h la⁠kò̇héֽn׃"],[23,21,"וּ⁠קְרָאתֶ֞ם בְּ⁠עֶ֣צֶם ׀ הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה מִֽקְרָא־קֹ֨דֶשׁ֙ יִהְיֶ֣ה לָ⁠כֶ֔ם כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֣א תַעֲשׂ֑וּ חֻקַּ֥ת עוֹלָ֛ם בְּ⁠כָל־מוֹשְׁבֹ֥תֵי⁠כֶ֖ם לְ⁠דֹרֹֽתֵי⁠כֶֽם׃","ẇ⁠qĕráʼţe֞m bĕ̇⁠ʻe֣ẕem ׀ ha⁠ẏ֣wòm ha⁠zė֗h miֽqĕráʼ-qò֨deş̌֙ yihĕye֣h lá⁠ke֔m ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֣ʼ ţaʻàş֑̂ẇ ẖuqȧ֥ţ ʻwòlá֛m bĕ̇⁠kál-mwòşĕ̌bò֥ţéy⁠ke֖m lĕ⁠dòròֽţéy⁠keֽm׃"],[23,22,"וּֽ⁠בְ⁠קֻצְרְ⁠כֶ֞ם אֶת־קְצִ֣יר אַרְצְ⁠כֶ֗ם לֹֽא־תְכַלֶּ֞ה פְּאַ֤ת שָֽׂדְ⁠ךָ֙ בְּ⁠קֻצְרֶ֔⁠ךָ וְ⁠לֶ֥קֶט קְצִירְ⁠ךָ֖ לֹ֣א תְלַקֵּ֑ט לֶֽ⁠עָנִ֤י וְ⁠לַ⁠גֵּר֙ תַּעֲזֹ֣ב אֹתָ֔⁠ם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃ס","ẇֽ⁠bĕ⁠quẕĕrĕ⁠ke֞m ʼeţ-qĕẕi֣yr ʼarĕẕĕ⁠ke֗m lòֽʼ-ţĕkalė֞h pĕ̇ʼa֤ţ şáֽ̂dĕ⁠ká֙ bĕ̇⁠quẕĕre֔⁠ká wĕ⁠le֥qet qĕẕiyrĕ⁠ká֖ lò֣ʼ ţĕlaqé֑̇t leֽ⁠ʻáni֤y wĕ⁠la⁠gé̇r֙ ţȧʻàzò֣b ʼòţá֔⁠m ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃s"],[23,23,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[23,24,"דַּבֵּ֛ר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר בַּ⁠חֹ֨דֶשׁ הַ⁠שְּׁבִיעִ֜י בְּ⁠אֶחָ֣ד לַ⁠חֹ֗דֶשׁ יִהְיֶ֤ה לָ⁠כֶם֙ שַׁבָּת֔וֹן זִכְר֥וֹן תְּרוּעָ֖ה מִקְרָא־קֹֽדֶשׁ׃","dȧbé֛̇r ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r bȧ⁠ẖò֨deş̌ ha⁠şĕ̇̌biyʻi֜y bĕ̇⁠ʼeẖá֣d la⁠ẖò֗deş̌ yihĕye֤h lá⁠kem֙ şǎbá̇ţ֔wòn zikĕr֥wòn ţĕ̇rẇʻá֖h miqĕráʼ-qòֽdeş̌׃"],[23,25,"כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֣א תַעֲשׂ֑וּ וְ⁠הִקְרַבְתֶּ֥ם אִשֶּׁ֖ה לַ⁠יהוָֽה׃ס","ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֣ʼ ţaʻàş֑̂ẇ wĕ⁠hiqĕrabĕţė֥m ʼişė֖̌h la⁠yhwáֽh׃s"],[23,26,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[23,27,"אַ֡ךְ בֶּ⁠עָשׂ֣וֹר לַ⁠חֹדֶשׁ֩ הַ⁠שְּׁבִיעִ֨י הַ⁠זֶּ֜ה י֧וֹם הַ⁠כִּפֻּרִ֣ים ה֗וּא מִֽקְרָא־קֹ֨דֶשׁ֙ יִהְיֶ֣ה לָ⁠כֶ֔ם וְ⁠עִנִּיתֶ֖ם אֶת־נַפְשֹׁתֵי⁠כֶ֑ם וְ⁠הִקְרַבְתֶּ֥ם אִשֶּׁ֖ה לַ⁠יהוָֽה׃","ʼa֡kĕ bė⁠ʻáş֣̂wòr la⁠ẖòdeş̌֩ ha⁠şĕ̇̌biyʻi֨y ha⁠zė֜h y֧wòm ha⁠ki̇pu̇ri֣ym h֗ẇʼ miֽqĕráʼ-qò֨deş̌֙ yihĕye֣h lá⁠ke֔m wĕ⁠ʻini̇yţe֖m ʼeţ-napĕşò̌ţéy⁠ke֑m wĕ⁠hiqĕrabĕţė֥m ʼişė֖̌h la⁠yhwáֽh׃"],[23,28,"וְ⁠כָל־מְלָאכָה֙ לֹ֣א תַעֲשׂ֔וּ בְּ⁠עֶ֖צֶם הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֣י י֤וֹם כִּפֻּרִים֙ ה֔וּא לְ⁠כַפֵּ֣ר עֲלֵי⁠כֶ֔ם לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠kál-mĕláʼkáh֙ lò֣ʼ ţaʻàş̂֔ẇ bĕ̇⁠ʻe֖ẕem ha⁠ẏ֣wòm ha⁠zė֑h ki֣̇y y֤wòm ki̇pu̇riym֙ h֔ẇʼ lĕ⁠kapé֣̇r ʻàléy⁠ke֔m li⁠pĕné֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[23,29,"כִּ֤י כָל־הַ⁠נֶּ֨פֶשׁ֙ אֲשֶׁ֣ר לֹֽא־תְעֻנֶּ֔ה בְּ⁠עֶ֖צֶם הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וְ⁠נִכְרְתָ֖ה מֵֽ⁠עַמֶּֽי⁠הָ׃","ki֤̇y kál-ha⁠nė֨peş̌֙ ʼàşě֣r lòֽʼ-ţĕʻunė֔h bĕ̇⁠ʻe֖ẕem ha⁠ẏ֣wòm ha⁠zė֑h wĕ⁠nikĕrĕţá֖h méֽ⁠ʻamėֽy⁠há׃"],[23,30,"וְ⁠כָל־הַ⁠נֶּ֗פֶשׁ אֲשֶׁ֤ר תַּעֲשֶׂה֙ כָּל־מְלָאכָ֔ה בְּ⁠עֶ֖צֶם הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וְ⁠הַֽאֲבַדְתִּ֛י אֶת־הַ⁠נֶּ֥פֶשׁ הַ⁠הִ֖וא מִ⁠קֶּ֥רֶב עַמָּֽ⁠הּ׃","wĕ⁠kál-ha⁠nė֗peş̌ ʼàşě֤r ţȧʻàşêh֙ ká̇l-mĕláʼká֔h bĕ̇⁠ʻe֖ẕem ha⁠ẏ֣wòm ha⁠zė֑h wĕ⁠haֽʼàbadĕţi֛̇y ʼeţ-ha⁠nė֥peş̌ ha⁠hi֖wʼ mi⁠qė֥reb ʻamáֽ̇⁠ḣ׃"],[23,31,"כָּל־מְלָאכָ֖ה לֹ֣א תַעֲשׂ֑וּ חֻקַּ֤ת עוֹלָם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם בְּ⁠כֹ֖ל מֹֽשְׁבֹֽתֵי⁠כֶֽם׃","ká̇l-mĕláʼká֖h lò֣ʼ ţaʻàş֑̂ẇ ẖuqȧ֤ţ ʻwòlám֙ lĕ⁠dòrò֣ţéy⁠ke֔m bĕ̇⁠kò֖l mòֽşĕ̌bòֽţéy⁠keֽm׃"],[23,32,"שַׁבַּ֨ת שַׁבָּת֥וֹן הוּא֙ לָ⁠כֶ֔ם וְ⁠עִנִּיתֶ֖ם אֶת־נַפְשֹׁתֵי⁠כֶ֑ם בְּ⁠תִשְׁעָ֤ה לַ⁠חֹ֨דֶשׁ֙ בָּ⁠עֶ֔רֶב מֵ⁠עֶ֣רֶב עַד־עֶ֔רֶב תִּשְׁבְּת֖וּ שַׁבַּתְּ⁠כֶֽם׃פ","şǎbȧ֨ţ şǎbá̇ţ֥wòn hẇʼ֙ lá⁠ke֔m wĕ⁠ʻini̇yţe֖m ʼeţ-napĕşò̌ţéy⁠ke֑m bĕ̇⁠ţişĕ̌ʻá֤h la⁠ẖò֨deş̌֙ bá̇⁠ʻe֔reb mé⁠ʻe֣reb ʻad-ʻe֔reb ţi̇şĕ̌bĕ̇ţ֖ẇ şǎbȧţĕ̇⁠keֽm׃p"],[23,33,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[23,34,"דַּבֵּ֛ר אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר בַּ⁠חֲמִשָּׁ֨ה עָשָׂ֜ר י֗וֹם לַ⁠חֹ֤דֶשׁ הַ⁠שְּׁבִיעִי֙ הַ⁠זֶּ֔ה חַ֧ג הַ⁠סֻּכּ֛וֹת שִׁבְעַ֥ת יָמִ֖ים לַ⁠יהֹוָֽה׃","dȧbé֛̇r ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l lé⁠ʼmò֑r bȧ⁠ẖàmişá̇̌֨h ʻáşá̂֜r y֗wòm la⁠ẖò֤deş̌ ha⁠şĕ̇̌biyʻiy֙ ha⁠zė֔h ẖa֧g ha⁠su̇k֛̇wòţ şǐbĕʻa֥ţ yámi֖ym la⁠yhòwáֽh׃"],[23,35,"בַּ⁠יּ֥וֹם הָ⁠רִאשׁ֖וֹן מִקְרָא־קֹ֑דֶשׁ כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֥א תַעֲשֽׂוּ׃","bȧ⁠ẏ֥wòm há⁠riʼş֖̌wòn miqĕráʼ-qò֑deş̌ ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֥ʼ ţaʻàşֽ̂ẇ׃"],[23,36,"שִׁבְעַ֣ת יָמִ֔ים תַּקְרִ֥יבוּ אִשֶּׁ֖ה לַ⁠יהוָ֑ה בַּ⁠יּ֣וֹם הַ⁠שְּׁמִינִ֡י מִקְרָא־קֹדֶשׁ֩ יִהְיֶ֨ה לָ⁠כֶ֜ם וְ⁠הִקְרַבְתֶּ֨ם אִשֶּׁ֤ה לַֽ⁠יהוָה֙ עֲצֶ֣רֶת הִ֔וא כָּל־מְלֶ֥אכֶת עֲבֹדָ֖ה לֹ֥א תַעֲשֽׂוּ׃","şǐbĕʻa֣ţ yámi֔ym ţȧqĕri֥ybẇ ʼişė֖̌h la⁠yhwá֑h bȧ⁠ẏ֣wòm ha⁠şĕ̇̌miyni֡y miqĕráʼ-qòdeş̌֩ yihĕye֨h lá⁠ke֜m wĕ⁠hiqĕrabĕţė֨m ʼişė֤̌h laֽ⁠yhwáh֙ ʻàẕe֣reţ hi֔wʼ ká̇l-mĕle֥ʼkeţ ʻàbòdá֖h lò֥ʼ ţaʻàşֽ̂ẇ׃"],[23,37,"אֵ֚לֶּה מוֹעֲדֵ֣י יְהוָ֔ה אֲשֶׁר־תִּקְרְא֥וּ אֹתָ֖⁠ם מִקְרָאֵ֣י קֹ֑דֶשׁ לְ⁠הַקְרִ֨יב אִשֶּׁ֜ה לַ⁠יהוָ֗ה עֹלָ֧ה וּ⁠מִנְחָ֛ה זֶ֥בַח וּ⁠נְסָכִ֖ים דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","ʼé֚lėh mwòʻàdé֣y yĕhwá֔h ʼàşěr-ţi̇qĕrĕʼ֥ẇ ʼòţá֖⁠m miqĕráʼé֣y qò֑deş̌ lĕ⁠haqĕri֨yb ʼişė̌֜h la⁠yhwá֗h ʻòlá֧h ẇ⁠minĕẖá֛h ze֥baẖ ẇ⁠nĕsáki֖ym dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[23,38,"מִ⁠לְּ⁠בַ֖ד שַׁבְּתֹ֣ת יְּהוָ֑ה וּ⁠מִ⁠לְּ⁠בַ֣ד מַתְּנֽוֹתֵי⁠כֶ֗ם וּ⁠מִ⁠לְּ⁠בַ֤ד כָּל־נִדְרֵי⁠כֶם֙ וּ⁠מִ⁠לְּ⁠בַד֙ כָּל־נִדְב֣וֹתֵי⁠כֶ֔ם אֲשֶׁ֥ר תִּתְּנ֖וּ לַ⁠יהוָֽה׃","mi⁠lĕ̇⁠ba֖d şǎbĕ̇ţò֣ţ yĕ̇hwá֑h ẇ⁠mi⁠lĕ̇⁠ba֣d maţĕ̇nֽwòţéy⁠ke֗m ẇ⁠mi⁠lĕ̇⁠ba֤d ká̇l-nidĕréy⁠kem֙ ẇ⁠mi⁠lĕ̇⁠bad֙ ká̇l-nidĕb֣wòţéy⁠ke֔m ʼàşě֥r ţi̇ţĕ̇n֖ẇ la⁠yhwáֽh׃"],[23,39,"אַ֡ךְ בַּ⁠חֲמִשָּׁה֩ עָשָׂ֨ר י֜וֹם לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֗י בְּ⁠אָסְפְּ⁠כֶם֙ אֶת־תְּבוּאַ֣ת הָ⁠אָ֔רֶץ תָּחֹ֥גּוּ אֶת־חַג־יְהוָ֖ה שִׁבְעַ֣ת יָמִ֑ים בַּ⁠יּ֤וֹם הָֽ⁠רִאשׁוֹן֙ שַׁבָּת֔וֹן וּ⁠בַ⁠יּ֥וֹם הַ⁠שְּׁמִינִ֖י שַׁבָּתֽוֹן׃","ʼa֡kĕ bȧ⁠ẖàmişá̇̌h֩ ʻáşá̂֨r y֜wòm la⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֗y bĕ̇⁠ʼásĕpĕ̇⁠kem֙ ʼeţ-ţĕ̇bẇʼa֣ţ há⁠ʼá֔reẕ ţá̇ẖò֥ġẇ ʼeţ-ẖag-yĕhwá֖h şǐbĕʻa֣ţ yámi֑ym bȧ⁠ẏ֤wòm háֽ⁠riʼş̌wòn֙ şǎbá̇ţ֔wòn ẇ⁠ba⁠ẏ֥wòm ha⁠şĕ̇̌miyni֖y şǎbá̇ţֽwòn׃"],[23,40,"וּ⁠לְקַחְתֶּ֨ם לָ⁠כֶ֜ם בַּ⁠יּ֣וֹם הָ⁠רִאשׁ֗וֹן פְּרִ֨י עֵ֤ץ הָדָר֙ כַּפֹּ֣ת תְּמָרִ֔ים וַ⁠עֲנַ֥ף עֵץ־עָבֹ֖ת וְ⁠עַרְבֵי־נָ֑חַל וּ⁠שְׂמַחְתֶּ֗ם לִ⁠פְנֵ֛י יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם שִׁבְעַ֥ת יָמִֽים׃","ẇ⁠lĕqaẖĕţė֨m lá⁠ke֜m bȧ⁠ẏ֣wòm há⁠riʼş̌֗wòn pĕ̇ri֨y ʻé֤ẕ hádár֙ kȧpò֣̇ţ ţĕ̇mári֔ym wa⁠ʻàna֥p ʻéẕ-ʻábò֖ţ wĕ⁠ʻarĕbéy-ná֑ẖal ẇ⁠şĕ̂maẖĕţė֗m li⁠pĕné֛y yĕhwá֥h ʼèlòhéy⁠ke֖m şǐbĕʻa֥ţ yámiֽym׃"],[23,41,"וְ⁠חַגֹּתֶ֤ם אֹת⁠וֹ֙ חַ֣ג לַֽ⁠יהוָ֔ה שִׁבְעַ֥ת יָמִ֖ים בַּ⁠שָּׁנָ֑ה חֻקַּ֤ת עוֹלָם֙ לְ⁠דֹרֹ֣תֵי⁠כֶ֔ם בַּ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִיעִ֖י תָּחֹ֥גּוּ אֹתֽ⁠וֹ׃","wĕ⁠ẖagò̇ţe֤m ʼòţ⁠wò֙ ẖa֣g laֽ⁠yhwá֔h şǐbĕʻa֥ţ yámi֖ym bȧ⁠şá̇̌ná֑h ẖuqȧ֤ţ ʻwòlám֙ lĕ⁠dòrò֣ţéy⁠ke֔m bȧ⁠ẖò֥deş̌ ha⁠şĕ̇̌biyʻi֖y ţá̇ẖò֥ġẇ ʼòţֽ⁠wò׃"],[23,42,"בַּ⁠סֻּכֹּ֥ת תֵּשְׁב֖וּ שִׁבְעַ֣ת יָמִ֑ים כָּל־הָֽ⁠אֶזְרָח֙ בְּ⁠יִשְׂרָאֵ֔ל יֵשְׁב֖וּ בַּ⁠סֻּכֹּֽת׃","bȧ⁠su̇kò֥̇ţ ţé̇şĕ̌b֖ẇ şǐbĕʻa֣ţ yámi֑ym ká̇l-háֽ⁠ʼezĕráẖ֙ bĕ̇⁠yişĕ̂ráʼé֔l yéşĕ̌b֖ẇ bȧ⁠su̇kòֽ̇ţ׃"],[23,43,"לְמַעַן֮ יֵדְע֣וּ דֹרֹֽתֵי⁠כֶם֒ כִּ֣י בַ⁠סֻּכּ֗וֹת הוֹשַׁ֨בְתִּי֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠הוֹצִיאִ֥⁠י אוֹתָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","lĕmaʻan֮ yédĕʻ֣ẇ dòròֽţéy⁠kem֒ ki֣̇y ba⁠su̇k̇֗wòţ hwòşǎ֨bĕţi̇y֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠hwòẕiyʼi֥⁠y ʼwòţá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[23,44,"וַ⁠יְדַבֵּ֣ר מֹשֶׁ֔ה אֶת־מֹעֲדֵ֖י יְהוָ֑ה אֶל־בְּנֵ֖י יִשְׂרָאֵֽל׃פ","wa⁠yĕdabé֣̇r mòşě֔h ʼeţ-mòʻàdé֖y yĕhwá֑h ʼel-bĕ̇né֖y yişĕ̂ráʼéֽl׃p"],[24,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[24,2,"צַ֞ו אֶת־בְּנֵ֣י יִשְׂרָאֵ֗ל וְ⁠יִקְח֨וּ אֵלֶ֜י⁠ךָ שֶׁ֣מֶן זַ֥יִת זָ֛ךְ כָּתִ֖ית לַ⁠מָּא֑וֹר לְ⁠הַעֲלֹ֥ת נֵ֖ר תָּמִֽיד׃","ẕa֞w ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֗l wĕ⁠yiqĕẖ֨ẇ ʼéle֜y⁠ká şě֣men za֥yiţ zá֛kĕ ká̇ţi֖yţ la⁠má̇ʼ֑wòr lĕ⁠haʻàlò֥ţ né֖r ţá̇miֽyd׃"],[24,3,"מִ⁠חוּץ֩ לְ⁠פָרֹ֨כֶת הָ⁠עֵדֻ֜ת בְּ⁠אֹ֣הֶל מוֹעֵ֗ד יַעֲרֹךְ֩ אֹת֨⁠וֹ אַהֲרֹ֜ן מֵ⁠עֶ֧רֶב עַד־בֹּ֛קֶר לִ⁠פְנֵ֥י יְהוָ֖ה תָּמִ֑יד חֻקַּ֥ת עוֹלָ֖ם לְ⁠דֹרֹֽתֵי⁠כֶֽם׃","mi⁠ẖẇẕ֩ lĕ⁠párò֨keţ há⁠ʻédu֜ţ bĕ̇⁠ʼò֣hel mwòʻé֗d yaʻàròkĕ֩ ʼòţ֨⁠wò ʼahàrò֜n mé⁠ʻe֧reb ʻad-bò֛̇qer li⁠pĕné֥y yĕhwá֖h ţá̇mi֑yd ẖuqȧ֥ţ ʻwòlá֖m lĕ⁠dòròֽţéy⁠keֽm׃"],[24,4,"עַ֚ל הַ⁠מְּנֹרָ֣ה הַ⁠טְּהֹרָ֔ה יַעֲרֹ֖ךְ אֶת־הַ⁠נֵּר֑וֹת לִ⁠פְנֵ֥י יְהוָ֖ה תָּמִֽיד׃פ","ʻa֚l ha⁠mĕ̇nòrá֣h ha⁠tĕ̇hòrá֔h yaʻàrò֖kĕ ʼeţ-ha⁠né̇r֑wòţ li⁠pĕné֥y yĕhwá֖h ţá̇miֽyd׃p"],[24,5,"וְ⁠לָקַחְתָּ֣ סֹ֔לֶת וְ⁠אָפִיתָ֣ אֹתָ֔⁠הּ שְׁתֵּ֥ים עֶשְׂרֵ֖ה חַלּ֑וֹת שְׁנֵי֙ עֶשְׂרֹנִ֔ים יִהְיֶ֖ה הַֽ⁠חַלָּ֥ה הָ⁠אֶחָֽת׃","wĕ⁠láqaẖĕţá֣̇ sò֔leţ wĕ⁠ʼápiyţá֣ ʼòţá֔⁠ḣ şĕ̌ţé֥̇ym ʻeşĕ̂ré֖h ẖal֑̇wòţ şĕ̌néy֙ ʻeşĕ̂ròni֔ym yihĕye֖h haֽ⁠ẖalá֥̇h há⁠ʼeẖáֽţ׃"],[24,6,"וְ⁠שַׂמְתָּ֥ אוֹתָ֛⁠ם שְׁתַּ֥יִם מַֽעֲרָכ֖וֹת שֵׁ֣שׁ הַֽ⁠מַּעֲרָ֑כֶת עַ֛ל הַ⁠שֻּׁלְחָ֥ן הַ⁠טָּהֹ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠şâmĕţá֥̇ ʼwòţá֛⁠m şĕ̌ţȧ֥yim maֽʻàrák֖wòţ şé֣̌ş̌ haֽ⁠mȧʻàrá֑keţ ʻa֛l ha⁠şu̇̌lĕẖá֥n ha⁠tá̇hò֖r li⁠pĕné֥y yĕhwáֽh׃"],[24,7,"וְ⁠נָתַתָּ֥ עַל־הַֽ⁠מַּעֲרֶ֖כֶת לְבֹנָ֣ה זַכָּ֑ה וְ⁠הָיְתָ֤ה לַ⁠לֶּ֨חֶם֙ לְ⁠אַזְכָּרָ֔ה אִשֶּׁ֖ה לַֽ⁠יהוָֽה׃","wĕ⁠náţaţá֥̇ ʻal-haֽ⁠mȧʻàre֖keţ lĕbòná֣h zaká֑̇h wĕ⁠háyĕţá֤h la⁠lė֨ẖem֙ lĕ⁠ʼazĕká̇rá֔h ʼişė֖̌h laֽ⁠yhwáֽh׃"],[24,8,"בְּ⁠י֨וֹם הַ⁠שַּׁבָּ֜ת בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֗ת יַֽעַרְכֶ֛⁠נּוּ לִ⁠פְנֵ֥י יְהוָ֖ה תָּמִ֑יד מֵ⁠אֵ֥ת בְּנֵֽי־יִשְׂרָאֵ֖ל בְּרִ֥ית עוֹלָֽם׃","bĕ̇⁠y֨wòm ha⁠şȧ̌bá̇֜ţ bĕ̇⁠y֣wòm ha⁠şȧ̌bá̇֗ţ yaֽʻarĕke֛⁠ṅẇ li⁠pĕné֥y yĕhwá֖h ţá̇mi֑yd mé⁠ʼé֥ţ bĕ̇néֽy-yişĕ̂ráʼé֖l bĕ̇ri֥yţ ʻwòláֽm׃"],[24,9,"וְ⁠הָֽיְתָה֙ לְ⁠אַהֲרֹ֣ן וּ⁠לְ⁠בָנָ֔י⁠ו וַ⁠אֲכָלֻ֖⁠הוּ בְּ⁠מָק֣וֹם קָדֹ֑שׁ כִּ֡י קֹדֶשׁ֩ קָֽדָשִׁ֨ים ה֥וּא ל֛⁠וֹ מֵ⁠אִשֵּׁ֥י יְהוָ֖ה חָק־עוֹלָֽם׃ס","wĕ⁠háֽyĕţáh֙ lĕ⁠ʼahàrò֣n ẇ⁠lĕ⁠báná֔y⁠w wa⁠ʼàkálu֖⁠hẇ bĕ̇⁠máq֣wòm qádò֑ş̌ ki̇֡y qòdeş̌֩ qֽádáşǐ֨ym h֥ẇʼ l֛⁠wò mé⁠ʼişé֥̇̌y yĕhwá֖h ẖáq-ʻwòláֽm׃s"],[24,10,"וַ⁠יֵּצֵא֙ בֶּן־אִשָּׁ֣ה יִשְׂרְאֵלִ֔ית וְ⁠הוּא֙ בֶּן־אִ֣ישׁ מִצְרִ֔י בְּ⁠ת֖וֹךְ בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּנָּצוּ֙ בַּֽ⁠מַּחֲנֶ֔ה בֶּ֚ן הַ⁠יִּשְׂרְאֵלִ֔ית וְ⁠אִ֖ישׁ הַ⁠יִּשְׂרְאֵלִֽי׃","wa⁠yé̇ẕéʼ֙ bėn-ʼişá֣̇̌h yişĕ̂rĕʼéli֔yţ wĕ⁠hẇʼ֙ bėn-ʼi֣yş̌ miẕĕri֔y bĕ̇⁠ţ֖wòkĕ bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yi̇ná̇ẕẇ֙ bȧֽ⁠mȧẖàne֔h bė֚n ha⁠yi̇şĕ̂rĕʼéli֔yţ wĕ⁠ʼi֖yş̌ ha⁠yi̇şĕ̂rĕʼéliֽy׃"],[24,11,"וַ֠⁠יִּקֹּב בֶּן־הָֽ⁠אִשָּׁ֨ה הַ⁠יִּשְׂרְאֵלִ֤ית אֶת־הַ⁠שֵּׁם֙ וַ⁠יְקַלֵּ֔ל וַ⁠יָּבִ֥יאוּ אֹת֖⁠וֹ אֶל־מֹשֶׁ֑ה וְ⁠שֵׁ֥ם אִמּ֛⁠וֹ שְׁלֹמִ֥ית בַּת־דִּבְרִ֖י לְ⁠מַטֵּה־דָֽן׃","wa֠⁠yi̇qò̇b bėn-háֽ⁠ʼişá̇̌֨h ha⁠yi̇şĕ̂rĕʼéli֤yţ ʼeţ-ha⁠şé̇̌m֙ wa⁠yĕqalé̇֔l wa⁠yá̇bi֥yʼẇ ʼòţ֖⁠wò ʼel-mòşě֑h wĕ⁠şé֥̌m ʼiṁ֛⁠wò şĕ̌lòmi֥yţ bȧţ-di̇bĕri֖y lĕ⁠maté̇h-dáֽn׃"],[24,12,"וַ⁠יַּנִּיחֻ֖⁠הוּ בַּ⁠מִּשְׁמָ֑ר לִ⁠פְרֹ֥שׁ לָ⁠הֶ֖ם עַל־פִּ֥י יְהוָֽה׃פ","wa⁠yȧni̇yẖu֖⁠hẇ bȧ⁠mi̇şĕ̌má֑r li⁠pĕrò֥ş̌ lá⁠he֖m ʻal-pi֥̇y yĕhwáֽh׃p"],[24,13,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[24,14,"הוֹצֵ֣א אֶת־הַֽ⁠מְקַלֵּ֗ל אֶל־מִ⁠חוּץ֙ לַֽ⁠מַּחֲנֶ֔ה וְ⁠סָמְכ֧וּ כָֽל־הַ⁠שֹּׁמְעִ֛ים אֶת־יְדֵי⁠הֶ֖ם עַל־רֹאשׁ֑⁠וֹ וְ⁠רָגְמ֥וּ אֹת֖⁠וֹ כָּל־הָ⁠עֵדָֽה׃","hwòẕé֣ʼ ʼeţ-haֽ⁠mĕqalé̇֗l ʼel-mi⁠ẖẇẕ֙ laֽ⁠mȧẖàne֔h wĕ⁠sámĕk֧ẇ káֽl-ha⁠şò̇̌mĕʻi֛ym ʼeţ-yĕdéy⁠he֖m ʻal-ròʼş֑̌⁠wò wĕ⁠rágĕm֥ẇ ʼòţ֖⁠wò ká̇l-há⁠ʻédáֽh׃"],[24,15,"וְ⁠אֶל־בְּנֵ֥י יִשְׂרָאֵ֖ל תְּדַבֵּ֣ר לֵ⁠אמֹ֑ר אִ֥ישׁ אִ֛ישׁ כִּֽי־יְקַלֵּ֥ל אֱלֹהָ֖י⁠ו וְ⁠נָשָׂ֥א חֶטְאֽ⁠וֹ׃","wĕ⁠ʼel-bĕ̇né֥y yişĕ̂ráʼé֖l ţĕ̇dabé֣̇r lé⁠ʼmò֑r ʼi֥yş̌ ʼi֛yş̌ kiֽ̇y-yĕqalé֥̇l ʼèlòhá֖y⁠w wĕ⁠náşá֥̂ʼ ẖetĕʼֽ⁠wò׃"],[24,16,"וְ⁠נֹקֵ֤ב שֵׁם־יְהוָה֙ מ֣וֹת יוּמָ֔ת רָג֥וֹם יִרְגְּמוּ־ב֖⁠וֹ כָּל־הָ⁠עֵדָ֑ה כַּ⁠גֵּר֙ כָּֽ⁠אֶזְרָ֔ח בְּ⁠נָקְב⁠וֹ־שֵׁ֖ם יוּמָֽת׃","wĕ⁠nòqé֤b şé̌m-yĕhwáh֙ m֣wòţ yẇmá֔ţ rág֥wòm yirĕgĕ̇mẇ-b֖⁠wò ká̇l-há⁠ʻédá֑h kȧ⁠gé̇r֙ káֽ̇⁠ʼezĕrá֔ẖ bĕ̇⁠náqĕb⁠wò-şé֖̌m yẇmáֽţ׃"],[24,17,"וְ⁠אִ֕ישׁ כִּ֥י יַכֶּ֖ה כָּל־נֶ֣פֶשׁ אָדָ֑ם מ֖וֹת יוּמָֽת׃","wĕ⁠ʼi֕yş̌ ki֥̇y yakė֖h ká̇l-ne֣peş̌ ʼádá֑m m֖wòţ yẇmáֽţ׃"],[24,18,"וּ⁠מַכֵּ֥ה נֶֽפֶשׁ־בְּהֵמָ֖ה יְשַׁלְּמֶ֑⁠נָּה נֶ֖פֶשׁ תַּ֥חַת נָֽפֶשׁ׃","ẇ⁠maké֥̇h neֽpeş̌-bĕ̇hémá֖h yĕşǎlĕ̇me֑⁠ná̇h ne֖peş̌ ţȧ֥ẖaţ náֽpeş̌׃"],[24,19,"וְ⁠אִ֕ישׁ כִּֽי־יִתֵּ֥ן מ֖וּם בַּ⁠עֲמִית֑⁠וֹ כַּ⁠אֲשֶׁ֣ר עָשָׂ֔ה כֵּ֖ן יֵעָ֥שֶׂה לּֽ⁠וֹ׃","wĕ⁠ʼi֕yş̌ kiֽ̇y-yiţé֥̇n m֖ẇm bȧ⁠ʻàmiyţ֑⁠wò kȧ⁠ʼàşě֣r ʻáşá̂֔h ké֖̇n yéʻá֥şêh lֽ̇⁠wò׃"],[24,20,"שֶׁ֚בֶר תַּ֣חַת שֶׁ֔בֶר עַ֚יִן תַּ֣חַת עַ֔יִן שֵׁ֖ן תַּ֣חַת שֵׁ֑ן כַּ⁠אֲשֶׁ֨ר יִתֵּ֥ן מוּם֙ בָּֽ⁠אָדָ֔ם כֵּ֖ן יִנָּ֥תֶן בּֽ⁠וֹ׃","şě֚ber ţȧ֣ẖaţ şě֔ber ʻa֚yin ţȧ֣ẖaţ ʻa֔yin şé֖̌n ţȧ֣ẖaţ şé֑̌n kȧ⁠ʼàşě֨r yiţé֥̇n mẇm֙ báֽ̇⁠ʼádá֔m ké֖̇n yiná֥̇ţen ḃֽ⁠wò׃"],[24,21,"וּ⁠מַכֵּ֥ה בְהֵמָ֖ה יְשַׁלְּמֶ֑⁠נָּה וּ⁠מַכֵּ֥ה אָדָ֖ם יוּמָֽת׃","ẇ⁠maké֥̇h bĕhémá֖h yĕşǎlĕ̇me֑⁠ná̇h ẇ⁠maké֥̇h ʼádá֖m yẇmáֽţ׃"],[24,22,"מִשְׁפַּ֤ט אֶחָד֙ יִהְיֶ֣ה לָ⁠כֶ֔ם כַּ⁠גֵּ֥ר כָּ⁠אֶזְרָ֖ח יִהְיֶ֑ה כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","mişĕ̌pȧ֤t ʼeẖád֙ yihĕye֣h lá⁠ke֔m kȧ⁠gé֥̇r ká̇⁠ʼezĕrá֖ẖ yihĕye֑h ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[24,23,"וַ⁠יְדַבֵּ֣ר מֹשֶׁה֮ אֶל־בְּנֵ֣י יִשְׂרָאֵל֒ וַ⁠יּוֹצִ֣יאוּ אֶת־הַֽ⁠מְקַלֵּ֗ל אֶל־מִ⁠חוּץ֙ לַֽ⁠מַּחֲנֶ֔ה וַ⁠יִּרְגְּמ֥וּ אֹת֖⁠וֹ אָ֑בֶן וּ⁠בְנֵֽי־יִשְׂרָאֵ֣ל עָשׂ֔וּ כַּֽ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃פ","wa⁠yĕdabé֣̇r mòşěh֮ ʼel-bĕ̇né֣y yişĕ̂ráʼél֒ wa⁠ẏwòẕi֣yʼẇ ʼeţ-haֽ⁠mĕqalé̇֗l ʼel-mi⁠ẖẇẕ֙ laֽ⁠mȧẖàne֔h wa⁠yi̇rĕgĕ̇m֥ẇ ʼòţ֖⁠wò ʼá֑ben ẇ⁠bĕnéֽy-yişĕ̂ráʼé֣l ʻáş̂֔ẇ kֽ̇a⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃p"],[25,1,"וַ⁠יְדַבֵּ֤ר יְהוָה֙ אֶל־מֹשֶׁ֔ה בְּ⁠הַ֥ר סִינַ֖י לֵ⁠אמֹֽר׃","wa⁠yĕdabé֤̇r yĕhwáh֙ ʼel-mòşě֔h bĕ̇⁠ha֥r siyna֖y lé⁠ʼmòֽr׃"],[25,2,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם כִּ֤י תָבֹ֨אוּ֙ אֶל־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר אֲנִ֖י נֹתֵ֣ן לָ⁠כֶ֑ם וְ⁠שָׁבְתָ֣ה הָ⁠אָ֔רֶץ שַׁבָּ֖ת לַ⁠יהוָֽה׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m ki֤̇y ţábò֨ʼẇ֙ ʼel-há⁠ʼá֔reẕ ʼàşě֥r ʼàni֖y nòţé֣n lá⁠ke֑m wĕ⁠şá̌bĕţá֣h há⁠ʼá֔reẕ şǎbá֖̇ţ la⁠yhwáֽh׃"],[25,3,"שֵׁ֤שׁ שָׁנִים֙ תִּזְרַ֣ע שָׂדֶ֔⁠ךָ וְ⁠שֵׁ֥שׁ שָׁנִ֖ים תִּזְמֹ֣ר כַּרְמֶ֑⁠ךָ וְ⁠אָסַפְתָּ֖ אֶת־תְּבוּאָתָֽ⁠הּ׃","şé֤̌ş̌ şá̌niym֙ ţi̇zĕra֣ʻ şá̂de֔⁠ká wĕ⁠şé֥̌ş̌ şá̌ni֖ym ţi̇zĕmò֣r kȧrĕme֑⁠ká wĕ⁠ʼásapĕţá֖̇ ʼeţ-ţĕ̇bẇʼáţáֽ⁠ḣ׃"],[25,4,"וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠שְּׁבִיעִ֗ת שַׁבַּ֤ת שַׁבָּתוֹן֙ יִהְיֶ֣ה לָ⁠אָ֔רֶץ שַׁבָּ֖ת לַ⁠יהוָ֑ה שָֽׂדְ⁠ךָ֙ לֹ֣א תִזְרָ֔ע וְ⁠כַרְמְ⁠ךָ֖ לֹ֥א תִזְמֹֽר׃","ẇ⁠ba⁠şá̇̌ná֣h ha⁠şĕ̇̌biyʻi֗ţ şǎbȧ֤ţ şǎbá̇ţwòn֙ yihĕye֣h lá⁠ʼá֔reẕ şǎbá֖̇ţ la⁠yhwá֑h şáֽ̂dĕ⁠ká֙ lò֣ʼ ţizĕrá֔ʻ wĕ⁠karĕmĕ⁠ká֖ lò֥ʼ ţizĕmòֽr׃"],[25,5,"אֵ֣ת סְפִ֤יחַ קְצִֽירְ⁠ךָ֙ לֹ֣א תִקְצ֔וֹר וְ⁠אֶת־עִנְּבֵ֥י נְזִירֶ֖⁠ךָ לֹ֣א תִבְצֹ֑ר שְׁנַ֥ת שַׁבָּת֖וֹן יִהְיֶ֥ה לָ⁠אָֽרֶץ׃","ʼé֣ţ sĕpi֤yẖa qĕẕiֽyrĕ⁠ká֙ lò֣ʼ ţiqĕẕ֔wòr wĕ⁠ʼeţ-ʻinĕ̇bé֥y nĕziyre֖⁠ká lò֣ʼ ţibĕẕò֑r şĕ̌na֥ţ şǎbá̇ţ֖wòn yihĕye֥h lá⁠ʼáֽreẕ׃"],[25,6,"וְ֠⁠הָיְתָה שַׁבַּ֨ת הָ⁠אָ֤רֶץ לָ⁠כֶם֙ לְ⁠אָכְלָ֔ה לְ⁠ךָ֖ וּ⁠לְ⁠עַבְדְּ⁠ךָ֣ וְ⁠לַ⁠אֲמָתֶ֑⁠ךָ וְ⁠לִ⁠שְׂכִֽירְ⁠ךָ֙ וּ⁠לְ⁠תוֹשָׁ֣בְ⁠ךָ֔ הַ⁠גָּרִ֖ים עִמָּֽ⁠ךְ׃","wĕ֠⁠háyĕţáh şǎbȧ֨ţ há⁠ʼá֤reẕ lá⁠kem֙ lĕ⁠ʼákĕlá֔h lĕ⁠ká֖ ẇ⁠lĕ⁠ʻabĕdĕ̇⁠ká֣ wĕ⁠la⁠ʼàmáţe֑⁠ká wĕ⁠li⁠şĕ̂kiֽyrĕ⁠ká֙ ẇ⁠lĕ⁠ţwòşá֣̌bĕ⁠ká֔ ha⁠gá̇ri֖ym ʻimáֽ̇⁠kĕ׃"],[25,7,"וְ⁠לִ֨⁠בְהֶמְתְּ⁠ךָ֔ וְ⁠לַֽ⁠חַיָּ֖ה אֲשֶׁ֣ר בְּ⁠אַרְצֶ֑⁠ךָ תִּהְיֶ֥ה כָל־תְּבוּאָתָ֖⁠הּ לֶ⁠אֱכֹֽל׃ס","wĕ⁠li֨⁠bĕhemĕţĕ̇⁠ká֔ wĕ⁠laֽ⁠ẖayá֖̇h ʼàşě֣r bĕ̇⁠ʼarĕẕe֑⁠ká ţi̇hĕye֥h kál-ţĕ̇bẇʼáţá֖⁠ḣ le⁠ʼèkòֽl׃s"],[25,8,"וְ⁠סָפַרְתָּ֣ לְ⁠ךָ֗ שֶׁ֚בַע שַׁבְּתֹ֣ת שָׁנִ֔ים שֶׁ֥בַע שָׁנִ֖ים שֶׁ֣בַע פְּעָמִ֑ים וְ⁠הָי֣וּ לְ⁠ךָ֗ יְמֵי֙ שֶׁ֚בַע שַׁבְּתֹ֣ת הַ⁠שָּׁנִ֔ים תֵּ֥שַׁע וְ⁠אַרְבָּעִ֖ים שָׁנָֽה׃","wĕ⁠sáparĕţá֣̇ lĕ⁠ká֗ şě֚baʻ şǎbĕ̇ţò֣ţ şá̌ni֔ym şě֥baʻ şá̌ni֖ym şě֣baʻ pĕ̇ʻámi֑ym wĕ⁠háy֣ẇ lĕ⁠ká֗ yĕméy֙ şě֚baʻ şǎbĕ̇ţò֣ţ ha⁠şá̇̌ni֔ym ţé֥̇şǎʻ wĕ⁠ʼarĕbá̇ʻi֖ym şá̌náֽh׃"],[25,9,"וְ⁠הַֽעֲבַרְתָּ֞ שׁוֹפַ֤ר תְּרוּעָה֙ בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִעִ֔י בֶּ⁠עָשׂ֖וֹר לַ⁠חֹ֑דֶשׁ בְּ⁠יוֹם֙ הַ⁠כִּפֻּרִ֔ים תַּעֲבִ֥ירוּ שׁוֹפָ֖ר בְּ⁠כָל־אַרְצְ⁠כֶֽם׃","wĕ⁠hֽaʻàbarĕţá̇֞ ş̌wòpa֤r ţĕ̇rẇʻáh֙ bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌biʻi֔y bė⁠ʻáş֖̂wòr la⁠ẖò֑deş̌ bĕ̇⁠ywòm֙ ha⁠ki̇pu̇ri֔ym ţȧʻàbi֥yrẇ ş̌wòpá֖r bĕ̇⁠kál-ʼarĕẕĕ⁠keֽm׃"],[25,10,"וְ⁠קִדַּשְׁתֶּ֗ם אֵ֣ת שְׁנַ֤ת הַ⁠חֲמִשִּׁים֙ שָׁנָ֔ה וּ⁠קְרָאתֶ֥ם דְּר֛וֹר בָּ⁠אָ֖רֶץ לְ⁠כָל־יֹשְׁבֶ֑י⁠הָ יוֹבֵ֥ל הִוא֙ תִּהְיֶ֣ה לָ⁠כֶ֔ם וְ⁠שַׁבְתֶּ֗ם אִ֚ישׁ אֶל־אֲחֻזָּת֔⁠וֹ וְ⁠אִ֥ישׁ אֶל־מִשְׁפַּחְתּ֖⁠וֹ תָּשֻֽׁבוּ׃","wĕ⁠qidȧşĕ̌ţė֗m ʼé֣ţ şĕ̌na֤ţ ha⁠ẖàmişi̇̌ym֙ şá̌ná֔h ẇ⁠qĕráʼţe֥m dĕ̇r֛wòr bá̇⁠ʼá֖reẕ lĕ⁠kál-yòşĕ̌be֑y⁠há ywòbé֥l hiwʼ֙ ţi̇hĕye֣h lá⁠ke֔m wĕ⁠şǎbĕţė֗m ʼi֚yş̌ ʼel-ʼàẖuzá̇ţ֔⁠wò wĕ⁠ʼi֥yş̌ ʼel-mişĕ̌pȧẖĕţ֖̇⁠wò ţá̇şǔֽbẇ׃"],[25,11,"יוֹבֵ֣ל הִ֗וא שְׁנַ֛ת הַ⁠חֲמִשִּׁ֥ים שָׁנָ֖ה תִּהְיֶ֣ה לָ⁠כֶ֑ם לֹ֣א תִזְרָ֔עוּ וְ⁠לֹ֤א תִקְצְרוּ֙ אֶת־סְפִיחֶ֔י⁠הָ וְ⁠לֹ֥א תִבְצְר֖וּ אֶת־נְזִרֶֽי⁠הָ׃","ywòbé֣l hi֗wʼ şĕ̌na֛ţ ha⁠ẖàmişi֥̇̌ym şá̌ná֖h ţi̇hĕye֣h lá⁠ke֑m lò֣ʼ ţizĕrá֔ʻẇ wĕ⁠lò֤ʼ ţiqĕẕĕrẇ֙ ʼeţ-sĕpiyẖe֔y⁠há wĕ⁠lò֥ʼ ţibĕẕĕr֖ẇ ʼeţ-nĕzireֽy⁠há׃"],[25,12,"כִּ֚י יוֹבֵ֣ל הִ֔וא קֹ֖דֶשׁ תִּהְיֶ֣ה לָ⁠כֶ֑ם מִן־הַ֨⁠שָּׂדֶ֔ה תֹּאכְל֖וּ אֶת־תְּבוּאָתָֽ⁠הּ׃","ki֚̇y ywòbé֣l hi֔wʼ qò֖deş̌ ţi̇hĕye֣h lá⁠ke֑m min-ha֨⁠şá̇̂de֔h ţò̇ʼkĕl֖ẇ ʼeţ-ţĕ̇bẇʼáţáֽ⁠ḣ׃"],[25,13,"בִּ⁠שְׁנַ֥ת הַ⁠יּוֹבֵ֖ל הַ⁠זֹּ֑את תָּשֻׁ֕בוּ אִ֖ישׁ אֶל־אֲחֻזָּתֽ⁠וֹ׃","bi̇⁠şĕ̌na֥ţ ha⁠ẏwòbé֖l ha⁠zò֑̇ʼţ ţá̇şǔ֕bẇ ʼi֖yş̌ ʼel-ʼàẖuzá̇ţֽ⁠wò׃"],[25,14,"וְ⁠כִֽי־תִמְכְּר֤וּ מִמְכָּר֙ לַ⁠עֲמִיתֶ֔⁠ךָ א֥וֹ קָנֹ֖ה מִ⁠יַּ֣ד עֲמִיתֶ֑⁠ךָ אַל־תּוֹנ֖וּ אִ֥ישׁ אֶת־אָחִֽי⁠ו׃","wĕ⁠kiֽy-ţimĕkĕ̇r֤ẇ mimĕká̇r֙ la⁠ʻàmiyţe֔⁠ká ʼ֥wò qánò֖h mi⁠yȧ֣d ʻàmiyţe֑⁠ká ʼal-ţ̇wòn֖ẇ ʼi֥yş̌ ʼeţ-ʼáẖiֽy⁠w׃"],[25,15,"בְּ⁠מִסְפַּ֤ר שָׁנִים֙ אַחַ֣ר הַ⁠יּוֹבֵ֔ל תִּקְנֶ֖ה מֵ⁠אֵ֣ת עֲמִיתֶ֑⁠ךָ בְּ⁠מִסְפַּ֥ר שְׁנֵֽי־תְבוּאֹ֖ת יִמְכָּר־לָֽ⁠ךְ׃","bĕ̇⁠misĕpȧ֤r şá̌niym֙ ʼaẖa֣r ha⁠ẏwòbé֔l ţi̇qĕne֖h mé⁠ʼé֣ţ ʻàmiyţe֑⁠ká bĕ̇⁠misĕpȧ֥r şĕ̌néֽy-ţĕbẇʼò֖ţ yimĕká̇r-láֽ⁠kĕ׃"],[25,16,"לְ⁠פִ֣י ׀ רֹ֣ב הַ⁠שָּׁנִ֗ים תַּרְבֶּה֙ מִקְנָת֔⁠וֹ וּ⁠לְ⁠פִי֙ מְעֹ֣ט הַ⁠שָּׁנִ֔ים תַּמְעִ֖יט מִקְנָת֑⁠וֹ כִּ֚י מִסְפַּ֣ר תְּבוּאֹ֔ת ה֥וּא מֹכֵ֖ר לָֽ⁠ךְ׃","lĕ⁠pi֣y ׀ rò֣b ha⁠şá̇̌ni֗ym ţȧrĕbėh֙ miqĕnáţ֔⁠wò ẇ⁠lĕ⁠piy֙ mĕʻò֣t ha⁠şá̇̌ni֔ym ţȧmĕʻi֖yt miqĕnáţ֑⁠wò ki֚̇y misĕpȧ֣r ţĕ̇bẇʼò֔ţ h֥ẇʼ mòké֖r láֽ⁠kĕ׃"],[25,17,"וְ⁠לֹ֤א תוֹנוּ֙ אִ֣ישׁ אֶת־עֲמִית֔⁠וֹ וְ⁠יָרֵ֖אתָ מֵֽ⁠אֱלֹהֶ֑י⁠ךָ כִּ֛י אֲנִ֥י יְהֹוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠lò֤ʼ ţwònẇ֙ ʼi֣yş̌ ʼeţ-ʻàmiyţ֔⁠wò wĕ⁠yáré֖ʼţá méֽ⁠ʼèlòhe֑y⁠ká ki֛̇y ʼàni֥y yĕhòwá֖h ʼèlòhéy⁠keֽm׃"],[25,18,"וַ⁠עֲשִׂיתֶם֙ אֶת־חֻקֹּתַ֔⁠י וְ⁠אֶת־מִשְׁפָּטַ֥⁠י תִּשְׁמְר֖וּ וַ⁠עֲשִׂיתֶ֣ם אֹתָ֑⁠ם וִֽ⁠ישַׁבְתֶּ֥ם עַל־הָ⁠אָ֖רֶץ לָ⁠בֶֽטַח׃","wa⁠ʻàşîyţem֙ ʼeţ-ẖuqò̇ţa֔⁠y wĕ⁠ʼeţ-mişĕ̌pá̇ta֥⁠y ţi̇şĕ̌mĕr֖ẇ wa⁠ʻàşîyţe֣m ʼòţá֑⁠m wiֽ⁠yşǎbĕţė֥m ʻal-há⁠ʼá֖reẕ lá⁠beֽtaẖ׃"],[25,19,"וְ⁠נָתְנָ֤ה הָ⁠אָ֨רֶץ֙ פִּרְיָ֔⁠הּ וַ⁠אֲכַלְתֶּ֖ם לָ⁠שֹׂ֑בַע וִֽ⁠ישַׁבְתֶּ֥ם לָ⁠בֶ֖טַח עָלֶֽי⁠הָ׃","wĕ⁠náţĕná֤h há⁠ʼá֨reẕ֙ pi̇rĕyá֔⁠ḣ wa⁠ʼàkalĕţė֖m lá⁠şò֑̂baʻ wiֽ⁠yşǎbĕţė֥m lá⁠be֖taẖ ʻáleֽy⁠há׃"],[25,20,"וְ⁠כִ֣י תֹאמְר֔וּ מַה־נֹּאכַ֤֖ל בַּ⁠שָּׁנָ֣ה הַ⁠שְּׁבִיעִ֑ת הֵ֚ן לֹ֣א נִזְרָ֔ע וְ⁠לֹ֥א נֶאֱסֹ֖ף אֶת־תְּבוּאָתֵֽ⁠נוּ׃","wĕ⁠ki֣y ţòʼmĕr֔ẇ mah-nò̇ʼka֤֖l bȧ⁠şá̇̌ná֣h ha⁠şĕ̇̌biyʻi֑ţ hé֚n lò֣ʼ nizĕrá֔ʻ wĕ⁠lò֥ʼ neʼèsò֖p ʼeţ-ţĕ̇bẇʼáţéֽ⁠nẇ׃"],[25,21,"וְ⁠צִוִּ֤יתִי אֶת־בִּרְכָתִ⁠י֙ לָ⁠כֶ֔ם בַּ⁠שָּׁנָ֖ה הַ⁠שִּׁשִּׁ֑ית וְ⁠עָשָׂת֙ אֶת־הַ⁠תְּבוּאָ֔ה לִ⁠שְׁלֹ֖שׁ הַ⁠שָּׁנִֽים׃","wĕ⁠ẕiwi֤̇yţiy ʼeţ-bi̇rĕkáţi⁠y֙ lá⁠ke֔m bȧ⁠şá̇̌ná֖h ha⁠şi̇̌şi֑̇̌yţ wĕ⁠ʻáşá̂ţ֙ ʼeţ-ha⁠ţĕ̇bẇʼá֔h li⁠şĕ̌lò֖ş̌ ha⁠şá̇̌niֽym׃"],[25,22,"וּ⁠זְרַעְתֶּ֗ם אֵ֚ת הַ⁠שָּׁנָ֣ה הַ⁠שְּׁמִינִ֔ת וַ⁠אֲכַלְתֶּ֖ם מִן־הַ⁠תְּבוּאָ֣ה יָשָׁ֑ן עַ֣ד ׀ הַ⁠שָּׁנָ֣ה הַ⁠תְּשִׁיעִ֗ת עַד־בּוֹא֙ תְּב֣וּאָתָ֔⁠הּ תֹּאכְל֖וּ יָשָֽׁן׃","ẇ⁠zĕraʻĕţė֗m ʼé֚ţ ha⁠şá̇̌ná֣h ha⁠şĕ̇̌miyni֔ţ wa⁠ʼàkalĕţė֖m min-ha⁠ţĕ̇bẇʼá֣h yáşá֑̌n ʻa֣d ׀ ha⁠şá̇̌ná֣h ha⁠ţĕ̇şǐyʻi֗ţ ʻad-ḃwòʼ֙ ţĕ̇b֣ẇʼáţá֔⁠ḣ ţò̇ʼkĕl֖ẇ yáşáֽ̌n׃"],[25,23,"וְ⁠הָ⁠אָ֗רֶץ לֹ֤א תִמָּכֵר֙ לִ⁠צְמִתֻ֔ת כִּי־לִ֖⁠י הָ⁠אָ֑רֶץ כִּֽי־גֵרִ֧ים וְ⁠תוֹשָׁבִ֛ים אַתֶּ֖ם עִמָּדִֽ⁠י׃","wĕ⁠há⁠ʼá֗reẕ lò֤ʼ ţimá̇kér֙ li⁠ẕĕmiţu֔ţ ki̇y-li֖⁠y há⁠ʼá֑reẕ kiֽ̇y-géri֧ym wĕ⁠ţwòşá̌bi֛ym ʼaţė֖m ʻimá̇diֽ⁠y׃"],[25,24,"וּ⁠בְ⁠כֹ֖ל אֶ֣רֶץ אֲחֻזַּתְ⁠כֶ֑ם גְּאֻלָּ֖ה תִּתְּנ֥וּ לָ⁠אָֽרֶץ׃ס","ẇ⁠bĕ⁠kò֖l ʼe֣reẕ ʼàẖuzȧţĕ⁠ke֑m gĕ̇ʼulá֖̇h ţi̇ţĕ̇n֥ẇ lá⁠ʼáֽreẕ׃s"],[25,25,"כִּֽי־יָמ֣וּךְ אָחִ֔י⁠ךָ וּ⁠מָכַ֖ר מֵ⁠אֲחֻזָּת֑⁠וֹ וּ⁠בָ֤א גֹֽאֲל⁠וֹ֙ הַ⁠קָּרֹ֣ב אֵלָ֔י⁠ו וְ⁠גָאַ֕ל אֵ֖ת מִמְכַּ֥ר אָחִֽי⁠ו׃","kiֽ̇y-yám֣ẇkĕ ʼáẖi֔y⁠ká ẇ⁠máka֖r mé⁠ʼàẖuzá̇ţ֑⁠wò ẇ⁠bá֤ʼ gòֽʼàl⁠wò֙ ha⁠qá̇rò֣b ʼélá֔y⁠w wĕ⁠gáʼa֕l ʼé֖ţ mimĕkȧ֥r ʼáẖiֽy⁠w׃"],[25,26,"וְ⁠אִ֕ישׁ כִּ֛י לֹ֥א יִֽהְיֶה־לּ֖⁠וֹ גֹּאֵ֑ל וְ⁠הִשִּׂ֣יגָה יָד֔⁠וֹ וּ⁠מָצָ֖א כְּ⁠דֵ֥י גְאֻלָּתֽ⁠וֹ׃","wĕ⁠ʼi֕yş̌ ki֛̇y lò֥ʼ yiֽhĕyeh-l֖̇⁠wò gò̇ʼé֑l wĕ⁠hişi֣̇̂ygáh yád֔⁠wò ẇ⁠máẕá֖ʼ kĕ̇⁠dé֥y gĕʼulá̇ţֽ⁠wò׃"],[25,27,"וְ⁠חִשַּׁב֙ אֶת־שְׁנֵ֣י מִמְכָּר֔⁠וֹ וְ⁠הֵשִׁיב֙ אֶת־הָ֣⁠עֹדֵ֔ף לָ⁠אִ֖ישׁ אֲשֶׁ֣ר מָֽכַר־ל֑⁠וֹ וְ⁠שָׁ֖ב לַ⁠אֲחֻזָּתֽ⁠וֹ׃","wĕ⁠ẖişȧ̌b֙ ʼeţ-şĕ̌né֣y mimĕká̇r֔⁠wò wĕ⁠héşǐyb֙ ʼeţ-há֣⁠ʻòdé֔p lá⁠ʼi֖yş̌ ʼàşě֣r máֽkar-l֑⁠wò wĕ⁠şá֖̌b la⁠ʼàẖuzá̇ţֽ⁠wò׃"],[25,28,"וְ⁠אִ֨ם לֹֽא־מָֽצְאָ֜ה יָד֗⁠וֹ דֵּי֮ הָשִׁ֣יב ל⁠וֹ֒ וְ⁠הָיָ֣ה מִמְכָּר֗⁠וֹ בְּ⁠יַד֙ הַ⁠קֹּנֶ֣ה אֹת֔⁠וֹ עַ֖ד שְׁנַ֣ת הַ⁠יּוֹבֵ֑ל וְ⁠יָצָא֙ בַּ⁠יֹּבֵ֔ל וְ⁠שָׁ֖ב לַ⁠אֲחֻזָּתֽ⁠וֹ׃","wĕ⁠ʼi֨m lòֽʼ-mֽáẕĕʼá֜h yád֗⁠wò dé̇y֮ háşǐ֣yb l⁠wò֒ wĕ⁠háyá֣h mimĕká̇r֗⁠wò bĕ̇⁠yad֙ ha⁠qò̇ne֣h ʼòţ֔⁠wò ʻa֖d şĕ̌na֣ţ ha⁠ẏwòbé֑l wĕ⁠yáẕáʼ֙ bȧ⁠yò̇bé֔l wĕ⁠şá֖̌b la⁠ʼàẖuzá̇ţֽ⁠wò׃"],[25,29,"וְ⁠אִ֗ישׁ כִּֽי־יִמְכֹּ֤ר בֵּית־מוֹשַׁב֙ עִ֣יר חוֹמָ֔ה וְ⁠הָיְתָה֙ גְּאֻלָּת֔⁠וֹ עַד־תֹּ֖ם שְׁנַ֣ת מִמְכָּר֑⁠וֹ יָמִ֖ים תִּהְיֶ֥ה גְאֻלָּתֽ⁠וֹ׃","wĕ⁠ʼi֗yş̌ kiֽ̇y-yimĕkò֤̇r bé̇yţ-mwòşǎb֙ ʻi֣yr ẖwòmá֔h wĕ⁠háyĕţáh֙ gĕ̇ʼulá̇ţ֔⁠wò ʻad-ţò֖̇m şĕ̌na֣ţ mimĕká̇r֑⁠wò yámi֖ym ţi̇hĕye֥h gĕʼulá̇ţֽ⁠wò׃"],[25,30,"וְ⁠אִ֣ם לֹֽא־יִגָּאֵ֗ל עַד־מְלֹ֣את ל⁠וֹ֮ שָׁנָ֣ה תְמִימָה֒ וְ֠⁠קָם הַ⁠בַּ֨יִת אֲשֶׁר־בָּ⁠עִ֜יר אֲשֶׁר־לא חֹמָ֗ה לַ⁠צְּמִיתֻ֛ת לַ⁠קֹּנֶ֥ה אֹת֖⁠וֹ לְ⁠דֹרֹתָ֑י⁠ו לֹ֥א יֵצֵ֖א בַּ⁠יֹּבֵֽל׃","wĕ⁠ʼi֣m lòֽʼ-yigá̇ʼé֗l ʻad-mĕlò֣ʼţ l⁠wò֮ şá̌ná֣h ţĕmiymáh֒ wĕ֠⁠qám ha⁠bȧ֨yiţ ʼàşěr-bá̇⁠ʻi֜yr ʼàşěr-lʼ ẖòmá֗h la⁠ẕĕ̇miyţu֛ţ la⁠qò̇ne֥h ʼòţ֖⁠wò lĕ⁠dòròţá֑y⁠w lò֥ʼ yéẕé֖ʼ bȧ⁠yò̇béֽl׃"],[25,31,"וּ⁠בָתֵּ֣י הַ⁠חֲצֵרִ֗ים אֲשֶׁ֨ר אֵין־לָ⁠הֶ֤ם חֹמָה֙ סָבִ֔יב עַל־שְׂדֵ֥ה הָ⁠אָ֖רֶץ יֵחָשֵׁ֑ב גְּאֻלָּה֙ תִּהְיֶה־לּ֔⁠וֹ וּ⁠בַ⁠יֹּבֵ֖ל יֵצֵֽא׃","ẇ⁠báţé֣̇y ha⁠ẖàẕéri֗ym ʼàşě֨r ʼéyn-lá⁠he֤m ẖòmáh֙ sábi֔yb ʻal-şĕ̂dé֥h há⁠ʼá֖reẕ yéẖáşé֑̌b gĕ̇ʼulá̇h֙ ţi̇hĕyeh-l̇֔⁠wò ẇ⁠ba⁠yò̇bé֖l yéẕéֽʼ׃"],[25,32,"וְ⁠עָרֵי֙ הַ⁠לְוִיִּ֔ם בָּתֵּ֖י עָרֵ֣י אֲחֻזָּתָ֑⁠ם גְּאֻלַּ֥ת עוֹלָ֖ם תִּהְיֶ֥ה לַ⁠לְוִיִּֽם׃","wĕ⁠ʻáréy֙ ha⁠lĕwiyi̇֔m bá̇ţé֖̇y ʻáré֣y ʼàẖuzá̇ţá֑⁠m gĕ̇ʼulȧ֥ţ ʻwòlá֖m ţi̇hĕye֥h la⁠lĕwiyiֽ̇m׃"],[25,33,"וַ⁠אֲשֶׁ֤ר יִגְאַל֙ מִן־הַ⁠לְוִיִּ֔ם וְ⁠יָצָ֧א מִמְכַּר־בַּ֛יִת וְ⁠עִ֥יר אֲחֻזָּת֖⁠וֹ בַּ⁠יֹּבֵ֑ל כִּ֣י בָתֵּ֞י עָרֵ֣י הַ⁠לְוִיִּ֗ם הִ֚וא אֲחֻזָּתָ֔⁠ם בְּ⁠ת֖וֹךְ בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠ʼàşě֤r yigĕʼal֙ min-ha⁠lĕwiyi̇֔m wĕ⁠yáẕá֧ʼ mimĕkȧr-bȧ֛yiţ wĕ⁠ʻi֥yr ʼàẖuzá̇ţ֖⁠wò bȧ⁠yò̇bé֑l ki֣̇y báţé̇֞y ʻáré֣y ha⁠lĕwiyi̇֗m hi֚wʼ ʼàẖuzá̇ţá֔⁠m bĕ̇⁠ţ֖wòkĕ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[25,34,"וּֽ⁠שְׂדֵ֛ה מִגְרַ֥שׁ עָרֵי⁠הֶ֖ם לֹ֣א יִמָּכֵ֑ר כִּֽי־אֲחֻזַּ֥ת עוֹלָ֛ם ה֖וּא לָ⁠הֶֽם׃ס","ẇֽ⁠şĕ̂dé֛h migĕra֥ş̌ ʻáréy⁠he֖m lò֣ʼ yimá̇ké֑r kiֽ̇y-ʼàẖuzȧ֥ţ ʻwòlá֛m h֖ẇʼ lá⁠heֽm׃s"],[25,35,"וְ⁠כִֽי־יָמ֣וּךְ אָחִ֔י⁠ךָ וּ⁠מָ֥טָה יָד֖⁠וֹ עִמָּ֑⁠ךְ וְ⁠הֶֽחֱזַ֣קְתָּ בּ֔⁠וֹ גֵּ֧ר וְ⁠תוֹשָׁ֛ב וָ⁠חַ֖י עִמָּֽ⁠ךְ׃","wĕ⁠kiֽy-yám֣ẇkĕ ʼáẖi֔y⁠ká ẇ⁠má֥táh yád֖⁠wò ʻimá֑̇⁠kĕ wĕ⁠heֽẖèza֣qĕţá̇ ḃ֔⁠wò gé֧̇r wĕ⁠ţwòşá֛̌b wá⁠ẖa֖y ʻimáֽ̇⁠kĕ׃"],[25,36,"אַל־תִּקַּ֤ח מֵֽ⁠אִתּ⁠וֹ֙ נֶ֣שֶׁךְ וְ⁠תַרְבִּ֔ית וְ⁠יָרֵ֖אתָ מֵֽ⁠אֱלֹהֶ֑י⁠ךָ וְ⁠חֵ֥י אָחִ֖י⁠ךָ עִמָּֽ⁠ךְ׃","ʼal-ţi̇qȧ֤ẖ méֽ⁠ʼiţ̇⁠wò֙ ne֣şěkĕ wĕ⁠ţarĕbi̇֔yţ wĕ⁠yáré֖ʼţá mֽé⁠ʼèlòhe֑y⁠ká wĕ⁠ẖé֥y ʼáẖi֖y⁠ká ʻimáֽ̇⁠kĕ׃"],[25,37,"אֶ֨ת־כַּסְפְּ⁠ךָ֔ לֹֽא־תִתֵּ֥ן ל֖⁠וֹ בְּ⁠נֶ֑שֶׁךְ וּ⁠בְ⁠מַרְבִּ֖ית לֹא־תִתֵּ֥ן אָכְלֶֽ⁠ךָ׃","ʼe֨ţ-kȧsĕpĕ̇⁠ká֔ lòֽʼ-ţiţé֥̇n l֖⁠wò bĕ̇⁠ne֑şěkĕ ẇ⁠bĕ⁠marĕbi֖̇yţ lòʼ-ţiţé֥̇n ʼákĕleֽ⁠ká׃"],[25,38,"אֲנִ֗י יְהוָה֙ אֱלֹ֣הֵי⁠כֶ֔ם אֲשֶׁר־הוֹצֵ֥אתִי אֶתְ⁠כֶ֖ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם לָ⁠תֵ֤ת לָ⁠כֶם֙ אֶת־אֶ֣רֶץ כְּנַ֔עַן לִ⁠הְי֥וֹת לָ⁠כֶ֖ם לֵ⁠אלֹהִֽים׃ס","ʼàni֗y yĕhwáh֙ ʼèlò֣héy⁠ke֔m ʼàşěr-hwòẕé֥ʼţiy ʼeţĕ⁠ke֖m mé⁠ʼe֣reẕ miẕĕrá֑yim lá⁠ţé֤ţ lá⁠kem֙ ʼeţ-ʼe֣reẕ kĕ̇na֔ʻan li⁠hĕy֥wòţ lá⁠ke֖m lé⁠ʼlòhiֽym׃s"],[25,39,"וְ⁠כִֽי־יָמ֥וּךְ אָחִ֛י⁠ךָ עִמָּ֖⁠ךְ וְ⁠נִמְכַּר־לָ֑⁠ךְ לֹא־תַעֲבֹ֥ד בּ֖⁠וֹ עֲבֹ֥דַת עָֽבֶד׃","wĕ⁠kiֽy-yám֥ẇkĕ ʼáẖi֛y⁠ká ʻimá֖̇⁠kĕ wĕ⁠nimĕkȧr-lá֑⁠kĕ lòʼ-ţaʻàbò֥d ḃ֖⁠wò ʻàbò֥daţ ʻáֽbed׃"],[25,40,"כְּ⁠שָׂכִ֥יר כְּ⁠תוֹשָׁ֖ב יִהְיֶ֣ה עִמָּ֑⁠ךְ עַד־שְׁנַ֥ת הַ⁠יֹּבֵ֖ל יַעֲבֹ֥ד עִמָּֽ⁠ךְ׃","kĕ̇⁠şá̂ki֥yr kĕ̇⁠ţwòşá֖̌b yihĕye֣h ʻimá֑̇⁠kĕ ʻad-şĕ̌na֥ţ ha⁠yò̇bé֖l yaʻàbò֥d ʻimáֽ̇⁠kĕ׃"],[25,41,"וְ⁠יָצָא֙ מֵֽ⁠עִמָּ֔⁠ךְ ה֖וּא וּ⁠בָנָ֣י⁠ו עִמּ֑⁠וֹ וְ⁠שָׁב֙ אֶל־מִשְׁפַּחְתּ֔⁠וֹ וְ⁠אֶל־אֲחֻזַּ֥ת אֲבֹתָ֖י⁠ו יָשֽׁוּב׃","wĕ⁠yáẕáʼ֙ méֽ⁠ʻimá̇֔⁠kĕ h֖ẇʼ ẇ⁠báná֣y⁠w ʻiṁ֑⁠wò wĕ⁠şá̌b֙ ʼel-mişĕ̌pȧẖĕţ̇֔⁠wò wĕ⁠ʼel-ʼàẖuzȧ֥ţ ʼàbòţá֖y⁠w yáşֽ̌ẇb׃"],[25,42,"כִּֽי־עֲבָדַ֣⁠י הֵ֔ם אֲשֶׁר־הוֹצֵ֥אתִי אֹתָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם לֹ֥א יִמָּכְר֖וּ מִמְכֶּ֥רֶת עָֽבֶד׃","kiֽ̇y-ʻàbáda֣⁠y hé֔m ʼàşěr-hwòẕé֥ʼţiy ʼòţá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim lò֥ʼ yimá̇kĕr֖ẇ mimĕkė֥reţ ʻáֽbed׃"],[25,43,"לֹא־תִרְדֶּ֥ה ב֖⁠וֹ בְּ⁠פָ֑רֶךְ וְ⁠יָרֵ֖אתָ מֵ⁠אֱלֹהֶֽי⁠ךָ׃","lòʼ-ţirĕdė֥h b֖⁠wò bĕ̇⁠pá֑rekĕ wĕ⁠yáré֖ʼţá mé⁠ʼèlòheֽy⁠ká׃"],[25,44,"וְ⁠עַבְדְּ⁠ךָ֥ וַ⁠אֲמָתְ⁠ךָ֖ אֲשֶׁ֣ר יִהְיוּ־לָ֑⁠ךְ מֵ⁠אֵ֣ת הַ⁠גּוֹיִ֗ם אֲשֶׁר֙ סְבִיבֹ֣תֵי⁠כֶ֔ם מֵ⁠הֶ֥ם תִּקְנ֖וּ עֶ֥בֶד וְ⁠אָמָֽה׃","wĕ⁠ʻabĕdĕ̇⁠ká֥ wa⁠ʼàmáţĕ⁠ká֖ ʼàşě֣r yihĕyẇ-lá֑⁠kĕ mé⁠ʼé֣ţ ha⁠ġwòyi֗m ʼàşěr֙ sĕbiybò֣ţéy⁠ke֔m mé⁠he֥m ţi̇qĕn֖ẇ ʻe֥bed wĕ⁠ʼámáֽh׃"],[25,45,"וְ֠⁠גַם מִ⁠בְּנֵ֨י הַ⁠תּוֹשָׁבִ֜ים הַ⁠גָּרִ֤ים עִמָּ⁠כֶם֙ מֵ⁠הֶ֣ם תִּקְנ֔וּ וּ⁠מִ⁠מִּשְׁפַּחְתָּ⁠ם֙ אֲשֶׁ֣ר עִמָּ⁠כֶ֔ם אֲשֶׁ֥ר הוֹלִ֖ידוּ בְּ⁠אַרְצְ⁠כֶ֑ם וְ⁠הָי֥וּ לָ⁠כֶ֖ם לַֽ⁠אֲחֻזָּֽה׃","wĕ֠⁠gam mi⁠bĕ̇né֨y ha⁠ţ̇wòşá̌bi֜ym ha⁠gá̇ri֤ym ʻimá̇⁠kem֙ mé⁠he֣m ţi̇qĕn֔ẇ ẇ⁠mi⁠mi̇şĕ̌pȧẖĕţá̇⁠m֙ ʼàşě֣r ʻimá̇⁠ke֔m ʼàşě֥r hwòli֖ydẇ bĕ̇⁠ʼarĕẕĕ⁠ke֑m wĕ⁠háy֥ẇ lá⁠ke֖m lֽa⁠ʼàẖuzáֽ̇h׃"],[25,46,"וְ⁠הִתְנַחֲלְתֶּ֨ם אֹתָ֜⁠ם לִ⁠בְנֵי⁠כֶ֤ם אַחֲרֵי⁠כֶם֙ לָ⁠רֶ֣שֶׁת אֲחֻזָּ֔ה לְ⁠עֹלָ֖ם בָּ⁠הֶ֣ם תַּעֲבֹ֑דוּ וּ⁠בְ⁠אַ֨חֵי⁠כֶ֤ם בְּנֵֽי־יִשְׂרָאֵל֙ אִ֣ישׁ בְּ⁠אָחִ֔י⁠ו לֹא־תִרְדֶּ֥ה ב֖⁠וֹ בְּ⁠פָֽרֶךְ׃ס","wĕ⁠hiţĕnaẖàlĕţė֨m ʼòţá֜⁠m li⁠bĕnéy⁠ke֤m ʼaẖàréy⁠kem֙ lá⁠re֣şěţ ʼàẖuzá̇֔h lĕ⁠ʻòlá֖m bá̇⁠he֣m ţȧʻàbò֑dẇ ẇ⁠bĕ⁠ʼa֨ẖéy⁠ke֤m bĕ̇néֽy-yişĕ̂ráʼél֙ ʼi֣yş̌ bĕ̇⁠ʼáẖi֔y⁠w lòʼ-ţirĕdė֥h b֖⁠wò bĕ̇⁠páֽrekĕ׃s"],[25,47,"וְ⁠כִ֣י תַשִּׂ֗יג יַ֣ד גֵּ֤ר וְ⁠תוֹשָׁב֙ עִמָּ֔⁠ךְ וּ⁠מָ֥ךְ אָחִ֖י⁠ךָ עִמּ֑⁠וֹ וְ⁠נִמְכַּ֗ר לְ⁠גֵ֤ר תּוֹשָׁב֙ עִמָּ֔⁠ךְ א֥וֹ לְ⁠עֵ֖קֶר מִשְׁפַּ֥חַת גֵּֽר׃","wĕ⁠ki֣y ţaşi̇̂֗yg ya֣d gé֤̇r wĕ⁠ţwòşá̌b֙ ʻimá̇֔⁠kĕ ẇ⁠má֥kĕ ʼáẖi֖y⁠ká ʻiṁ֑⁠wò wĕ⁠nimĕkȧ֗r lĕ⁠gé֤r ţ̇wòşá̌b֙ ʻimá̇֔⁠kĕ ʼ֥wò lĕ⁠ʻé֖qer mişĕ̌pȧ֥ẖaţ géֽ̇r׃"],[25,48,"אַחֲרֵ֣י נִמְכַּ֔ר גְּאֻלָּ֖ה תִּהְיֶה־לּ֑⁠וֹ אֶחָ֥ד מֵ⁠אֶחָ֖י⁠ו יִגְאָלֶֽ⁠נּוּ׃","ʼaẖàré֣y nimĕkȧ֔r gĕ̇ʼulá֖̇h ţi̇hĕyeh-l֑̇⁠wò ʼeẖá֥d mé⁠ʼeẖá֖y⁠w yigĕʼáleֽ⁠ṅẇ׃"],[25,49,"אוֹ־דֹד֞⁠וֹ א֤וֹ בֶן־דֹּד⁠וֹ֙ יִגְאָלֶ֔⁠נּוּ אֽוֹ־מִ⁠שְּׁאֵ֧ר בְּשָׂר֛⁠וֹ מִ⁠מִּשְׁפַּחְתּ֖⁠וֹ יִגְאָלֶ֑⁠נּוּ אֽוֹ־הִשִּׂ֥יגָה יָד֖⁠וֹ וְ⁠נִגְאָֽל׃","ʼwò-dòd֞⁠wò ʼ֤wò ben-dò̇d⁠wò֙ yigĕʼále֔⁠ṅẇ ʼֽwò-mi⁠şĕ̇̌ʼé֧r bĕ̇şá̂r֛⁠wò mi⁠mi̇şĕ̌pȧẖĕţ֖̇⁠wò yigĕʼále֑⁠ṅẇ ʼֽwò-hişi֥̇̂ygáh yád֖⁠wò wĕ⁠nigĕʼáֽl׃"],[25,50,"וְ⁠חִשַּׁב֙ עִם־קֹנֵ֔⁠הוּ מִ⁠שְּׁנַת֙ הִמָּ֣כְר⁠וֹ ל֔⁠וֹ עַ֖ד שְׁנַ֣ת הַ⁠יֹּבֵ֑ל וְ⁠הָיָ֞ה כֶּ֤סֶף מִמְכָּר⁠וֹ֙ בְּ⁠מִסְפַּ֣ר שָׁנִ֔ים כִּ⁠ימֵ֥י שָׂכִ֖יר יִהְיֶ֥ה עִמּֽ⁠וֹ׃","wĕ⁠ẖişȧ̌b֙ ʻim-qòné֔⁠hẇ mi⁠şĕ̇̌naţ֙ himá֣̇kĕr⁠wò l֔⁠wò ʻa֖d şĕ̌na֣ţ ha⁠yò̇bé֑l wĕ⁠háyá֞h kė֤sep mimĕká̇r⁠wò֙ bĕ̇⁠misĕpȧ֣r şá̌ni֔ym ki̇⁠ymé֥y şá̂ki֖yr yihĕye֥h ʻiṁֽ⁠wò׃"],[25,51,"אִם־ע֥וֹד רַבּ֖וֹת בַּ⁠שָּׁנִ֑ים לְ⁠פִי⁠הֶן֙ יָשִׁ֣יב גְּאֻלָּת֔⁠וֹ מִ⁠כֶּ֖סֶף מִקְנָתֽ⁠וֹ׃","ʼim-ʻ֥wòd raḃ֖wòţ bȧ⁠şá̇̌ni֑ym lĕ⁠piy⁠hen֙ yáşǐ֣yb gĕ̇ʼulá̇ţ֔⁠wò mi⁠kė֖sep miqĕnáţֽ⁠wò׃"],[25,52,"וְ⁠אִם־מְעַ֞ט נִשְׁאַ֧ר בַּ⁠שָּׁנִ֛ים עַד־שְׁנַ֥ת הַ⁠יֹּבֵ֖ל וְ⁠חִשַּׁב־ל֑⁠וֹ כְּ⁠פִ֣י שָׁנָ֔י⁠ו יָשִׁ֖יב אֶת־גְּאֻלָּתֽ⁠וֹ׃","wĕ⁠ʼim-mĕʻa֞t nişĕ̌ʼa֧r bȧ⁠şá̇̌ni֛ym ʻad-şĕ̌na֥ţ ha⁠yò̇bé֖l wĕ⁠ẖişȧ̌b-l֑⁠wò kĕ̇⁠pi֣y şá̌ná֔y⁠w yáşǐ֖yb ʼeţ-gĕ̇ʼulá̇ţֽ⁠wò׃"],[25,53,"כִּ⁠שְׂכִ֥יר שָׁנָ֛ה בְּ⁠שָׁנָ֖ה יִהְיֶ֣ה עִמּ֑⁠וֹ לֹֽא־יִרְדֶּ֥⁠נּֽוּ בְּ⁠פֶ֖רֶךְ לְ⁠עֵינֶֽי⁠ךָ׃","ki̇⁠şĕ̂ki֥yr şá̌ná֛h bĕ̇⁠şá̌ná֖h yihĕye֣h ʻiṁ֑⁠wò lòֽʼ-yirĕdė֥⁠ṅֽẇ bĕ̇⁠pe֖rekĕ lĕ⁠ʻéyneֽy⁠ká׃"],[25,54,"וְ⁠אִם־לֹ֥א יִגָּאֵ֖ל בְּ⁠אֵ֑לֶּה וְ⁠יָצָא֙ בִּ⁠שְׁנַ֣ת הַ⁠יֹּבֵ֔ל ה֖וּא וּ⁠בָנָ֥י⁠ו עִמּֽ⁠וֹ׃","wĕ⁠ʼim-lò֥ʼ yigá̇ʼé֖l bĕ̇⁠ʼé֑lėh wĕ⁠yáẕáʼ֙ bi̇⁠şĕ̌na֣ţ ha⁠yò̇bé֔l h֖ẇʼ ẇ⁠báná֥y⁠w ʻiṁֽ⁠wò׃"],[25,55,"כִּֽי־לִ֤⁠י בְנֵֽי־יִשְׂרָאֵל֙ עֲבָדִ֔ים עֲבָדַ֣⁠י הֵ֔ם אֲשֶׁר־הוֹצֵ֥אתִי אוֹתָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","kiֽ̇y-li֤⁠y bĕnéֽy-yişĕ̂ráʼél֙ ʻàbádi֔ym ʻàbáda֣⁠y hé֔m ʼàşěr-hwòẕé֥ʼţiy ʼwòţá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[26,1,"לֹֽא־תַעֲשׂ֨וּ לָ⁠כֶ֜ם אֱלִילִ֗ם וּ⁠פֶ֤סֶל וּ⁠מַצֵּבָה֙ לֹֽא־תָקִ֣ימוּ לָ⁠כֶ֔ם וְ⁠אֶ֣בֶן מַשְׂכִּ֗ית לֹ֤א תִתְּנוּ֙ בְּ⁠אַרְצְ⁠כֶ֔ם לְ⁠הִֽשְׁתַּחֲוֺ֖ת עָלֶ֑י⁠הָ כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","lòֽʼ-ţaʻàş̂֨ẇ lá⁠ke֜m ʼèliyli֗m ẇ⁠pe֤sel ẇ⁠maẕé̇báh֙ lòֽʼ-ţáqi֣ymẇ lá⁠ke֔m wĕ⁠ʼe֣ben maşĕ̂ki̇֗yţ lò֤ʼ ţiţĕ̇nẇ֙ bĕ̇⁠ʼarĕẕĕ⁠ke֔m lĕ⁠hiֽşĕ̌ţȧẖàwֺ֖ţ ʻále֑y⁠há ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[26,2,"אֶת־שַׁבְּתֹתַ֣⁠י תִּשְׁמֹ֔רוּ וּ⁠מִקְדָּשִׁ֖⁠י תִּירָ֑אוּ אֲנִ֖י יְהוָֽה׃ס","ʼeţ-şǎbĕ̇ţòţa֣⁠y ţi̇şĕ̌mò֔rẇ ẇ⁠miqĕdá̇şǐ֖⁠y ţi̇yrá֑ʼẇ ʼàni֖y yĕhwáֽh׃s"],[26,3,"אִם־בְּ⁠חֻקֹּתַ֖⁠י תֵּלֵ֑כוּ וְ⁠אֶת־מִצְוֺתַ֣⁠י תִּשְׁמְר֔וּ וַ⁠עֲשִׂיתֶ֖ם אֹתָֽ⁠ם׃","ʼim-bĕ̇⁠ẖuqò̇ţa֖⁠y ţé̇lé֑kẇ wĕ⁠ʼeţ-miẕĕwֺţa֣⁠y ţi̇şĕ̌mĕr֔ẇ wa⁠ʻàşîyţe֖m ʼòţáֽ⁠m׃"],[26,4,"וְ⁠נָתַתִּ֥י גִשְׁמֵי⁠כֶ֖ם בְּ⁠עִתָּ֑⁠ם וְ⁠נָתְנָ֤ה הָ⁠אָ֨רֶץ֙ יְבוּלָ֔⁠הּ וְ⁠עֵ֥ץ הַ⁠שָּׂדֶ֖ה יִתֵּ֥ן פִּרְיֽ⁠וֹ׃","wĕ⁠náţaţi֥̇y gişĕ̌méy⁠ke֖m bĕ̇⁠ʻiţá֑̇⁠m wĕ⁠náţĕná֤h há⁠ʼá֨reẕ֙ yĕbẇlá֔⁠ḣ wĕ⁠ʻé֥ẕ ha⁠şá̇̂de֖h yiţé֥̇n pi̇rĕyֽ⁠wò׃"],[26,5,"וְ⁠הִשִּׂ֨יג לָ⁠כֶ֥ם דַּ֨יִשׁ֙ אֶת־בָּצִ֔יר וּ⁠בָצִ֖יר יַשִּׂ֣יג אֶת־זָ֑רַע וַ⁠אֲכַלְתֶּ֤ם לַחְמְ⁠כֶם֙ לָ⁠שֹׂ֔בַע וִֽ⁠ישַׁבְתֶּ֥ם לָ⁠בֶ֖טַח בְּ⁠אַרְצְ⁠כֶֽם׃","wĕ⁠hişi̇̂֨yg lá⁠ke֥m dȧ֨yiş̌֙ ʼeţ-bá̇ẕi֔yr ẇ⁠báẕi֖yr yaşi֣̇̂yg ʼeţ-zá֑raʻ wa⁠ʼàkalĕţė֤m laẖĕmĕ⁠kem֙ lá⁠şò̂֔baʻ wiֽ⁠yşǎbĕţė֥m lá⁠be֖taẖ bĕ̇⁠ʼarĕẕĕ⁠keֽm׃"],[26,6,"וְ⁠נָתַתִּ֤י שָׁלוֹם֙ בָּ⁠אָ֔רֶץ וּ⁠שְׁכַבְתֶּ֖ם וְ⁠אֵ֣ין מַחֲרִ֑יד וְ⁠הִשְׁבַּתִּ֞י חַיָּ֤ה רָעָה֙ מִן־הָ⁠אָ֔רֶץ וְ⁠חֶ֖רֶב לֹא־תַעֲבֹ֥ר בְּ⁠אַרְצְ⁠כֶֽם׃","wĕ⁠náţaţi֤̇y şá̌lwòm֙ bá̇⁠ʼá֔reẕ ẇ⁠şĕ̌kabĕţė֖m wĕ⁠ʼé֣yn maẖàri֑yd wĕ⁠hişĕ̌bȧţi̇֞y ẖayá֤̇h ráʻáh֙ min-há⁠ʼá֔reẕ wĕ⁠ẖe֖reb lòʼ-ţaʻàbò֥r bĕ̇⁠ʼarĕẕĕ⁠keֽm׃"],[26,7,"וּ⁠רְדַפְתֶּ֖ם אֶת־אֹיְבֵי⁠כֶ֑ם וְ⁠נָפְל֥וּ לִ⁠פְנֵי⁠כֶ֖ם לֶ⁠חָֽרֶב","ẇ⁠rĕdapĕţė֖m ʼeţ-ʼòyĕbéy⁠ke֑m wĕ⁠nápĕl֥ẇ li⁠pĕnéy⁠ke֖m le⁠ẖáֽreb"],[26,8,"וְ⁠רָדְפ֨וּ מִ⁠כֶּ֤ם חֲמִשָּׁה֙ מֵאָ֔ה וּ⁠מֵאָ֥ה מִ⁠כֶּ֖ם רְבָבָ֣ה יִרְדֹּ֑פוּ וְ⁠נָפְל֧וּ אֹיְבֵי⁠כֶ֛ם לִ⁠פְנֵי⁠כֶ֖ם לֶ⁠חָֽרֶב׃","wĕ⁠rádĕp֨ẇ mi⁠kė֤m ẖàmişá̇̌h֙ méʼá֔h ẇ⁠méʼá֥h mi⁠kė֖m rĕbábá֣h yirĕdò֑̇pẇ wĕ⁠nápĕl֧ẇ ʼòyĕbéy⁠ke֛m li⁠pĕnéy⁠ke֖m le⁠ẖáֽreb׃"],[26,9,"וּ⁠פָנִ֣יתִי אֲלֵי⁠כֶ֔ם וְ⁠הִפְרֵיתִ֣י אֶתְ⁠כֶ֔ם וְ⁠הִרְבֵּיתִ֖י אֶתְ⁠כֶ֑ם וַ⁠הֲקִימֹתִ֥י אֶת־בְּרִיתִ֖⁠י אִתְּ⁠כֶֽם׃","ẇ⁠páni֣yţiy ʼàléy⁠ke֔m wĕ⁠hipĕréyţi֣y ʼeţĕ⁠ke֔m wĕ⁠hirĕbé̇yţi֖y ʼeţĕ⁠ke֑m wa⁠hàqiymòţi֥y ʼeţ-bĕ̇riyţi֖⁠y ʼiţĕ̇⁠keֽm׃"],[26,10,"וַ⁠אֲכַלְתֶּ֥ם יָשָׁ֖ן נוֹשָׁ֑ן וְ⁠יָשָׁ֕ן מִ⁠פְּנֵ֥י חָדָ֖שׁ תּוֹצִֽיאוּ׃","wa⁠ʼàkalĕţė֥m yáşá֖̌n nwòşá֑̌n wĕ⁠yáşá̌֕n mi⁠pĕ̇né֥y ẖádá֖ş̌ ţ̇wòẕiֽyʼẇ׃"],[26,11,"וְ⁠נָתַתִּ֥י מִשְׁכָּנִ֖⁠י בְּ⁠תוֹכְ⁠כֶ֑ם וְ⁠לֹֽא־תִגְעַ֥ל נַפְשִׁ֖⁠י אֶתְ⁠כֶֽם׃","wĕ⁠náţaţi֥̇y mişĕ̌ká̇ni֖⁠y bĕ̇⁠ţwòkĕ⁠ke֑m wĕ⁠lòֽʼ-ţigĕʻa֥l napĕşǐ֖⁠y ʼeţĕ⁠keֽm׃"],[26,12,"וְ⁠הִתְהַלַּכְתִּי֙ בְּ⁠ת֣וֹכְ⁠כֶ֔ם וְ⁠הָיִ֥יתִי לָ⁠כֶ֖ם לֵֽ⁠אלֹהִ֑ים וְ⁠אַתֶּ֖ם תִּהְיוּ־לִ֥⁠י לְ⁠עָֽם׃","wĕ⁠hiţĕhalȧkĕţi̇y֙ bĕ̇⁠ţ֣wòkĕ⁠ke֔m wĕ⁠háyi֥yţiy lá⁠ke֖m léֽ⁠ʼlòhi֑ym wĕ⁠ʼaţė֖m ţi̇hĕyẇ-li֥⁠y lĕ⁠ʻáֽm׃"],[26,13,"אֲנִ֞י יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֗ם אֲשֶׁ֨ר הוֹצֵ֤אתִי אֶתְ⁠כֶם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם מִֽ⁠הְיֹ֥ת לָ⁠הֶ֖ם עֲבָדִ֑ים וָ⁠אֶשְׁבֹּר֙ מֹטֹ֣ת עֻלְּ⁠כֶ֔ם וָ⁠אוֹלֵ֥ךְ אֶתְ⁠כֶ֖ם קֽוֹמְמִיּֽוּת׃פ","ʼàni֞y yĕhwá֣h ʼèlòֽhéy⁠ke֗m ʼàşě֨r hwòẕé֤ʼţiy ʼeţĕ⁠kem֙ mé⁠ʼe֣reẕ miẕĕra֔yim miֽ⁠hĕyò֥ţ lá⁠he֖m ʻàbádi֑ym wá⁠ʼeşĕ̌bò̇r֙ mòtò֣ţ ʻulĕ̇⁠ke֔m wá⁠ʼwòlé֥kĕ ʼeţĕ⁠ke֖m qֽwòmĕmiẏֽẇţ׃p"],[26,14,"וְ⁠אִם־לֹ֥א תִשְׁמְע֖וּ לִ֑⁠י וְ⁠לֹ֣א תַעֲשׂ֔וּ אֵ֥ת כָּל־הַ⁠מִּצְוֺ֖ת הָ⁠אֵֽלֶּה׃","wĕ⁠ʼim-lò֥ʼ ţişĕ̌mĕʻ֖ẇ li֑⁠y wĕ⁠lò֣ʼ ţaʻàş̂֔ẇ ʼé֥ţ ká̇l-ha⁠mi̇ẕĕwֺ֖ţ há⁠ʼéֽlėh׃"],[26,15,"וְ⁠אִם־בְּ⁠חֻקֹּתַ֣⁠י תִּמְאָ֔סוּ וְ⁠אִ֥ם אֶת־מִשְׁפָּטַ֖⁠י תִּגְעַ֣ל נַפְשְׁ⁠כֶ֑ם לְ⁠בִלְתִּ֤י עֲשׂוֹת֙ אֶת־כָּל־מִצְוֺתַ֔⁠י לְ⁠הַפְרְ⁠כֶ֖ם אֶת־בְּרִיתִֽ⁠י׃","wĕ⁠ʼim-bĕ̇⁠ẖuqò̇ţa֣⁠y ţi̇mĕʼá֔sẇ wĕ⁠ʼi֥m ʼeţ-mişĕ̌pá̇ta֖⁠y ţi̇gĕʻa֣l napĕşĕ̌⁠ke֑m lĕ⁠bilĕţi֤̇y ʻàş̂wòţ֙ ʼeţ-ká̇l-miẕĕwֺţa֔⁠y lĕ⁠hapĕrĕ⁠ke֖m ʼeţ-bĕ̇riyţiֽ⁠y׃"],[26,16,"אַף־אֲנִ֞י אֶֽעֱשֶׂה־זֹּ֣את לָ⁠כֶ֗ם וְ⁠הִפְקַדְתִּ֨י עֲלֵי⁠כֶ֤ם בֶּֽהָלָה֙ אֶת־הַ⁠שַּׁחֶ֣פֶת וְ⁠אֶת־הַ⁠קַּדַּ֔חַת מְכַלּ֥וֹת עֵינַ֖יִם וּ⁠מְדִיבֹ֣ת נָ֑פֶשׁ וּ⁠זְרַעְתֶּ֤ם לָ⁠רִיק֙ זַרְעֲ⁠כֶ֔ם וַ⁠אֲכָלֻ֖⁠הוּ אֹיְבֵי⁠כֶֽם׃","ʼap-ʼàni֞y ʼֽeʻèşêh-zò֣̇ʼţ lá⁠ke֗m wĕ⁠hipĕqadĕţi̇֨y ʻàléy⁠ke֤m bėֽháláh֙ ʼeţ-ha⁠şȧ̌ẖe֣peţ wĕ⁠ʼeţ-ha⁠qȧdȧ֔ẖaţ mĕkal֥̇wòţ ʻéyna֖yim ẇ⁠mĕdiybò֣ţ ná֑peş̌ ẇ⁠zĕraʻĕţė֤m lá⁠riyq֙ zarĕʻà⁠ke֔m wa⁠ʼàkálu֖⁠hẇ ʼòyĕbéy⁠keֽm׃"],[26,17,"וְ⁠נָתַתִּ֤י פָנַ⁠י֙ בָּ⁠כֶ֔ם וְ⁠נִגַּפְתֶּ֖ם לִ⁠פְנֵ֣י אֹיְבֵי⁠כֶ֑ם וְ⁠רָד֤וּ בָ⁠כֶם֙ שֹֽׂנְאֵי⁠כֶ֔ם וְ⁠נַסְתֶּ֖ם וְ⁠אֵין־רֹדֵ֥ף אֶתְ⁠כֶֽם׃ס","wĕ⁠náţaţi֤̇y pána⁠y֙ bá̇⁠ke֔m wĕ⁠nigȧpĕţė֖m li⁠pĕné֣y ʼòyĕbéy⁠ke֑m wĕ⁠rád֤ẇ bá⁠kem֙ şòֽ̂nĕʼéy⁠ke֔m wĕ⁠nasĕţė֖m wĕ⁠ʼéyn-ròdé֥p ʼeţĕ⁠keֽm׃s"],[26,18,"וְ⁠אִ֨ם־עַד־אֵ֔לֶּה לֹ֥א תִשְׁמְע֖וּ לִ֑⁠י וְ⁠יָסַפְתִּי֙ לְ⁠יַסְּרָ֣ה אֶתְ⁠כֶ֔ם שֶׁ֖בַע עַל־חַטֹּאתֵי⁠כֶֽם׃","wĕ⁠ʼi֨m-ʻad-ʼé֔lėh lò֥ʼ ţişĕ̌mĕʻ֖ẇ li֑⁠y wĕ⁠yásapĕţi̇y֙ lĕ⁠yasĕ̇rá֣h ʼeţĕ⁠ke֔m şě֖baʻ ʻal-ẖatò̇ʼţéy⁠keֽm׃"],[26,19,"וְ⁠שָׁבַרְתִּ֖י אֶת־גְּא֣וֹן עֻזְּ⁠כֶ֑ם וְ⁠נָתַתִּ֤י אֶת־שְׁמֵי⁠כֶם֙ כַּ⁠בַּרְזֶ֔ל וְ⁠אֶֽת־אַרְצְ⁠כֶ֖ם כַּ⁠נְּחֻשָֽׁה׃","wĕ⁠şá̌barĕţi֖̇y ʼeţ-gĕ̇ʼ֣wòn ʻuzĕ̇⁠ke֑m wĕ⁠náţaţi֤̇y ʼeţ-şĕ̌méy⁠kem֙ kȧ⁠bȧrĕze֔l wĕ⁠ʼeֽţ-ʼarĕẕĕ⁠ke֖m kȧ⁠nĕ̇ẖuşáֽ̌h׃"],[26,20,"וְ⁠תַ֥ם לָ⁠רִ֖יק כֹּחֲ⁠כֶ֑ם וְ⁠לֹֽא־תִתֵּ֤ן אַרְצְ⁠כֶם֙ אֶת־יְבוּלָ֔⁠הּ וְ⁠עֵ֣ץ הָ⁠אָ֔רֶץ לֹ֥א יִתֵּ֖ן פִּרְיֽ⁠וֹ׃","wĕ⁠ţa֥m lá⁠ri֖yq kò̇ẖà⁠ke֑m wĕ⁠lòֽʼ-ţiţé֤̇n ʼarĕẕĕ⁠kem֙ ʼeţ-yĕbẇlá֔⁠ḣ wĕ⁠ʻé֣ẕ há⁠ʼá֔reẕ lò֥ʼ yiţé֖̇n pi̇rĕyֽ⁠wò׃"],[26,21,"וְ⁠אִם־תֵּֽלְכ֤וּ עִמִּ⁠י֙ קֶ֔רִי וְ⁠לֹ֥א תֹאב֖וּ לִ⁠שְׁמֹ֣עַֽ לִ֑⁠י וְ⁠יָסַפְתִּ֤י עֲלֵי⁠כֶם֙ מַכָּ֔ה שֶׁ֖בַע כְּ⁠חַטֹּאתֵי⁠כֶֽם׃","wĕ⁠ʼim-ţéֽ̇lĕk֤ẇ ʻimi̇⁠y֙ qe֔riy wĕ⁠lò֥ʼ ţòʼb֖ẇ li⁠şĕ̌mò֣ʻaֽ li֑⁠y wĕ⁠yásapĕţi֤̇y ʻàléy⁠kem֙ maká̇֔h şě֖baʻ kĕ̇⁠ẖatò̇ʼţéy⁠keֽm׃"],[26,22,"וְ⁠הִשְׁלַחְתִּ֨י בָ⁠כֶ֜ם אֶת־חַיַּ֤ת הַ⁠שָּׂדֶה֙ וְ⁠שִׁכְּלָ֣ה אֶתְ⁠כֶ֔ם וְ⁠הִכְרִ֨יתָה֙ אֶת־בְּהֶמְתְּ⁠כֶ֔ם וְ⁠הִמְעִ֖יטָה אֶתְ⁠כֶ֑ם וְ⁠נָשַׁ֖מּוּ דַּרְכֵי⁠כֶֽם׃","wĕ⁠hişĕ̌laẖĕţi̇֨y bá⁠ke֜m ʼeţ-ẖayȧ֤ţ ha⁠şá̇̂deh֙ wĕ⁠şǐkĕ̇lá֣h ʼeţĕ⁠ke֔m wĕ⁠hikĕri֨yţáh֙ ʼeţ-bĕ̇hemĕţĕ̇⁠ke֔m wĕ⁠himĕʻi֖ytáh ʼeţĕ⁠ke֑m wĕ⁠náşǎ֖ṁẇ dȧrĕkéy⁠keֽm׃"],[26,23,"וְ⁠אִ֨ם־בְּ⁠אֵ֔לֶּה לֹ֥א תִוָּסְר֖וּ לִ֑⁠י וַ⁠הֲלַכְתֶּ֥ם עִמִּ֖⁠י קֶֽרִי׃","wĕ⁠ʼi֨m-bĕ̇⁠ʼé֔lėh lò֥ʼ ţiwá̇sĕr֖ẇ li֑⁠y wa⁠hàlakĕţė֥m ʻimi֖̇⁠y qeֽriy׃"],[26,24,"וְ⁠הָלַכְתִּ֧י אַף־אֲנִ֛י עִמָּ⁠כֶ֖ם בְּ⁠קֶ֑רִי וְ⁠הִכֵּיתִ֤י אֶתְ⁠כֶם֙ גַּם־אָ֔נִי שֶׁ֖בַע עַל־חַטֹּאתֵי⁠כֶֽם׃","wĕ⁠hálakĕţi֧̇y ʼap-ʼàni֛y ʻimá̇⁠ke֖m bĕ̇⁠qe֑riy wĕ⁠hiké̇yţi֤y ʼeţĕ⁠kem֙ gȧm-ʼá֔niy şě֖baʻ ʻal-ẖatò̇ʼţéy⁠keֽm׃"],[26,25,"וְ⁠הֵבֵאתִ֨י עֲלֵי⁠כֶ֜ם חֶ֗רֶב נֹקֶ֨מֶת֙ נְקַם־בְּרִ֔ית וְ⁠נֶאֱסַפְתֶּ֖ם אֶל־עָרֵי⁠כֶ֑ם וְ⁠שִׁלַּ֤חְתִּי דֶ֨בֶר֙ בְּ⁠ת֣וֹכְ⁠כֶ֔ם וְ⁠נִתַּתֶּ֖ם בְּ⁠יַד־אוֹיֵֽב׃","wĕ⁠hébéʼţi֨y ʻàléy⁠ke֜m ẖe֗reb nòqe֨meţ֙ nĕqam-bĕ̇ri֔yţ wĕ⁠neʼèsapĕţė֖m ʼel-ʻáréy⁠ke֑m wĕ⁠şǐlȧ֤ẖĕţi̇y de֨ber֙ bĕ̇⁠ţ֣wòkĕ⁠ke֔m wĕ⁠niţȧţė֖m bĕ̇⁠yad-ʼwòyéֽb׃"],[26,26,"בְּ⁠שִׁבְרִ֣⁠י לָ⁠כֶם֮ מַטֵּה־לֶחֶם֒ וְ֠⁠אָפוּ עֶ֣שֶׂר נָשִׁ֤ים לַחְמְ⁠כֶם֙ בְּ⁠תַנּ֣וּר אֶחָ֔ד וְ⁠הֵשִׁ֥יבוּ לַחְמְ⁠כֶ֖ם בַּ⁠מִּשְׁקָ֑ל וַ⁠אֲכַלְתֶּ֖ם וְ⁠לֹ֥א תִשְׂבָּֽעוּ׃ס","bĕ̇⁠şǐbĕri֣⁠y lá⁠kem֮ maté̇h-leẖem֒ wĕ֠⁠ʼápẇ ʻe֣şêr náşǐ֤ym laẖĕmĕ⁠kem֙ bĕ̇⁠ţaṅ֣ẇr ʼeẖá֔d wĕ⁠héşǐ֥ybẇ laẖĕmĕ⁠ke֖m bȧ⁠mi̇şĕ̌qá֑l wa⁠ʼàkalĕţė֖m wĕ⁠lò֥ʼ ţişĕ̂báֽ̇ʻẇ׃s"],[26,27,"וְ⁠אִ֨ם־בְּ⁠זֹ֔את לֹ֥א תִשְׁמְע֖וּ לִ֑⁠י וַ⁠הֲלַכְתֶּ֥ם עִמִּ֖⁠י בְּ⁠קֶֽרִי׃","wĕ⁠ʼi֨m-bĕ̇⁠zò֔ʼţ lò֥ʼ ţişĕ̌mĕʻ֖ẇ li֑⁠y wa⁠hàlakĕţė֥m ʻimi֖̇⁠y bĕ̇⁠qeֽriy׃"],[26,28,"וְ⁠הָלַכְתִּ֥י עִמָּ⁠כֶ֖ם בַּ⁠חֲמַת־קֶ֑רִי וְ⁠יִסַּרְתִּ֤י אֶתְ⁠כֶם֙ אַף־אָ֔נִי שֶׁ֖בַע עַל־חַטֹּאתֵי⁠כֶם׃","wĕ⁠hálakĕţi֥̇y ʻimá̇⁠ke֖m bȧ⁠ẖàmaţ-qe֑riy wĕ⁠yisȧrĕţi֤̇y ʼeţĕ⁠kem֙ ʼap-ʼá֔niy şě֖baʻ ʻal-ẖatò̇ʼţéy⁠kem׃"],[26,29,"וַ⁠אֲכַלְתֶּ֖ם בְּשַׂ֣ר בְּנֵי⁠כֶ֑ם וּ⁠בְשַׂ֥ר בְּנֹתֵי⁠כֶ֖ם תֹּאכֵֽלוּ׃","wa⁠ʼàkalĕţė֖m bĕ̇şâ֣r bĕ̇néy⁠ke֑m ẇ⁠bĕşâ֥r bĕ̇nòţéy⁠ke֖m ţò̇ʼkéֽlẇ׃"],[26,30,"וְ⁠הִשְׁמַדְתִּ֞י אֶת־בָּמֹֽתֵי⁠כֶ֗ם וְ⁠הִכְרַתִּי֙ אֶת־חַמָּ֣נֵי⁠כֶ֔ם וְ⁠נָֽתַתִּי֙ אֶת־פִּגְרֵי⁠כֶ֔ם עַל־פִּגְרֵ֖י גִּלּוּלֵי⁠כֶ֑ם וְ⁠גָעֲלָ֥ה נַפְשִׁ֖⁠י אֶתְ⁠כֶֽם׃","wĕ⁠hişĕ̌madĕţi̇֞y ʼeţ-bá̇mòֽţéy⁠ke֗m wĕ⁠hikĕraţi̇y֙ ʼeţ-ẖamá֣̇néy⁠ke֔m wĕ⁠náֽţaţi̇y֙ ʼeţ-pi̇gĕréy⁠ke֔m ʻal-pi̇gĕré֖y gi̇l̇ẇléy⁠ke֑m wĕ⁠gáʻàlá֥h napĕşǐ֖⁠y ʼeţĕ⁠keֽm׃"],[26,31,"וְ⁠נָתַתִּ֤י אֶת־עָֽרֵי⁠כֶם֙ חָרְבָּ֔ה וַ⁠הֲשִׁמּוֹתִ֖י אֶת־מִקְדְּשֵׁי⁠כֶ֑ם וְ⁠לֹ֣א אָרִ֔יחַ בְּ⁠רֵ֖יחַ נִיחֹֽחֲ⁠כֶֽם׃","wĕ⁠náţaţi֤̇y ʼeţ-ʻáֽréy⁠kem֙ ẖárĕbá̇֔h wa⁠hàşǐṁwòţi֖y ʼeţ-miqĕdĕ̇şé̌y⁠ke֑m wĕ⁠lò֣ʼ ʼári֔yẖa bĕ̇⁠ré֖yẖa niyẖòֽẖà⁠keֽm׃"],[26,32,"וַ⁠הֲשִׁמֹּתִ֥י אֲנִ֖י אֶת־הָ⁠אָ֑רֶץ וְ⁠שָֽׁמְמ֤וּ עָלֶ֨י⁠הָ֙ אֹֽיְבֵי⁠כֶ֔ם הַ⁠יֹּשְׁבִ֖ים בָּֽ⁠הּ׃","wa⁠hàşǐmò̇ţi֥y ʼàni֖y ʼeţ-há⁠ʼá֑reẕ wĕ⁠şáֽ̌mĕm֤ẇ ʻále֨y⁠há֙ ʼòֽyĕbéy⁠ke֔m ha⁠yò̇şĕ̌bi֖ym báֽ̇⁠ḣ׃"],[26,33,"וְ⁠אֶתְ⁠כֶם֙ אֱזָרֶ֣ה בַ⁠גּוֹיִ֔ם וַ⁠הֲרִיקֹתִ֥י אַחֲרֵי⁠כֶ֖ם חָ֑רֶב וְ⁠הָיְתָ֤ה אַרְצְ⁠כֶם֙ שְׁמָמָ֔ה וְ⁠עָרֵי⁠כֶ֖ם יִהְי֥וּ חָרְבָּֽה׃","wĕ⁠ʼeţĕ⁠kem֙ ʼèzáre֣h ba⁠ġwòyi֔m wa⁠hàriyqòţi֥y ʼaẖàréy⁠ke֖m ẖá֑reb wĕ⁠háyĕţá֤h ʼarĕẕĕ⁠kem֙ şĕ̌mámá֔h wĕ⁠ʻáréy⁠ke֖m yihĕy֥ẇ ẖárĕbáֽ̇h׃"],[26,34,"אָז֩ תִּרְצֶ֨ה הָ⁠אָ֜רֶץ אֶת־שַׁבְּתֹתֶ֗י⁠הָ כֹּ֚ל יְמֵ֣י הֳשַׁמָּ֔⁠ה וְ⁠אַתֶּ֖ם בְּ⁠אֶ֣רֶץ אֹיְבֵי⁠כֶ֑ם אָ֚ז תִּשְׁבַּ֣ת הָ⁠אָ֔רֶץ וְ⁠הִרְצָ֖ת אֶת־שַׁבְּתֹתֶֽי⁠הָ׃","ʼáz֩ ţi̇rĕẕe֨h há⁠ʼá֜reẕ ʼeţ-şǎbĕ̇ţòţe֗y⁠há kò֚̇l yĕmé֣y hoşǎmá̇֔⁠h wĕ⁠ʼaţė֖m bĕ̇⁠ʼe֣reẕ ʼòyĕbéy⁠ke֑m ʼá֚z ţi̇şĕ̌bȧ֣ţ há⁠ʼá֔reẕ wĕ⁠hirĕẕá֖ţ ʼeţ-şǎbĕ̇ţòţeֽy⁠há׃"],[26,35,"כָּל־יְמֵ֥י הָשַּׁמָּ֖⁠ה תִּשְׁבֹּ֑ת אֵ֣ת אֲשֶׁ֧ר לֹֽא־שָׁבְתָ֛ה בְּ⁠שַׁבְּתֹתֵי⁠כֶ֖ם בְּ⁠שִׁבְתְּ⁠כֶ֥ם עָלֶֽי⁠הָ׃","ká̇l-yĕmé֥y háşȧ̌má֖̇⁠h ţi̇şĕ̌bò֑̇ţ ʼé֣ţ ʼàşě֧r lòֽʼ-şá̌bĕţá֛h bĕ̇⁠şǎbĕ̇ţòţéy⁠ke֖m bĕ̇⁠şǐbĕţĕ̇⁠ke֥m ʻáleֽy⁠há׃"],[26,36,"וְ⁠הַ⁠נִּשְׁאָרִ֣ים בָּ⁠כֶ֔ם וְ⁠הֵבֵ֤אתִי מֹ֨רֶךְ֙ בִּ⁠לְבָבָ֔⁠ם בְּ⁠אַרְצֹ֖ת אֹיְבֵי⁠הֶ֑ם וְ⁠רָדַ֣ף אֹתָ֗⁠ם ק֚וֹל עָלֶ֣ה נִדָּ֔ף וְ⁠נָס֧וּ מְנֻֽסַת־חֶ֛רֶב וְ⁠נָפְל֖וּ וְ⁠אֵ֥ין רֹדֵֽף׃","wĕ⁠ha⁠ni̇şĕ̌ʼári֣ym bá̇⁠ke֔m wĕ⁠hébé֤ʼţiy mò֨rekĕ֙ bi̇⁠lĕbábá֔⁠m bĕ̇⁠ʼarĕẕò֖ţ ʼòyĕbéy⁠he֑m wĕ⁠ráda֣p ʼòţá֗⁠m q֚wòl ʻále֣h nidá̇֔p wĕ⁠nás֧ẇ mĕnuֽsaţ-ẖe֛reb wĕ⁠nápĕl֖ẇ wĕ⁠ʼé֥yn ròdéֽp׃"],[26,37,"וְ⁠כָשְׁל֧וּ אִישׁ־בְּ⁠אָחִ֛י⁠ו כְּ⁠מִ⁠פְּנֵי־חֶ֖רֶב וְ⁠רֹדֵ֣ף אָ֑יִן וְ⁠לֹא־תִֽהְיֶ֤ה לָ⁠כֶם֙ תְּקוּמָ֔ה לִ⁠פְנֵ֖י אֹֽיְבֵי⁠כֶֽם׃","wĕ⁠káşĕ̌l֧ẇ ʼiyş̌-bĕ̇⁠ʼáẖi֛y⁠w kĕ̇⁠mi⁠pĕ̇néy-ẖe֖reb wĕ⁠ròdé֣p ʼá֑yin wĕ⁠lòʼ-ţiֽhĕye֤h lá⁠kem֙ ţĕ̇qẇmá֔h li⁠pĕné֖y ʼòֽyĕbéy⁠keֽm׃"],[26,38,"וַ⁠אֲבַדְתֶּ֖ם בַּ⁠גּוֹיִ֑ם וְ⁠אָכְלָ֣ה אֶתְ⁠כֶ֔ם אֶ֖רֶץ אֹיְבֵי⁠כֶֽם׃","wa⁠ʼàbadĕţė֖m bȧ⁠ġwòyi֑m wĕ⁠ʼákĕlá֣h ʼeţĕ⁠ke֔m ʼe֖reẕ ʼòyĕbéy⁠keֽm׃"],[26,39,"וְ⁠הַ⁠נִּשְׁאָרִ֣ים בָּ⁠כֶ֗ם יִמַּ֨קּוּ֙ בַּֽ⁠עֲוֺנָ֔⁠ם בְּ⁠אַרְצֹ֖ת אֹיְבֵי⁠כֶ֑ם וְ⁠אַ֛ף בַּ⁠עֲוֺנֹ֥ת אֲבֹתָ֖⁠ם אִתָּ֥⁠ם יִמָּֽקּוּ׃","wĕ⁠ha⁠ni̇şĕ̌ʼári֣ym bá̇⁠ke֗m yimȧ֨q̇ẇ֙ ḃֽa⁠ʻàwֺná֔⁠m bĕ̇⁠ʼarĕẕò֖ţ ʼòyĕbéy⁠ke֑m wĕ⁠ʼa֛p bȧ⁠ʻàwֺnò֥ţ ʼàbòţá֖⁠m ʼiţá֥̇⁠m yimáֽ̇q̇ẇ׃"],[26,40,"וְ⁠הִתְוַדּ֤וּ אֶת־עֲוֺנָ⁠ם֙ וְ⁠אֶת־עֲוֺ֣ן אֲבֹתָ֔⁠ם בְּ⁠מַעֲלָ֖⁠ם אֲשֶׁ֣ר מָֽעֲלוּ־בִ֑⁠י וְ⁠אַ֕ף אֲשֶׁר־הָֽלְכ֥וּ עִמִּ֖⁠י בְּ⁠קֶֽרִי׃","wĕ⁠hiţĕwaḋ֤ẇ ʼeţ-ʻàwֺná⁠m֙ wĕ⁠ʼeţ-ʻàwֺ֣n ʼàbòţá֔⁠m bĕ̇⁠maʻàlá֖⁠m ʼàşě֣r máֽʻàlẇ-bi֑⁠y wĕ⁠ʼa֕p ʼàşěr-hֽálĕk֥ẇ ʻimi֖̇⁠y bĕ̇⁠qeֽriy׃"],[26,41,"אַף־אֲנִ֗י אֵלֵ֤ךְ עִמָּ⁠ם֙ בְּ⁠קֶ֔רִי וְ⁠הֵבֵאתִ֣י אֹתָ֔⁠ם בְּ⁠אֶ֖רֶץ אֹיְבֵי⁠הֶ֑ם אוֹ־אָ֣ז יִכָּנַ֗ע לְבָבָ⁠ם֙ הֶֽ⁠עָרֵ֔ל וְ⁠אָ֖ז יִרְצ֥וּ אֶת־עֲוֺנָֽ⁠ם׃","ʼap-ʼàni֗y ʼélé֤kĕ ʻimá̇⁠m֙ bĕ̇⁠qe֔riy wĕ⁠hébéʼţi֣y ʼòţá֔⁠m bĕ̇⁠ʼe֖reẕ ʼòyĕbéy⁠he֑m ʼwò-ʼá֣z yiká̇na֗ʻ lĕbábá⁠m֙ heֽ⁠ʻáré֔l wĕ⁠ʼá֖z yirĕẕ֥ẇ ʼeţ-ʻàwֺnáֽ⁠m׃"],[26,42,"וְ⁠זָכַרְתִּ֖י אֶת־בְּרִיתִ֣⁠י יַעֲק֑וֹב וְ⁠אַף֩ אֶת־בְּרִיתִ֨⁠י יִצְחָ֜ק וְ⁠אַ֨ף אֶת־בְּרִיתִ֧⁠י אַבְרָהָ֛ם אֶזְכֹּ֖ר וְ⁠הָ⁠אָ֥רֶץ אֶזְכֹּֽר׃","wĕ⁠zákarĕţi֖̇y ʼeţ-bĕ̇riyţi֣⁠y yaʻàq֑wòb wĕ⁠ʼap֩ ʼeţ-bĕ̇riyţi֨⁠y yiẕĕẖá֜q wĕ⁠ʼa֨p ʼeţ-bĕ̇riyţi֧⁠y ʼabĕráhá֛m ʼezĕkò֖̇r wĕ⁠há⁠ʼá֥reẕ ʼezĕkòֽ̇r׃"],[26,43,"וְ⁠הָ⁠אָרֶץ֩ תֵּעָזֵ֨ב מֵ⁠הֶ֜ם וְ⁠תִ֣רֶץ אֶת־שַׁבְּתֹתֶ֗י⁠הָ בָּ⁠הְשַׁמָּ⁠ה֙ מֵ⁠הֶ֔ם וְ⁠הֵ֖ם יִרְצ֣וּ אֶת־עֲוֺנָ֑⁠ם יַ֣עַן וּ⁠בְ⁠יַ֔עַן בְּ⁠מִשְׁפָּטַ֣⁠י מָאָ֔סוּ וְ⁠אֶת־חֻקֹּתַ֖⁠י גָּעֲלָ֥ה נַפְשָֽׁ⁠ם׃","wĕ⁠há⁠ʼáreẕ֩ ţé̇ʻázé֨b mé⁠he֜m wĕ⁠ţi֣reẕ ʼeţ-şǎbĕ̇ţòţe֗y⁠há bá̇⁠hĕşǎmá̇⁠h֙ mé⁠he֔m wĕ⁠hé֖m yirĕẕ֣ẇ ʼeţ-ʻàwֺná֑⁠m ya֣ʻan ẇ⁠bĕ⁠ya֔ʻan bĕ̇⁠mişĕ̌pá̇ta֣⁠y máʼá֔sẇ wĕ⁠ʼeţ-ẖuqò̇ţa֖⁠y gá̇ʻàlá֥h napĕşáֽ̌⁠m׃"],[26,44,"וְ⁠אַף־גַּם־זֹ֠את בִּֽ⁠הְיוֹתָ֞⁠ם בְּ⁠אֶ֣רֶץ אֹֽיְבֵי⁠הֶ֗ם לֹֽא־מְאַסְתִּ֤י⁠ם וְ⁠לֹֽא־גְעַלְתִּי⁠ם֙ לְ⁠כַלֹּתָ֔⁠ם לְ⁠הָפֵ֥ר בְּרִיתִ֖⁠י אִתָּ֑⁠ם כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠הֶֽם׃","wĕ⁠ʼap-gȧm-zò֠ʼţ biֽ̇⁠hĕywòţá֞⁠m bĕ̇⁠ʼe֣reẕ ʼòֽyĕbéy⁠he֗m lòֽʼ-mĕʼasĕţi֤̇y⁠m wĕ⁠lòֽʼ-gĕʻalĕţi̇y⁠m֙ lĕ⁠kalò̇ţá֔⁠m lĕ⁠hápé֥r bĕ̇riyţi֖⁠y ʼiţá֑̇⁠m ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠heֽm׃"],[26,45,"וְ⁠זָכַרְתִּ֥י לָ⁠הֶ֖ם בְּרִ֣ית רִאשֹׁנִ֑ים אֲשֶׁ֣ר הוֹצֵֽאתִי־אֹתָ⁠ם֩ מֵ⁠אֶ֨רֶץ מִצְרַ֜יִם לְ⁠עֵינֵ֣י הַ⁠גּוֹיִ֗ם לִ⁠הְיֹ֥ת לָ⁠הֶ֛ם לֵ⁠אלֹהִ֖ים אֲנִ֥י יְהוָֽה׃","wĕ⁠zákarĕţi֥̇y lá⁠he֖m bĕ̇ri֣yţ riʼşò̌ni֑ym ʼàşě֣r hwòẕéֽʼţiy-ʼòţá⁠m֩ mé⁠ʼe֨reẕ miẕĕra֜yim lĕ⁠ʻéyné֣y ha⁠ġwòyi֗m li⁠hĕyò֥ţ lá⁠he֛m lé⁠ʼlòhi֖ym ʼàni֥y yĕhwáֽh׃"],[26,46,"אֵ֠לֶּה הַֽ⁠חֻקִּ֣ים וְ⁠הַ⁠מִּשְׁפָּטִים֮ וְ⁠הַ⁠תּוֹרֹת֒ אֲשֶׁר֙ נָתַ֣ן יְהוָ֔ה בֵּינ֕⁠וֹ וּ⁠בֵ֖ין בְּנֵ֣י יִשְׂרָאֵ֑ל בְּ⁠הַ֥ר סִינַ֖י בְּ⁠יַד־מֹשֶֽׁה׃פ","ʼé֠lėh haֽ⁠ẖuqi֣̇ym wĕ⁠ha⁠mi̇şĕ̌pá̇tiym֮ wĕ⁠ha⁠ţ̇wòròţ֒ ʼàşěr֙ náţa֣n yĕhwá֔h bé̇yn֕⁠wò ẇ⁠bé֖yn bĕ̇né֣y yişĕ̂ráʼé֑l bĕ̇⁠ha֥r siyna֖y bĕ̇⁠yad-mòşěֽh׃p"],[27,1,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֶל־מֹשֶׁ֥ה לֵּ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼel-mòşě֥h lé̇⁠ʼmòֽr׃"],[27,2,"דַּבֵּ֞ר אֶל־בְּנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם אִ֕ישׁ כִּ֥י יַפְלִ֖א נֶ֑דֶר בְּ⁠עֶרְכְּ⁠ךָ֥ נְפָשֹׁ֖ת לַֽ⁠יהוָֽה׃","dȧbé̇֞r ʼel-bĕ̇né֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m ʼi֕yş̌ ki֥̇y yapĕli֖ʼ ne֑der bĕ̇⁠ʻerĕkĕ̇⁠ká֥ nĕpáşò֖̌ţ laֽ⁠yhwáֽh׃"],[27,3,"וְ⁠הָיָ֤ה עֶרְכְּ⁠ךָ֙ הַ⁠זָּכָ֔ר מִ⁠בֶּן֙ עֶשְׂרִ֣ים שָׁנָ֔ה וְ⁠עַ֖ד בֶּן־שִׁשִּׁ֣ים שָׁנָ֑ה וְ⁠הָיָ֣ה עֶרְכְּ⁠ךָ֗ חֲמִשִּׁ֛ים שֶׁ֥קֶל כֶּ֖סֶף בְּ⁠שֶׁ֥קֶל הַ⁠קֹּֽדֶשׁ׃","wĕ⁠háyá֤h ʻerĕkĕ̇⁠ká֙ ha⁠zá̇ká֔r mi⁠bėn֙ ʻeşĕ̂ri֣ym şá̌ná֔h wĕ⁠ʻa֖d bėn-şǐşi֣̇̌ym şá̌ná֑h wĕ⁠háyá֣h ʻerĕkĕ̇⁠ká֗ ẖàmişi֛̇̌ym şě֥qel kė֖sep bĕ̇⁠şě֥qel ha⁠qòֽ̇deş̌׃"],[27,4,"וְ⁠אִם־נְקֵבָ֖ה הִ֑וא וְ⁠הָיָ֥ה עֶרְכְּ⁠ךָ֖ שְׁלֹשִׁ֥ים שָֽׁקֶל׃","wĕ⁠ʼim-nĕqébá֖h hi֑wʼ wĕ⁠háyá֥h ʻerĕkĕ̇⁠ká֖ şĕ̌lòşǐ֥ym şáֽ̌qel׃"],[27,5,"וְ⁠אִ֨ם מִ⁠בֶּן־חָמֵ֜שׁ שָׁנִ֗ים וְ⁠עַד֙ בֶּן־עֶשְׂרִ֣ים שָׁנָ֔ה וְ⁠הָיָ֧ה עֶרְכְּ⁠ךָ֛ הַ⁠זָּכָ֖ר עֶשְׂרִ֣ים שְׁקָלִ֑ים וְ⁠לַ⁠נְּקֵבָ֖ה עֲשֶׂ֥רֶת שְׁקָלִֽים׃","wĕ⁠ʼi֨m mi⁠bėn-ẖámé֜ş̌ şá̌ni֗ym wĕ⁠ʻad֙ bėn-ʻeşĕ̂ri֣ym şá̌ná֔h wĕ⁠háyá֧h ʻerĕkĕ̇⁠ká֛ ha⁠zá̇ká֖r ʻeşĕ̂ri֣ym şĕ̌qáli֑ym wĕ⁠la⁠nĕ̇qébá֖h ʻàşê֥reţ şĕ̌qáliֽym׃"],[27,6,"וְ⁠אִ֣ם מִ⁠בֶּן־חֹ֗דֶשׁ וְ⁠עַד֙ בֶּן־חָמֵ֣שׁ שָׁנִ֔ים וְ⁠הָיָ֤ה עֶרְכְּ⁠ךָ֙ הַ⁠זָּכָ֔ר חֲמִשָּׁ֥ה שְׁקָלִ֖ים כָּ֑סֶף וְ⁠לַ⁠נְּקֵבָ֣ה עֶרְכְּ⁠ךָ֔ שְׁלֹ֥שֶׁת שְׁקָלִ֖ים כָּֽסֶף׃","wĕ⁠ʼi֣m mi⁠bėn-ẖò֗deş̌ wĕ⁠ʻad֙ bėn-ẖámé֣ş̌ şá̌ni֔ym wĕ⁠háyá֤h ʻerĕkĕ̇⁠ká֙ ha⁠zá̇ká֔r ẖàmişá֥̇̌h şĕ̌qáli֖ym ká֑̇sep wĕ⁠la⁠nĕ̇qébá֣h ʻerĕkĕ̇⁠ká֔ şĕ̌lò֥şěţ şĕ̌qáli֖ym káֽ̇sep׃"],[27,7,"וְ֠⁠אִם מִ⁠בֶּן־שִׁשִּׁ֨ים שָׁנָ֤ה וָ⁠מַ֨עְלָ⁠ה֙ אִם־זָכָ֔ר וְ⁠הָיָ֣ה עֶרְכְּ⁠ךָ֔ חֲמִשָּׁ֥ה עָשָׂ֖ר שָׁ֑קֶל וְ⁠לַ⁠נְּקֵבָ֖ה עֲשָׂרָ֥ה שְׁקָלִֽים׃","wĕ֠⁠ʼim mi⁠bėn-şǐşi̇̌֨ym şá̌ná֤h wá⁠ma֨ʻĕlá⁠h֙ ʼim-záká֔r wĕ⁠háyá֣h ʻerĕkĕ̇⁠ká֔ ẖàmişá֥̇̌h ʻáşá֖̂r şá֑̌qel wĕ⁠la⁠nĕ̇qébá֖h ʻàşá̂rá֥h şĕ̌qáliֽym׃"],[27,8,"וְ⁠אִם־מָ֥ךְ הוּא֙ מֵֽ⁠עֶרְכֶּ֔⁠ךָ וְ⁠הֶֽעֱמִיד⁠וֹ֙ לִ⁠פְנֵ֣י הַ⁠כֹּהֵ֔ן וְ⁠הֶעֱרִ֥יךְ אֹת֖⁠וֹ הַ⁠כֹּהֵ֑ן עַל־פִּ֗י אֲשֶׁ֤ר תַּשִּׂיג֙ יַ֣ד הַ⁠נֹּדֵ֔ר יַעֲרִיכֶ֖⁠נּוּ הַ⁠כֹּהֵֽן׃ס","wĕ⁠ʼim-má֥kĕ hẇʼ֙ méֽ⁠ʻerĕkė֔⁠ká wĕ⁠heֽʻèmiyd⁠wò֙ li⁠pĕné֣y ha⁠kò̇hé֔n wĕ⁠heʻèri֥ykĕ ʼòţ֖⁠wò ha⁠kò̇hé֑n ʻal-pi̇֗y ʼàşě֤r ţȧşi̇̂yg֙ ya֣d ha⁠nò̇dé֔r yaʻàriyke֖⁠ṅẇ ha⁠kò̇héֽn׃s"],[27,9,"וְ⁠אִם־בְּהֵמָ֔ה אֲשֶׁ֨ר יַקְרִ֧יבוּ מִמֶּ֛⁠נָּה קָרְבָּ֖ן לַֽ⁠יהוָ֑ה כֹּל֩ אֲשֶׁ֨ר יִתֵּ֥ן מִמֶּ֛⁠נּוּ לַ⁠יהוָ֖ה יִֽהְיֶה־קֹּֽדֶשׁ׃","wĕ⁠ʼim-bĕ̇hémá֔h ʼàşě֨r yaqĕri֧ybẇ mimė֛⁠ná̇h qárĕbá֖̇n laֽ⁠yhwá֑h kò̇l֩ ʼàşě֨r yiţé֥̇n mimė֛⁠ṅẇ la⁠yhwá֖h yiֽhĕyeh-qòֽ̇deş̌׃"],[27,10,"לֹ֣א יַחֲלִיפֶ֗⁠נּוּ וְ⁠לֹֽא־יָמִ֥יר אֹת֛⁠וֹ ט֥וֹב בְּ⁠רָ֖ע אוֹ־רַ֣ע בְּ⁠ט֑וֹב וְ⁠אִם־הָמֵ֨ר יָמִ֤יר בְּהֵמָה֙ בִּ⁠בְהֵמָ֔ה וְ⁠הָֽיָה־ה֥וּא וּ⁠תְמוּרָת֖⁠וֹ יִֽהְיֶה־קֹּֽדֶשׁ׃","lò֣ʼ yaẖàliype֗⁠ṅẇ wĕ⁠lòֽʼ-yámi֥yr ʼòţ֛⁠wò t֥wòb bĕ̇⁠rá֖ʻ ʼwò-ra֣ʻ bĕ̇⁠t֑wòb wĕ⁠ʼim-hámé֨r yámi֤yr bĕ̇hémáh֙ bi̇⁠bĕhémá֔h wĕ⁠háֽyáh-h֥ẇʼ ẇ⁠ţĕmẇráţ֖⁠wò yiֽhĕyeh-qòֽ̇deş̌׃"],[27,11,"וְ⁠אִם֙ כָּל־בְּהֵמָ֣ה טְמֵאָ֔ה אֲ֠שֶׁר לֹא־יַקְרִ֧יבוּ מִמֶּ֛⁠נָּה קָרְבָּ֖ן לַֽ⁠יהוָ֑ה וְ⁠הֶֽעֱמִ֥יד אֶת־הַ⁠בְּהֵמָ֖ה לִ⁠פְנֵ֥י הַ⁠כֹּהֵֽן׃","wĕ⁠ʼim֙ ká̇l-bĕ̇hémá֣h tĕméʼá֔h ʼà֠şěr lòʼ-yaqĕri֧ybẇ mimė֛⁠ná̇h qárĕbá֖̇n laֽ⁠yhwá֑h wĕ⁠hֽeʻèmi֥yd ʼeţ-ha⁠bĕ̇hémá֖h li⁠pĕné֥y ha⁠kò̇héֽn׃"],[27,12,"וְ⁠הֶעֱרִ֤יךְ הַ⁠כֹּהֵן֙ אֹתָ֔⁠הּ בֵּ֥ין ט֖וֹב וּ⁠בֵ֣ין רָ֑ע כְּ⁠עֶרְכְּ⁠ךָ֥ הַ⁠כֹּהֵ֖ן כֵּ֥ן יִהְיֶֽה׃","wĕ⁠heʻèri֤ykĕ ha⁠kò̇hén֙ ʼòţá֔⁠ḣ bé֥̇yn t֖wòb ẇ⁠bé֣yn rá֑ʻ kĕ̇⁠ʻerĕkĕ̇⁠ká֥ ha⁠kò̇hé֖n ké֥̇n yihĕyeֽh׃"],[27,13,"וְ⁠אִם־גָּאֹ֖ל יִגְאָלֶ֑⁠נָּה וְ⁠יָסַ֥ף חֲמִישִׁת֖⁠וֹ עַל־עֶרְכֶּֽ⁠ךָ׃","wĕ⁠ʼim-gá̇ʼò֖l yigĕʼále֑⁠ná̇h wĕ⁠yása֥p ẖàmiyşǐţ֖⁠wò ʻal-ʻerĕkėֽ⁠ká׃"],[27,14,"וְ⁠אִ֗ישׁ כִּֽי־יַקְדִּ֨שׁ אֶת־בֵּית֥⁠וֹ קֹ֨דֶשׁ֙ לַֽ⁠יהוָ֔ה וְ⁠הֶעֱרִיכ⁠וֹ֙ הַ⁠כֹּהֵ֔ן בֵּ֥ין ט֖וֹב וּ⁠בֵ֣ין רָ֑ע כַּ⁠אֲשֶׁ֨ר יַעֲרִ֥יךְ אֹת֛⁠וֹ הַ⁠כֹּהֵ֖ן כֵּ֥ן יָקֽוּם׃","wĕ⁠ʼi֗yş̌ kiֽ̇y-yaqĕdi̇֨ş̌ ʼeţ-bé̇yţ֥⁠wò qò֨deş̌֙ laֽ⁠yhwá֔h wĕ⁠heʻèriyk⁠wò֙ ha⁠kò̇hé֔n bé֥̇yn t֖wòb ẇ⁠bé֣yn rá֑ʻ kȧ⁠ʼàşě֨r yaʻàri֥ykĕ ʼòţ֛⁠wò ha⁠kò̇hé֖n ké֥̇n yáqֽẇm׃"],[27,15,"וְ⁠אִ֨ם־הַ⁠מַּקְדִּ֔ישׁ יִגְאַ֖ל אֶת־בֵּית֑⁠וֹ וְ֠⁠יָסַף חֲמִישִׁ֧ית כֶּֽסֶף־עֶרְכְּ⁠ךָ֛ עָלָ֖י⁠ו וְ⁠הָ֥יָה לֽ⁠וֹ׃","wĕ⁠ʼi֨m-ha⁠mȧqĕdi̇֔yş̌ yigĕʼa֖l ʼeţ-bé̇yţ֑⁠wò wĕ֠⁠yásap ẖàmiyşǐ֧yţ kėֽsep-ʻerĕkĕ̇⁠ká֛ ʻálá֖y⁠w wĕ⁠há֥yáh lֽ⁠wò׃"],[27,16,"וְ⁠אִ֣ם ׀ מִ⁠שְּׂדֵ֣ה אֲחֻזָּת֗⁠וֹ יַקְדִּ֥ישׁ אִישׁ֙ לַֽ⁠יהוָ֔ה וְ⁠הָיָ֥ה עֶרְכְּ⁠ךָ֖ לְ⁠פִ֣י זַרְע֑⁠וֹ זֶ֚רַע חֹ֣מֶר שְׂעֹרִ֔ים בַּ⁠חֲמִשִּׁ֖ים שֶׁ֥קֶל כָּֽסֶף׃","wĕ⁠ʼi֣m ׀ mi⁠şĕ̇̂dé֣h ʼàẖuzá̇ţ֗⁠wò yaqĕdi֥̇yş̌ ʼiyş̌֙ laֽ⁠yhwá֔h wĕ⁠háyá֥h ʻerĕkĕ̇⁠ká֖ lĕ⁠pi֣y zarĕʻ֑⁠wò ze֚raʻ ẖò֣mer şĕ̂ʻòri֔ym bȧ⁠ẖàmişi֖̇̌ym şě֥qel káֽ̇sep׃"],[27,17,"אִם־מִ⁠שְּׁנַ֥ת הַ⁠יֹּבֵ֖ל יַקְדִּ֣ישׁ שָׂדֵ֑⁠הוּ כְּ⁠עֶרְכְּ⁠ךָ֖ יָקֽוּם׃","ʼim-mi⁠şĕ̇̌na֥ţ ha⁠yò̇bé֖l yaqĕdi֣̇yş̌ şá̂dé֑⁠hẇ kĕ̇⁠ʻerĕkĕ̇⁠ká֖ yáqֽẇm׃"],[27,18,"וְ⁠אִם־אַחַ֣ר הַ⁠יֹּבֵל֮ יַקְדִּ֣ישׁ שָׂדֵ⁠הוּ֒ וְ⁠חִשַּׁב־ל֨⁠וֹ הַ⁠כֹּהֵ֜ן אֶת־הַ⁠כֶּ֗סֶף עַל־פִּ֤י הַ⁠שָּׁנִים֙ הַ⁠נּ֣וֹתָרֹ֔ת עַ֖ד שְׁנַ֣ת הַ⁠יֹּבֵ֑ל וְ⁠נִגְרַ֖ע מֵֽ⁠עֶרְכֶּֽ⁠ךָ׃","wĕ⁠ʼim-ʼaẖa֣r ha⁠yò̇bél֮ yaqĕdi֣̇yş̌ şá̂dé⁠hẇ֒ wĕ⁠ẖişȧ̌b-l֨⁠wò ha⁠kò̇hé֜n ʼeţ-ha⁠kė֗sep ʻal-pi֤̇y ha⁠şá̇̌niym֙ ha⁠ṅ֣wòţárò֔ţ ʻa֖d şĕ̌na֣ţ ha⁠yò̇bé֑l wĕ⁠nigĕra֖ʻ méֽ⁠ʻerĕkėֽ⁠ká׃"],[27,19,"וְ⁠אִם־גָּאֹ֤ל יִגְאַל֙ אֶת־הַ⁠שָּׂדֶ֔ה הַ⁠מַּקְדִּ֖ישׁ אֹת֑⁠וֹ וְ֠⁠יָסַף חֲמִשִׁ֧ית כֶּֽסֶף־עֶרְכְּ⁠ךָ֛ עָלָ֖י⁠ו וְ⁠קָ֥ם לֽ⁠וֹ׃","wĕ⁠ʼim-gá̇ʼò֤l yigĕʼal֙ ʼeţ-ha⁠şá̇̂de֔h ha⁠mȧqĕdi֖̇yş̌ ʼòţ֑⁠wò wĕ֠⁠yásap ẖàmişǐ֧yţ kėֽsep-ʻerĕkĕ̇⁠ká֛ ʻálá֖y⁠w wĕ⁠qá֥m lֽ⁠wò׃"],[27,20,"וְ⁠אִם־לֹ֤א יִגְאַל֙ אֶת־הַ⁠שָּׂדֶ֔ה וְ⁠אִם־מָכַ֥ר אֶת־הַ⁠שָּׂדֶ֖ה לְ⁠אִ֣ישׁ אַחֵ֑ר לֹ֥א יִגָּאֵ֖ל עֽוֹד׃","wĕ⁠ʼim-lò֤ʼ yigĕʼal֙ ʼeţ-ha⁠şá̇̂de֔h wĕ⁠ʼim-máka֥r ʼeţ-ha⁠şá̇̂de֖h lĕ⁠ʼi֣yş̌ ʼaẖé֑r lò֥ʼ yigá̇ʼé֖l ʻֽwòd׃"],[27,21,"וְ⁠הָיָ֨ה הַ⁠שָּׂדֶ֜ה בְּ⁠צֵאת֣⁠וֹ בַ⁠יֹּבֵ֗ל קֹ֛דֶשׁ לַֽ⁠יהוָ֖ה כִּ⁠שְׂדֵ֣ה הַ⁠חֵ֑רֶם לַ⁠כֹּהֵ֖ן תִּהְיֶ֥ה אֲחֻזָּתֽ⁠וֹ׃","wĕ⁠háyá֨h ha⁠şá̇̂de֜h bĕ̇⁠ẕéʼţ֣⁠wò ba⁠yò̇bé֗l qò֛deş̌ laֽ⁠yhwá֖h ki̇⁠şĕ̂dé֣h ha⁠ẖé֑rem la⁠kò̇hé֖n ţi̇hĕye֥h ʼàẖuzá̇ţֽ⁠wò׃"],[27,22,"וְ⁠אִם֙ אֶת־שְׂדֵ֣ה מִקְנָת֔⁠וֹ אֲשֶׁ֕ר לֹ֖א מִ⁠שְּׂדֵ֣ה אֲחֻזָּת֑⁠וֹ יַקְדִּ֖ישׁ לַֽ⁠יהוָֽה׃","wĕ⁠ʼim֙ ʼeţ-şĕ̂dé֣h miqĕnáţ֔⁠wò ʼàşě֕r lò֖ʼ mi⁠şĕ̇̂dé֣h ʼàẖuzá̇ţ֑⁠wò yaqĕdi֖̇yş̌ laֽ⁠yhwáֽh׃"],[27,23,"וְ⁠חִשַּׁב־ל֣⁠וֹ הַ⁠כֹּהֵ֗ן אֵ֚ת מִכְסַ֣ת הָֽ⁠עֶרְכְּ⁠ךָ֔ עַ֖ד שְׁנַ֣ת הַ⁠יֹּבֵ֑ל וְ⁠נָתַ֤ן אֶת־הָ⁠עֶרְכְּ⁠ךָ֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא קֹ֖דֶשׁ לַ⁠יהוָֽה׃","wĕ⁠ẖişȧ̌b-l֣⁠wò ha⁠kò̇hé֗n ʼé֚ţ mikĕsa֣ţ háֽ⁠ʻerĕkĕ̇⁠ká֔ ʻa֖d şĕ̌na֣ţ ha⁠yò̇bé֑l wĕ⁠náţa֤n ʼeţ-há⁠ʻerĕkĕ̇⁠ká֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ qò֖deş̌ la⁠yhwáֽh׃"],[27,24,"בִּ⁠שְׁנַ֤ת הַ⁠יּוֹבֵל֙ יָשׁ֣וּב הַ⁠שָּׂדֶ֔ה לַ⁠אֲשֶׁ֥ר קָנָ֖⁠הוּ מֵ⁠אִתּ֑⁠וֹ לַ⁠אֲשֶׁר־ל֖⁠וֹ אֲחֻזַּ֥ת הָ⁠אָֽרֶץ׃","bi̇⁠şĕ̌na֤ţ ha⁠ẏwòbél֙ yáş֣̌ẇb ha⁠şá̇̂de֔h la⁠ʼàşě֥r qáná֖⁠hẇ mé⁠ʼiţ֑̇⁠wò la⁠ʼàşěr-l֖⁠wò ʼàẖuzȧ֥ţ há⁠ʼáֽreẕ׃"],[27,25,"וְ⁠כָל־עֶרְכְּ⁠ךָ֔ יִהְיֶ֖ה בְּ⁠שֶׁ֣קֶל הַ⁠קֹּ֑דֶשׁ עֶשְׂרִ֥ים גֵּרָ֖ה יִהְיֶ֥ה הַ⁠שָּֽׁקֶל׃ס","wĕ⁠kál-ʻerĕkĕ̇⁠ká֔ yihĕye֖h bĕ̇⁠şě֣qel ha⁠qò֑̇deş̌ ʻeşĕ̂ri֥ym gé̇rá֖h yihĕye֥h ha⁠şáֽ̇̌qel׃s"],[27,26,"אַךְ־בְּכ֞וֹר אֲשֶׁר־יְבֻכַּ֤ר לַֽ⁠יהוָה֙ בִּ⁠בְהֵמָ֔ה לֹֽא־יַקְדִּ֥ישׁ אִ֖ישׁ אֹת֑⁠וֹ אִם־שׁ֣וֹר אִם־שֶׂ֔ה לַֽ⁠יהוָ֖ה הֽוּא׃","ʼakĕ-bĕ̇k֞wòr ʼàşěr-yĕbukȧ֤r laֽ⁠yhwáh֙ bi̇⁠bĕhémá֔h lòֽʼ-yaqĕdi֥̇yş̌ ʼi֖yş̌ ʼòţ֑⁠wò ʼim-ş֣̌wòr ʼim-şê֔h laֽ⁠yhwá֖h hֽẇʼ׃"],[27,27,"וְ⁠אִ֨ם בַּ⁠בְּהֵמָ֤ה הַ⁠טְּמֵאָה֙ וּ⁠פָדָ֣ה בְ⁠עֶרְכֶּ֔⁠ךָ וְ⁠יָסַ֥ף חֲמִשִׁת֖⁠וֹ עָלָ֑י⁠ו וְ⁠אִם־לֹ֥א יִגָּאֵ֖ל וְ⁠נִמְכַּ֥ר בְּ⁠עֶרְכֶּֽ⁠ךָ׃","wĕ⁠ʼi֨m bȧ⁠bĕ̇hémá֤h ha⁠tĕ̇méʼáh֙ ẇ⁠pádá֣h bĕ⁠ʻerĕkė֔⁠ká wĕ⁠yása֥p ẖàmişǐţ֖⁠wò ʻálá֑y⁠w wĕ⁠ʼim-lò֥ʼ yigá̇ʼé֖l wĕ⁠nimĕkȧ֥r bĕ̇⁠ʻerĕkėֽ⁠ká׃"],[27,28,"אַךְ־כָּל־חֵ֡רֶם אֲשֶׁ֣ר יַחֲרִם֩ אִ֨ישׁ לַֽ⁠יהוָ֜ה מִ⁠כָּל־אֲשֶׁר־ל֗⁠וֹ מֵ⁠אָדָ֤ם וּ⁠בְהֵמָה֙ וּ⁠מִ⁠שְּׂדֵ֣ה אֲחֻזָּת֔⁠וֹ לֹ֥א יִמָּכֵ֖ר וְ⁠לֹ֣א יִגָּאֵ֑ל כָּל־חֵ֕רֶם קֹֽדֶשׁ־קָֽדָשִׁ֥ים ה֖וּא לַ⁠יהוָֽה׃","ʼakĕ-ká̇l-ẖé֡rem ʼàşě֣r yaẖàrim֩ ʼi֨yş̌ laֽ⁠yhwá֜h mi⁠ká̇l-ʼàşěr-l֗⁠wò mé⁠ʼádá֤m ẇ⁠bĕhémáh֙ ẇ⁠mi⁠şĕ̇̂dé֣h ʼàẖuzá̇ţ֔⁠wò lò֥ʼ yimá̇ké֖r wĕ⁠lò֣ʼ yigá̇ʼé֑l ká̇l-ẖé֕rem qòֽdeş̌-qáֽdáşǐ֥ym h֖ẇʼ la⁠yhwáֽh׃"],[27,29,"כָּל־חֵ֗רֶם אֲשֶׁ֧ר יָחֳרַ֛ם מִן־הָ⁠אָדָ֖ם לֹ֣א יִפָּדֶ֑ה מ֖וֹת יוּמָֽת׃","ká̇l-ẖé֗rem ʼàşě֧r yáẖora֛m min-há⁠ʼádá֖m lò֣ʼ yipá̇de֑h m֖wòţ yẇmáֽţ׃"],[27,30,"וְ⁠כָל־מַעְשַׂ֨ר הָ⁠אָ֜רֶץ מִ⁠זֶּ֤רַע הָ⁠אָ֨רֶץ֙ מִ⁠פְּרִ֣י הָ⁠עֵ֔ץ לַ⁠יהוָ֖ה ה֑וּא קֹ֖דֶשׁ לַֽ⁠יהוָֽה׃","wĕ⁠kál-maʻĕşâ֨r há⁠ʼá֜reẕ mi⁠zė֤raʻ há⁠ʼá֨reẕ֙ mi⁠pĕ̇ri֣y há⁠ʻé֔ẕ la⁠yhwá֖h h֑ẇʼ qò֖deş̌ laֽ⁠yhwáֽh׃"],[27,31,"וְ⁠אִם־גָּאֹ֥ל יִגְאַ֛ל אִ֖ישׁ מִ⁠מַּֽעַשְׂר֑⁠וֹ חֲמִשִׁית֖⁠וֹ יֹסֵ֥ף עָלָֽי⁠ו׃","wĕ⁠ʼim-gá̇ʼò֥l yigĕʼa֛l ʼi֖yş̌ mi⁠mȧֽʻaşĕ̂r֑⁠wò ẖàmişǐyţ֖⁠wò yòsé֥p ʻáláֽy⁠w׃"],[27,32,"וְ⁠כָל־מַעְשַׂ֤ר בָּקָר֙ וָ⁠צֹ֔אן כֹּ֥ל אֲשֶׁר־יַעֲבֹ֖ר תַּ֣חַת הַ⁠שָּׁ֑בֶט הָֽ⁠עֲשִׂירִ֕י יִֽהְיֶה־קֹּ֖דֶשׁ לַֽ⁠יהוָֽה׃","wĕ⁠kál-maʻĕşâ֤r bá̇qár֙ wá⁠ẕò֔ʼn kò֥̇l ʼàşěr-yaʻàbò֖r ţȧ֣ẖaţ ha⁠şá֑̇̌bet hֽá⁠ʻàşîyri֕y yiֽhĕyeh-qò֖̇deş̌ laֽ⁠yhwáֽh׃"],[27,33,"לֹ֧א יְבַקֵּ֛ר בֵּֽין־ט֥וֹב לָ⁠רַ֖ע וְ⁠לֹ֣א יְמִירֶ֑⁠נּוּ וְ⁠אִם־הָמֵ֣ר יְמִירֶ֔⁠נּוּ וְ⁠הָֽיָה־ה֧וּא וּ⁠תְמוּרָת֛⁠וֹ יִֽהְיֶה־קֹ֖דֶשׁ לֹ֥א יִגָּאֵֽל׃","lò֧ʼ yĕbaqé֛̇r béֽ̇yn-t֥wòb lá⁠ra֖ʻ wĕ⁠lò֣ʼ yĕmiyre֑⁠ṅẇ wĕ⁠ʼim-hámé֣r yĕmiyre֔⁠ṅẇ wĕ⁠háֽyáh-h֧ẇʼ ẇ⁠ţĕmẇráţ֛⁠wò yiֽhĕyeh-qò֖deş̌ lò֥ʼ yigá̇ʼéֽl׃"],[27,34,"אֵ֣לֶּה הַ⁠מִּצְוֺ֗ת אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֖ה אֶל־בְּנֵ֣י יִשְׂרָאֵ֑ל בְּ⁠הַ֖ר סִינָֽי׃","ʼé֣lėh ha⁠mi̇ẕĕwֺ֗ţ ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֖h ʼel-bĕ̇né֣y yişĕ̂ráʼé֑l bĕ̇⁠ha֖r siynáֽy׃"]]}};